/* Fuente: A. G. Piñeiro, «Barrios, calles y plazas de la Ciudad de Buenos Aires: origen y razón de sus nombres», Instituto Histórico de la Ciudad, 2008. Formato: [nombre, tipo, texto] */
window.CALLES=[["Abanderada de los Humildes","plaza","Abanderada de los Humildes: apelativo con el que se conoce a Eva Perón como símbolo de lucha y sensibilidad por los más pobres y por la justicia social."],["Miguel Abuelo","plazoleta","Miguel Ángel Peralta (1946 a 1988), músico, cantante, compositor y poeta conocido con el seudónimo de Miguel Abuelo; precursor y fundador del conjunto de rock nacional Los Abuelos de la Nada en 1967; grupo que vuelve a crear en 1979 y 1985; autor de Los abuelos de la nada, Cosas mías, Vasos y besos."],["Las Acacias","calle","Acacia: árbol o arbusto de la familia de las leguminosas mimosáceas, muchas de cuyas especies crecen en nuestro país."],["Acassuso","calle","Domingo de Acassuso (1659 a 1727), militar y comerciante español; fundador de la capilla, hoy catedral, de San Isidro, en la ciudad del mismo nombre en la provincia de Buenos Aires."],["Acevedo","calle","Obras Públicas). Manuel Antonio Acevedo y Torino (1770 a 1825), sacerdote; diputado por Catamarca en el Congreso de Tucumán."],["Eduardo Acevedo","calle","Eduardo Acevedo (1815 a 1863), jurisconsulto uruguayo; coopera con Dalmacio Vélez Sarsfield en la redacción del Código de Comercio argentino; ministro de Gobierno y Relaciones Exteriores del presidente Berro."],["Mariano Acha","calle","Mariano Antonio de Acha (1799 a 1841), general; combate en Angaco; apresa a Dorrego después de la batalla de Navarro."],["Achala","calle","Achala: sierra de la provincia de Córdoba. En ella se encuentra el altiplano conocido como Pampa de Achala."],["Achával","calle","José Wenceslao Achával (1813 a 1898), sacerdote; maestro de Esquiú; ministro provincial de la orden franciscana desde 1848; constituyente de Santiago del Estero en 1855; obispo de San Juan de Cuyo desde 1867; fundador del Seminario Conciliar en 1874."],["Tristán Achával Rodríguez","avenida","Tristán Achával Rodríguez (1843 a 1887), jurisconsulto; diputado nacional por Córdoba en 1880, vota por la federalización de la ciudad de Buenos Aires; informa en 1881, con acopio de doctrina, el proyecto de Ley Orgánica de la Municipalidad de Buenos Aires."],["Achega","calle","Domingo Victorio de Achega (1781 a 1859), sacerdote; vicepresidente del Congreso Nacional en 1817; primer rector del Colegio de la Unión del Sur."],["Achira","calle","Achira: voz quechua que denomina a la hierba de la familia de las alismáceas. Es originaria de América meridional."],["Achupallas","calle","Achupallas: triunfo del ejército libertador al mando del mayor Antonio Arcos, el 4 de febrero de 1817."],["Aconcagua","calle","Aconcagua: cumbre más elevada del continente americano (7.130 metros). Está ubicada en el límite de las provincias de San Juan y Mendoza."],["Arquitecto Wladimiro Acosta","plaza","Wladimiro Acosta: nombre con el que se conoce profesionalmente al arquitecto de origen ruso Wladimir Konstantinovsky (1900 a 1967). Graduado en Roma, donde es profesor de Diseño Arquitectónico. Llega en 1928 a Buenos Aires, donde en acto de asimilación al país y a su lengua, retoma el apellido de Acosta original de su familia sefardita, anterior a su emigración a Rusia. En 1932 descubre y experimenta el “sistema helio”, que consiste en un corte del terreno en terrazas protegidas del sol con una losa visera ubicada en el nivel de la cubierta. Durante las décadas de 1930 y 1940, realiza gran cantidad de obras, entre ellas, las casas Ramos Mejía (1939), Punta del Este (1940) y Castelar (1944), el edificio de departamentos de Figueroa Alcorta (1942) y el primer proyecto de casa colectiva del Hogar Obrero (1941). Se destacan, entre sus obras, la Unidad Vecinal de la Isla Maciel en la ribera sudeste del Riachuelo y la que fue su vivienda particular de la calle La Pampa 3470 (1942) salvada por los vecinos cuando iba a ser demolida. Autor del libro Vivienda y clima, Buenos Aires, Ediciones Nueva Visión, 1976."],["Diputada Emar Acosta","canteros centrales","Emar Acosta (1900 a 1965), abogada; gracias a la reforma constitucional de 1927, realizada en la provincia de San Juan por iniciativa del gobierno de Aldo Cantoni, que establece el derecho de la mujer a elegir y ser elegida, es la primera mujer diputada de la provincia y de la República Argentina, durante los períodos 1934-1938 y 1942-1943. Como legisladora se dedica a la reforma de códigos provinciales en favor de los derechos de la mujer. Funda la Asociación de Cultura Cívica de la Mujer Sanjuanina y auspicia la creación de los Patronatos de Menores y de Presos y Excarcelados."],["Mariano Acosta","avenida","Mariano Acosta (1825 a 1893), político; gobernador de la provincia de Buenos Aires de 1872 a 1874; vicepresidente de la República de 1874 a 1880 durante la presidencia de Nicolás Avellaneda."],["Acoyte","calle","Acoyte: lugar de la provincia de Salta donde José Antonio Ruiz, al mando de una partida de gauchos, vence el 13 de febrero de 1818 a un destacamento realista muy superior en número."],["Francisco Acuña de Figueroa","calle","Francisco Esteban Acuña de Figueroa (1791 a 1862), poeta uruguayo; autor del Himno Nacional de la república hermana."],["Aerolíneas Argentinas","calle","Aerolíneas Argentinas: empresa argentina de navegación aérea creada por Decreto del 3 de mayo de 1949 a raíz de la fusión de las empresas Aeroposta Argentina, Sociedad Mixta Flota Aéreo Mercante (FAMA), Sociedad Mixta Zonas Oeste y Norte (ZONDA) y Sociedad Mixta de Aviación Territorial Fluvial Argentina (ALFA)."],["Aeronáutica Argentina","plazoleta","Aeronáutica Argentina: en las proximidades de esta plazoleta, precisamente entre las actuales calles Pilar, Murguiondo, Tabaré y avenida General Francisco Fernández de la Cruz, funcionó, desde 1910 hasta 1934, aproximadamente, el primer aeródromo nacional (Aeródromo de Villa Lugano), y es por ese motivo que se eligió este lugar para rendir homenaje a nuestra aeronáutica."],["África","cantero central","África: uno de los cinco continentes en que se halla dividida la tierra."],["Agaces","calle","Agaces: aborígenes del Chaco pertenecientes a la familia lingüística guaycurú."],["Doctor Luis Agote","calle","Luis Agote (1868 a 1954), médico; descubridor del método de transfusión de sangre sin peligro de coagulación."],["Pedro Agote","calle","Pedro Agote (1816 a 1909), economista; ministro de Hacienda de la provincia de Buenos Aires y fundador del Banco Hipotecario Nacional; colabora en la sanción de la Ley de Obras de Salubridad de Buenos Aires."],["Agrelo","calle","Pedro José Agrelo (1776 a 1846), jurisconsulto; miembro de la Asamblea de 1813 y del Congreso de 1826."],["Agronomía","barrio","Agronomía: denominación usual con la que comienza a identificarse a esta zona desde 1904, cuando se instala allí el Instituto Superior de Agronomía y Veterinaria, más tarde Facultad del mismo nombre."],["Alejandro María de Aguado","calle","Alejandro María de Aguado, Marqués de las Marismas del Guadalquivir (1785 a 1842), militar y banquero español amigo de San Martín, a quien ayuda económicamente cuando se establece en Francia y posteriormente en la compra de las propiedades del Libertador en Grand Bourg y París."],["Aguaribay","calle","Aguaribay: árbol de la familia de las anacardiáceas, llamado también molle, terebinto o falso pimiento."],["Aguas Buenas","calle","Aguas Buenas: localidad de la provincia de La Pampa, famosa por sus aguas termales."],["Agüero","calle","Julián Segundo de Agüero (1776 a 1851), sacerdote; ministro de Gobierno de Rivadavia en 1826; diputado en el Congreso General Constituyente de 1824."],["José Eusebio Agüero","plazoleta","José Eusebio Agüero (1791 a 1864) sacerdote; prefecto del Colegio de la Unión del Sud en 1818; diputado por Córdoba en el Congreso de 1826; profesor de Derecho Público Eclesiástico de la Universidad de Buenos Aires; rector del Colegio Nacional de Buenos Aires en 1863."],["Aguilar","calle","Victoriano Aguilar (1790 a 1855) coronel; combate durante las Invasiones Inglesas; comandante del Fuerte de Buenos Aires en 1842; edecán de Juan Manuel de Rosas."],["Ingeniero Félix Aguilar","plaza","Félix Aguilar (1884 a 1943) astrónomo y geodesta; director de la escuela de Ciencias Astronómicas de La Plata; director de Geodesia del Instituto Geográfico Militar de 1916 a 1926; director del Observatorio Astronómico de 1919 a 1921 y de 1934 a 1943."],["Aguirre","calle","Francisco de Aguirre (¿1500?-1580) militar y conquistador español fundador de Santiago del Estero."],["Julián Aguirre","calle","Julián Antonio Aguirre (1868 a 1924), músico; autor de Aires nacionales argentinos, Canciones argentinas y Aires populares."],["Delmira Agustini","cantero central","Delmira Agustini (1886 a 1914) poetisa uruguaya; autora de El libro blanco (1907), Cantos de la mañana (1910) y Cálices vacíos (1913)."],["Don Anselmo Aieta","calle","Anselmo Alfredo Aieta (1896 a 1964), músico; autor de Palomita blanca, Siga el corso, Bajo Belgrano y Ya estamos iguales. AIETA DE GULLO, ÁNGELA M. (espacio verde) Ley Nº 1.128-2003, BO Nº 1.818. Ángela María Aieta de Gullo (1921 a 1976), a raíz de la detención de su hijo Juan Carlos en 1975, comienza a bregar por la defensa de los derechos humanos y las condiciones de los presos en la Argentina; trabaja activamente junto a otras madres de detenidos y desaparecidos; el 5 de agosto de 1976 es secuestrada en su propio domicilio. Permanece desaparecida."],["Aizpurúa","calle","Benito Aizpurúa (1774 a 1833), marino; combate en la guerra contra el Brasil como piloto mayor de la escuadra nacional."],["Alagón","calle","Juan de Alagón (1761-?), funcionario; integra la Junta Grande luego de la revolución del 5 y 6 de abril de 1811; preside en 1821 la Junta de Representantes de Buenos Aires."],["Albania","calle","Albania: país europeo. Capital: Tirana."],["Albarellos","avenida","Nicanor Albarellos (1810 a 1891), médico y músico; titular de la Cátedra de Partos en 1866; presidente y decano de la Facultad de Medicina; autor de Variaciones de cielito; diputado nacional por dos períodos desde 1863 hasta 1866; senador nacional."],["Albariño","calle","Domingo Albariño (1781 a 1824), teniente coronel; combate durante las Invasiones Inglesas; en Cotagaita, Suipacha, Ayohuma (donde es tomado prisionero) y Chachapoyas. José María Albariño (1794 a 1867), coronel, hermano del anterior; combate durante las Invasiones Inglesas, en Sipe-Sipe, Sauce Grande y Quebracho Herrado; segundo jefe de la Legión Argentina; senador por Buenos Aires en 1857; convencional en las reformas de 1860. Homenaje conjunto a los hermanos Albariño."],["Albarracín","calle","José Pastor Albarracín (1790 a 1874), sargento mayor; combate durante las Invasiones Inglesas, en el sitio de Montevideo en 1814 y desde 1815 en el Ejército Auxiliar del Alto Perú, donde asiste a todas las acciones de guerra hasta la batalla de Sipe-Sipe."],["Paula Albarracín de Sarmiento","calle","Paula Albarracín de Sarmiento (1774 a 1861), patricia, madre de Domingo Faustino Sarmiento."],["Bm N° 16.625. Alberdi","plaza","Ordenanza N° 1.833 del 23-12-1926, BB.MM. Nros. 979 y 980 Juan Bautista Alberdi (1810 a 1884), jurisconsulto y escritor; autor de Bases y puntos de partida para la organización política de la República Argentina."],["Mayor Bernardo Alberte","cantero central","Bernardo Alberte (1918 a 1976), militar; delegado del general Juan Domingo Perón entre 1967 y 1968; es asesinado el 24 de marzo de 1976."],["Alberti","calle","Manuel Alberti (1763 a 1811), sacerdote; vocal de la Primera Junta."],["Alberti","plaza","Manuel Alberti (1763 a 1811), sacerdote; vocal de la Primera Junta."],["Alcaraz","calle","Rafael Feliciano Alcaraz (1774 a 1825), sargento mayor; combate durante las Invasiones Inglesas; comandante del Piquete Celador de Policía desde 1814."],["Amancio Alcorta","avenida","Amancio Alcorta (1842 a 1902), jurisconsulto; ministro de Relaciones Exteriores durante las presidencias de Juárez Celman, Sáenz Peña, Uriburu y Roca; director del Colegio Nacional de Buenos Aires y del Banco Nacional."],["Scholem Aleijem","plazoleta","Scholem Aleijem: seudónimo del escritor ruso-judío Solomon J. Rabinovich (1859 a 1916); autor de Tobías el lechero, Stempeniu, Mobel, camino de América y El nuevo Kaserilevcke."],["Leandro N. Alem","avenida","Leandro Alem (1842 a 1896), jurisconsulto y político; combate en la Guerra del Paraguay; diputado y senador nacional; fundador de la Unión Cívica de la Juventud."],["Leandro N. Alem","plaza","Leandro Alem (1842 a 1896), jurisconsulto y político; combate en la Guerra del Paraguay; diputado y senador nacional; fundador de la Unión Cívica de la Juventud."],["Alemania","calle","República Federal Alemana: país europeo. Capital: Berlín."],["Alemania","plaza","República Federal Alemana: país europeo. Capital: Berlín."],["El Alfabeto","calle","Alfabeto: reunión metódica de las letras que representan los sonidos de una lengua."],["Alfarero","calle","Alfarero: en recuerdo del artesano indígena que fabricaba objetos de barro."],["Eloy Alfaro","plazoleta","Eloy Alfaro (1842 a 1912), estadista, político y militar ecuatoriano; presidente del Ecuador de 1895 a 1901 y de 1906 a 1911; reelecto presidente en 1911, muere asesinado al estallar una revolución."],["Algarrobo","calle","Algarrobo: árbol de la familia de las leguminosas mimosoideas, especie típica del monte argentino."],["Alicante","calle","Alicante: ciudad y provincia de España."],["Elías Alippi","plazoleta","Elías Isaac Alippi (1885 a 1942), actor, autor y director teatral; autor de La loca de la guardia, El indio rubio y La duquesa; actúa en las películas Así es la vida, Medio millón para una mujer y Callejón sin salida."],["Allende","calle","Faustino de Allende (1786 a 1865), coronel; combate en La Tablada, San Roque y Oncativo."],["Diputado Nacional Jorge Mariano Almada","cantero central","Jorge Mariano Almada (1924 a 1967), político; diputado nacional entre 1963 y 1965; miembro del Partido Demócrata y secretario de la Federación Nacional de Partidos del Centro."],["Almafuerte","avenida","Almafuerte: seudónimo del poeta y escritor Pedro Bonifacio Palacios (1854 a 1917); autor de El misionero y La sombra de la patria."],["Almagro","barrio","Julián de Almagro (¿-?) compra una importante extensión de tierras en este lugar de Buenos Aires el 28 de septiembre de 1839; dona los terrenos para el tendido de las vías del Ferrocarril del Oeste y para la instalación de una estación de pasajeros que recibe su nombre y que por extensión pasará a denominar al barrio."],["Almagro","calle","Almagro: barrio de la ciudad de Buenos Aires que según los autores de esta ordenanza se debe a que estas tierras fueron de propiedad de don Juan María de Almagro y de la Torre (1755 a 1843), jurisconsulto y funcionario; asesor del Virreinato; auditor de guerra, oidor honorario de la Real Audiencia desde 1796; padre de Julián de Almagro."],["Almagro","plaza","Diego de Almagro (¿1472?-1538), conquistador español; participa junto con Francisco de Pizarro en la conquista del Perú; nombrado Adelantado en los territorios situados al sur de los de Pizarro, llega hasta Chile y se apodera de Cuzco en 1537."],["Capitán Aviador Vicente Almandos Almonacid","plazoleta","Vicente Almandos Almonacid (1882 a 1953), aviador; fundador de la aviación comercial argentina; cruza la Cordillera de los Andes el 1° de enero y el 29 de marzo de 1920."],["El Alma Que Canta","plazoleta","El Alma que Canta: revista fundada en 1916 por Vicente Buchieri dedicada a la música popular; por sus páginas desfilaron las obras de famosos poetas y las canciones de numerosos autores de tango, fox trot, milonga, chacarera y otros ritmos."],["Doctor Hilario de Almeira","calle","Hilario de Almeyra (1799 a 1885), médico; actúa durante las guerras contra el Brasil y Paraguay; miembro de la Corporación Municipal de Buenos Aires."],["Alpatacal","calle","Alpatacal: lugar del departamento La Paz en la provincia de Mendoza, donde ocurrió un accidente ferroviario que costó la vida a numerosos cadetes de la Escuela Militar de Chile, el 7 de julio de 1927, cuando se dirigían a Buenos Aires para asistir a la inauguración del monumento al general Bartolomé Mitre, que se inauguró al día siguiente."],["Adolfo Alsina","calle","Adolfo Alsina (1829 a 1877), jurisconsulto; gobernador de la provincia de Buenos Aires de 1866 a 1868; vicepresidente de la República con Sarmiento; ministro de Guerra de Avellaneda."],["Valentín Alsina","avenida","Valentín Alsina (1802 a 1869), jurisconsulto; gobernador de Buenos Aires en 1852 y de 1857 a 1859; senador nacional por Buenos Aires. ALTA GRACIA (calle) Ordenanza N° 5.325-1933, BM N° 3.527/8. Alta Gracia: ciudad de la provincia de Córdoba."],["Altolaguirre","calle","León Pedro José de Altolaguirre (1752-?), funcionario; miembro de la Hermandad de Caridad de Buenos Aires en 1790 y conciliario de la misma en 1795; comandante general de los Resguardos del Río de la Plata; combate durante las Invasiones Inglesas."],["Alvarado","calle","Rudecindo Alvarado (1792 a 1872), general; combate en las batallas de Tucumán, Chacabuco y Maipú; queda al frente del Ejército Unido cuando luego de Guayaquil, San Martín abandona el Perú; por su actuación, Bolívar le confiere el grado de Gran Mariscal del Perú en 1826; gobernador de Salta en 1831."],["Agustín Álvarez","calle","Agustín Enrique Álvarez (1857 a 1914), jurisconsulto y escritor; autor de La transformación de las razas en América y La creación del mundo moral; diputado nacional por Mendoza de 1892 a 1896."],["Crisóstomo Álvarez","calle","Juan Crisóstomo Álvarez (¿1819?-1852), coronel; combate en Chascomús, Los Cardones, Tapia y en Rincón del Manantial, donde es derrotado, hecho prisionero y condenado a muerte."],["Julián Álvarez","calle","Julián Baltasar Álvarez (1788 a 1843), jurisconsulto, diputado por San Juan a la Asamblea de 1812; redactor de La Gaceta; diputado por San José (Uruguay) a la Asamblea General Constituyente de 1828."],["Teniente General Donato Álvarez","avenida","Donato Álvarez (1825 a 1913), militar; combate en Caseros, en la guerra contra el Paraguay y durante las campañas al desierto."],["Tomás Álvarez de Acevedo","calle","Tomás Antonio Álvarez de Acevedo (1735 a 1802), jurisconsulto español; fiscal de la Audiencia de Charcas, cargo desde el cual dictamina sobre la necesidad de crear el Virreinato del Río de la Plata; regente de la Real Audiencia de Chile; consejero de Indias desde 1788."],["Álvarez Jonte","avenida","Antonio Álvarez Jonte (1784 a 1820), jurisconsulto; miembro del segundo Triunvirato; nombrado auditor del Ejército de los Andes, su muerte le impide ocupar este puesto."],["Manuel Álvarez Prado","calle","Manuel Álvarez Prado (1785 a 1836), coronel; combate en Puesto de Marqués y Sipe-Sipe; comandante del Primer Escuadrón de Gauchos de la Quebrada de Humahuaca desde 1818."],["Álvarez Thomas","avenida","Ignacio Álvarez Thomas (1787 a 1857), coronel mayor; Director Supremo Interino en 1815; convoca al Congreso de Tucumán."],["Alvear","avenida","Carlos Antonio José Gabino del Santo Ángel de la Guarda Alvear (1789 a 1852), brigadier general conocido como Carlos María de Alvear; Director Supremo en 1815; jefe del Ejército de Operaciones contra el Imperio del Brasil; vencedor en Ituzaingó."],["Emilio de Alvear","calle","Emilio de Alvear (1817 a 1885), jurisconsulto y funcionario; diputado al Congreso de Paraná de 1857 a 1861; ministro de Relaciones Exteriores del presidente Derqui; miembro de la Corporación Municipal de Buenos Aires en 1878; propicia y defiende la Ley N° 1.420 de Educación Común."],["Intendente Torcuato de Alvear","plaza","Torcuato de Alvear (1822 a 1890), hacendado y político; presidente de la Comisión Municipal de 1880 a 1883; primer Intendente Municipal, ocupa ese cargo desde el 10 de mayo de 1883 hasta el 10 de mayo de 1887."],["Marcelo T. de Alvear","calle","Marcelo Torcuato de Alvear (1868 a 1942), jurisconsulto y político; presidente de la República de 1922 a 1928."],["Álzaga","calle","Félix de Álzaga (1792 a 1841), general; ministro plenipotenciario en Chile, Perú y Colombia en 1822 con el objeto de gestionar adhesiones para la convención preliminar de Paz y Amistad entre las provincias Unidas del Río de la Plata y la Corte Española, celebrada el 4 de julio de 1823; director del Banco Nacional, era hijo de Martín. Martín de Álzaga (1755 a 1812).12."],["Martín de Álzaga","plaza","Martín de Álzaga (1755 a 1812), comerciante; héroe de la Reconquista y Defensa de Buenos Aires ante las Invasiones Inglesas; encabeza la revolución del 1° de enero de 1809; actúa durante la Revolución de Mayo; es fusilado por conspirar contra el Triunvirato el 6 de julio de 1812."],["José Amalfitani","plazoleta","José Amalfitani (1894 a 1969), dirigente deportivo; presidente del Club Atlético Vélez Sarsfield durante treinta años."],["Amalia","calle","Amalia: novela de José Mármol cuya primera parte fue publicada en Montevideo en 1851; fue terminada en 1855."],["Amambay","calle","Amambay: río y cordillera del Paraguay que atraviesa este país de norte a sur; cascada sobre el río Paraná descubierta el 5 de julio de 1870 por el coronel Lucio V. Mansilla. Amambay es una voz guaraní que significa helecho."],["Amancay","calle","Amancay: lirio silvestre de la región andina."],["Amberes","calle","Amberes: ciudad, provincia y puerto fluvial de Bélgica."],["Juan B. Ambrosetti","calle","Juan Bautista Ambrosetti (1865 a 1917), etnólogo y arqueólogo; fundador del Museo Etnográfico de la Facultad de Filosofía y Letras; autor de Materiales para el estudio del folklore misionero y Costumbres y supersticiones de los valles calchaquíes."],["Florentino Ameghino","parque","Florentino Ameghino (1854 a 1911), paleontólogo, antropólogo y naturalista, director del Museo de Historia Natural de La Plata; autor de La antigüedad del hombre en el Plata."],["Amenábar","calle","José de Amenábar (1784 a 1863), sacerdote; miembro de la Asamblea de 1813 y del Congreso de 1826; gobernador delegado de Santa Fe en varias oportunidades."],["De las Américas","paseo","América: homenaje al continente americano y a sus distintas naciones."],["De las Américas","plazoleta","América: homenaje al continente americano y a sus distintas naciones."],["De la Amistad","plazoleta","Amigos - Amistad: ambos espacios verdes rinden homenaje al afecto puro y desinteresado que nace entre las personas y se fortalece con el trato. AMPÈRE (calle). Ordenanza N° 1.424 del 30-12-1925. Andrés María Ampère (1775 a 1836), físico francés; creador de la ciencia de la electrodinámica."],["Amsterdam","calle","Amsterdam: ciudad capital de los Países Bajos, aunque no de la corte y del gobierno que residen en La Haya."],["Anasagasti","calle","Anasagasti: apellido de la familia que donó los terrenos por donde se abrió esta calle."],["Ancaste","calle","Sierra de Ancaste: rama austral del Aconquija y departamento de la provincia de Catamarca."],["Doctor Tomás Manuel de Anchorena","calle","Anchorena por Disposición del presidente de la Corporación Municipal, Torcuato de Alvear, del 6-3-1882 (Archivo Histórico Municipal, Legajo 3, 1882. Obras Públicas). Por Ordenanza N° 29.962-1974, BM N° 14.910, su nombre actual. Tomás Manuel de Anchorena (1783 a 1847), jurisconsulto; diputado por Buenos Aires en el Congreso de Tucumán; ministro de Gobierno y Relaciones Exteriores en el gobierno de don Juan Manuel de Rosas."],["Intendente Joaquín S. de Anchorena","plazoleta","Joaquín Samuel de Anchorena (1876 a 1961), jurisconsulto; intendente municipal de la Ciudad de Buenos Aires desde el 20 de octubre de 1910 hasta el 24 de octubre de 1914; interventor de Entre Ríos en 1916 y 1917; presidente de la Sociedad Rural Argentina de 1916 a 1922; presidente del Jockey Club de 1922 a 1924."],["Anchoris","calle","Ramón Eduardo de Anchoris (1775 a 1831), sacerdote y jurisconsulto; miembro de la Asamblea de 1813."],["Ancón","calle","Ancón: puerto del Perú a siete leguas de Lima, donde fondeó el general José de San Martín en su marcha hacia el norte, en octubre de 1820."],["Andalgalá","calle","Andalgalá: departamento de la provincia de Catamarca."],["Andalucía","calle","Andalucía: región del sur de España."],["Los Andes","calle","Cordillera de los Andes: cordillera que bordea América del Sur siguiendo su costa occidental desde el Mar de las Antillas hasta el Cabo de Hornos, donde se sumerge en paso Drake para reaparecer en el continente antártico."],["Los Andes","parque","Cordillera de los Andes: cordillera que bordea América del Sur siguiendo su costa occidental desde el Mar de las Antillas hasta el Cabo de Hornos, donde se sumerge en paso Drake para reaparecer en el continente antártico."],["Andonaegui","calle","José de Andonaegui (1685 a 1761), militar español; gobernador del Río de la Plata desde 1745 hasta 1756."],["Andorra","calle","Andorra: principado europeo independiente. Capital: Andorra La Vella."],["Olegario V. Andrade","calle","Olegario Víctor Andrade (1839 a 1882), poeta; autor de El nido de cóndores, Prometeo, El arca perdida y Paysandú."],["Monseñor Miguel de Andrea","plaza","Miguel de Andrea (1877 a 1960) sacerdote y doctor en Teología y Leyes; párroco de San Miguel Arcángel en 1912; director de los Círculos de Obreros; obispo de Tennos en 1920; fundador del Hogar de la Empleada; autor de El Evangelio y la actualidad y El catolicismo social y su aplicación."],["Angaco","calle","Angaco: combate librado en la provincia de San Juan entre las fuerzas unitarias y las federales mandadas por Acha y Aldao, respectivamente, con la intervención de Nazario Benavídez, el 16 de agosto de 1841. ÁNGEL, LA CASA DEL véase CASA DEL ÁNGEL, LA."],["Obispo Enrique Angelelli","plazoleta","Enrique Ángel Angelelli (1923 a 1976), sacerdote; obispo de Listra y de La Rioja; ejemplo de pastor y hombre comprometido con su gente; murió en un confuso accidente."],["Ankara","calle","Ankara: ciudad capital de Turquía y de la provincia de su nombre."],["Antártida Argentina","avenida","Antártida Argentina: región del continente antártico limitada por el paralelo de 60 grados de latitud, el polo austral y los meridianos de 25 grados y 74 grados longitud oeste, donde la Argentina ejerce su soberanía desde principios de siglo."],["Pioneros de la Antártida Argentina","plaza","Pioneros de la Antártida Argentina: homenaje a los primeros expedicionarios argentinos que por primera vez izaron la Bandera Argentina en las Islas Orcadas del Sur el 22 de febrero de 1904."],["Antequera","calle","José de Antequera y Castro (1690 a 1731), funcionario; fiscal de la Audiencia de Charcas; gobernador del Paraguay, fundador del partido de los Comuneros del Paraguay, es enjuiciado por su actuación y decapitado el 5 de julio de 1731."],["Antezana","calle","Mariano Antezana (1771 a 1812), funcionario; mártir de la Independencia, es fusilado por los realistas en Cochabamba junto con Bartolomé Pizarro."],["Antofagasta","calle","Antofagasta de la Sierra: departamento de la provincia de Catamarca."],["Añasco","calle","José Ignacio Añasco (?-1814), capitán paraguayo; contribuye en 1811 al triunfo de la revolución de la independencia en Asunción; comanda en 1812 los auxilios que se destacan para cubrir los pasos de Capitá-Miní, Caaguazú y Santillán en la provincia de Corrientes ante la amenaza de invasión portuguesa."],["Apulé","calle","Apulé: combate librado en Neuquén el 22 de febrero de 1883, durante la campaña del desierto, entre las fuerzas del capitán Adolfo Drury y el cacique Sayhueque."],["Aquino","calle","Pedro León Aquino y Gainza (1812 a 1852), coronel; combate en La Tablada, Oncativo y en la Legión del General Lavalle. Muerto este último, es uno de los que lleva sus restos hasta Potosí."],["De la Ciencia y la Cultura Árabes","paseo","De la Ciencia y la Cultura Árabes: homenaje a los representantes intelectuales, artísticos, científicos y culturales árabes."],["Teniente General Pedro Eugenio Aramburu","plaza","Pedro Eugenio Aramburu (1903 a 1970), militar y político; presidente de la República de 1955 a 1958."],["Teniente General Adolfo A. Arana","plazoleta","Adolfo Anastasio Arana (1857 a 1926), militar; combate en las campañas al Río Negro y en Corrales durante la revolución de 1880."],["Doctor Juan Felipe Aranguren","calle","Juan Felipe Aranguren (1870 a 1951), médico; director del Hospital Teodoro Álvarez de 1901 a 1911."],["Aráoz","calle","Obras Públicas). Pedro José Miguel Aráoz (1759 a 1832), sacerdote; diputado por Tucumán en el Congreso de 1816; fundador de El Tucumano Imparcial, que fue el primer periódico aparecido en esa ciudad."],["Doctor Gregorio Aráoz Alfaro","calle","Gregorio Aráoz Alfaro (1870 a 1955), médico; presidente de la Academia Nacional de Medicina; dirige durante veinte años las campañas antituberculosas en el país."],["General Gregorio Aráoz de Lamadrid","calle","Gregorio Aráoz de Lamadrid (1795 a 1857), militar; combate en Las Piedras, Tucumán, Salta, La Tablada, Oncativo y Caseros; gobernador de Tucumán de 1825 a 1826."],["Héctor Félix Arata","cantero central","Héctor Félix Arata (1907 a 1993) historiador; miembro fundador de la Asociación de Fomento de Villa Urquiza y de otras instituciones del barrio; autor de Villa Urquiza. Sus primeros cien años."],["Pedro N. Arata","calle","Pedro Narciso Arata (1849 a 1922), médico; fundador de la Sociedad Científica Argentina y del Instituto Superior de Agronomía y Veterinaria, que al pasar a la Universidad en 1909 se transforma en facultad, siendo Arata su primer decano; presidente del Consejo Nacional de Educación; fundador de la Oficina Química Municipal en 1883."],["El Araucano","calle","Araucano: aborigen natural de Arauco (Chile) que en el momento de la conquista española habitaba el territorio comprendido entre los ríos Itala y Tolten. Llamábanse asimismo mapuches (gente del país) y ocupan posteriormente el territorio sur argentino."],["Araujo","calle","José Joaquín Araujo (1762 a 1835), publicista; autor de la Guía de Forasteros del Virreinato de Buenos Aires en 1803, colaborador del Telégrafo Mercantil."],["Aníbal Pedro Arbeletche","calle","Aníbal Pedro Arbeletche (1900 a 1954), agrimensor; diputado nacional por la Unión Cívica Radical de 1936 a 1943."],["María Teresa Arbeletche","plazoleta","María Teresa Arbeletche (1898 a 1969), política; militó en la Unión Cívica Radical en el barrio de Nueva Pompeya; era hermana de Aníbal Pedro."],["Del Árbol","plazoleta","Árbol: homenaje al árbol como símbolo del cuidado del medio ambiente. Esta plazoleta se crea por la iniciativa de los vecinos que constituyen una comisión con el fin de mejorar el deterioro de esta esquina (Agüero y Charcas) luego de la demolición del edificio que albergaba al Departamento de Pesas y Medidas de la Municipalidad. La comuna convalidó esta denominación y contribuyó a la parquización del lugar. Iniciativas como ésta han proliferado en toda la ciudad, donde los vecinos se asocian para crear o mejorar lugares transformándolos en espacios verdes y/o de recreación."],["Arcamendia","calle","Domingo de Arcamendia (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Arce","calle","Esteban Arce (?-1815), coronel; vencedor en Aroma y Chayanta; presidente provisorio de la Junta Provincial de Cochabamba en 1811."],["Manuel Arce","calle","Manuel Arce (?-1807), capitán; muere durante la Defensa de Buenos Aires ante las Invasiones Inglesas. Es éste un nombre tradicional de Buenos Aires pues entre 1808 y 1822 se denominó “Arce” la actual 25 de Mayo."],["Arcos","calle","Antonio Arcos (¿1790?-¿1861 o 1864?), ingeniero; se desempeñó en el Ejército de los Andes combatiendo en Chacabuco y Maipú; director de la Academia Militar de Chile."],["Concepción Arenal","calle","Concepción Arenal Ponte (1820 a 1893), escritora y socióloga española; autora de Cartas a un obrero y El visitador del pobre."],["Arenales","calle","Juan Antonio Álvarez de Arenales (1770 a 1831), general; vencedor de La Florida, Ica, Nazca y Pasco; gobernador de Salta de 1824 a 1827."],["Arenales","plaza","Juan Antonio Álvarez de Arenales (1770 a 1831), general; vencedor de La Florida, Ica, Nazca y Pasco; gobernador de Salta de 1824 a 1827."],["Arengreen","calle","Juan Arengreen (1791 a 1831), militar sueco radicado en nuestro país donde alcanza el grado de coronel; combate en la guerra contra el Brasil, en San Roque, Oncativo, La Tablada y Ciudadela, donde pierde la vida."],["Arévalo","calle","Domingo Soriano de Arévalo (1783 a 1834), coronel; combate en Salta, Tucumán, Vilcapugio y Ayohuma; gobernador de Tarija de 1815 a 1816."],["Argañarás","calle","Francisco de Argañarás y Murguía (¿-?), conquistador español; fundador de San Salvador de Jujuy en 1593."],["Argelia","calle","Argelia: país africano. Capital: Argel."],["Argentina","avenida","Argentina: nombre de nuestro país. Capital: Buenos Aires. ARGENTINAS, MUJERES véase MUJERES ARGENTINAS."],["Argerich","calle","Cosme Mariano Argerich (1758 a 1820), médico; primer examinador del Protomedicato en 1794; médico jefe del Hospital de la Caridad durante las Invasiones Inglesas; autor del Plan de Estudios para la Facultad Médica y Quirúrgica aprobado por la Asamblea de 1813 y a sugerencia del cual se crea el Instituto Médico Militar bajo su asesoramiento. Francisco Cosme Argerich (1787 a 1846), médico; hijo del anterior; actúa durante las Invasiones Inglesas; atiende en San Lorenzo en 1813 a los heridos del combate; médico cirujano del Ejército del Alto Perú; cirujano mayor del Ejército durante la guerra contra el Brasil. Luis Argerich (1791 a 1839), teniente coronel; hermano del anterior; combate durante la guerra contra el Brasil; director del Parque de Artillería de Buenos Aires; diputado a la Legislatura de 1834 a 1838."],["Andrés Arguibel","calle","Andrés Arguibel (1773 a 1826), militar; propala noticias falsas y consigue detener, en 1811 y 1812, las expediciones de reconquista que vendrían a América; descubierto el complot por España, es apresado y, aunque logra escapar, se le confiscan sus bienes viviendo desde entonces en la mayor pobreza."],["Arias","calle","Manuel Eduardo Arias (?-1822), coronel; guerrero de la Independencia, lucha junto a Güemes; comandante del Primer Escuadrón de Gauchos de Orán, Santa Victoria, San Andrés y La Puna, en 1820."],["Ariel","calle","Ariel: obra literaria del escritor uruguayo José Enrique Rodó."],["Arismendi","calle","Juan Bautista Arismendi (1775 a 1841), general venezolano; participa, en 1812, en la expedición enviada por Miranda para conquistar la Guayana; gobernador interino de Caracas; vicepresidente de la República, en 1819, por renuncia de Zea; nuevamente gobernador interino de Caracas en 1835."],["Arizona","calle","Arizona: localidad del departamento Pedernera, en la provincia de San Luis."],["Arjonilla","calle","Arjonilla: victoria del ejército español donde actuaba el general San Martín, contra los franceses en 1808. Por su acción se lo asciende al grado de capitán del regimiento Borbón."],["Roberto Arlt","plaza","Roberto Arlt (1900 a 1942), escritor y periodista; autor de Los siete locos, Los lanzallamas, Aguafuertes porteñas, El juguete rabioso, El jorobadito, Amor brujo, Saverio el cruel y La isla desierta; redactor de Crítica y El Mundo."],["Armenia","calle","Armenia: república asiática. Capital: Ereván."],["Armenia","plazoleta","Armenia: república asiática. Capital: Ereván."],["Eduardo Arolas","calle","Eduardo Arolas (1892 a 1924), compositor; conocido como El tigre del bandoneón, es el autor de Una noche de garufa, El Marne y Derecho viejo."],["Eduardo Arolas","cantero central","Eduardo Arolas (1892 a 1924), compositor; conocido como El tigre del bandoneón, es el autor de Una noche de garufa, El Marne y Derecho viejo."],["Aroma","calle","Aroma: combate librado en el llano de Arohuma (Bolivia) el 14 de noviembre de 1810, por las fuerzas patriotas al mando de Esteban Arce y Bartolomé Guzmán."],["Aromo","calle","Aromo: árbol de la familia de las leguminosas, especie Acacias farnesiana, de flores amarillas y olorosas."],["Arquímedes","calle","Arquímedes (287-212 a.C.), sabio griego de Siracusa; inventor de numerosos mecanismos y máquinas."],["Virrey Arredondo","calle","Nicolás Antonio de Arredondo (1726 a 1802), militar español; virrey del Río de la Plata de 1789 a 1795."],["Arregui","calle","Gabriel de Arregui (1655 a 1724), sacerdote; obispo de Buenos Aires de 1712 a 1717. Juan de Arregui (1652 a 1736), sacerdote, hermano del anterior; obispo de Buenos Aires de 1731 a 1736; gobernador del Paraguay en 1733. Homenaje conjunto a los hermanos Arregui."],["Arribeños","calle","Arribeños: regimiento de infantería creado durante las Invasiones Inglesas y formado por oriundos de las provincias del norte o de “arriba”. Arribeño significaba ser procedente de las tierras altas."],["Arriola","calle","José Nicolás Arriola (1793 a 1835), teniente coronel; combate en Chacabuco, Maipú, Ayacucho y durante la guerra contra el Brasil."],["Arrotea","calle","Manuel de Arrotea (1793 a 1861), político; regidor y alcalde del Cabildo; miembro de la Sociedad Filantrópica y del Tribunal del Consulado; representante de la Legislatura de Buenos Aires desde 1836 hasta 1852."],["Arroyo","calle","Manuel Andrés Arroyo y Pinedo (1778 a 1839), funcionario; presidente del Banco Nacional en 1826; presidente del Congreso Constituyente en ese mismo año; poseía una casaquinta en la actual Cerrito y la calle que lleva su nombre."],["Amigos de las Artes","espacio público","Amigos de las Artes: nombre con el que se identifica a un grupo de artistas plásticos que realizan, en este preciso lugar del barrio de Villa Luro, diversas actividades culturales."],["De las Artes","calle","De las Artes: nombre tradicional que entre 1822 y 1907 poseyó la actual Carlos Pellegrini, debido a que en la misma había numerosos talleres artesanales, fundamentalmente de platería."],["De las Artes Latinoamericanas","paseo","De las Artes Latinoamericanas: homenaje a los artistas y escritores latinoamericanos."],["El Artesano","calle","Artesano: recuerda a la persona que ejerce un oficio o arte casi mecánico."],["General José Gervasio Artigas","calle","José Gervasio Artigas (1764 a 1850), general uruguayo; prócer de la Independencia Americana y héroe máximo de la nación hermana."],["Manuel Artigas","calle","Manuel Antonio Artigas (1774 a 1811), comandante; combate en la expedición al Paraguay junto a Belgrano; en Uruguay comanda el ataque a San José donde es herido de muerte. Su nombre se halla inscripto en la Pirámide de Mayo."],["Artilleros","calle","Artilleros: regimiento creado durante las Invasiones Inglesas en 1806."],["De los Artistas","paseo","De los Artistas: se denomina así ya que en este sector del parque Juan Bautista Alberdi se realizan actividades vecinales de interés artístico y cultural."],["Ascasubi","calle","Hilario Ascasubi (1807 a 1875), militar y poeta; autor de Santos Vega o los mellizos de la Flor."],["Asia","calle","Asia: una de las cinco partes del mundo. Junto con Europa forma el continente euroasiático."],["Asturias","calle","Asturias: región del norte de España. Capital: Oviedo."],["Asunción","calle","Asunción: ciudad capital del Paraguay."],["De la Asunción","plaza","Asunción de la Virgen: solemnidad de la Iglesia católica que conmemora la elevación de la Santísima Virgen a los cielos. Este misterio se celebra el 15 de agosto por disposición del emperador Mauricio (539 a 602)."],["Atacalco","calle","Atacalco: paso de la cordillera de los Andes en el departamento Minas, provincia de Neuquén."],["Atahualpa","calle","Atahualpa (1502 a 1533), inca peruano, hijo de Huaina Cápac; disputa el trono a su hermano Huáscar, lo que motiva el estallido de la guerra civil (1530). En el año 1532 llega Pizarro y aprovechando la situación hace prisionero a Atahualpa, exigiendo un recate. A pesar de ser pagado, el inca es condenado a muerte y ahorcado en la misma prisión."],["Atenas","calle","Atenas: ciudad capital de Grecia."],["Mecánico Militar Leopoldo Atenzo","calle","Leopoldo Atenzo (1896 a 1930), mecánico militar; falleció en un accidente de aviación durante la revolución del 6 de septiembre de 1930."],["Atuel","calle","Atuel: río de Mendoza que nace en el cerro Choique y desagua en los bañados de su mismo nombre en la provincia de La Pampa."],["Doctor Teodoro Aubain","calle","Teodoro Aubain (1815 a 1896), médico; se desempeña como tal en la parroquia del Pilar en 1857; actúa durante la epidemia de fiebre amarilla en 1871 presidiendo la Comisión de Higiene de su parroquia; fue el primer médico del pueblo de Belgrano y tenía su consultorio en 25 de Mayo 100 (hoy Cabildo 2064, altos)."],["Australia","calle","Australia: país de Oceanía. Capital: Camberra."],["Austria","calle","Austria: país europeo. Capital: Viena."],["Glorias del Automovilismo Argentino","plaza","Glorias del Automovilismo Argentino: homenaje a los cultores de este deporte que tuvo su inicio en la Argentina a comienzos del siglo XX. El primer Gran Premio se corre en 1910."],["Avalle","calle","Antonio Avalle (?-1901), propietario de una quinta cuyos fondos coincidían con el trazado de esta calle y que dona los terrenos para la apertura de la misma; era de origen español y se dedicaba a la compra de ganado en los Corrales Viejos. Por Resolución del 30-6-1899 la Municipalidad le compra terrenos para la apertura de la avenida Sáenz."],["Ávalos","calle","José Domingo Ávalos (?-1853), general; combate en Don Cristóbal, Sauce Grande, Quebracho Herrado y Caseros."],["Avellaneda","avenida","Marco Manuel de Avellaneda (1813 a 1841), jurisconsulto; promotor de la Asociación de Mayo en el interior y miembro de la filial tucumana; gobernador de Tucumán en 1841, asiste a la batalla de Famaillá donde es tomado prisionero y poco después condenado a muerte."],["Parque Avellaneda","barrio","Se conoce a este barrio con esta denominación desde 1914, cuando se bautiza así al parque que en él se encuentra."],["Presidente Nicolás Avellaneda","parque","Nicolás Avellaneda (1836 a 1885), jurisconsulto; presidente de la República de 1874 a 1880."],["Virrey Avilés","calle","Gabriel de Avilés y Fierro (1735 a 1810), militar y funcionario; virrey del Río de la Plata de 1799 a 1801."],["Delia Avilés de Elizalde","espacio verde","Delia Norberta Avilés de Elizalde (1918 a 1977), enfermera; debido a la detención de su hijo Alberto en 1973, participa en la Comisión de Familiares de Presos Políticos, Estudiantiles y Gremiales; trabaja y se compromete cada vez más con esta lucha, hasta que es secuestrada en enero de 1977. Permanece desaparecida."],["Aviso A.r.a. Alférez Sobral","plazoleta","Aviso ARA Alférez Sobral: nombre de la nave que participa del conflicto bélico del Atlántico Sur en 1982 y que al socorrer al buque ARA Gral. Belgrano, es agredida por dos misiles británicos que la averían y causan varias víctimas, entre ellas su comandante."],["Ayacucho","calle","Ayacucho: batalla en la que el general Antonio José de Sucre derrota a las fuerzas del Virrey del Perú, general José de la Serna, el 9 de diciembre de 1824, y que pone fin a la guerra de la Independencia Americana."],["Ayolas","calle","Juan de Ayolas (1493 a 1538), conquistador español; continuador de la empresa de don Pedro de Mendoza; funda Corpus Christi y Candelaria."],["Ayuí","calle","Ayuí: palabra guaraní que denomina al laurel en la zona del Chaco y Corrientes."],["Azara","calle","Félix de Azara (1746 a 1821), marino y naturalista español; en 1780 demarca los límites de las posesiones americanas de España y Portugal; autor de Descripción e Historia del Paraguay y del Río de la Plata y Viajes por la América Meridional desde 1781 hasta 1801."],["Azcuénaga","calle","Miguel de Azcuénaga (1754 a 1833), brigadier general; vocal de la Primera Junta de Gobierno; gobernador intendente de Buenos Aires en 1812."],["Domingo de Azcuénaga","calle","Domingo de Azcuénaga (1758 a 1821), jurisconsulto y poeta; fundador de la Sociedad Literaria del Plata."],["Azopardo","calle","Juan Bautista Azopardo (1772 a 1848), coronel de marina de origen maltés; combate durante las Invasiones Inglesas y la guerra contra el Brasil; comandante de la flotilla integrada por la goleta Invencible, el bergantín 25 de Mayo y la balandra Americana en 1811; derrotado en el combate de San Nicolás, es tomado prisionero."],["Azul","calle","Azul: ciudad y partido de la provincia de Buenos Aires."],["Juana Azurduy","calle","Juana Azurduy de Padilla (1780 a 1862), heroína de la guerra de la Independencia que combate en las guerrillas del Alto Perú. Notas."],["Bacacay","calle","Bacacay: triunfo logrado durante la guerra contra el Brasil por las fuerzas del entonces coronel Juan Lavalle sobre las imperiales del coronel Bentos Manuel, el 13 de febrero de 1827."],["Juan Sebastián Bach","calle","Juan Sebastián Bach (1685 a 1750), músico alemán; autor de Conciertos de Brandeburgo."],["César H. Bacle","calle","César Hipólito Bacle (1794 a 1838), litógrafo ginebrino; autor de la colección Trajes y Costumbres y de los planos topográficos de Buenos Aires de 1830 y 1836."],["Bacon","calle","Francis Bacon (1561 a 1626), filósofo inglés; autor de Novum Organum y Nova Atlantis; es uno de los fundadores del método experimental. Rogelio Bacon (1214 a 1294), filósofo inglés; autor de Opus Majus, Opus Minus y Opus tertium."],["Báez","calle","Manuel José Báez (¿-?), jurisconsulto paraguayo; jefe de los unitarios en el Congreso paraguayo del 17 de junio de 1811, propaga las ideas revolucionarias; miembro de la junta vinculada al Consulado de Buenos Aires."],["Bahía","calle","Bahía: Estado del Brasil. Capital: Salvador."],["Bahía Blanca","calle","Bahía Blanca: ciudad y partido de la provincia de Buenos Aires."],["Baigorri","calle","Pedro Baigorri Ruiz (?-¿1670?), militar y funcionario español; gobernador del Río de la Plata desde 1653 hasta 1660."],["Baigorria","calle","Juan Bautista Baigorria (¿-?), granadero que salva la vida del general San Martín en el combate de San Lorenzo."],["Balandra Carmen","calle","Balandra Carmen: balandra comprada en 1814 al armarse la escuadra para combatir contra las fuerzas realistas de Montevideo. Participa en el combate de Martín García y en Arroyo de la China al mando de Samuel Spiro, quien para evitar que cayese en manos enemigas la hace volar, muriendo a bordo de la misma."],["Balbastro","calle","Matías Balbastro (1773 a 1848), coronel; combate durante las Invasiones Inglesas y en Suipacha."],["Ricardo N° 19.211. Balbín","cantero central","Ricardo Balbín (1904 a 1981), político; diputado nacional de 1946 a 1949; candidato presidencial en 1952, 1958, 1973; presidente de la Unión Cívica Radical."],["Balboa","calle","Vasco Núñez de Balboa (1475 a 1517), navegante y conquistador español; descubridor del Océano Pacífico en 1513."],["Balcarce","calle","Antonio González Balcarce (1775 a 1820), general; vencedor en Suipacha; gobernador intendente de Buenos Aires en 1814; Director Supremo en 1816, sustituye a San Martín, que se encontraba enfermo, como jefe del Ejército de los Andes; combate en Cancha Rayada y Maipú."],["Balcarce","plaza","Antonio González Balcarce (1775 a 1820), general; vencedor en Suipacha; gobernador intendente de Buenos Aires en 1814; Director Supremo en 1816, sustituye a San Martín, que se encontraba enfermo, como jefe del Ejército de los Andes; combate en Cancha Rayada y Maipú."],["Florencio Balcarce","calle","Florencio González Balcarce (1818 a 1839), poeta; autor de La partida, Endechas a la memoria del Coronel Dorrego y La Canción a las Hijas del Plata."],["Coronel Juan Amadeo de Baldrich","avenida","Juan Amadeo de Baldrich (1859 a 1917), militar; participa en la expedición a Formosa bajo las órdenes del coronel Solá; edecán del presidente Dr. Manuel Quintana; autor de Historia de la Guerra del Brasil. Contribución al estudio razonado de la historia militar argentina."],["Doctor Pedro Luis Baliña","calle","Pedro Luis Baliña (1880 a 1949), médico; miembro fundador de la Asociación Argentina de Dermatología; propulsor de las campañas de lucha contra la lepra, promueve junto al doctor Aberastury la sanción de la Ley N° 11.359 destinada a combatir ese mal; promotor del sanatorio Sommer de General Rodríguez."],["Esther Ballestrino de Careaga","espacio público","Esther Ballestrino de Careaga (1918 a 1977), bioquímica y farmacéutica paraguaya; radicada en la Argentina desde 1947, es una de las fundadoras de Madres de Plaza de Mayo y participa desde el inicio en las rondas. El 8 de diciembre de 1977 es secuestrada en el operativo realizado en la Iglesia de la Santa Cruz. Sus restos fueron finalmente identificados por el Equipo Argentino de Antropología Forense, luego de haber sido encontrados en el cementerio de General Lavalle, cuando se exhuman siete cuerpos enterrados como NN que habían sido encontrados en las costas de San Bernardo y Santa Teresita entre diciembre de 1977 y enero de 1978. A través de análisis de ADN pudo confirmarse que tres de esos cadáveres eran los de Esther Ballestrino de Careaga, María Ponce de Bianco y Azucena Villaflor de De Vincenti."],["Paseo del Ballet Argentino","cantero central","Ballet Argentino: homenaje a los Bailarines del Teatro Colón, desaparecidos en el trágico accidente de avión del 10 de octubre de 1971."],["Ballivián","calle","José Ballivián (1805 a 1852), general boliviano; presidente de Bolivia de 1841 a 1847."],["José R. Baltoré","calle","José Romualdo Baltoré (1832 a 1891), jurisconsulto; senador nacional por Entre Ríos; presidente de la Cámara Legislativa de esa provincia; catedrático de Derecho Internacional y Canónico; fundador de los periódicos La voz del pueblo y La Democracia, propicia y defiende la Ley N° 1.420 de Educación Común."],["Balvanera","barrio","Nuestra Señora de Valvanera: imagen de la Virgen descubierta por Nuño Oñez en el siglo IX, en el tronco de un roble, rodeada de enjambres de abejas. En el lugar, La Rioja, provincia de Logroño, España, se levantó una capilla que se convirtió luego en el monasterio de su nombre. El origen de esta denominación en Buenos Aires, donde la costumbre y el uso de nuestro país modificó su ortografía, se remonta a la primera década del siglo XIX, cuando se erige la capilla dedicada a Nuestra Señora de Valvanera, comenzándose a identificar el lugar con este nombre a partir de la erección de la parroquia de Balvanera en 1833."],["Enrique Banchs","calle","Enrique Banchs (1888 a 1968), poeta; autor de La Urna, Las Barcas y El libro de los elogios; presidente de la SADE de 1938 a 1940."],["Enrique Banchs","plazoleta","Enrique Banchs (1888 a 1968), poeta; autor de La Urna, Las Barcas y El libro de los elogios; presidente de la SADE de 1938 a 1940."],["De la Bandera","plaza","Bandera: homenaje a la Bandera Nacional, creada por el general Manuel Belgrano e izada por primera vez en las Barrancas de Rosario el 27 de febrero de 1812."],["Escuela la Banderita","plazoleta","Escuela “La Banderita”: homenaje a la Escuela N° 16, DE 5, Sabina Bove de Bozza, ubicada hoy en Amancio Alcorta 3402, que comienza a funcionar en mayo de 1909 en el pasaje Servet, y desde esa época es reconocida con el nombre La Banderita, porque la bandera izada en su mástil se divisaba desde los cuatro puntos cardinales."],["Ciudad de Banff","plaza","Banff: ciudad de Escocia que el 19 de agosto de 1824 designó al general José de San Martín ciudadano libre y cófrade del guild de dicho burgo, cuando el Libertador visitó la misma invitado por Lord Fife."],["Del Bañado","calle","Combate del Bañado: combate librado entre el 20 y el 23 de abril de 1817, entre los gauchos a las órdenes del comandante Luis Burela y Saavedra y las fuerzas del coronel español Vicente Sardina."],["Baradero","calle","Baradero: ciudad y partido de la provincia de Buenos Aires."],["Baragaña","calle","Diego Álvarez Baragaña (?-1807), patriota; combate durante las Invasiones Inglesas, y muere como consecuencia de las heridas recibidas en la defensa de la ciudad. Es este un nombre tradicional de Buenos Aires, pues entre 1808 y 1822 se denominó así la actual avenida San Juan."],["Guillermoy Alfredo Barbieri","espacio verde","Guillermo Desiderio Barbieri (1894 a 1935), músico, guitarrista de Carlos Gardel, muere en el accidente de avión de Medellín; compositor de Anclao en París, Viejo smoking y Barrio viejo. Alfredo Barbieri (1923 a 1985), actor de teatro, cine y televisión; se destaca como humorista; integra un recordado dúo con Don Pelele. Como se desprende de sus denominaciones, el cantero central rinde homenaje solamente a Guillermo, en tanto el espacio verde rinde homenaje conjunto a padre e hijo."],["Barca Cabo de Hornos","calle","Barca Cabo de Hornos: nave comprada en 1878 con motivo de la situación producida por la ocupación de Santa Cruz por la cañonera chilena Magallanes. Fue comandada por el comodoro Luis Py."],["Barcala","calle","Lorenzo Barcala (1795 a 1835), coronel; esclavo liberto desde 1813, combate en la guerra contra el Brasil, La Tablada y Oncativo; hecho prisionero en la Ciudadela acepta ser asistente de Facundo Quiroga; participa en la campaña al desierto en 1835."],["Barcelona","calle","Barcelona: ciudad y provincia de España."],["Del Barco Centenera","calle","Martín del Barco Centenera (¿1535?-1605), sacerdote y escritor; autor del poema Argentina y conquista del Río de la Plata, con otros acaecimientos de los reinos del Perú, Tucumán y estado del Brasil, publicado en Lisboa en 1602, y en el que se emplea por primera vez el nombre de “Argentina” para designar a este territorio."],["Agustín Bardi","plazoleta","Agustín Bardi (1884 a 1941), pianista; compositor de Gallo ciego, Qué noche, Tinta verde, Tierrita."],["Almirante Atilio Sixto Barilari","calle","Atilio Sixto Barilari (1857 a 1928), marino; actúa en 1878 sosteniendo los derechos argentinos en el conflicto con Chile; jefe del Estado Mayor General de la Armada en 1898."],["Bariloche","calle","Bariloche: ciudad y departamento de la provincia de Río Negro."],["Emma de la Barra","calle","Emma de la Barra de Llanos (1861 a 1947), escritora, conocida por el seudónimo de César Duayen; autora de Stella, Micha Iturbe y El manantial."],["Barracas","barrio","Barracas: denominación usual con la que se identifica a esta zona de la ciudad desde el siglo XVII, cuando comenzaron a instalarse en el lugar las rudimentarias construcciones llamadas barracas, que almacenaban cueros y otros productos que entraban o salían de la ciudad."],["Barragán","calle","Ensenada de Barragán: antiguo partido de la provincia de Buenos Aires y ensenada del Río de la Plata."],["Barrancas de Belgrano","plaza","Barrancas de Belgrano: alude a las barrancas visibles en la conformación de esta plaza ubicada en el barrio de Belgrano. Las barrancas son un accidente geográfico propio de la topografía madura de una red fluvial en que la erosión del agua ha hecho que los terrenos se inclinen hacia las corrientes, en este caso las del Río de la Plata. Similares barrancas se observan en plaza San Martín, en la zona céntrica y en parque Lezama."],["Barrientos","calle","Cristóbal Barrientos (¿-?), piloto-agrimensor; autor del plano de Buenos Aires de 1772 que abarca los sectores de Retiro y Recoleta."],["José Barros Pazos","calle","José Barros Pazos (1808 a 1877), jurisconsulto; rector de la Universidad de Buenos Aires de 1852 a 1857; presidente de la Suprema Corte de Justicia."],["Barzana","calle","Alonso de Barzana (1528 a 1598), sacerdote y misionero jesuita que actúa en el Tucumán y Paraguay, dedicándose a la conversión de los aborígenes."],["Basavilbaso","calle","Capital de la República Argentina, levantado por el Departamento Topográfico de la Municipalidad, año 1895. Domingo de Basavilbaso (1709 a 1775), funcionario; alcalde de primer voto; fundador y primer administrador de Correos de Buenos Aires en 1748."],["Leopoldo Basavilbaso","calle","Leopoldo Basavilbaso (1843 a 1908), jurisconsulto; decano de la Facultad de Derecho en 1881; rector de la Universidad de Buenos Aires y desde 1886 interventor nacional en Corrientes; diputado nacional por la Unión Cívica Radical en 1894. BASE MARAMBIO véase MARAMBIO, BASE."],["Las Bases","calle","Bases y puntos de partida para la organización política de la República Argentina: libro de Juan Bautista Alberdi aparecido en 1852."],["Región Basilicata","cantero central","Región Basilicata: región del sur de Italia que comprende las provincias de Matera y Potenza."],["Micaela Bastidas","parque","Micaela Bastidas (¿1742-1744?-1781) heroína peruana; es la esposa y la principal lugarteniente del Inca Túpac-Amaru con quien inicia la insurrección indígena; pierde la vida luego de ser cruelmente torturada."],["Basualdo","calle","Juan de Basualdo (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["J. F. Bateman","calle","Juan Federico La Trobe Bateman (1810 a 1889), ingeniero inglés; es contratado en 1870 para la construcción del puerto de Buenos Aires, obra para la cual presenta un plan; realiza también un plano para la provisión de agua corriente, desagües y adoquinado de la ciudad."],["Bathurst","calle","Guillermo Bathurst (1796 a 1844), marino; actúa en la guerra contra el Brasil y en la campaña al desierto en 1833."],["José Pablo Torcuato Batlle y Ordóñez","calle","José Pablo Torcuato Batlle y Ordóñez (1856 a 1929), político uruguayo; presidente de la República Oriental del Uruguay de 1903 a 1907 y de 1911 a 1915."],["Bauness","calle","Carlos Bauness (1797 a 1855), teniente coronel; combate en Chacabuco y Maipú; marcha en la Expedición al Perú."],["Francisco Bauzá","calle","Francisco Bauzá (1851 a 1899), estadista uruguayo; redactor de Los Debates; ministro de Gobierno del presidente Julio Herrera y Obes; autor de Historia de la Dominación Española en el Uruguay."],["Ernesto A. Bavio","calle","Ernesto A. Bavio (1860 a 1916), educador; autor de Curso de Geografía general; secretario general del Consejo de Enseñanza Secundaria y Normal; inspector general de Provincias y secretario general de Enseñanza Normal."],["Bazurco","calle","José Antonio Bazurco y Herrera (?-1761), sacerdote; Obispo de Buenos Aires de 1760 a 1761."],["Beade","calle","Fernando Beade (¿1842?-1916), comerciante; creador, junto con el doctor Eduardo Costa, de la Empresa y Puerto de Campana, participa en la fundación de esa ciudad; dona los terrenos donde se encuentra esta calle. Cabe señalar que Enrique Udaondo y Adrián Béccar Varela, en la obra Plazas y calles de Buenos Aires, significación histórica de sus nombres, Buenos Aires, 1910, mencionan como dueño de esas tierras al escribano Fernando Beade (1882 a 1955), quien fue en realidad hijo del originario dueño y donante de las mismas."],["Beauchef","calle","Jorge Beauchef (1787 a 1840), coronel de marina de origen francés; asiste al asalto de Talcahuano; combate en Bío-Bío; realiza las campañas del Perú en 1823 y las de Chiloé en 1824 y 1826."],["Beazley","calle","Roberto Guillermo Beazley (¿-?), marino de origen estadounidense; combate durante la guerra contra el Brasil como comandante del bergantín República Argentina y de la goleta corsario General Mansilla."],["Emilio Becher","calle","Emilio Becher (1882 a 1921), periodista del diario La Nación, donde escribe con el seudónimo de Stylo; autor de Diálogos de las sombras."],["Elías Bedoya","calle","Elías Estanislao de Bedoya (1798 a 1870), jurisconsulto; diputado por Córdoba en el Congreso de 1824; fundador del periódico El Argentino, de Córdoba; ministro de Hacienda de la Confederación de 1857 a 1859."],["Beethoven","calle","Ludwig van Beethoven (1770 a 1827), músico alemán; autor de las célebres nueve sinfonías."],["Behring","calle","Emilio Adolfo von Behring (1854 a 1917), médico alemán; uno de los fundadores de la inmunología moderna; descubridor de los sueros antitetánico y antidiftérico; Premio Nobel de Medicina y Fisiología en 1901."],["Francisco Beiró","avenida","Francisco Beiró (1876 a 1928), jurisconsulto; presidente del Comité de la Capital de la Unión Cívica Radical; presidente de la Comisión Municipal de la ciudad de Buenos Aires en 1917; electo vicepresidente de la República en la fórmula que encabeza en 1928 don Hipólito Yrigoyen, fallece antes de ocupar el cargo."],["Doctor Luis Beláustegui","calle","Luis V. Beláustegui (1842 a 1909), jurisconsulto; asesor municipal; ministro de Justicia, Culto e Instrucción Pública de José Evaristo Uriburu en 1897."],["Belén","calle","Belén: pueblo y departamento de la provincia de Catamarca."],["Belfast","calle","Belfast: ciudad capital de Irlanda del Norte."],["Bélgica","calle","Bélgica: país europeo. Capital: Bruselas."],["Bélgica","plaza","Bélgica: país europeo. Capital: Bruselas."],["Belgrado","calle","Belgrado: ciudad capital de la República de Serbia."],["Belgrano","avenida","El origen del nombre de este barrio data del decreto del 6 de diciembre de 1855, en el que el Poder Ejecutivo de la provincia de Buenos Aires aprueba el proyecto de delineación que el Departamento Topográfico le elevara para el pueblo a erigirse en la zona conocida como La Calera. Se cumplía así con un demorado homenaje al creador de la Bandera."],["Belgrano","barrio","El origen del nombre de este barrio data del decreto del 6 de diciembre de 1855, en el que el Poder Ejecutivo de la provincia de Buenos Aires aprueba el proyecto de delineación que el Departamento Topográfico le elevara para el pueblo a erigirse en la zona conocida como La Calera. Se cumplía así con un demorado homenaje al creador de la Bandera."],["Bm N° 16.731. Belgrano, General Manuel N° 37.499-1982","plaza","Manuel Joaquín Corazón de Jesús Belgrano (1770 a 1820), general; redactor del Correo de Comercio; vocal de la Primera Junta; creador de la Bandera Nacional; vencedor en Salta y Tucumán."],["Bell Ville","calle","Bell Ville: ciudad del departamento de Unión, provincia de Córdoba, denominada anteriormente Fraile Muerto."],["Bella Vista","calle","Bella Vista: denominación de diversas localidades argentinas. Es este un nombre muy difundido en nuestro país, y existen pueblos así denominados en las provincias de Buenos Aires, Catamarca, Córdoba, Corrientes, Jujuy, La Pampa, La Rioja, Misiones, Neuquén, Salta, San Juan, San Luis, Santa Cruz, Santiago del Estero y Tucumán."],["Vicente Bellini","plazoleta","Vicente Bellini (1802 a 1835), compositor italiano; autor de las óperas La sonámbula, Los puritanos y Norma."],["Andrés Bello","calle","Andrés Bello (1781 a 1865), escritor, filólogo y político venezolano; autor de Gramática de la lengua española y Filosofía del entendimiento; redactor del Código Civil chileno."],["Diputado Nacional Carlos Bello","paseo","Carlos Bello (1936 a 1989), político radical de la Boca y Barracas; concejal de la ciudad de Buenos Aires de 1973 a 1976 y diputado nacional entre 1985 y 1989."],["Fray Luis Beltrán","calle","Luis Beltrán (1784 a 1827), sacerdote y teniente coronel; capellán del Ejército de los Andes, se hace cargo del montaje del parque y maestranza del Ejército; actúa durante la guerra contra el Brasil participando en la batalla de Ituzaingó."],["Diputado Nacional Osvaldo Ernesto Benedetti","calle","Osvaldo Ernesto Benedetti (1916 a 1978), político; diputado nacional por la Unión Cívica Radical de 1973 a 1976."],["Carlos Javier Benielli","calle","Carlos Javier Benielli (1878 a 1934), docente; autor de las letras de la Marcha de San Lorenzo, Tuyutí y A San Martín; escritor, poeta y periodista, es autor de Menudencias lingüísticas."],["Carlos Berg","calle","Federico Guillermo Carlos Berg (1843 a 1902), naturalista ruso; director del Museo de Historia Natural de Buenos Aires; profesor de Historia Natural en el Colegio Nacional de Buenos Aires; presidente de la Sociedad Científica Argentina."],["Bergantín Congreso Nacional","calle","Bergantín Congreso Nacional: bergantín norteamericano comprado en 1826 al prepararse la escuadra para combatir en la guerra contra el Brasil."],["Bergantín Echagüe","calle","Bergantín Echagüe: nave que se integra a la escuadra que comandaba el almirante Guillermo Brown durante el bloqueo anglofrancés. Denominado anteriormente Cagancha, pertenecía a las fuerzas uruguayas y fue capturado el 9 de diciembre de 1841."],["Bergantín General Balcarce","calle","Bergantín General Balcarce: bergantín de bandera sarda, que, adquirido por el Gobierno en 1825, prestó importantes servicios; fue el primer buque insignia de Brown durante la guerra contra el Brasil."],["Bergantín General Belgrano","calle","Bergantín General Belgrano: nave que participó en combate el 9 de febrero de 1826 al mando de Francisco Seguí; encalló y se hundió posteriormente en el asalto a Colonia el 26 de febrero de 1826."],["Bergantín Goleta Espora","calle","Bergantín goleta Espora: denominado anteriormente Nancy, en él navegó el comandante Luis Piedra Buena, que lo compró en 1860. Esta nave naufraga el 10 de marzo de 1873 en tareas de salvamento en la isla de Año Nuevo."],["Bergantín Nancy","calle","Bergantín Nancy: buque de la escuadra que comandaba Brown en 1814 que intervino en numerosas acciones navales frente a Montevideo."],["Bergantín Vigilante","calle","Bergantín Vigilante: nave que, junto con el Belgrano, Echagüe y San Martín, integra la escuadra de Brown en 1841."],["Berlín","calle","Berlín: ciudad capital de la República Alemana."],["Bermejo","calle","Bermejo: río que nace en Tarija, Bolivia, desemboca en el río Paraguay, y sirve de límite entre las provincias de Chaco y Formosa."],["Doctor Antonio Bermejo","calle","Antonio Bermejo (1852 a 1929), jurisconsulto; ministro de Justicia e Instrucción Pública de 1895 a 1897, durante la presidencia de José Evaristo Uriburu; presidente de la Suprema Corte de Justicia de 1905 a 1929."],["Bermúdez","calle","Justo Germán Bermúdez (1774 a 1813), capitán; fallece como consecuencia de las heridas recibidas en el combate de San Lorenzo, donde herido el caballo de San Martín, se constituye en jefe de la acción."],["Antonio Bermúdez","calle","Antón Bermúdez (1548-¿1609?); acompaña a Garay en la fundación de Buenos Aires en 1580; regidor del primer Cabildo porteño."],["Jorge Bermúdez","calle","Jorge Bermúdez (1883 a 1926), pintor; autor de La Patroncita, Don Panta Vílquez y Riña de gallos."],["Berna","calle","Berna: ciudad capital de Suiza y del estado de su nombre."],["Bernal","calle","Francisco Bernal (1558-¿1613?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Bernaldes","calle","José Bernaldes Polledo (1772 a 1820), coronel; combate durante las Invasiones Inglesas, en Las Piedras, Tucumán, Salta y Vilcapugio, donde cae prisionero."],["Cesáreo Bernaldo de Quirós","plazoleta","Cesáreo Bernaldo de Quirós (1879 a 1968), pintor; autor de Lanzas y guitarras, El juez federal, Tortas y carretas, El patroncito, Los algarrobos y Autorretrato."],["Conscripto Bernardi","calle","Anacleto Bernardi (1906 a 1927), marinero; muere ayudando a los náufragos del barco Princesa Mafalda frente a las costas del Brasil."],["Paquita Bernardo","plazoleta","Paquita Bernardo (1900 a 1925), bandoneonista; es la primera mujer que se destaca en la ejecución de este instrumento; consigue trascendencia artística y una destacada actuación profesional interpretando obras como Floreal, Soñando, Cachito, Cerro Divino, y Villa Crespo, entre otras."],["Irene Bernasconi","cantero central","Irene Bernasconi (1897 a 1989), investigadora y bióloga; se consagra al estudio de las ciencias naturales, especializándose en zoología en el Museo Argentino Bernardino Rivadavia; en 1947 obtiene el premio Dr. Eduardo Holmberg por su obra Asteroides argentinos (estrellas de mar); es autora de Equinodermos: resultado de la primera expedición a Tierra del Fuego, Los equinodermos de los mares argentinos y Los asteroides sudamericanos de la familia Indiae."],["Mario Bernasconi","calle","Mario Bernasconi (1900 a 1960), político; diputado nacional por la Unión Cívica Radical del Pueblo de 1958 a 1960."],["Antonio Berni","cantero central","Antonio Berni (1905 a 1981), artista plástico; es laureado con el premio máximo en la sección de dibujo y grabado en la Bienal de Venecia en 1962; presidente de la Asociación Argentina de Artistas Plásticos; autor de las obras La siesta, Desocupados, Manifestación, Chacareros, Villa Cartón, Villa Piolín y la célebre serie de Juanito Laguna."],["Berón de Astrada","calle","Genaro Berón de Astrada (1804 a 1839), general; gobernador de Corrientes de 1838 a 1839, se levanta contra el gobierno de Rosas siendo derrotado y muerto en la batalla de Pago Largo, el 31 de marzo de 1839."],["Adolfo Berro","avenida","Adolfo Tiburcio Berro (1819 a 1841), poeta uruguayo; autor de El esclavo, La expósita, El mendigo, La cárcel y Los detenidos."],["Berthelot","calle","Pedro Eugenio Marcelino Berthelot (1827 a 1907), químico francés; uno de los fundadores de la síntesis química y el primero que obtiene, por ese medio, hidrocarburos, acetileno, benceno, etc.; enuncia la Ley de la Termoquímica o Ley del Trabajo Máximo."],["Beruti","calle","Antonio Luis Beruti (1772 a 1841), coronel; activista de la Revolución de Mayo; teniente de Gobernador de Santa Fe de 1812 a 1813 y de Tucumán de 1813 a 1814; combate en Chacabuco."],["Arturo Beruti","calle","Arturo Beruti (1862 a 1938), músico; autor de Vendetta, Los héroes y Pampa."],["Besares","calle","Manuel Besares (1792 a 1827), teniente coronel; combate en Tucumán, Salta y en la guerra contra el Brasil, donde muere en la batalla de Ituzaingó."],["Julián Besteiro","plazoleta","Julián Besteiro Fernández (1870 a 1940), político y sociólogo español; vicepresidente del Partido Socialista en 1912; presidente del mismo en 1925; diputado y concejal de Madrid; presidente de las Cortes Constituyentes en 1931; condenado a cadena perpetua al culminar la guerra civil, muere en la prisión."],["Almirante Onofre Betbeder","calle","Onofre Betbeder (1861 a 1915), marino; comandante de la Fragata Sarmiento, realiza el primer viaje de circunnavegación en 1899; ministro de Marina de 1901 a 1904 y de 1906 a 1910."],["Bethlem","calle","Bethlem: ciudad de Jordania donde nació Jesucristo; llamada en español Belén, es una palabra que proviene del hebreo; Beth: casa y Lehem: pan. Es éste un nombre tradicional de Buenos Aires, pues entre 1769 y 1808 se denominó así la actual Humberto I, ya que en la misma, entre Defensa y Balcarce, se encuentra la iglesia de Nuestra Señora de Belén. Los primeros sacerdotes de la Orden de los Bethlemitas, fundada por Fray José de Bethencourt en Gua- temala, en 1687, llegaron a la ciudad de Buenos Aires en 1748 para hacerse cargo del Hospital."],["Beyrouth","calle","Beyrouth: ciudad de Baviera, Alemania, donde se encuentra el palacio Wagner, en el cual descansan los restos del célebre músico de ese nombre y los de Liszt."],["Bialet Massé","calle","Juan Bialet Massé (1846 a 1907), médico y jurisconsulto; autor del Informe sobre el estado de las clases obreras en el interior de la República; colaborador del ingeniero Casaffousth en la construcción del dique San Roque."],["Andrés Bianchi","calle","Andrés Bianchi (o Blanqui) (1677 a 1740), maestro mayor que, junto con el arquitecto Juan Bautista Prímoli, transformó el panorama arquitectónico del Buenos Aires de principios del siglo XVIII; construyen la fachada de la Catedral y los templos de la Merced, San Francisco, San Telmo y del Pilar."],["Biarritz","calle","Biarritz: ciudad de Francia."],["Juan Antonio Bibiloni","calle","Juan Antonio Bibiloni (1860 a 1933), jurisconsulto; ministro de Justicia e Instrucción Pública de 1907 a 1908; presidente del Instituto de Altos Estudios comerciales, donde se forma el grupo de profesores de la Facultad de Ciencias Económicas creada en 1913; planea la reforma del Código Civil."],["Pedro Bidegain","calle","Pedro Bidegain (1887 a 1933), político; obrero ferroviario afiliado al radicalismo, llega a ser electo concejal y diputado nacional en Buenos Aires; presidente del Club San Lorenzo de Almagro; autor de Mi radicalismo."],["José Juan Biedma","calle","José Juan Biedma (1864 a 1933), historiador; director del Archivo General de la Nación; autor de Crónica histórica del Río Negro y Patagones, y, junto con José Pillado, del Diccionario Biográfico Argentino."],["Doctor Rafael Bielsa","calle","Rafael Bielsa (1889 a 1966), jurisconsulto; tratadista de Derecho Administrativo; autor de Derecho administrativo y legislación argentina administrativa, Limitaciones impuestas a la propiedad en interés público y Reflexiones sobre sistemas políticos."],["Francisco Bilbao","calle","Francisco Bilbao (1823 a 1865), publicista chileno; exiliado de Chile por problemas políticos, se desempeña como redactor de El Nacional Argentino, de Paraná; autor de La América en peligro y El Evangelio Americano."],["Billinghurst","calle","Roberto Billinghurst (1781 a 1841), comerciante inglés; obtiene la segunda carta de ciudadanía otorgada el 29 de noviembre de 1811 por el Superior Gobierno de las Provincias Unidas del Río de la Plata “teniendo en consideración sus relevantes servicios”; había combatido en Las Piedras y en el primer sitio de Montevideo."],["Blanco Encalada","calle","Manuel Blanco Encalada (1790 a 1876), almirante; combate en Maipú; participa en las campañas de Puertos Intermedios; presidente de Chile en 1826."],["Blandengues","calle","Blandengues: cuerpo creado en 1752 por el gobernador Andonaegui para contrarrestar las correrías de los indios con el nombre de Blandengues de la Frontera."],["Juan Manuel Blanes","calle","Juan Manuel Blanes (1830 a 1901), pintor uruguayo; autor de Un episodio de la fiebre amarilla en Buenos Aires y La conquista del desierto."],["La Blanqueada","calle","La Blanqueada: nombre tradicional con que se conocía al actual barrio de Belgrano y que provenía de una pulpería que por el color de sus paredes era denominada “la blanqueada” o “las blanqueadas”. Estaba ubicada en lo que hoy es la intersección de Cabildo y La Pampa, en su esquina noroeste."],["Boca","barrio","Boca del Riachuelo: denominación usual proveniente de la boca mediante la cual desembocan en el Río de la Plata las aguas del Riachuelo, y con la cual se conoce a esta zona desde los orígenes de la ciudad."],["Quintino Bocayuva","calle","Quintino Ferreyra da Souza Bocayuva (1836 a 1912), estadista y diplomático brasileño; promotor del movimiento que instaura la República en la nación hermana el 15 de noviembre de 1889; ministro de Relaciones Exteriores; embajador del Brasil en la República Argentina."],["Boedo","barrio","La denominación de este barrio proviene de la calle epónima, así llamada desde 1882. Habiendo formado parte del barrio de Almagro, la importancia que tomó la calle Boedo hizo que esta zona comenzara a ser identificada como un barrio independiente desde las primeras décadas del siglo XX."],["Boedo","calle","Obras Públicas). Mariano Joaquín Boedo (1782 a 1819), jurisconsulto; diputado por Salta en el Congreso de Tucumán, es nombrado vicepresidente del mismo firmando en tal carácter el Acta de la Independencia."],["Juan A. Boeri","calle","Juan A. Boeri (1849 a 1924), médico; profesor de Botánica y Zoología de la Facultad de Medicina, y de Farmacognosia en la Escuela de Farmacia; miembro de la Academia de Medicina; concejal, juez de Paz y presidente del Consejo Escolar de Vélez Sarsfield."],["Bogado","calle","José Félix Bogado (1777 a 1829), coronel; combate en Chacabuco, Maipú, en las campañas de Puertos Intermedios, Junín y Ayacucho."],["Bogotá","calle","Bogotá: ciudad capital de Colombia."],["Bolaños","calle","José Bonifacio Bolaños (1751 a 1824), coronel; combate durante las Invasiones Inglesas, en Suipacha, Las Piedras, Tucumán y Salta; teniente Gobernador de Mendoza en 1812 y de Jujuy de 1813 a 1814."],["Bolívar","calle","Simón Bolívar (1783 a 1830), general venezolano; vencedor en Carabobo, Pichincha y Junín; Libertador de América es, junto con San Martín, la figura mayor de la Independencia."],["República de Bolivia","plaza","Bolivia: país sudamericano. Capital: La Paz y Sucre."],["Bollini","calle","Francisco Bollini (1814 a 1887), arquitecto; realiza los primeros trabajos de nivelación de calles y construcción de desagües de Buenos Aires."],["Bolonia","calle","Bolonia: ciudad y provincia de Italia."],["Virginia Bolten","parque","Virginia Bolten (¿-?), militante anarquista y feminista uruguaya; es la primera mujer oradora en una concentración realizada en la ciudad de Rosario el 1º de mayo de 1890; durante 1896 y 1897 está al frente de la primera publicación feminista La voz de la Mujer en Rosario; en 1904 se traslada a Buenos Aires e integra el Comité de Huelga Femenino que participa en las huelgas de los trabajadores del Mercado de Frutos y en la de Inquilinos de 1907; organizadora del Centro Femenino Anarquista; es deportada a su país natal."],["Bombay","calle","Bombay: ciudad de la India, capital del estado de Maharashtra."],["Policía Federal Argentina, Superintendencia de Bomberos","plazoleta","Superintendencia de Bomberos, Policía Federal Argentina: homenaje a los bomberos de la Policía Federal Argentina, cuerpo creado el 2 de enero de 1870, con el nombre de Vigilantes Bomberos."],["Bomberos Voluntarios de la Boca","plazoleta","Bomberos Voluntarios de la Boca: homenaje a este cuerpo de bomberos voluntarios creado el 2 de junio de 1884; fue el primero del país y constituyó el modelo sobre el cual se crearon otros similares."],["Oscar Natalio Bonavena","calle","Oscar Natalio Bonavena (1942 a 1976), boxeador; campeón argentino de peso pesado en 1965."],["Coronel Esteban Bonorino","calle","Esteban Bonorino (1778 a 1824), militar; combate durante las Invasiones Inglesas y en la campaña a la Banda Oriental en 1812."],["Martiniano Bonorino","calle","Martiniano Bonorino (1810 a 1887), comerciante; primer rematador público que se establece en Buenos Aires en 1835, su establecimiento influye en la transformación edilicia de la ciudad."],["Bonpland","calle","Amado Jacobo Alejandro Bonpland (1773 a 1858), naturalista francés; su verdadero apellido era Goujaud; catedrático de medicina y profesor de Historia Natural en Buenos Aires, ciudad a la que llega en 1817."],["Boquerón","calle","Batalla de Boquerón: triunfo del ejército de la Triple Alianza durante la guerra contra el Paraguay, el 18 de julio de 1866."],["José Borches","calle","José Borches (1802-?), comerciante; participa en la fundación del pueblo, hoy barrio de Belgrano; secretario de su primera corporación municipal; miembro de la Lotería de Beneficencia de Buenos Aires en 1857."],["Doctor Enzo Bordabehere","calle","Enzo Bordabehere (1889 a 1935), jurisconsulto; diputado provincial y nacional; senador nacional por Santa Fe; muere asesinado en pleno recinto del Senado de la Nación el 23 de julio de 1935 cuando se disponía a auxiliar a su colega de bancada, Lisandro de la Torre, en un acalorado debate sobre el comercio de la carne."],["Tato Bores","espacio público","Mauricio Borensztein (1927 a 1996); actor conocido como Tato Bores. Inicia su carrera en la radio en la década de 1940 y en el cine en 1948. En la televisión se impone como un notable monologuista. Su personaje más destacado es el que, desde 1958, realiza los domingos en Tato y sus monólogos, Tato siempre en domingo, Por siempre Tato, Dígale sí a Tato, Déle crédito a Tato, Tato versus Tato, Tato de América y Good Show, entre otros títulos, donde aparece vestido de frac, peluca, lentes y habano. Su lucidez e ironía analizando la realidad política nacional le valieron el apoyo del público y también la atención de la censura."],["Jorge Luis Borges","calle","Jorge Luis Borges (1899 a 1986), escritor y poeta; autor de Fervor de Buenos Aires, La luna de enfrente, Historia universal de la infamia y El Aleph."],["Jorge Luis Borges","espacio verde","Jorge Luis Borges (1899 a 1986), escritor y poeta; autor de Fervor de Buenos Aires, La luna de enfrente, Historia universal de la infamia y El Aleph."],["Michel Borowsky","cantero central","Michel Borowsky (1910 a 1971), bailarín; maestro y coreógrafo del Teatro Colón."],["Ventura Bosch","calle","Ventura Pedro Bosch (1814 a 1871), médico; fundador del Hospicio de San Buenaventura, luego Hospicio de las Mercedes; actúa durante la guerra contra el Paraguay; víctima de la epidemia de fiebre amarilla."],["Don Bosco","calle","San Juan Bosco (1815 a 1888), religioso italiano; fundador de la Congregación de los Salesianos en 1845 y del Instituto de Hijas de María Auxiliadora."],["Don Bosco","plaza","San Juan Bosco (1815 a 1888), religioso italiano; fundador de la Congregación de los Salesianos en 1845 y del Instituto de Hijas de María Auxiliadora."],["Boston","calle","Boston: ciudad de los Estados Unidos de Norteamérica."],["Hipólito Bouchard","plazoleta","Hipólito Bouchard (1780-¿1837?), marino francés cuyo nombre verdadero era Andrés Pablo; combate en San Lorenzo y Callao; al mando de La Argentina, declarada oficialmente en corso, recorre el mundo en 1817 enarbolando la bandera argentina."],["Boulogne-Sur-Mer","calle","Boulogne-Sur-Mer: ciudad de Francia donde vivió el general San Martín desde 1848; fallece allí el 17 de agosto de 1850."],["Boyacá","calle","Boyacá: triunfo de Bolívar que decide la independencia de Colombia el 7 de agosto de 1819."],["Bragado","calle","Bragado: ciudad y partido de la provincia de Buenos Aires."],["Luis Braille","calle","Luis Braille (1809 a 1852), pedagogo francés; ciego desde los tres años de edad, inventa la escritura punteada para no videntes que lleva su nombre."],["Brandsen","calle","Federico de Brandsen (1785 a 1827), coronel de origen francés; asiste a la campaña de Bío-Bío; combate en Parral, Nazca, Zepita; general en jefe de la Defensa de la Ciudad de Lima durante el ataque de febrero de 1824; combate durante la guerra contra el Brasil, donde muere en la batalla de Ituzaingó."],["República Federativa del Brasil","plaza","República Federativa del Brasil: país sudamericano. Capital: Brasilia."],["Doctor Eduardo Braun Menéndez","calle","Eduardo Braun Menéndez (1903 a 1959), médico y fisiólogo; profesor de Fisiología de la Facultad de Medicina de Buenos Aires; jefe de Investigaciones de Circulación del Instituto de Fisiología dirigido por Houssay."],["Bravard","calle","Augusto Bravard (?-1861), paleontólogo; realiza investigaciones arqueológicas en Buenos Aires, Entre Ríos y Mendoza; autor de Observaciones geológicas sobre diferentes terrenos de transporte de la hoya del Plata y Estado físico del territorio. Geografía de las Pampas."],["Mario Bravo","calle","Mario Bravo (1882 a 1944), jurisconsulto, funcionario y escritor; senador nacional por la Capital Federal; director de La Vanguardia, secretario del Partido Socialista; autor de Canciones de Soledad."],["Ministro Brin","calle","Benedicto Brin (1833 a 1898), ingeniero y diplomático italiano; en 1898 facilita a la Argentina la compra de buques ante la inminencia de un conflicto con Chile."],["Cura Brochero","calle","José Gabriel Brochero (1840 a 1914), sacerdote; llamado el Cura Gaucho, realiza una importante obra religiosa en el interior de la provincia de Córdoba."],["Darío Broggi","plazoleta","Darío Broggi (¿1861?-1933) sacerdote de origen italiano; llega a Buenos Aires con el propósito de asistir a los inmigrantes de esa nacionalidad; a su iniciativa se debe la erección del Santuario de Nuestra Señora de Pompeya, cuya piedra fundamental se coloca el 14 de mayo de 1896; impulsa la creación del colegio de Artes y Oficios de Nueva Pompeya que pasa a pertenecer a la Sociedad de Conservación de la Fe."],["Almirante Guillermo Brown","parque","Guillermo Brown (1777 a 1857), marino de origen irlandés; vencedor en Martín García, Los Pozos, Juncal y Quilmes; gobernador delegado de la provincia de Buenos Aires en 1828."],["Elisa Brown","plazoleta","Elisa Brown (1810 a 1827), hija del almirante Guillermo Brown; muere en un accidente al tomar un baño en el Riachuelo. Otras fuentes aseguran que fue un suicidio motivado por la muerte del sargento mayor de marina Francisco Drummond, que muere en combate durante la guerra contra el Brasil, y de quien estaba enamorada."],["Frank Brown","calle","Frank Brown (1858 a 1943), payaso y artista circense; actuó con gran éxito en el Politeama, San Martín e Hipódrome."],["Bruix","avenida","Alejo Bruix (?-1826), coronel de origen francés; combate en Maipú, Riobamba, Pichincha, Junín y Ayacucho."],["Herminia C. Brumana","plazoleta","Herminia C. Brumana (1901 a 1954), educadora y escritora; se interesa por los problemas sociales y económicos de la mujer; autora de La guía, Nuestro hombre, Me llamo niebla, A Buenos Aires le falta una calle y Cartas a las mujeres argentinas."],["Giordano Bruno","calle","Giordano Bruno (1548 a 1600), filósofo italiano; autor de La causa principio y uno y Del universo, infinito y mundo; muere en Roma en la hoguera condenado por hereje."],["Giordano Bruno","plaza","Giordano Bruno (1548 a 1600), filósofo italiano; autor de La causa principio y uno y Del universo, infinito y mundo; muere en Roma en la hoguera condenado por hereje."],["Bruselas","calle","Bruselas: ciudad capital de Bélgica."],["Bucarelli","calle","Francisco de Paula Bucarelli y Ursúa (¿-?) militar español; gobernador del Río de la Plata de 1766 a 1770."],["Bucarest","calle","Bucarest: ciudad capital de Rumania."],["Budapest","calle","Budapest: ciudad capital de Hungría."],["Del Buen Orden","calle","Buen Orden: es éste un nombre tradicional, ya que entre 1822 y 1907 se denominó así la actual Bernardo de Irigoyen. Recuerda el “buen orden” y comportamiento mantenido por las fuerzas que, en 1820, al mando de Juan Manuel de Rosas, ingresaron en la ciudad para reponer en su cargo al general Martín Rodríguez. Rosas les había recomendado proceder en correcto comportamiento con la frase: “¡En buen orden, muchachos!”, instrucción que fue cumplida al pie de la letra. El 7 de octubre de 1820, Juan Manuel de Rosas es ascendido a coronel de caballería en reconocimiento a su actuación en la jornada del 5 de octubre, como restaurador del orden y la autoridad legal."],["Provincia de Buenos Aires","cantero central","Buenos Aires: provincia de la República Argentina. Capital: La Plata."],["Bueras","calle","Santiago Bueras (1769 a 1818), teniente coronel; combate en Cucha Cucha, Talcahuano, Cancha Rayada y Maipú, batalla en la que muere."],["Alfredo R. Bufano","calle","Alfredo R. Bufano (1895 a 1950), poeta; autor de Canciones de mi casa, Valle de soledad y Romancero."],["Bulgaria","calle","Bulgaria: país europeo. Capital: Sofía."],["Intendente Bullrich","avenida","Adolfo Jorge Bullrich (1833 a 1904), comerciante; intendente municipal de la ciudad de Buenos Aires desde el 20 de octubre de 1898 hasta el 20 de octubre de 1902."],["Bulnes","calle","Obras Públicas). Eduardo Pérez Bulnes (1785 a 1851), jurisconsulto; diputado por Córdoba en el Congreso de Tucumán."],["Ingeniero Arquitecto Jorge Bunge","cantero central","Jorge Bunge (1893 a 1962), ingeniero y arquitecto; realizó varias obras entre ellas el Edificio del Banco Francés del Río de la Plata y el Museo Nacional de Bellas Artes; proyectista, creador y fundador de la ciudad balnearia de Pinamar (1940)."],["Intendente Bunge","calle","Emilio V. Bunge (1836 a 1909), jurisconsulto; intendente municipal de la ciudad de Buenos Aires desde el 14 de septiembre de 1894 hasta el 12 de septiembre de 1896."],["Burela","calle","Luis Burela y Saavedra (?-1834), coronel; luego de las derrotas de Vilcapugio y Ayohuma y ante el avance de Pezuela, toma la iniciativa de combatirlo iniciando así la resistencia salteña; participa en Puesto del Marqués y en el combate del Bañado, una de sus acciones más heroicas."],["Burgos","calle","Burgos: ciudad capital de la provincia homónima en Castilla la Vieja, España."],["Germán Burmeister","avenida","Carlos Germán Conrado Burmeister (1807 a 1892) naturalista alemán; autor de Viaje por los Estados del Plata, con relación especial a la naturaleza física y el estado cultural de la República Argentina, efectuado en los años 1857-1860; director del Museo Público de Buenos Aires desde 1862 hasta 1892."],["Juan A. Buschiazzo","calle","Juan Antonio Buschiazzo (1845 a 1917), arquitecto; director del Departamento de Obras Públicas de la Municipalidad, planea la Avenida de Mayo, demuele la Recova Vieja, la torre y los arcos de la derecha del Cabildo; idea la Avenida 9 de Julio; proyecta el cementerio de la Chacarita y la iglesia del Carmen; miembro fundador de la Sociedad de Arquitectos."],["Arquitecto Alejandro Bustillo","plaza","Alejandro Bustillo (1889 a 1982), pintor, escultor y arquitecto; entre sus obras se destacan el Museo Nacional de Bellas Artes, el conjunto del Casino y Hotel Provincial de Mar del Plata, el Banco de la Nación Argentina y el Hotel Llao- Llao de Bariloche."],["General José María Bustillo","calle","José María Bustillo (1816 a 1910), militar; combate en Caaguazú, durante el sitio de Hilario Lagos y en la guerra contra el Paraguay; interventor de la provincia de Buenos Aires en 1880; presidente del Club del Progreso."],["Butteler","calle","Azucena Butteler (¿-?) donante de la manzana de tierra comprendida por las calles Zelarrayán, Senillosa, Cobo y avenida La Plata, donde se encuentra esta calle, y en la que se construyó un grupo de casas para obreros; dicha donación fue aceptada por la Municipalidad por Resolución del 12-11-1907. El mensaje a la Comisión municipal fue enviado por el entonces intendente Carlos T. de Alvear, en su doble carácter de albacea testamentario de Azucena Butteler y de intendente municipal."],["Ingeniero Enrique Butty","calle","Enrique Butty (1887 a 1973), ingeniero, matemático, físico, filósofo y literato; autoridad científica en el campo de la matemática y de la física; se ocupó en nuestro país de la teoría de la relatividad; rector de la Universidad de Buenos Aires; presidente de Obras Sanitarias de la Nación desde 1933 hasta 1943."],["Bynon","calle","Santiago Jorge Bynon (1798 a 1883), marino oriundo de Inglaterra; combate durante la guerra contra el Brasil donde se destaca en Patagones; radicado en Chile, interviene en la lucha con la Confederación Peruano-Boliviana; gobernador marítimo de Valparaíso (1843), de Talcahuano (1844) y de Atacama (1849).20."],["Byron","calle","Jorge Gordon, Lord Byron (1788 a 1824), escritor inglés; autor de El corsario y Lara, Sardanápalo y Don Juan. Notas."],["Caaguazú","calle","Caaguazú: batalla en la que se enfrentan unitarios y federales al mando de José María Paz y Pascual Echagüe, respectivamente, el 28 de noviembre de 1841."],["Caballito","barrio","Caballito: denominación usual con la que se identifica a esta zona de la ciudad desde 1804, cuando don Nicolás Vila instala en la esquina de Rivadavia y Emilio Mitre su célebre pulpería, reconocida por su típica veleta con forma de caballo. Una réplica de la misma, obra de Luis Perlotti, se observa hoy en el mástil de la plaza Primera Junta."],["Caballito","calle","Caballito: denominación usual con la que se identifica a esta zona de la ciudad desde 1804, cuando don Nicolás Vila instala en la esquina de Rivadavia y Emilio Mitre su célebre pulpería, reconocida por su típica veleta con forma de caballo. Una réplica de la misma, obra de Luis Perlotti, se observa hoy en el mástil de la plaza Primera Junta."],["Cabello","calle","Francisco Antonio Cabello y Mesa (1764-¿1824?), jurisconsulto y periodista; radicado en Lima, edita el Diario Curioso, Erudito, Económico y Comercial que es la primera publicación periodística sudamericana; en Buenos Aires edita el Telégrafo Mercantil, Rural, Político, Económico e Historiógrafo del Río de la Plata."],["José León Cabezón","calle","José León Cabezón (1767 a 1844), educador; funda la Escuela de Gramática y Latinidad de Salta; eminente latinista, recorre Bolivia y Perú organizando equipos de educación; radicado en Chile desde 1828 funda un colegio de enseñanza superior."],["Cabildo","avenida","Cabildo: institución de origen hispánico de carácter comunal trasladada a América, que gobierna administrativa y judicialmente a la ciudad."],["Cabot","calle","Juan Manuel Cabot (1784 a 1837), militar; combate durante las Invasiones Inglesas y en Coquimbo, Barraza y Salala."],["Sargento Cabral","calle","Juan Bautista Cabral (?-1813), militar; sargento que en la batalla de San Lorenzo ayuda a San Martín cuando el General queda aprisionado por su caballo herido. En esa abnegada acción es herido de muerte."],["Sargento Cabral","plaza","Juan Bautista Cabral (?-1813), militar; sargento que en la batalla de San Lorenzo ayuda a San Martín cuando el General queda aprisionado por su caballo herido. En esa abnegada acción es herido de muerte."],["Doctor Domingo Cabred","calle","Domingo Cabred (1859 a 1929), médico psiquiatra; promueve en nuestro país el sistema de puertas abiertas y de clinoterapia; director del Hospital de las Mercedes; surgen bajo su impulso los policlínicos regionales de Resistencia, Bell Ville (Córdoba), La Rioja, Allen (Río Negro), Posadas y Concepción del Uruguay; fundador de la Liga Argentina contra el Alcoholismo."],["Coronel Cabrer","calle","José María Cabrer (1761 a 1836), coronel español; actúa en la Comisión Demarcadora de Límites con Portugal en 1781; autor del Diario de la segunda subdivisión de límites españoles entre los dominios de España y Portugal en la América Meridional; combate durante las Invasiones Inglesas; desde 1826 se desempeña en el Departamento General de Topografía y Estadística."],["José Antonio Cabrera","calle","Cabrera por Disposición del presidente de la Corporación Municipal, Torcuato de Alvear, del 6-3-1882. (Archivo Histórico Municipal, Legajo 3, 1882. Obras Públicas). Por Decreto Ordenanza N° 2.485-1949, BM N° 8.529, su nombre actual. José Antonio Cabrera (1768 a 1820), jurisconsulto; diputado por Córdoba en el Congreso de Tucumán."],["Santa Francisca Javier Cabrini","espacio verde","Francisca Javier Cabrini (1850 a 1917), religiosa y educadora de origen italiano; funda en 1880 el Instituto de las Misioneras del Sagrado Corazón de Jesús; canonizada por Pío XII en 1946, es declarada en 1950 Patrona Universal de los Emigrantes."],["Cacheuta","calle","Cacheuta: cerro, localidad y fuente de aguas termales en el departamento Luján de Cuyo, provincia de Mendoza."],["Cachi","calle","Cachi: departamento de la provincia de Salta y cerro de seis mil metros de altura en la cordillera salto-jujeña."],["La Cachila","calle","Cachila: pájaro pequeño, de color pardo, que hace su nido en el suelo. Llamado también ratona o ratoncita en Buenos Aires, tacuarita en el litoral y cucharita en Córdoba, su nombre científico es Trodlodytes furvus."],["Cachimayo","calle","Cachimayo: acción de Gregorio Aráoz de Lamadrid el 20 de mayo de 1817, cuando al penetrar en la quebrada de Cachimayo, en su intersección con la de Yotala, a dos leguas de Chuquisaca, hace prisionera a una fuerza de caballería realista de 50 hombres aproximadamente, mediante una estratagema en la que no se dispara un solo tiro."],["Cacique","calle","Cacique: voz caribe empleada para designar al jefe de una tribu indígena."],["Cádiz","calle","Cádiz: ciudad de España, capital de la provincia de su nombre."],["Cafayate","calle","Cafayate: ciudad y departamento de la provincia de Salta."],["Agustín R. Caffarena","calle","Agustín Rafael Caffarena (1872 a 1933), pedagogo; presidente de varios distritos escolares de la Capital Federal, fue un decidido propulsor de las asociaciones cooperadoras; se cuentan entre sus iniciativas la implantación de la Fiesta del Árbol en 1902 y la ceremonia del Saludo a la Bandera en 1906."],["Francisco Cafferata","calle","Francisco Cafferata (1861 a 1890), escultor; autor del bronce El esclavo (Parque 3 de Febrero), del monumento al Almirante Brown (plaza Esteban Adrogué); iniciador de la estatua de Falucho que concluye su discípulo Lucio Correa Morales."],["Jorge Cafrune","pasaje peatonal","Jorge Cafrune (1937 a 1978) cantante; popular intérprete del folclore nacional, su canto y estilo carismático se pudieron disfrutar en festivales, peñas, progra- mas de radio y televisión. Muere en un accidente en extrañas circunstancias cuando, a modo de homenaje a José de San Martín, emprende una travesía a caballo que lo llevaría a Yapeyú, para depositar allí tierra de Boulogne-sur- Mer, lugar del fallecimiento del Libertador. En la primera noche de cabalgata es embestido a la altura de Benavídez por una camioneta."],["Cagliari","calle","Cagliari: capital de la provincia de su nombre en la isla italiana de Cerdeña. En un santuario de la ciudad se venera a la Virgen de Bonaria o del Buen Aire, cuyo nombre ostenta nuestra ciudad."],["Cajaravilla","calle","Miguel Cajaravilla (1794 a 1852), teniente coronel; combate en Chacabuco, Cancha Rayada y Maipú; participa en la expedición al desierto comandada por Martín Rodríguez."],["Calabria","calle","Calabria: región del sudoeste de Italia que comprende las provincias de Cosenza, Reggio, Calabria y Catanzaro."],["Calabria","cantero central","Calabria: región del sudoeste de Italia que comprende las provincias de Cosenza, Reggio, Calabria y Catanzaro."],["La Calandria","calle","Calandria: ave cantora de la familia de los mímidos."],["José María Calaza","calle","José María Calaza (1852 a 1913), coronel; jefe del Cuerpo de Bomberos, reorganiza y transforma esa institución; autor del Plan de Defensa contra incendios para la ciudad de Buenos Aires y Memoria descriptiva de la División Bomberos de Buenos Aires, su pasado, su presente y su futuro."],["Cálcena","calle","José Alberto Cálcena y Echeverría (1760 a 1821), comerciante, conciliario del Consulado; contador y Agente Mayor de Negocios de la Hermandad de Caridad del Cabildo de Buenos Aires; coopera económicamente con la Revolución de Mayo y con Belgrano durante su campaña al Paraguay, donde se alista como Comisario de Guerra e Intendente General; combate en Tacuarí; participa en la Campaña a la Banda Oriental como Intendente General del Ejército. CALCUTA, MADRE TERESA DE véase TERESA DE CALCUTA."],["Caldas","calle","Francisco José de Caldas (1771 a 1816), naturalista colombiano; autor de Obras, cartas y viajes; realiza estudios zoofitogeográficos en el actual Ecuador, intercambiando información con Bonpland y Humboldt; director del Observatorio de Santa Fe de Bogotá, es fusilado por Murillo."],["Caldén","calle","Caldén: árbol de la familia de las leguminosas del mismo género que el algarrobo."],["Pedro Calderón de la Barca","calle","Pedro Calderón de la Barca (1600 a 1681), dramaturgo español; autor de La vida es sueño y El alcalde de Zalamea."],["Calfucurá","calle","Juan Calfucurá (?-1873), cacique araucano; fundador de la Confederación de las Salinas Grandes; actúa junto a Urquiza en el sitio de Buenos Aires de 1853; participa en la campaña de Cepeda; es vencido por el general Ignacio Rivas en Pichi-Carhué."],["Ricardo José Calichio","plazoleta","Ricardo José Calichio (1927 a 1979), deportista; boxeador; conquista los torneos Guantes de Oro en los años 1944 y 1945; campeón argentino en 1949."],["California","calle","Aparece mencionada por primera vez en el Anuario General del Comercio, de la Industria, de la Magistratura y de la Administración de Buenos Aires, publicado por J. Alejandro Bernheim, 1854-1855, Buenos Aires, Imprenta del British Packet, calle Defensa 73, 1854. En el mismo, en el capítulo titulado “La Boca” (pp. 184-190) aparecen mencionadas con domicilio en la calle de este nombre, la fábrica de cerveza de J. L. Isabel y las casas de comestibles de Justo Oliva y de Manuel Reinoco. Con respecto a su aparición en planos, el primero en el que la misma figura es el Plano Topográfico de la Ciudad de Buenos Aires y de todo su Municipio, incluyendo parte de los partidos de Belgrano, San José de Flores y Barracas al Sur, levantado por el Departamento Topográfico de la provincia de Buenos Aires, 1867. El Decreto-Ordenanza N° 1.665-1976, BM N° 15.257 restituye nuevamente este nombre. California: denominación popular que confirmó la Municipalidad y que alude al estado de los Estados Unidos de Norteamérica."],["Calingasta","calle","Calingasta: departamento y localidad de la provincia de San Juan."],["Callao","avenida","Callao: ciudad y puerto cercano a Lima, Perú. Durante la lucha por la Independencia fue un baluarte de los ejércitos realistas, hasta que San Martín la conquistó el 21 de septiembre de 1821."],["Miguel Caló","plazoleta","Miguel Caló (1907 a 1972), músico, bandoneonista; director de orquesta; compositor de Todo es mentira, Mi gaucha, Garabino y Qué falta que me hacés."],["Juan P. Calou","calle","Juan Pedro Calou (1890 a 1923), poeta; autor de Brevario de los tristes y Humanamente."],["Carlos Calvo","calle","Carlos Calvo (1822 a 1906), jurista y diplomático; autor de Colección de tratados de la América Latina y Derecho internacional teórico y práctico."],["Santiago Calzadilla","calle","Santiago Calzadilla (1806 a 1896), militar y escritor; alcanza el grado de teniente coronel; autor de Las beldades de mi tiempo."],["Camacuá","calle","Camacuá: batalla librada por el general Alvear el 23 de abril de 1827, durante la guerra contra el Imperio del Brasil."],["Camargo","calle","Vicente Camargo (?-1816), teniente coronel boliviano; era de sangre indígena y al frente de otros grupos aborígenes domina la región altoperuana; se destaca por su triunfo sobre los realistas en Uturango; derrotado en los cerros de Aucapuñima es tomado prisionero y degollado."],["Camarones","calle","Camarones: bahía y localidad de la provincia del Chubut."],["Antonio Cambiasso","plazoleta","Antonio Cambiasso (¿-?), homenaje a uno de los primeros pobladores del barrio Villa del Parque, que alrededor de 1906 donó los solares donde se levantó la capilla de la Santísima Virgen Niña y la plaza Aristóbulo del Valle."],["Eustaquio Cambieses","calle","Eustaquio Cabieces (?-1807), teniente de artillería urbano; combate durante las Invasiones Inglesas y muere en la Defensa de Buenos Aires en 1807. Es éste un nombre tradicional de la ciudad, pues entre 1807 y 1822 se denominó “Cabieces” la actual avenida Juan de Garay."],["Caminito","calle","Esta calle era un desvío del Ferrocarril General Roca, en la línea que unía Casa Amarilla con el puerto, y que originariamente había pertenecido al Ferrocarril de la Ensenada. Ya en la década de 1920 no circulaban trenes por allí, y por ese motivo, en agosto de 1954 el ferrocarril procedió a retirar las vías. Finalmente, por Decreto del Poder Ejecutivo del 10 de febrero de 1958, se autorizó el traspaso a la Municipalidad de la fracción de terreno “necesaria para la habilitación del paraje denominado Caminito”. El 28 de julio de 1959 se firmó la escritura de transferencia y el 18 de octubre del mismo año, el intendente Hernán Giralt inauguró oficialmente esta particular calle de la ciudad (véase Decreto Nº 11.755-1959 sobre la organización de los festejos con ese motivo en el BM N° 11.199). Caminito: canción porteña con música de Juan de Dios Filiberto y letra de Gabino Coria Peñaloza, estrenada en 1924."],["Miguel A. Camino","calle","Miguel Andrés Camino (1877 a 1944), poeta y funcionario; autor de Chayaleras, Chaquiras y El paisaje, el hombre y su canción; subsecretario de Obras Públicas de la Municipalidad de Buenos Aires; director del Servicio Social para obreros y empleados municipales desde 1934."],["Camoatí","calle","Camoatí: voz guaraní que denomina a una especie de avispa y al panal que ellas construyen."],["Joaquín Campana","cantero central","Joaquín Campana (1783 a 1847), jurisconsulto; combate durante las Invasiones Inglesas; secretario particular de Cornelio Saavedra el 22 de mayo de 1810; promotor del movimiento del 5 y 6 de abril de 1811 y secretario de Gobierno y Guerra de la Junta a raíz de esos sucesos. Si bien la Ordenanza del 27-11-1893 no permite establecer con certeza si esta denominación alude al citado jurisconsulto o a la ciudad y partido de Campana, creemos que el estudio detallado de la citada Ordenanza sugiere la improbabilidad de que sea un homenaje a la ciudad, debido a la modernidad de la misma, ya que fue fundada en 1875. Finalmente, el problema queda dilucidado en la discusión que precede a la sanción de la Ordenanza N° 1.632 del 25 de junio de 1926, donde se afirma el criterio aquí sustentado."],["Licenciado Carlos Campelo","espacio verde","Carlos Campelo (1942 a 1997) psicólogo; pionero en la promoción de experiencias comunitarias de salud mental; creador del Programa de Salud Mental Barrial del Hospital Pirovano."],["Campichuelo","calle","Campichuelo: victoria de Belgrano el 19 de diciembre de 1810, cuando ataca, en su expedición al Paraguay, la guardia de Campichuelo, frente a Candelaria, luego de atravesar el Paraná en una de las operaciones militares más notables de la historia argentina."],["Campillo","calle","Juan Crisóstomo Nolasco del Campillo (1812 a 1866), jurisconsulto; diputado por Córdoba en el Congreso General Constituyente de 1853, y miembro de la Comisión Redactora de la Constitución; ministro de Justicia, Culto e Instrucción Pública de Urquiza, resuelve el problema de las relaciones con el Vaticano, interrumpidas desde 1810; es el primer enviado argentino ante la Santa Sede, nombrado por decreto del 30 de septiembre de 1858."],["Del Campo","avenida","Estanislao del Campo (1834 a 1880), poeta; autor de Fausto: impresiones del gaucho Anastasio el Pollo en la representación de esta ópera. Juan Estanislao del Campo (1795 a 1861), coronel, padre del anterior; combate en el Sitio de Montevideo, en Las Piedras, Palmar, Cepeda, Cañada de la Cruz, Sauce Grande, Navarro, Quebracho Herrado y Famaillá; acompaña los restos de Lavalle hasta Potosí."],["Presidente Héctor J. Cámpora","autopista","Héctor José Cámpora (1909 a 1980), político; en 1971 es designado por Juan Domingo Perón como su delegado personal; lleva a cabo una intensa labor política que culmina con su candidatura presidencial. Obtiene el triunfo y asume la presidencia de la Nación el 25 de mayo de 1973; con el retorno de Perón a la Argentina en ese mismo año, abandona el cargo."],["Gaspar Campos","calle","Gaspar Campos (1831 a 1868), teniente coronel; combate en Cepeda, Pavón y en la guerra contra el Paraguay, donde es tomado prisionero al ser sorprendido en la batalla de Acayuasá, muriendo en cautiverio."],["Luis María Campos","avenida","Luis María Campos (1838 a 1907), teniente general; combate en Pavón y en la guerra contra el Paraguay; ministro de Guerra y Marina desde 1892 hasta 1896; ministro de Guerra desde 1898, se crea por iniciativa suya la Escuela Superior de Guerra."],["Campos Salles","calle","Manuel Ferraz de Campos Salles (1846 a 1913), político brasileño; gobernador de São Paulo entre 1896 y 1898; presidente de la República de 1898 a 1902, visita como tal la República Argentina en noviembre de 1900."],["Canadá","calle","Canadá: país americano. Capital: Ottawa."],["Canadá","plaza","Canadá: país americano. Capital: Ottawa."],["Doctor Benjamín Canard","calle","Benjamín Canard (1844 a 1903), jurisconsulto; miembro de la Municipalidad de Buenos Aires por la parroquia de San Nicolás; presidente de la Comisión Municipal en 1874 y 1880; diputado provincial entre 1880 y 1886; ministro de Gobierno de Buenos Aires con el doctor Carlos D´Amico."],["Islas Canarias","cantero central","Islas Canarias: archipiélago español en el Atlántico, dividido en dos provincias: Santa Cruz de Tenerife y Las Palmas."],["Francisco Canaro","Patio de recreación","Francisco Canaro: nombre artístico de Francisco Canarozzo (1888 a 1964), violinista, compositor y director de orquesta uruguayo; en 1940 se nacionaliza argentino. Es el creador del tango-milonga y también uno de los que más contribuye a la extensión y popularidad del tango en Europa. Autor de Sentimiento gaucho, Madreselva y Adiós pampa mía, entre otras."],["Padre Canavery","calle","Tomás O. Canaveri (1839 a 1913), sacerdote; capellán del Ejército desde 1852; participa como tal en la guerra contra el Paraguay y su acción inspira al médico y poeta Ricardo Gutiérrez para componer su poema El Misionero."],["Candelaria","calle","Candelaria: departamento, ciudad y puerto de Misiones, fundado por Juan de Ayolas en 1537 y trasladado en 1665 al lugar que hoy ocupa."],["Miguel Cané","calle","Miguel Cané (1851 a 1905), escritor; autor de Juvenilia."],["Cangallo","calle","Cangallo: pueblo del Perú en el departamento de Ayacucho que era, en su mayor parte, de población aborigen y que, al sublevarse por tercera vez en apoyo a la causa de la Independencia, es destruido por los realistas el 17 de diciembre de 1821."],["Cangayé","calle","Cangayé: reducción para indios mocovíes fundada en la actual provincia del Chaco por Francisco Gabino Arias en 1781."],["Cantilo","calle","José María Cantilo (1816 a 1872), químico y periodista; fundador de los periódicos El siglo, El correo del domingo y La verdad; diputado provincial de Buenos Aires y miembro de la Convención de esa provincia en 1860; miembro de la Comisión Sanitaria durante la guerra contra el Paraguay y organizador de la Comisión Popular en la epidemia de fiebre amarilla de 1871."],["José Luis Cantilo","calle","José Luis Cantilo (1871 a 1944), profesor, periodista y político radical; intendente municipal de Buenos Aires desde el 4 de diciembre de 1919 hasta el 25 de octubre de 1921 y del 14 de noviembre de 1928 al 6 de septiembre de 1930; gobernador de Buenos Aires de 1922 a 1926."],["Padre Gaspar Cañada","plazoleta","Gaspar Cañada (1892 a 1965), sacerdote; párroco de Santa Inés desde 1932, capellán del Hospital Alvear; procurador y vicario general de la Orden de los Camilos en Roma; autor de Vida popular de San Camilo de Lelis."],["Cañada de Gómez","calle","Cañada de Gómez: ciudad del departamento de Iriondo, en la provincia de Santa Fe, en cuyas inmediaciones, luego de la batalla de Pavón, Mitre derrota el 22 de noviembre de 1861 al ejército de la Confederación al mando del general Virasoro."],["Cañonera América","calle","Cañonera América: nave que pertenecía a la armada del almirante Brown en 1814."],["Cañuelas","calle","Cañuelas: ciudad y partido de la provincia de Buenos Aires."],["Capdevila","calle","José Antonio Capdevila (1765 a 1841), comerciante y funcionario; regidor y alférez real en 1807, se destaca por su acción durante la Defensa de Buenos Aires. Es éste un nombre tradicional de la ciudad, pues entre 1808 y 1822 se denominó así la actual calle Chile."],["Arturo Capdevila","calle","Arturo Capdevila (1889 a 1967), escritor y poeta; autor de Melpómene, Babel y el castellano, El gran regidor Segovia y Soliloquio del alma en la noche."],["Caperucita","calle","Caperucita Roja: cuento del escritor francés Carlos Perrault."],["La Capital","calle","Capital Federal: se refiere a la ciudad de Buenos Aires, declarada Capital Federal de la República Argentina por Ley del 21 de septiembre de 1880, promulgada el 6 de diciembre del mismo año."],["Carabelas","calle","Carabelas: recuerda a la Santa María, la Niña y la Pinta, las tres embarcaciones que componían la expedición de Cristóbal Colón, que descubre América el 12 de octubre de 1492."],["Carabobo","avenida","Carabobo: conmemora las dos batallas de ese nombre en las que Bolívar vence al ejército realista el 18 de mayo de 1814 y el 24 de junio de 1821."],["Caracas","calle","Caracas: ciudad capital de Venezuela."],["Caranday","calle","Caranday o Carandaí: nombre guaraní de una palma de mucha altura que crece en las orillas de ríos y lagunas, y que abunda en el Litoral y también en Orán, Salta; es originaria del Brasil y se la encuentra en toda América del Sur."],["Carapachay","calle","Carapachay o Carapachaí: río del Delta del Paraná. Es una voz guaraní con la que se designaba al delta y por extensión a sus habitantes."],["Caras y Caretas","plazoleta","Caras y Caretas: revista que marca una época en la gráfica argentina; aparece el 8 de octubre de 1898 y se mantiene hasta el 17 de octubre de 1939."],["Carbajal","calle","Baltasar Carbajal (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["José E. Carballido","calle","José Escolástico Carballido (1814 a 1871), teniente coronel; combate en Quebracho Herrado, Famaillá y Caaguazú; comandante militar de San Nicolás de los Arroyos en 1857; combate en Cepeda y Pavón; presidente de una de las comisiones populares de Higiene durante la epidemia de fiebre amarilla de 1871; es víctima de la enfermedad."],["Comandante Francisco Carbonari","calle","Francisco Carbonari (1867 a 1949), bombero; jefe de los Bomberos Voluntarios de la Boca, entidad en la cual se desempeña durante sesenta años."],["Carlos Carboni","cantero central","Carlos Carbone (1901 a 1989), maestro fileteador de origen italiano; es, entre los fileteadores, uno de los más finos y armoniosos. Sus “tablas” fileteadas se exhiben en el Museo de la Ciudad y en el Museo de Arte Contemporáneo Luís González Robles de la Universidad de Alcalá de Henares (España)."],["Ramón J. Cárcano","calle","Ramón José Cárcano (1860 a 1946), jurisconsulto, historiador y funcionario; ministro de Gobierno de Córdoba en 1886; director general de Correos y Telégrafos de la Nación en 1887; interventor nacional en San Juan en 1913; dos veces gobernador de Córdoba; decano de la Facultad de Agronomía y Veterinaria de 1921 a 1926; embajador en el Brasil de 1933 a 1938; autor de La guerra del Paraguay. Orígenes y causas y Mis primeros ochenta años."],["Ramón J. Cárcano","plaza","Ramón José Cárcano (1860 a 1946), jurisconsulto, historiador y funcionario; ministro de Gobierno de Córdoba en 1886; director general de Correos y Telégrafos de la Nación en 1887; interventor nacional en San Juan en 1913; dos veces gobernador de Córdoba; decano de la Facultad de Agronomía y Veterinaria de 1921 a 1926; embajador en el Brasil de 1933 a 1938; autor de La guerra del Paraguay. Orígenes y causas y Mis primeros ochenta años."],["De la Cárcova","calle","Tiburcio de la Cárcova (1809 a 1868), jurisconsulto; censor de la Academia de Jurisprudencia Teórico-Práctica en 1838; fiscal de la misma en 1839 y vicepresidente en 1840; juez de primera instancia entre 1844 y 1852; diputado a la Legislatura de Buenos Aires de 1844 a 1851; víctima del cólera en la epidemia de 1868."],["El Cardenal","calle","Cardenal: nombre vulgar con el que se designa a distintas especies de pájaros y que se adopta por el copete rojo que su mayoría posee en la cabeza."],["Coronel Cárdenas","calle","Baltasar Cárdenas (¿-?), militar; natural del Alto Perú, fue uno de los mejores guerrilleros que enfrenta al general realista Goyeneche; combate en Salta, Vilcapugio, Ayohuma, Cotagaita y Tupiza."],["Cardoso","calle","Valentín Cardoso (1792 a 1865), militar; combate en Ayohuma y Famaillá; comandante general del Parque de Buenos Aires en 1853; convencional constituyente de Buenos Aires en 1854."],["Carhué","calle","Carhué: ciudad cabecera del partido de Adolfo Alsina, provincia de Buenos Aires."],["Caricancha","calle","Caricancha, Coricanche o Koricancha: voz quechua que significa “Cerco de Oro”, y con la que se designa al templo del Sol, erigido en el Cuzco durante el reinado del Inca Pachacutec, y sobre cuyos restos levantaron los españoles el templo de Santo Domingo. En ningún sitio como en éste aparece tan próximo el nexo entre los dos pasados del Perú, el indígena y el hispánico, con la superposición del templo cristiano al del Sol."],["Del Carmen","calle","Nuestra Señora del Carmen: advocación de la Virgen María cuya imagen era venerada por los eremitas del desierto del monte Carmelo en Palestina, y desde donde se extendió por todo el mundo, principalmente por España. Esta calle se denomina así en razón de la cercanía en que se encuentra la capilla Nuestra Señora del Carmen, ubicada en Rodríguez Peña, entre Córdoba y Paraguay."],["Caroya","calle","Caroya: colonia próxima a la ciudad de Jesús María, en la provincia de Córdoba."],["Elías Cárpena","cantero central","Elías Cárpena (1897 a 1988), escritor y poeta; autor de El cuatrero Montenegro, El doradillo, El inglés del bañado y Romances del pago de la Matanza."],["Alejo Carpentier","cantero central","Alejo Carpentier (1904 a 1980), escritor, novelista y diplomático cubano; autor de La música en Cuba, El reino de este mundo, Los pasos perdidos, El siglo de las luces, El recurso del método, La consagración de la primavera y El arpa y la sombra."],["El Carpintero","calle","Carpintero: nombre vulgar aplicado a varias aves del orden de los Piciformes, que deben su denominación al hecho de que al extraer su alimento de la corteza de los árboles y excavar su nido en la madera, valiéndose de su fuerte y agudo pico, producen un característico ruido semejante a un martilleo."],["Adolfo P. Carranza","calle","Adolfo P. Carranza (1857 a 1914), historiador; fundador de la Revista Nacional y del Museo Histórico Nacional que dirigió durante veinticinco años; autor de Razón del nombre de las calles, plazas y parques de la ciudad de Buenos Aires (1ª ed.: Editores Ivaldi-Checchi, 1895; 2ª ed., G. Kraft, 1895; 3ª ed., G. Kraft, 1910)."],["Ángel Justiniano Carranza","calle","Ángel Justiniano Carranza (1834 a 1899), historiador y funcionario; autor de Campañas Navales de la República Argentina, El general Lavalle ante la justicia póstuma y El abrazo de Yatasto (San Martín y Belgrano); redactor del Código de la Armada Nacional."],["Carlos Carranza","calle","Carlos Carranza (1842 a 1913), diplomático y funcionario; participa en la guerra contra el Paraguay como ayudante de Mitre; cónsul general en los Estados Unidos en 1879; miembro de la Comisión Municipal de Buenos Aires en 1902, interviene en el proyecto de apertura de la Avenida de Mayo."],["Carrasco","avenida","Pedro Buenaventura Carrasco (1780 a 1839), médico; diputado por Cochabamba en el Congreso de Tucumán, se incorpora al mismo el 17 de agosto de 1816, y es nombrado presidente en las sesiones de septiembre y vicepresidente cuando el Congreso se reúne en Buenos Aires en 1818."],["Ingeniero Agrónomo Benito J. Carrasco","parque","Benito J. Carrasco (1877 a 1954), agrónomo; director de Paseos de la Municipalidad de Buenos Aires de 1914 a 1918; presidente honorario de la Escuela de Jardinería; autor de Parques y Jardines y Anfiteatro para música en el Parque Lezama."],["Santiago de las Carreras","calle","Santiago de las Carreras (1788 a 1815), coronel; gobernador político y militar de Córdoba de 1811 a 1813; combate en Cucha Cucha, Membrillar, Tres Montes y Río Claro; gobernador de Santa Cruz de la Sierra en reemplazo de Warnes."],["Irma Carrica","cantero central","Irma Leonor Laciar de Carrica (1926 a 1977), enfermera, docente y gremialista; se desempeña como profesional y representante gremial en el Hospital Alejandro Posadas y en el Hospital Rivadavia; docente en la Oficina Panamericana de la Salud y en la Universidad de Buenos Aires; miembro de la Asociación de Trabajadores del Estado. Es secuestrada el 18 de abril de 1977. Permanece desaparecida."],["Evaristo N° 838. Carriego","plazoleta","Evaristo Carriego (1883 a 1912), poeta; autor de Misas herejes, Íntimas y Los que pasan."],["Hugo del Carril","cantero central","Piero Bruno Hugo Fontana (1912 a 1989), artísticamente conocido por Hugo del Carril. Actor, cantor y compositor de tangos, director y productor cinematográfico. Actúa en renombradas películas como Los muchachos de antes no usaban gomina, La vida de Carlos Gardel, Tres anclados en París y Pobre mi madre querida, entre otras. En 1949 graba la popular versión de la marcha Los muchachos peronistas. Como director y productor dirige Historias del 900, Las aguas bajan turbias y Yo maté a Facundo."],["Hugo del Carril","pasaje peatonal","Piero Bruno Hugo Fontana (1912 a 1989), artísticamente conocido por Hugo del Carril. Actor, cantor y compositor de tangos, director y productor cinematográfico. Actúa en renombradas películas como Los muchachos de antes no usaban gomina, La vida de Carlos Gardel, Tres anclados en París y Pobre mi madre querida, entre otras. En 1949 graba la popular versión de la marcha Los muchachos peronistas. Como director y productor dirige Historias del 900, Las aguas bajan turbias y Yo maté a Facundo."],["Salvador María del Bm N° 5.724. Carril","plaza","Salvador María del Carril (1798 a 1883), jurisconsulto; gobernador de San Juan de 1823 a 1825; ministro de Gobierno y Relaciones Exteriores de Lavalle; diputado en el Congreso de 1853; vicepresidente de la República bajo la presidencia de Urquiza de 1854 a 1860."],["Doctor Ramón Carrillo","calle","Ramón Carrillo (1906 a 1956), médico neurocirujano; secretario de Salud Pública de la Nación de 1946 a 1949; primer ministro de Salud desde 1949 hasta 1954; autor de Política Sanitaria Argentina y Teoría del Hospital."],["Casacuberta","calle","Juan Antonio Casacuberta (1796 a 1871), coronel; combate en Cepeda y Cañada de la Cruz. Participa en la expedición a la sierra de Tandil con Martín Rodríguez en 1823 y en la de Bahía Blanca en 1824. Combate en la guerra contra el Brasil y en Famaillá; acompaña los restos de Lavalle hasta Potosí."],["Casa Cuna","plaza","Casa Cuna: institución creada por el virrey Juan José Vértiz en 1779 con el nombre de Casa de Niños Expósitos, con el fin de alojar a chicos abandonados por sus madres. Recibe en 1920 el nombre de Casa Cuna y en 1962, por decreto del Ministerio de Asistencia Social y Salud Pública, se le da oficialmente el nombre de Hospital Doctor Pedro de Elizalde. En 1963, pasa a la órbita de la Municipalidad de Buenos Aires, como Hospital Municipal de Pediatría."],["La Casa del Ángel","cantero central","La Casa del Ángel: película dirigida por Leopoldo Torre Nilson; con la actuación de Elsa Daniel y Lautaro Murúa, en 1957."],["Casafoust","calle","Carlos Adolfo Cassaffousth (1854 a 1900), ingeniero; director técnico de las obras del dique San Roque y constructor del canal de la Cuarteada en Santiago del Estero."],["Casares","avenida","Carlos Casares (1830 a 1883), hacendado; gobernador de Buenos Aires de 1875 a 1878; director y presidente del Banco de la Provincia de Buenos Aires; presidente de la Sociedad Rural Argentina."],["Intendente Casares","plaza","Alberto Casares (1855 a 1906), funcionario; intendente municipal de la ciudad de Buenos Aires desde el 20 de octubre de 1902 hasta el 9 de noviembre de 1904; nombrado por segunda vez para ejercer ese cargo el 22 de mayo de 1906, su muerte interrumpe su gestión el 11 de noviembre del mismo año."],["Casco","calle","Víctor Casco de Mendoza (?-¿1615?), militar; acompaña a Garay en la fundación de Buenos Aires en 1580."],["Doctor Horacio Casco","calle","Horacio Casco (?-1931), jurisconsulto y funcionario; intendente municipal de la ciudad de Buenos Aires del 3 de mayo de 1927 al 12 de octubre de 1928."],["Caseros","avenida","Caseros: batalla librada entre las fuerzas del brigadier general Juan Manuel de Rosas y el general Justo José de Urquiza el 3 de febrero de 1852, como consecuencia de la cual Rosas queda destituido de su cargo de gobernador de Buenos Aires."],["Juan Carlos Castagnino","espacio verde","Juan Carlos Castagnino (1908 a 1972), pintor y arquitecto; obtiene el primer Premio Nacional en 1948 por el óleo Hombre del río y el Premio de Honor del Salón Nacional de Artes Plásticas de 1956 por El Tango; ilustra la edición del Martín Fierro publicada por Eudeba en 1962; autor del mural La ofrenda de la nueva tierra de la Sociedad Hebraica Argentina y de los óleos Tierra adentro y Trabajadores de la curtiembre, entre tantos otros."],["Castañares","avenida","Castañares: nombre del campo donde se libra la batalla de Salta, en la que el general Belgrano vence a las fuerzas realistas el 20 de febrero de 1813."],["Castañeda","calle","Francisco de Paula Castañeda (1776 a 1832), sacerdote y periodista; enfrentado con Rivadavia, publica entre otros, los siguientes periódicos: La verdad desnuda, Desengañador gauchi-político, El padre Castañeda y Despertador Teofilantrópico Místico Político; empeñoso propagador de la enseñanza primaria en el Río de la Plata."],["Castañón","calle","Bernardo Castañón (1787 a 1859), coronel; combate durante las Invasiones Inglesas; edecán de Rivadavia, Vicente López, Dorrego, Rosas y Balcarce."],["Alfonso R. Castelao","plazoleta","Alfonso Daniel Rodríguez Castelao (1886 a 1950), escritor, dibujante y político español; diputado en las Cortes Constituyentes en 1931 y 1936, exiliado en la Argentina al finalizar la Guerra Civil Española; autor de Cousas, Cousas da vida, Coarenta homes por des réas y Os dóus de sempre."],["Emilio Castelar","calle","Emilio Castelar y Ripoll (1832 a 1899), político y escritor español; ministro de Estado y presidente del Poder Ejecutivo español al proclamarse la República; autor de Historia de Europa durante el siglo XIX y Vida de Lord Byron."],["Joaquín Castellanos","calle","Joaquín Castellanos (1861 a 1932), escritor y político; autor de El borracho y Marcas a fuego; gobernador de Salta."],["Castelli","calle","Juan José Castelli (1764 a 1812), jurisconsulto; vocal de la Primera Junta de Gobierno."],["Castelli","plaza","Juan José Castelli (1764 a 1812), jurisconsulto; vocal de la Primera Junta de Gobierno."],["Castex","calle","Alejo Castex (1766 a 1841), jurisconsulto; secretario del Consulado de 1810 a 1814; Síndico Procurador General en 1816; diputado al Congreso interviene en la sanción de la Constitución de 1826. Vicente José Castex (1762 a 1846), hacendado; combate durante las Invasiones Inglesas; diputado provincial en 1821. Homenaje conjunto a los hermanos Castex. Si bien la bibliografía existente sobre nomenclatura urbana asigna esta calle solamente a Alejo, entendemos que es éste un homenaje conjunto, pues la Ordenanza denomina Castex “a la calle conocida por Castex”, es decir que confirma un nombre tradicional. Esta denominación de “Castex”, anterior a 1904, se refiere a Vicente, quien en 1801 adquirió una quinta en este lugar de la ciudad y con cuyo nombre se conoció a esta calle hasta que fue oficializado por la Municipalidad."],["Doctor Mariano R. Castex","plazoleta","Mariano Rafael Castex (1886 a 1968), médico; rector de la Universidad de Buenos Aires en 1931; presidente de la Academia Nacional de Medicina; autor de Hemiplejías sensitivas, Sífilis hereditaria tardía, La digitaloterapia y La hipertensión arterial."],["Mariscal Ramón Castilla","calle","Ramón Castilla (1797 a 1867), militar peruano; combate en Ayacucho; presidente del Perú de 1845 a 1851; presidente provisional entre 1855 y 1858 y nuevamente constitucional de 1858 a 1862."],["Castillo","calle","Pedro del Castillo (¿1521?-1563), conquistador español; fundador de la ciudad de Mendoza en 1561."],["Cátulo Castillo","calle","Cátulo Ovidio González Castillo (1906 a 1975), poeta, músico, compositor, autor teatral, escritor, guionista cinematográfico, periodista y dirigente de la Sociedad Argentina de Autores y Compositores de Música; autor de María, Café de los Angelitos, La última curda, Tinta roja, A Homero y El último café; compositor de Organito de la tarde, Silbando y Viejo ciego."],["Juan del Castillo","calle","Juan del Castillo (1596 a 1628), sacerdote y misionero jesuita; evangeliza en las reducciones del Uruguay; acompaña al padre Roque González de Santa Cruz en la fundación de la Asunción de Yjuhí, donde muere en manos de los indios del hechicero Ñezú; fue beatificado en 1934 junto con los padres Roque González de Santa Cruz y Alonso Rodríguez."],["Presidente Ramón S. Castillo","avenida","Ramón S. Castillo (1873 a 1944), jurisconsulto; vicepresidente de la República en la fórmula presidencial que encabeza Roberto M. Ortiz, ejerce la primera magistratura desde julio de 1940 y es nombrado presidente de la Nación al renunciar Ortiz por problemas de salud; ocupa el cargo hasta el 4 de junio de 1943."],["Castro","calle","Manuel Antonio de Castro (1776 a 1832), jurisconsulto; director de la Academia de Jurisprudencia en 1815; fundador del periódico El Observador Americano; gobernador intendente de Córdoba de 1817 a 1820; diputado por Buenos Aires en el Congreso de 1824."],["Emilio Castro","avenida","Emilio Castro (1821 a 1899), político y militar; presidente del Ferrocarril del Oeste; gobernador de Buenos Aires de 1869 a 1872; presidente de la Asociación Bernardino Rivadavia y de la Biblioteca Popular del Municipio."],["Juan de Castro","calle","Juan Manuel de Castro Carreño (¿-?), funcionario colonial; teniente ministro real de la hacienda de San Juan de 1793 a 1803 y de 1810 a 1812; en ocasión de la primera invasión inglesa hace una donación de sus sueldos mientras durase la guerra contra Inglaterra."],["Rosalía de Castro","calle","Rosalía de Castro (1837 a 1885), poetisa gallega; autora de Cantares gallegos y Follas novas."],["Castro Barros","calle","Legajo 3, 1882. Obras Públicas). Pedro Ignacio Castro Barros (1777 a 1849), sacerdote; diputado por La Rioja en el Congreso de Tucumán."],["Villa de las Catalinas","plazoleta","Villa de las Catalinas: primera denominación que tuvo el barrio Villa Urquiza; fundado el 2 de octubre de 1887 por don Francisco Seeber."],["Catalinas Sur","espacio verde","Catalinas Sur: nombre con que se conoció el actual barrio Alfredo Palacios y que se origina en la denominación con la que se identificaba a los galpones y depósitos portuarios de la empresa Muelles y Depósitos de las Catalinas en esta zona de La Boca. El agregado de la palabra “Sur”, los distinguía de los depósitos del “Norte”, ubicados en la cercanía del Convento de Santa Catalina de Siena."],["De Cataluña","plaza","Cataluña: región del nordeste de España, que se divide en las provincias de Barcelona, Gerona, Lérida y Tarragona."],["Provincia de Catamarca","cantero central","Catamarca: ciudad y provincia de la República Argentina."],["Catania","calle","Catania: ciudad y provincia de Italia, en la isla de Sicilia. 14 DE JULIO (calle). Ordenanza del 1-4-1924, BB. MM. Nros. 19, 69 y 80. 14 de Julio de 1789: fecha de la toma de la Bastilla, durante la Revolución Francesa."],["Catriel","calle","Cipriano Catriel (?-1874), cacique indio; combate en las fuerzas nacionales contra Calfucurá y con el general Rivas en 1872 en San Carlos; muere decapitado en 1874."],["La Cautiva","calle","La Cautiva: poema de Esteban Echeverría publicado en 1837."],["Ildefonso Félix Cavagna Martínez","plaza","Ildefonso Félix Cavagna Martínez (1905 a 1971), jurisconsulto; Escribano Mayor de la provincia de Buenos Aires; en 1946 elabora las bases que dan origen al IAPI (Instituto Argentino de Promoción del Intercambio); presidente del Banco Nación de 1946 a 1949; ministro de Relaciones Exteriores en 1955; autor de Función de la tierra rural."],["Cavia","calle","Pedro Feliciano Sáinz de Cavia (1776 a 1848), escribano y periodista; redactor de El Avisador Patriota, El Americano y El Argentino; acompaña a Belgrano en su expedición al Paraguay en 1811; diputado por Montevideo a la Asamblea en 1814 y por Corrientes al Congreso de 1826."],["Cayastá","calle","Cayastá: localidad del departamento de Garay, en la provincia de Santa Fe, y lugar donde Juan de Garay fundó el 15 de noviembre de 1573 la ciudad de Santa Fe, que permaneció en esa ubicación hasta que se la trasladó a su actual emplazamiento entre 1650 y 1660."],["Cazadores","calle","Cazadores Correntinos: nombre del cuerpo enviado por la provincia de Corrientes para combatir contra la invasión inglesa de 1806."],["Higinio Cazón","cantero central","Higinio D. Cazón (1866 a 1914), poeta y payador; autor de Alegrías y Pesares, donde aparece su composición “Bajo el ombú copioso”. El 30 de junio de 1896 protagoniza una célebre payada con Gabino Ezeiza en el escenario del teatro Doria. Su nombre perdura en la letra del tango Café de los Angelitos (“bar de Gabino y Cazón”) de Cátulo Castillo."],["El Ceibo","calle","Ceibo: árbol de origen americano cuyo nombre científico es Erithrina Crista Galli, ya que sus hermosas flores rojas recuerdan la cresta del gallo. La suya es la flor nacional argentina."],["Centenario","calle","Centenario: homenaje a la Revolución de Mayo en ese aniversario. CENTENERA, DEL BARCO véase BARCO CENTENERA."],["Centenario","parque","Centenario: homenaje a la Revolución de Mayo en ese aniversario. CENTENERA, DEL BARCO véase BARCO CENTENERA."],["Julián Centeya","plazoleta","Julián Centeya: seudónimo de Amleto Enrique Vergiat (1910 a 1974), escritor y poeta porteño de origen italiano; autor de La musa mistonga, El misterio del tango y de los poemas de los discos Antología lunfarda y El hombre gris de Buenos Aires."],["Rodrigo de Cepeda y Ahumada","calle","Rodrigo de Cepeda y Ahumada (1511-?), militar; era hermano de Santa Teresa de Jesús; toma parte de la expedición de don Pedro de Mendoza, encontrándose presente en la primera fundación de Buenos Aires; acompañó a Juan de Ayolas en su expedición al Chaco."],["Ceretti","calle","Bartolomé Ceretti (?-1826), mayor de marina de origen genovés; combate en San Nicolás y Arroyo de la China; asiste al sitio y toma de Montevideo en 1814; combate en la guerra contra el Brasil, falleciendo en acción durante el ataque a Colonia."],["General Daniel Cerri","calle","Daniel Cerri (1841 a 1914), militar de origen italiano; combate en Pavón y en la guerra contra el Paraguay; actúa en las comandancias de frontera en la lucha contra el indio; asiste a las campañas al desierto de Levalle y Roca; gobernador del territorio de Los Andes en 1900."],["Cerrillos","calle","Cerrillos: nombre del establecimiento de campo que en el partido de Monte tuvo don Juan Manuel de Rosas."],["Cerrito","calle","Cerrito: batalla librada en la República Oriental del Uruguay, entre las fuerzas del general Rondeau y las del mariscal Gaspar de Vigodet, el 31 de diciembre de 1812."],["El Cerro","calle","El Cerro: cerro y paraje del departamento de Curuzú Cuatiá, en la provincia de Corrientes."],["Cervantes","calle","Miguel de Cervantes Saavedra (1547 a 1616), escritor español; autor de Don Quijote de la Mancha."],["Cerviño","avenida","Pedro Antonio Cerviño (1757 a 1816), ingeniero; miembro de la comisión demarcadora de límites americanos entre España y Portugal; director de la Academia de Náutica en 1799; director de la Academia de Matemáticas en 1813; autor del Plano Topográfico de la Ciudad de Buenos Aires de 1814."],["Céspedes","calle","Francisco de Céspedes (¿-?), funcionario; gobernador del Río de la Plata desde 1624 hasta 1631."],["Virrey Cevallos","calle","Pedro Antonio de Cevallos (1715 a 1778), militar; gobernador y primer virrey del Río de la Plata de 1756 a 1766 y de 1776 a 1778, respectivamente."],["Parque Chacabuco","barrio","Este barrio comienza a identificarse así desde 1903, cuando al denominarse “Chacabuco” al parque anteriormente señalado, la denominación se hace extensiva popularmente a la zona que lo circunda. Chacabuco: batalla en la que el general San Martín vence a los realistas en Chile, el 12 de febrero de 1817."],["Nº 2.776. Chacarita de los Colegiales","paseo","Chacarita de los Colegiales: chacarita es el diminutivo de la voz quechua chácara o chacra. Los orígenes de este nombre en Buenos Aires se remontan al siglo XVIII, cuando el Real Colegio Convictorio Carolino, luego de la expulsión de los jesuitas en 1767, toma posesión de este lugar y lo utiliza para las vacaciones de sus estudiantes, proviniendo de allí el agregado de “Colegiales”. Este Colegio de San Carlos se denominará más tarde Colegio de la Unión del Sud, de Ciencias Morales, y finalmente Colegio Nacional de Buenos Aires."],["El Chacho","calle","El Chacho: trabajo de Domingo Faustino Sarmiento que se refiere a don Ángel Vicente Peñaloza, caudillo riojano."],["Provincia del Chaco","cantero central","Chaco: provincia de la República Argentina. Capital: Resistencia."],["Campaña del Chaco","plazoleta","Campaña del Chaco: homenaje a las distintas fuerzas que desde 1854 participaron en las distintas campañas de incorporación de los territorios del Chaco, extendiendo hacia el norte las fronteras hasta alcanzar sus límites actuales."],["Carlos Chagas","calle","Carlos Chagas (1879 a 1934), médico patólogo y epidemiólogo brasileño, descubridor de la enfermedad llamada tripanosomiasis americana, conocida como Mal de Chagas."],["Chajarí","calle","Chajarí: arroyo del departamento de Monte Caseros, Corrientes."],["Chamical","calle","Chamical: lugar de la provincia de Salta donde tuvieron lugar algunos combates de los gauchos de Güemes, y donde se encuentra la capilla de San Francisco de Chamical, en cuyo cementerio adyacente fue sepultado el caudillo norteño en 1821, permaneciendo allí hasta que en 1823 fue trasladado a la Catedral de Salta."],["Padre Marcelino Champagnat","plazoleta","José Benito Marcelino Champagnat (1789 a 1840), sacerdote y beato francés; fundador del Instituto de los Hermanos Maristas de la Enseñanza, en 1817."],["Charcas","calle","Charcas: ciudad del Alto Perú (Bolivia) que recibió sucesivamente los nombres de Chuquisaca, Charcas, La Plata y, actualmente, Sucre, capital del departamento de Charcas. Con el nombre de Chuquisaca fue fundada en 1539 por Pedro Auzúres. Fue asiento de la Real Audiencia y de una de las universidades más antiguas de América."],["Charlone","calle","Juan Bautista Charlone (1826 a 1866), coronel de origen italiano; combate en Caseros incorporado a la División Oriental, en Pavón, Cañada de Gómez y en la guerra del Paraguay, donde fallece como consecuencia de las heridas recibidas en la batalla de Curupaytí."],["Charrúa","calle","Charrúa: aborígenes que ocupaban la costa septentrional del Río de la Plata y las márgenes del río Uruguay."],["Parque Chas","barrio","Francisco Chas (¿?-1890), hacendado; funda un establecimiento agropecuario en el partido de General Belgrano, cerca de la estación que lleva su nombre. Vicente Chas (1845 a 1928), hijo del hacendado Francisco Chas; concejal de Buenos Aires de 1878 a 1880, senador y presidente del Banco Hipotecario; propietario de los terrenos que dieron origen al barrio por Ordenanza 1129 del 29 de septiembre de 1925. Francisco Chas (1897 a 1954), jurisconsulto y ganadero; actuó en diversas obras de carácter social y humanitario. Dio impulso al barrio porteño que lleva el nombre de sus mayores."],["Chascomús","calle","Chascomús: ciudad y partido de la provincia de Buenos Aires."],["El Chasque","calle","Chasque: chasque o chasqui es una voz quechua que significa correo o mensajero, y con la cual se denominaba al jinete que conducía comunicaciones o llevaba un encargo urgente."],["Juan Chassaing","calle","Juan Chassaing (1839 a 1864), jurisconsulto y periodista; redactor de El Nacional y fundador de El Pueblo; autor de las estrofas de A mi Bandera."],["Jorge Chávez","calle","Jorge Chávez (1887 a 1910), aviador peruano; precursor de la aviación, fallece el 23 de septiembre de 1910 cuando consumaba su cruce aéreo de los Alpes desde Francia hacia Italia."],["Andrés Chazarreta","plazoleta","Andrés A. Chazarreta (1876 a 1960), músico; compila y transcribe numerosas obras folclóricas, entre ellas la Zamba de Vargas, La Lorencita, El Marote y El Remedio."],["Checoslovaquia","calle","Checoslovaquia: país europeo. Capital: Praga. Desde 1993 dividida en República Checa (Capital: Praga) y República de Eslovaquia (Capital: Bratislava).18."],["General Indalecio Chenaut","avenida","Indalecio Chenaut (1808 a 1871), militar; combate en la guerra contra el Brasil, la Tablada, Oncativo, Caseros y en la guerra contra el Paraguay."],["Fenia Chertkoff","espacio verde","Fenia Chertkoff de Repetto (1869 a 1928), feminista, educadora y escritora de origen ruso; impulsa el desarrollo de bibliotecas; funda el centro Socialista Femenino para la defensa de los derechos civiles y sociales de las mujeres en 1902 y crea la Asociación de Bibliotecas y recreos infantiles en 1913; esposa del dirigente socialista Nicolás Repetto."],["Chiclana","avenida","Feliciano Antonio Chiclana (1771 a 1826), coronel y jurisconsulto; auditor del Ejército Auxiliar del Perú en 1810, gobernador intendente interino de Salta y Potosí; miembro del primer Triunvirato."],["Chicoana","calle","Chicoana: departamento de la provincia de Salta."],["Santiago José Chierico","espacio público","Santiago José Chierico (1891 a 1974) escultor; obtiene el premio del Salón Nacional en 1935; el segundo Premio Municipal en 1940 y el primer premio de la Comisión Nacional de Cultura en 1942; entre sus obras se destacan los bustos de Castelar y Miguel Cané y los monumentos La Cautiva, La Madre y Florencio Sánchez."],["Coronel Martiniano Chilavert","calle","Martiniano Chilavert (1798 a 1852), militar; combate en la guerra contra el Brasil y a su fin se enrola en las fuerzas de Lavalle; en 1847 ofrece sus servicios a Rosas combatiendo en Caseros como jefe de la artillería; considerado traidor por Urquiza es ejecutado el 4 de febrero."],["República de Chile","plaza","Chile: país sudamericano. Capital: Santiago de Chile."],["Chilecito","calle","Chilecito: ciudad y departamento de la provincia de La Rioja."],["Chimborazo","calle","Chimborazo: pico de la Cordillera de los Andes, en Ecuador."],["China","calle","República Popular China: país asiático. Capital: Pekín."],["Chiriguanos","calle","Chiriguanos: aborígenes del grupo guaranítico que habitaban el Chaco y el sur de Bolivia."],["Chirimay","calle","Chirimay: localidad de la provincia de Misiones."],["Chivilcoy","calle","Chivilcoy: ciudad de la provincia de Buenos Aires."],["Chonino","calle","Chonino: nombre del perro de la Policía Federal matrícula N° 716; herido y muerto en un enfrentamiento con delincuentes el 2 de junio de 1983. La actitud del animal posibilitó que el agente Luis Alberto Sibert salvase su vida."],["Chorroarín","avenida","Luis José de Chorroarín (1757 a 1823), sacerdote; rector del Real Colegio de San Carlos en 1791; director de la Biblioteca Pública de 1811 a 1821, la inaugura el 16 de marzo de 1812; diputado en la Asamblea de 1813 y del Congreso reunido en Buenos Aires en 1817, del cual es presidente al año siguiente."],["Provincia del Chubut","cantero central","Chubut: provincia de la República Argentina. Capital: Rawson."],["Ismael Chukri","plazoleta","Ismael Chukri (1937 a 1977), deportista; representa entre 1960 y 1963 a la Argentina en competencias internacionales de ciclismo, logrando varios trofeos. A raíz de su militancia en el peronismo en los barrios de Villa Lugano y Villa Riachuelo, es detenido en septiembre de 1977 y aún permanece desaparecido. En su memoria, el Club Boca Juniors organiza el Gran Premio de Ciclismo Ismael Chukri y desde 2001, el Club Lomas de Zamora, el Gran Premio Ismael Chukri."],["Chumbicha","calle","Chumbicha: localidad de la provincia de Catamarca."],["Profesor Doctor Pedro Chutro","calle","Pedro Chutro (1880 a 1937), médico; profesor de Clínica Quirúrgica de la Facultad de Medicina de Buenos Aires; fundador de la Sociedad de Cirugía de Buenos Aires; miembro de la Academia de Medicina de París; autor de Clínica Quirúrgica; se desempeñó en los hospitales San Roque (hoy Ramos Mejía), Álvarez y Durand."],["Cid Campeador","plazoleta","Rodrigo Díaz de Vivar (1043 a 1099), noble castellano, llamado Cid (palabra de origen árabe que significa señor) y Campeador a raíz de sus acciones en combate. Encabeza la epopeya contra los moros que ocupaban la península hispánica. En destacada acción, conquista la ciudad de Valencia en 1094. Sus virtudes caballerescas, su heroísmo y lealtad fueron fuente de inspiración de leyendas y poesías, que lo han tomado como símbolo del héroe universal. El Cantar de Mio Cid (h.1140) es considerado el primer monumento de la literatura española. CIENCIA Y LA CULTURA ÁRABES, DE LA véase ÁRABES, DE LA CIENCIA."],["De las y la Cultura. Ciencias","calle","Ciencias: homenaje a la ciencia, que es el conocimiento de las cosas por sus principios y causas. 5 DE JULIO (calle). Ordenanza del 27-11-1893. 5 de Julio de 1807: fecha del ataque y defensa de Buenos Aires durante la segunda invasión inglesa. La exitosa acción permite a Liniers intimar a Whitelocke su rendición, y el 7 de julio se firma el tratado que pone fin a las hostilidades."],["Paseo del Cine","canteros centrales","Cine: término popular con el que se conoce al medio de comunicación social que se basa en la representación de imágenes en movimiento, mediante la técnica del cinematógrafo. Homenaje general a los creadores y a las creaciones de la cinematografía argentina. Cabe destacar que por Ordenanza Nº 49.599-1995, BM Nº 20.154 se rindió otro homenaje a esta actividad artística, cuando se declaró “calle del Cine al tramo de la calle Lavalle que va desde Carlos Pellegrini hasta la calle Florida” debido a la cantidad de salas que allí funcionaron durante muchos años. No obstante, como se señala expresamente, esta disposición es sólo una declaración que no alteraba ni altera la nomenclatura de la calle Lavalle."],["Cipolletti","calle","César Cipolletti (1846 a 1908), ingeniero italiano; contratado en 1888 para la organización de las obras de riego de la provincia de Mendoza, se construyen bajo su dirección las tomas de riego de los ríos Tunuyán y Mendoza; actúa en San Juan y Tucumán en tareas similares; en 1898 el Gobierno nacional le confía un estudio del Río Negro que titula Estudios de irrigación, ríos Negro y Colorado, proyecto que se realiza luego de su muerte."],["Subcomisario Severino José Cirigliano","plazoleta","Severino José Cirigliano (1882 a 1967), policía; subcomisario de la Seccional a 39 ; defensor de la Constitución Nacional en los hechos ocurridos el 6 de septiembre de 1930 que culminan con el derrocamiento de Hipólito Yrigoyen."],["Ciro el Grande","plazoleta","Ciro ll, el Grande o el Viejo (560-529 a.C.), fundador del Imperio Persa de los Aqueménidas."],["Rosa H. Cirullo de Carnaghi","jardín","Rosa H. Cirullo de Carnaghi (1923 a 1976), es secuestrada junto a su hija, María Carnaghi, el 4 de agosto de 1976; ambas son asesinadas en el episodio conocido como la Masacre de Fátima, entre la noche del 19 y la madrugada del 20 de agosto de 1976, cuando treinta personas que se encontraban detenidas ilegalmente en la Superintendencia de Seguridad Federal de la Policía Federal son trasladadas hasta la localidad de Fátima, en el partido de Pilar, provincia de Buenos Aires, donde son ejecutadas mediante un disparo en sus cabezas y luego dinamitadas. Madre e hija fueron identificadas por el Equipo Argentino de Antropología Forense."],["Cisne","calle","El Cisne: lago vinculado al Menéndez en el Parque Nacional Los Alerces, Chubut."],["Virrey Cisneros","calle","Baltasar Hidalgo de Cisneros (1756 a 1829), marino; virrey del Río de la Plata de 1809 a 1810."],["Basilio Cittadini","calle","Basilio Cittadini (1843 a 1921), periodista italiano; llega a Buenos Aires en 1869 para dirigir el periódico La Nazione Italiana; director de El Italiano; fundador de La Patria, denominado posteriormente La Patria Italiana, y por último La Patria degli Italiani; presidente del Círculo de la Prensa y de la Sociedad Dante Alighieri."],["Ciudadela","calle","Ciudadela: campo atrincherado, vecino a la ciudad de Tucumán, en el que San Martín y el Ejército del Norte permanecen en 1814 en actitud defensiva ante el accionar de las fuerzas realistas, y donde aquél concibe su plan libertador."],["Emilio Civit","calle","Emilio Civit (1856 a 1920), jurisconsulto y funcionario; senador nacional por Mendoza en 1892; gobernador de Mendoza en 1897; ministro de Obras Públicas de Roca entre 1898 y 1904; gobernador de Mendoza por segunda vez de 1907 a 1910; propicia y defiende la Ley N° 1.420 de Educación Común."],["Clay","calle","Enrique Clay (1777 a 1852), jurisconsulto y estadista estadounidense; diputado, senador y presidente de la Cámara de Representantes en seis oportunidades; realiza fervientes campañas en su país tendientes al reconocimiento de la Independencia sudamericana y muy especialmente del Río de la Plata, lo que se concreta en 1882."],["Juan Carlos Cobián","plazoleta","Juan Carlos Cobián (1896 a 1953), músico y compositor de El motivo y Mi refugio; junto con Enrique Cadícamo son autores de Los mareados, Nieblas del Riachuelo, Nostalgias y La casita de mis viejos."],["Cobo","avenida","Juan Francisco Cobo (1754 a 1835), comerciante; introduce el álamo en Mendoza, debiéndosele su prodigiosa multiplicación; colabora económicamente con el Ejército de los Andes entre 1815 y 1817."],["Cochabamba","calle","Cochabamba: departamento y ciudad de Bolivia, antigua Intendencia del mismo nombre que adhirió a la Junta de Mayo el 21 de septiembre de 1810."],["Cochicó","calle","Cochicó: batalla durante la Campaña del Desierto ocurrida el 15 de enero de 1879 en la laguna de este nombre, entre las tropas del capitán Vicente Laciar y una fuerza indígena."],["Cochrane","calle","Alejandro Tomás Cochrane (1775 a 1860), marino de origen escocés; llega a Chile en 1818 y es nombrado por San Martín vicealmirante de la escuadra que parte al Perú; al mando de la O´Higgins y la Lautaro bloquea, en 1819, los puertos peruanos y se apodera de la isla de San Lorenzo; en 1820 traslada por mar al Perú a las fuerzas libertadoras del general San Martín; en 1822 asume el mando de la escuadra brasileña Don Pedro I para enfrentar a las naves portuguesas, afianzando con su acción la independencia del Brasil."],["Juan M. Coghlan","calle","Juan M. Coghlan (1824 a 1890), ingeniero irlandés; presta servicios a la Municipalidad de Buenos Aires con un proyecto de entubamiento para lugares céntricos de la ciudad; proyecta en 1859 un puerto en la desembocadura del Riachuelo; proyecta las primeras instalaciones de aguas corrientes en 1868, ampliadas luego por el ingeniero Bateman; presidente del Ferrocarril del Sud; director del Ferrocarril a Campana y de la Oficina de Puertos y Caminos de la Provincia de Buenos Aires; vinculado al Ferrocarril Central Argentino (Bartolomé Mitre) se le da su nombre a la estación inaugurada el 14 de febrero de 1891, y cuya denominación identificará al barrio desde entonces."],["De los Colegiales","plaza","Colegiales: originariamente conformaba, junto con Chacarita, una única denominación (Chacarita de los Colegiales). Tal nombre proviene de los colegiales o alumnos que allí iban a disfrutar sus vacaciones, como explicamos al referirnos a Chacarita. Se conoce así a esta zona desde fines del siglo XVIII."],["Del Colegio","calle","Del Colegio: nombre tradicional con que se conoció en Buenos Aires a la actual calle Bolívar y al barrio que circundaba al Colegio Nacional de Buenos Aires."],["Coligüe","calle","Coligüe o colihué: planta oriunda de la Argentina y Chile que se utilizó para hacer lanzas y que en la zona de los lagos del sur forma matorrales impenetrables."],["Coliqueo","calle","Ignacio Coliqueo (?-1871), cacique indígena; fundador de la tribu que lleva su nombre; ministro de Relaciones Exteriores de la confederación indígena de Calfucurá; combate en Pavón. Justo Coliqueo (?-1876), cacique indígena, hijo y sucesor de Ignacio; coopera con Juan Manuel de Rosas en la defensa de las fronteras."],["Pío Collivadino","calle","Pío Collivadino (1869 a 1945), pintor, grabador y escenógrafo; director de la Academia Nacional de Bellas Artes en 1907; autor de La Diagonal Norte, El truco y La hora del almuerzo."],["Alfredo Colmo","calle","Alfredo Colmo (1878 a 1934), jurisconsulto; profesor de Derecho Civil de la Facultad de Derecho de Buenos Aires desde 1904; juez en lo civil y vocal de la Cámara de Apelaciones; cónsul argentino en Toulouse y Liverpool; autor de La Revolución en América Latina y Mi neutralismo."],["Colombia","avenida","Colombia: país sudamericano. Capital: Bogotá."],["Colombia","plaza","Colombia: país sudamericano. Capital: Bogotá."],["Eduardo Colombo Leoni","calle","Eduardo Colombo Leoni (¿1863?-1927), maestro de origen italiano; director de la primera escuela del barrio de Nueva Pompeya donada por la firma Santos Luppi Hnos. y Cía., que se encontraba ubicada en la esquina de Centenera y Esquiú. Falleció el 24 de noviembre de 1927."],["Colombres","calle","Legajo 3, 1882. Obras Públicas). José Eusebio Colombres (1778 a 1859) sacerdote; diputado por Catamarca en el Congreso de Tucumán; promotor y precursor de la industria azucarera."],["Paseo Colón","avenida","Cristóbal Colón (1451 a 1506), navegante de origen genovés; descubridor de América."],["Colonia","calle","Colonia del Sacramento: ciudad uruguaya fundada con el nombre de Colonia do Sacramento por el portugués Manuel de Lobo, en enero de 1680."],["Colonia Esperanza","espacio verde","Colonia Esperanza: nombre del pueblo y primera colonia agrícola fundada en la República, en la provincia de Santa Fe, por don Aarón Castellanos, quien firma el contrato con el gobierno provincial el 15 de junio de 1853. Los trabajos de mensura y las instalaciones de la colonia se iniciaron el 5 de septiembre de 1855, y los primeros pobladores llegaron el 27 de enero de 1856."],["Las Colonias","calle","Colonias: establecimientos de inmigrantes que se unían en nuestra campaña para cultivar la tierra en un paraje determinado."],["Río Colorado","calle","Río Colorado: río que nace en la confluencia de los ríos Grande y Barracas y desemboca en el Océano Atlántico; sirve de límite entre las provincias de Mendoza y Neuquén y La Pampa y Río Negro."],["Colpayo","calle","Colpayo: combate librado en el lugar de Bolivia de este nombre, el 15 de septiembre de 1816, cuando una columna realista es sorprendida por Juan Fernández Campero, Marqués de Yavi."],["Columbia","calle","Columbia: distrito federal y universidad de los Estados Unidos de Norteamérica."],["Agustín Comastri","plazoleta","Agustín Rafael Comastri (1830 a 1891), agricultor de origen italiano; pionero de los barrios de Villa Crespo y Chacarita; poseyó una extensa quinta en esta zona; y su casa, en la que se destaca su mirador, aún se conserva como sede de la Escuela Técnica Ingeniero Enrique M. Hermitte. COMBATE DE LOS POZOS véase LOS POZOS. COMBATIENTES DE MALVINAS véase MALVINAS, COMBATIENTES DE."],["Del Comercio","calle","Comercio: nombre tradicional que entre 1822 y 1900 ostentó la actual Humberto I, y que recuerda a la negociación y tráfico que se hace comprando, vendiendo o permutando unas cosas por otras."],["La Comuna","calle","Comuna: nombre que se refiere al municipio o al conjunto de ciudadanos que lo conforman."],["Comunidad Organizada","puente peatonal","La Comunidad Organizada: título de la conferencia pronunciada el 9 de abril de 1949 por el entonces presidente de la Nación, general Juan Domingo Perón, en el acto de clausura del Primer Congreso Nacional de Filosofía realizado en la ciudad de Mendoza, en la que plantea los principios ideológicos de su pensamiento político."],["Concepción del Alto de San Pedro","plaza","Concepción del Alto de San Pedro: se denominó así como homenaje a la iglesia de la Inmaculada Concepción en el bicentenario de su creación, celebrado el 28 de octubre de 1948. Se le agregó “del Alto de San Pedro” por ser éste el nombre tradicional con que se conocía al barrio de San Telmo, donde está ubicada esta plaza, desde el siglo XVII."],["Concordia","calle","Concordia: ciudad y departamento de la provincia de Entre Ríos."],["Condarco","calle","José Antonio Álvarez de Condarco (1780 a 1855), sargento mayor; secretario privado y ayudante de campo de San Martín, dirige la fábrica de pólvora que abastece al Ejército de los Andes; estudia la topografía de los pasos de la cordillera; combate en Chacabuco y Maipú."],["Conde","calle","Pedro Conde (1785 a 1821), coronel; combate durante las Invasiones Inglesas, en Chacabuco, Cancha Rayada, Maipú y en la primera etapa de la campaña al Perú."],["Cóndor","calle","Cóndor: ave del orden de los Falconiformes que es la mayor de las aves voladoras; habita en las cumbres andinas."],["Conesa","calle","Emilio Conesa (1823 a 1873), general; combate en Quebracho Herrado, Rodeo del Medio, Caseros, Cepeda y en la guerra contra el Paraguay."],["República Democrática del Congo","espacio verde","República Democrática del Congo: país africano. Capital: Brazzaville."],["Congreso","avenida","Congreso de Tucumán: congreso reunido en Tucumán el 24 de marzo de 1816 y que el 9 de julio del mismo año declaró la Independencia de las Provincias Unidas de la América del Sur. Si bien Carranza y Udaondo, en sus obras sobre nomenclatura urbana, dan como razón de este nombre a la institución del congreso en forma general, el informe de la Comisión que precede a la Ordenanza del 27-11-1893 dice que “hemos creído justo recordar las instituciones o cuerpos políticos que han gobernado el país y han conseguido su Independencia”, con lo cual es evidentemente al Congreso de Tucumán a quien se ha recordado con esta designación."],["Del Congreso","plaza","Del Congreso: se denomina así por encontrarse ubicada frente al edificio del Congreso Nacional."],["Doctor Emilio R. Coni","calle","Emilio Ramón Coni (1854 a 1928), médico; fundador de la Oficina Estadística Municipal de Buenos Aires y de los Anales de la Higiene Pública; director de la Administración Sanitaria y Asistencia Pública de Buenos Aires en 1891; fundador del Patronato y Asistencia de la Infancia."],["La Conquista","calle","Conquista: recuerda al período de nuestra historia en el que las distintas expediciones españolas conquistaron el territorio americano. CONSTANCIA, LA véase LA CONSTANCIA."],["Constantinopla","calle","Constantinopla: nombre que tomó la antigua ciudad de Bizancio al transformarse en la capital del Imperio Bizantino. Es la actual Estambul y fue capital de Turquía hasta 1923."],["Constitución","barrio","La denominación de este barrio data de 1857, cuando a sugerencia del gobernador Pastor Obligado se instaló, en la actual plaza homónima, el mercado que, según establece la Memoria de la Municipalidad de la Ciudad de Buenos Aires correspondiente a los años 1856 y 1857, recibe el nombre de Constitución que se hizo así extensivo al barrio circundante."],["De la Constitución","plaza","Esta plaza recibe este nombre cuando se denomina así al mercado allí existente, en la Memoria de la Municipalidad de la Ciudad de Buenos Aires correspondiente a los años 1856 y 1857. Buenos Aires, Imprenta del Orden, San Martín 5 y Buen Orden 155, 1858. Cuando en 1884 se inicia la construcción de la plaza, comenzando a desaparecer con ello el viejo mercado, el paseo hereda el nombre de aquél. Constitución: si bien por la fecha de aparición de este nombre en lo que hace a la plaza y al barrio, es presumible que el mismo rindiera homenaje a la Constitución del segregado Estado de Buenos Aires, sancionada en abril de 1854; en la actualidad esta nomenclatura recuerda a la Carta Fundamental que rige a la República, aprobada por el Congreso Constituyente de Santa Fe el 1° de mayo de 1853 y promulgada el 25 del mismo mes."],["De los Constituyentes","avenida","Constituyentes: homenaje a los ciudadanos que formaron parte del Congreso General Constituyente que sancionó la Constitución de 1853."],["Padre Enrique Contardi","calle","Enrique Contardi (1885 a 1957), sacerdote de origen italiano; párroco de Nuestra Señora de la Divina Providencia; discípulo de don Orione, dirige el Asilo Infantil “Dopo Scuola” convirtiéndolo en la parroquia mencionada; había llegado a Buenos Aires en 1922."],["Haroldo Conti","plazoleta","Haroldo Conti (1925 a 1976), escritor; autor de Con otra gente, Sudeste y Mascaro; desaparecido el 5 de mayo de 1976 durante la última dictadura militar."],["Pascual Contursi","plazoleta","Pascual Contursi (1888 a 1932), poeta y compositor de tango; autor de Mi noche triste, Milonguita, Ivette y Flor de fango."],["Convención","calle","Convención Nacional: fue convocada por la Confederación Argentina en cumplimiento de los pactos del 11 de noviembre de 1859 y del 6 de junio de 1860. Sesiona en el Cabildo de Santa Fe desde el 14 de septiembre y aprueba algunas reformas, supresiones y agregados a la Constitución, con lo cual se incorpora la provincia de Buenos Aires a la Confederación. A raíz de ello, el 21 de octubre de 1860 la Constitución Nacional es jurada por el gobierno y pueblo de Buenos Aires."],["John William Cooke","calle","John William Cooke (1919 a 1968), político; diputado nacional entre 1946 y 1952; delegado personal del general Perón, es uno de los primeros políticos argentinos que tiene contactos con la Revolución Cubana; sus libros Apuntes para la militancia y Correspondencia Perón-Cooke, donde se reúnen las cartas que intercambia con el general Perón en el exilio, adquieren gran predicamento en la juventud de los años de la década de 1970."],["Cooperación","calle","Cooperación: acción y efecto de cooperar; obrar juntamente con otro u otros para un mismo fin. Por extensión es un homenaje al cooperativismo."],["Cooperadoras Escolares","plazoleta","Cooperadoras Escolares: en reconocimiento a la labor desarrollada por estas entidades de bien público que han promovido el acercamiento de las familias a las escuelas y colaborado en el sostenimiento de las mismas."],["Copahue","calle","Copahue: volcán y fuentes termales de la provincia del Neuquén."],["Copenhague","calle","Copenhague: ciudad capital de Dinamarca y del condado de su nombre."],["Copérnico","calle","Nicolás Copérnico (1473 a 1543), astrónomo polaco; autor de Sobre las revoluciones de los cuerpos celestes, donde sostiene la teoría heliocéntrica según la cual son los planetas los que giran alrededor del Sol, en contra de la teoría geocéntrica de Tolomeo aceptada hasta ese momento."],["Corbeta Agreable","calle","Corbeta Agreable: nave que integró, en 1814, la escuadra comandada por el almirante Guillermo Brown."],["Corbeta Belfast","calle","Corbeta Belfast: nave que integró, en 1814, la escuadra comandada por el almirante Guillermo Brown."],["Corbeta Uruguay","calle","Corbeta Uruguay: buque que, al mando de Julián de Irizar, rescató de la Antártida, en 1903, a la expedición del noruego Nordenskchordl. Esta corbeta había llegado al país en 1874 y en ella funcionó la Escuela Naval."],["La Cordillera","calle","Cordillera de los Andes: cordillera que bordea América del Sur siguiendo su costa occidental desde el Mar de las Antillas hasta el cabo de Hornos, donde se sumerge en paso Drake para reaparecer en el continente antártico."],["Provincia de Córdoba","cantero central","Córdoba: ciudad y provincia de la República Argentina."],["Corea","calle","Corea: península centro oriental del continente asiático en el Pacífico; está dividida en dos estados, Corea del Norte y Corea del Sur; capitales Pyongyang y Seúl."],["Martín Coronado","calle","Martín Coronado (1850 a 1919), poeta y comediógrafo; autor de La piedra del escándalo, Culpas ajenas y Tormenta de verano."],["Coronda","calle","Coronda: localidad del departamento de San Jerónimo, en la provincia de Santa Fe."],["Corrales","calle","Corrales: nombre tradicional con que se conocía también al actual barrio de Parque Patricios, que se origina en la existencia de los Mataderos del Sur, inaugurados oficialmente el 11 de noviembre de 1872 en la esquina de Caseros y Monteagudo. Funcionó allí hasta principios del siglo XX, cuando fueron trasladados a su emplazamiento en el barrio de Mataderos."],["De los Corrales","avenida","Corrales: nombre tradicional con el que se conocía a esta avenida y por la que ingresaban los animales para consumo con destino al matadero de Liniers."],["Corrales Viejos","calle","Corrales Viejos: nombre con que se conoció durante mucho tiempo al barrio de Parque Patricios, por haber estado en este lugar el Matadero del Sur."],["Correa","calle","Cirilo Correa (1795 a 1827), general; combate en Suipacha, Las Piedras, Tucumán, Salta, Vilcapugio, Ayohuma, Venta y Media, Sipe-Sipe, Chacabuco, Cancha Rayada y Maipú; marcha en el Ejército Libertador del Perú y participa en la campaña de Puertos Intermedios."],["Doctor Guillermo Correa","calle","Guillermo Correa (1858 a 1934), jurisconsulto; periodista y escritor; gobernador de Catamarca en dos oportunidades; autor de La sonsera, Nupciales y Patri."],["Lucio Correa Morales","calle","Lucio Correa Morales (1852 a 1923), escultor; autor de La Ondina del Plata (Jardín Botánico), La Cautiva (plaza Capitán General Justo José de Urquiza), del monumento a Falucho (plaza homónima) y a Manuel Alberti (plaza Barrancas de Belgrano)."],["Corregidores","calle","Corregidores: funcionarios de la época hispánica que eran jefes políticos y administrativos del área de su dominio (generalmente una sola ciudad y su ejido) y jueces superiores de los alcaldes ordinarios. Hubo corregidores de pueblos de españoles y de pueblos de indios."],["Del Correo","plaza","Del Correo: homenaje al Correo Argentino y al telégrafo en ocasión de celebrarse en 1983 el Año Mundial de las Comunicaciones."],["Provincia de Corrientes","cantero central","Corrientes: ciudad y provincia de la República Argentina."],["Canónigo Miguel Calixto del Corro","avenida","Miguel Calixto del Corro (1775 a 1851), sacerdote; precursor de la Independencia; rector de la Universidad de Córdoba en 1816 y 1829; diputado por Córdoba en el Congreso de Tucumán en reemplazo del deán Gregorio Funes; no firma el acta de la Independencia por encontrarse desempeñando una misión ante don José Gervasio Artigas."],["Ignacio Corsini","plazoleta","Andrés Ignacio Corsini (1891 a 1967), cantor y actor; se consagra interpretando El patotero sentimental; sus relevantes dotes de cantor hacen que en 1935 la revista El Suplemento lo distinga en un concurso como “El príncipe de la canción porteña”."],["Julio Cortázar","calle","Julio Cortázar (1914 a 1984), escritor; innovador de la narrativa contemporánea; autor de: Bestiario, Rayuela, Final del juego y Todos los fuegos el fuego."],["Julio Cortázar","plazoleta","Julio Cortázar (1914 a 1984), escritor; innovador de la narrativa contemporánea; autor de: Bestiario, Rayuela, Final del juego y Todos los fuegos el fuego."],["José A. Cortejarena","calle","José Antonio Cortejarena (1877 a 1921), periodista y abogado; dueño y director del diario La Razón, inaugura su edificio en la Avenida de Mayo, en 1913; profesor de Literatura e Historia en el Colegio Nacional de Buenos Aires."],["Gerónimo Cortés","calle","Gerónimo Cortés Funes (1833 a 1891), jurisconsulto; miembro del Superior Tribunal de Justicia de Córdoba de 1864 a 1866; senador nacional de 1875 a 1880; fiscal de la Cámara de Apelaciones de la Capital en 1881, se reúnen sus “Vistas Fiscales” en 1887 publicándose en cinco tomos; senador nacional en 1890."],["Cortina","calle","José María Cortina (1794 a 1869), coronel; combate en la guerra contra el Brasil, en Vuelta de Obligado y Caseros; comandante de la Frontera Norte de Buenos Aires en 1848."],["Corto Maltés","cantero central","Corto Maltés: personaje que da nombre a la historieta creada por el dibujante y escritor Hugo Pratt en 1967."],["Corvalán","calle","Eugenio Corvalán (1791 a 1858), coronel; capitán de la compañía de Zapadores del Ejército de los Andes, combate en Chacabuco, Gavilán, Talcahuano y Maipú; marcha en la Expedición al Perú. Gabino Corvalán (1792 a 1842), teniente coronel y sacerdote; combate en la Expedición al Perú y en la del Ecuador; al enterarse en 1825 de la muerte de su esposa se ordena sacerdote; fiscal eclesiástico de Mendoza en 1835. José Corvalán (1802 a 1842), teniente coronel, hijo de Manuel de la Trinidad; combate en Pasco, Penco, en la guerra contra el Brasil y en la lucha contra el indio. Manuel de la Trinidad Corvalán (1774 a 1847), general; combate durante las Invasiones Inglesas; gobernador de San Juan en 1814 y 1815; jefe de Órdenes y director del Parque y Maestranza del Ejército de los Andes; edecán de Dorrego y de Rosas. Mateo Corvalán (1792-?), sargento mayor; combate en Chacabuco, Curapaligüe, Talcahuano, Cancha Rayada y Maipú. Victorino Corvalán (1791 a 1854), coronel; combate en Chacabuco; es el primer argentino que ingresa a Santiago persiguiendo a los dispersos; actuó en Curapaligüe, Cancha Rayada y Maipú. Homenaje conjunto a los hermanos Corvalán, hijos de Domingo Rege Corvalán y Manuela Sotomayor, y al hijo de Manuel de la Trinidad."],["Cosquín","calle","Cosquín: ciudad de la provincia de Córdoba."],["Olga Cossettini","calle","Olga Cossettini (1898 a 1987) escritora y educadora; organiza la Escuela Experimental de Santa Fe, innovando sus métodos pedagógicos; directora general de escuelas de la provincia de Buenos Aires en 1958; es autora de los libros: Escuela Serena, El niño y su expresión, Lenguaje y lectura en primer grado y Educación del adulto en Inglaterra, Francia y Estados Unidos."],["Eduardo Costa","calle","Eduardo Costa (1823 a 1897), jurisconsulto y funcionario; ministro de Justicia, Culto e Instrucción Pública e interino de Interior con Mitre, se crean durante su administración los primeros colegios nacionales del país y el Registro Nacional; ministro de Relaciones Exteriores con Carlos Pellegrini y de Justicia, Culto e Instrucción Pública con Luis Sáenz Peña."],["Combate de Costa Brava","calle","Combate de Costa Brava: triunfo del almirante Guillermo Brown el 15 de agosto de 1842, cuando vence a la flota al mando de José Garibaldi, en el límite entre Corrientes y Entre Ríos sobre el río Paraná. El combate tuvo lugar durante el enfrentamiento entre don Juan Manuel de Rosas y el gobernador de la Banda Oriental, Fructuoso Rivera."],["Santiago Costamagna","calle","Santiago Costamagna (1846 a 1921), sacerdote italiano; encabeza la tercera expedición de misioneros salesianos enviados a América; viaja en 1878 a la Patagonia para iniciar su obra apostólica en la región; acompaña a Roca, en 1879, en su expedición al Río Negro; Vicario Apostólico de Méndez y Guadaquiza, Ecuador, en 1894; autor de Compelle Intrare."],["Costa Rica","calle","Costa Rica: país de América Central. Capital: San José."],["Cotagaita","calle","Cotagaita: combate librado en esa localidad del Alto Perú, entre las fuerzas realistas del general Córdoba y las patriotas de Antonio González Balcarce, el 27 de octubre de 1810."],["Cotocollao","calle","Cotocollao: municipio y llanura del Ecuador en la provincia de Pichincha."],["Pierre de Coubertin","plazoleta","Pierre de Fredi Coubertin (1863 a 1937), deportista francés; presidente del Comité Olímpico Internacional; restableció los Juegos Olímpicos modernos en 1896 en Atenas, Grecia; secretario general de la Sociedad de Propaganda de Ejercicios Físicos; publicó varias obras destinadas a la educación de los adolescentes, a la pedagogía deportiva y a la historia universal."],["Miguel Couto","calle","Miguel Couto (?-1934), médico brasileño; profesor de Clínica Médica de la Universidad de Río de Janeiro; presidente de la Academia Nacional de Medicina de su país de 1915 a 1934."],["Eduardo Juan Couture","calle","Eduardo Juan Couture (1906 a 1956), jurisconsulto y escritor uruguayo; presidente del Colegio de Abogados del Uruguay; autor de Mandamientos del abogado y La comarca y el mundo; miembro de la Academia de Letras del Uruguay y socio honorario del Colegio de Abogados de Buenos Aires."],["Craig","calle","Tomás Craig (1780 a 1863), sargento mayor de marina de origen irlandés; llega a Buenos Aires como sargento 1° del ejército británico que invade Buenos Aires en 1806, pero permanece aquí luego de expulsado el invasor; combate en Tucumán, Salta, Vilcapugio, Ayohuma, en la guerra contra el Brasil y en Vuelta de Obligado; fue comandante de la goleta Libertad en 1841, y de las corbetas 25 de Mayo y 9 de Julio y del bergantín Republicano."],["Crainqueville","calle","Jerónimo Crainqueville: personaje del cuento Crainqueville, de Anatole France (Crainqueville, Putoes Riquet et plusieurs autres recites profitables) publicado en 1902."],["Cramer","calle","Ambrosio Cramer (1790 a 1839), coronel de origen francés; combate en Chacabuco; realiza en 1823 la campaña a Tandil; en 1824 acompaña al general Martín Rodríguez en su expedición a Bahía Blanca; muere en la batalla de Chascomús combatiendo contra las fuerzas de Prudencio Ortiz de Rosas."],["Cranwell","calle","Guillermo A. Cranwell (1841 a 1909), farmacéutico; intendente de la ciudad de Buenos Aires desde el 14 de agosto de 1888 hasta el 10 de mayo de 1889; presidente del Concejo Deliberante de 1880 a 1886."],["Crespo","calle","Francisco Crespo y Denis (1791 a 1849), coronel; combate en Suipacha, Huaqui, Chacabuco, en la Expedición Libertadora al Perú y en la guerra contra el Brasil; edecán de Rosas; combate contra la escuadra anglofrancesa y en la Vuelta de Obligado como segundo de Mansilla."],["Villa Crespo","barrio","Esta denominación nace como un homenaje al segundo intendente municipal, por parte de los propietarios de la Fábrica Nacional de Calzados. Crespo apadrinó, el 3 de junio de 1888, la colocación de la piedra fundamental del edificio de esta empresa propulsora del nacimiento de este barrio. Antonio F. Crespo (1851 a 1893), médico; intendente municipal de la ciudad de Buenos Aires del 20 de mayo de 1887 al 18 de agosto de 1888."],["El Criollo","calle","Criollo: originariamente se llamó así al hijo de español nacido en estas tierras. Hoy, define más ampliamente al hijo del país y en forma más específica al nativo auténtico. CRISTÓBAL, DON véase DON CRISTÓBAL."],["República de Croacia","plazoleta","República de Croacia: estado del Sur de Europa. Capital: Zagreb."],["Crucero General Belgrano","plazoleta","Crucero General Belgrano: homenaje a la nave atacada y hundida por un submarino británico en las aguas del Atlántico Sur el 2 de mayo de 1982 durante el conflicto por las Islas Malvinas."],["Crucero General Belgrano","calle","Crucero General Belgrano: homenaje a la nave atacada y hundida por un submarino británico en las aguas del Atlántico Sur el 2 de mayo de 1982 durante el conflicto por las Islas Malvinas."],["Julio Cruciani","cantero central","Julio Cruciani (1898 a 1949), médico e investigador; participa en el movimiento estudiantil que culmina con la Reforma Universitaria de 1918; en 1927 es jefe de Trabajos Prácticos de Patología Médica de la Cátedra del profesor Juan José Vitón. Es autor del libro Asma, interpretación actual, especialidad a la que se dedica en el Hospital Ramos Mejía, en el primer servicio de asistencia pública de esta enfermedad, donde es nombrado jefe del Consultorio de Asma."],["Osvaldo Cruz","calle","Osvaldo Cruz (1872 a 1917), médico bacteriólogo brasileño; director del Instituto Manguinhos que hoy lleva su nombre, donde se preparan sueros y vacunas para combatir enfermedades tropicales; director de Salud Pública de Río de Janeiro en 1903. CRUZ, SOR JUANA INÉS DE LA (calle) véase JUANA INÉS DE LA CRUZ,."],["Sor. Cruz del Eje","calle","Cruz del Eje: departamento de la provincia de Córdoba."],["Cruz del Sur","calle","Cruz del Sur: constelación austral situada en la vía láctea entre las del Centauro y la Mosca, formada por cuatro estrellas bien visibles. Es interesante destacar que se le otorgó este nombre a esta calle en razón de que la misma presenta un ensanche en la mitad de su recorrido, el cual le ofrece así la apariencia de una cruz cuya orientación coincide, además, con los puntos cardinales."],["Cuba","calle","Cuba: país antillano. Capital: La Habana."],["José Cubas","calle","José Cubas (1798 a 1841), político; gobernador de Catamarca desde 1836; en 1840 se adhiere a la Liga del Norte; es vencido y muerto en 1841 por Mariano Maza."],["Cucha Cucha","calle","Cucha Cucha: combate librado el 23 de febrero de 1814 en el que Las Heras derrota a las fuerzas realistas en ese paraje chileno."],["Fray Pedro Agustín Cueli","plazoleta","Pedro Agustín Cueli (1742 a 1809), sacerdote; tiene una destacada actuación en la Reconquista de Buenos Aires en 1806 ante las Invasiones Inglesas; capellán del 3° Escuadrón de Caballería de Campaña de Buenos Aires y primer capellán de la Legión de Patricios Argentinos."],["Cuenca","calle","Claudio Mamerto Cuenca (1812 a 1852), médico; cirujano mayor del ejército designado en 1851 por Rosas, muere en la batalla de Caseros."],["Rufino José Cuervo","calle","Rufino José Cuervo (1844 a 1911), filólogo colombiano, fue el más eminente durante la segunda mitad del siglo XIX; autor de Notas a la Gramática de Bello, Gramática latina y Diccionario de Construcción y régimen de la lengua castellana."],["Cullen","calle","Domingo Cullen (1791 a 1839), político; secretario privado de Estanislao López en 1828 y su ministro de Gobierno en 1832; elegido gobernador de Santa Fe el 29 de junio de 1838 es derrotado por Juan Pablo López poco después; refugiado en Santiago del Estero participa en distintas tentativas revolucionarias por lo que es apresado y ejecutado el 22 de junio de 1839 en la Posta de Vergara, San Nicolás de los Arroyos."],["Culpina","calle","Culpina: combate librado el 31 de enero de 1816 entre Lamadrid y una columna realista al mando de Antonio Álvarez."],["La Cumparsita","plazoleta","La Cumparsita: tango compuesto por Gerardo H. Matos Rodríguez, en 1917 en Montevideo (Uruguay); su primera versión orquestal estuvo a cargo de la agrupación de Roberto Firpo y la primera llevada al disco correspondió al conjunto dirigido por Alberto Alonso y Minoto Di Cico, quienes la registraron en 1917 para la Casa Víctor en Buenos Aires."],["Francisco Cúneo","calle","Francisco Cúneo (1875 a 1920), político; miembro del Partido Socialista desde 1895; diputado nacional en 1914 y concejal en 1918."],["Roberto Cunninghame Graham","calle","Roberto Cunninghame Graham (1852 a 1936), escritor inglés; residió en nuestro país; autor de Los caballos de la conquista, Río de la Plata y Espejismo, relatos criollos."],["Curapaligüe","calle","Curapaligüe: combate librado el 4 y 5 de abril de 1817 por el general Las Heras, quien vence a Ordóñez en la hacienda de Curapaligüe, al sur de Chile."],["Pablo Curatella Manes","calle","Pablo Curatella Manes (1891 a 1962), escultor; autor de La familia, Sirenas, La mujer del tapado y Desnudo."],["María Curie","avenida","María Scklodowska de Curie (1867 a 1934), física y química polaca; comparte en 1903 el premio Nobel de Física con su esposo, Pierre Curie, y el profesor Henri Becquerel, por sus investigaciones de los fenómenos de radiación; obtiene en 1911 el premio Nobel de Química por el descubrimiento de los elementos radiactivos radio y polonio."],["Curityba","calle","Curitiba: ciudad capital del Estado de Paraná, Brasil."],["Curupaytí","calle","Curupaytí: batalla librada durante la guerra del Paraguay el 22 de septiembre de 1866."],["Curuzú Cuatiá","calle","Curuzú Cuatiá: ciudad y departamento de la provincia de Corrientes, y pueblo donde acampó el general Belgrano, a quien se considera su fundador, en su expedición al Paraguay."],["Curuzú Cuatiá","plazoleta","Curuzú Cuatiá: ciudad y departamento de la provincia de Corrientes, y pueblo donde acampó el general Belgrano, a quien se considera su fundador, en su expedición al Paraguay."],["Cuter Luisito","calle","Cuter Luisito: nave construida por el comandante Luis Piedra Buena con los restos del bergantín Espora al naufragar éste en 1873."],["Cuyo","calle","Cuyo: antigua provincia argentina que comprendía a las actuales de San Juan, San Luis y Mendoza. Es éste un nombre tradicional de Buenos Aires, pues, entre 1822 y 1911 se denominó así a la actual calle Sarmiento."],["Cuzco","calle","Cuzco: capital del departamento de su nombre, en la República del Perú, célebre por haber sido la antigua capital de los incas."],["Coronel Juan F. Czetz","plazoleta","Juan F. Czetz (1822 a 1904), agrimensor y militar de origen húngaro; alcanzó en su patria natal el grado de general; exiliado de Hungría se radica en la Argentina en 1859; traza el mapa argentino en sus límites con Paraguay y Brasil; proyecta el pueblo de Olavarría; organiza el Colegio Militar desde 1870; alcanza en nuestras Fuerzas Armadas el grado de coronel. Notas."],["Daguerre","calle","Luis Jacobo Daguerre (1789 a 1851), pintor y físico francés; asociado con Niepce en 1829, anuncian diez años más tarde la invención del daguerrotipo."],["José Dames","plazoleta","José Dames (1907 a 1994), bandoneonísta y compositor de tango; autor de Fuimos, Nada, El Buscapié, Por unos ojos negros, Horizonte azul, La Luciérnaga, entre otros."],["Doctor Eleodoro Damianovich","calle","Eleodoro Damianovich (1843 a 1925), médico y militar; actúa en la guerra contra el Paraguay; como militar alcanza el grado de general; combate la epidemia de fiebre amarilla al frente del Hospital Militar; autor de Proyecto de procedimiento para declarar la inaptitud para el servicio de armas."],["Danel","calle","Alejandro Danel (1791 a 1865), coronel de origen francés; combate en la guerra contra el Brasil; incorporado al ejército de Lavalle en 1839 combate en Yeruá, Don Cristóbal, Sauce Grande, Quebracho Herrado y Famaillá; muerto Lavalle, es quien descarna su cadáver y uno de quienes lo lleva hasta Potosí; combate en Caseros."],["Julio S. Dantas","calle","Julio Secundino Dantas (1847 a 1922), coronel, combate en la guerra contra el Paraguay; jefe de la Policía de la provincia de Buenos Aires; diputado nacional de 1883 a 1886, 1890 a 1894, en 1898, y de 1900 a 1904."],["Dante","calle","Dante Alighieri (1265 a 1321), poeta italiano; autor de La Divina Comedia..2."],["Dante","plaza","Dante Alighieri (1265 a 1321), poeta italiano; autor de La Divina Comedia..2."],["Daract","avenida","Justo Daract (1804 a 1887), funcionario; gobernador de San Luis de 1854 a 1859, de 1860 a 1862 y de 1865 a 1867. Mauricio P. Daract (1807 a 1887), funcionario, hermano del anterior; goberna- dor delegado de San Luis de 1852 a 1854, dispone la jura de la Constitución Nacional."],["Rubén Darío","plaza","Rubén Darío: seudónimo de Félix Rubén García Sarmiento (1867 a 1916), poeta y diplomático nicaragüense; autor de Azul, Prosas profanas, Cantos de Vida y Esperanza, Poema del otoño, El viaje a Nicaragua y Canto a la Argentina."],["Juan Darquier","calle","Juan Darquier (1829 a 1897), médico; alcalde y juez de paz de la parroquia de Balvanera; vicepresidente de la Municipalidad de Buenos Aires; diputado nacional de 1882 a 1886."],["Darregueyra","calle","Obras Públicas). José de Darregueyra y Lugo (1771 a 1817), jurisconsulto; diputado por Buenos Aires en el Congreso de Tucumán."],["Darwin","calle","Carlos Roberto Darwin (1809 a 1882), naturalista inglés; participa en la expedición de Fitz Roy que a bordo del Beagle explora las costas de la Patagonia, Chile, Perú y algunas islas del Pacífico; llega a Buenos Aires en 1832; como fruto de sus investigaciones publica Viaje de un naturalista alrededor del mundo; autor de Origen de las especies y El Origen del Hombre."],["Doctor Desiderio Fernando Davel","calle","Desiderio Fernando Davel (1857 a 1943), médico; el 4 de septiembre de 1886 elabora y aplica por primera vez a un ser humano en Buenos Aires (y en América latina) la vacuna antirrábica, desarrollada por Luis Pasteur en Francia."],["Dávila","calle","Nicolás Dávila (1786 a 1876), coronel; comandante militar del departamento de Famatina en 1816, participa como segundo jefe en la toma de la ciudad chilena de Copiapó, por lo que recibe la medalla acordada a los vencedores de Chacabuco; gobernador de La Rioja de 1821 a 1823."],["Leonardo Da Vinci","calle","Leonardo Da Vinci (1452 a 1519), pintor y sabio italiano; autor de La Gioconda."],["Pierina Dealessi","calle","Pierina Dealessi (1894 a 1983), actriz de origen italiano; debuta en 1906 con los hermanos Podestá; se une a la compañía de Enrique Muiño en el Teatro Olimpo y a los 18 años se convierte en primera figura actuando con Florencio Parravicini; en 1924 forma su propia compañía. Por sus actuaciones en el teatro se destaca en El tango en París, La gringa, La piel de la manzana y El conventillo de la paloma; en el cine, en Puente Alsina, El Morocho de Abasto y Mosquita muerta."],["Edmundo de Amicis","calle","Edmundo De Amicis (1846 a 1908), escritor italiano; autor de Corazón y Muertos y Vivos."],["Francisco de Caro","plazoleta","Francisco De Caro (1898 a 1976), músico; autor de Flores negras, Colombina y Loca bohemia."],["Julio de Caro","plazoleta","Julio De Caro (1899 a 1980), violinista; compositor de Boedo, Buen Amigo, El Malevo, El Mareo, Tierra querida y Mala junta."],["Agente Domingo Dedico","calle","Domingo Dedico (?-1931), agente policial; muere trágicamente en un procedimiento en la localidad de Burzaco el 30 de enero de 1931."],["Defensa","calle","La Defensa por Orden del Gobernador de Buenos Aires del 9 de octubre de 1848. En el Plano Topográfico de los Alrededores de Buenos Ayres, por Adolfo Sourdeaux (ca. 1850), su nombre actual."],["De la Defensa","plaza","Defensa: en recuerdo de la heroica Defensa de la ciudad de Buenos Aires en julio de 1807 contra la segunda invasión inglesa."],["Deheza","calle","Román Antonio Deheza (1791 a 1872), general; combate en Cucha Cucha, Membrillar, Plumerillo, Guardia Vieja, Chacabuco, Gavilán, Talcahuano, Cancha Rayada y Maipú; realiza la expedición al Perú y la campaña de la Sierra; combate en Pasco, Junín y Ayacucho; jefe del Estado Mayor del Ejército Libertador en 1825; combate en la guerra contra el Brasil; gobernador de Santiago del Estero en 1830."],["Dekay","calle","Jorge C. Dekay (1802 a 1849), marino; combate en la guerra contra el Brasil al mando del bergantín General Brandsen y de la fragata 25 de Mayo. DE LA ASUNCIÓN véase ASUNCIÓN, DE LA. DE LA BANDERA véase BANDERA, DE LA. DE LA CIENCIA Y LA CULTURA ÁRABES véase ÁRABES, DE LA CIENCIA Y LA CULTURA. DE LA HISTORIETA, PASEO véase HISTORIETA, PASEO DE LA."],["Delambre","calle","Ordenanza N° 2.411 del 21-12-1927, BM N° 1.322-3 Juan Bautista José Delambre (1749 a 1822), astrónomo francés; mide en colaboración con Méchain el arco de meridiano comprendido entre Dunkerque y Barcelona; autor de Bases del sistema métrico decimal. DE LA MEMORIA véase MEMORIA, DE LA. DE LAS ARMAS, EJÉRCITO ARGENTINO véase EJÉRCITO ARGENTINO, DE LAS ARMAS. DE LAS ARTES LATINOAMERICANAS véase ARTES LATINOAMERICA- NAS, DE LAS. DE LA SIERRA, PADRE DANIEL véase SIERRA, PADRE DANIEL DE LA. DE LAS GARANTÍAS véase GARANTÍAS, DE LAS. DE LAS NEREIDAS véase NEREIDAS, DE LAS. DEL BAÑADO véase BAÑADO, DEL. DEL BARCO CENTENERA véase BARCO CENTENERA, DEL."],["Enrique Delfino","cantero central","Enrique Pedro Delfino (1895 a 1967), pianista; compositor de Sans Souci, Re Fa Si, Milonguita, Griseta, Aquel tapado de armiño y Padrino pelao. Contribuye con su música en las películas La vuelta de Rocha, Tres anclaos en Paris y Los tres berretines, entre otras."],["Delgado","calle","Agustín Delgado (¿1790?-1859), funcionario; redactor de El Mensajero Argentino, diputado por Mendoza en el Congreso General Constituyente de 1853, gobernador delegado de esa provincia y presidente de la Convención Constituyente provincial de 1854. DEL KIOSCO DE LA FLORESTA véase KIOSCO DE LA FLORESTA, DEL."],["Ingeniero Carlos María N° 14.159. Della Paolera","plazoleta","Carlos María Della Paolera (1890 a 1960), ingeniero y urbanista; creador del Día Mundial del Urbanismo, primer director de la Dirección de Urbanismo de la Municipalidad de la Ciudad de Buenos Aires en 1932; promotor del proyecto de la Avenida 9 de Julio."],["Luis Dellepiane","calle","Luis Dellepiane (1895 a 1951), médico y legislador; defensor de la nacionalización del petróleo; miembro fundador de FORJA; diputado nacional de 1946 a 1950."],["Teniente General Luis J. Dellepiane","avenida","Luis J. Dellepiane (1865 a 1941), militar e ingeniero; director del Instituto Geográfico Militar; jefe de la Policía Federal de 1909 a 1919; ministro de Guerra en la segunda presidencia de Hipólito Yrigoyen."],["Bernardo B. Delom","plazoleta","Bernardo B. Delom (?-1956), economista, representante del movimiento cooperativista argentino en la Alianza Cooperativa Internacional; presidente de la Federación Argentina de Cooperativas; miembro del directorio de El Hogar Obrero; publica la revista Democracia Económica; autor de El cooperativismo en la escuela y El ABC del empleado cooperativo. DE LOS INCAS véase INCAS, DE LOS. DE LOS PERIODISTAS véase PERIODISTAS, DE LOS. DE LOS SUSPIROS véase SUSPIROS, DE LOS."],["Ingeniero José Luis Delpini","plaza","José Luis Delpini (1897 a 1964), ingeniero civil; profesor de Matemáticas y Cosmografía en el Instituto Nacional del Profesorado Secundario; miembro de la Academia Nacional de Ciencias Exactas. Entre sus obras se destacan el Mercado de Abasto de Buenos Aires, el estadio de Boca Juniors, la iglesia del asilo del Hospital Italiano de San Justo."],["Ingeniero José Luis Delpini","sendero","José Luis Delpini (1897 a 1964), ingeniero civil; profesor de Matemáticas y Cosmografía en el Instituto Nacional del Profesorado Secundario; miembro de la Academia Nacional de Ciencias Exactas. Entre sus obras se destacan el Mercado de Abasto de Buenos Aires, el estadio de Boca Juniors, la iglesia del asilo del Hospital Italiano de San Justo."],["El Delta","calle","Delta del Paraná: delta que forma el río Paraná en su desembocadura."],["Lucio Demare","cantero central","Lucio Demare (1906 a 1974), pianista; compositor de Mañanitas de Montmartre, Dandy, Malena y Solamente ella."],["Demaría","calle","José De María (1760 a 1827), comerciante; comprador de yerba mate en el Paraguay, se adhiere a la causa de la Independencia realizando trabajos en favor de la misma entre 1810 y 1811, en Asunción y Villa Real de la Concepción."],["Isidoro Demaría","calle","Isidoro De María (1815 a 1906), historiador y periodista uruguayo; director y propietario de El Constitucional de 1838 a 1846; fundador de la Revista del Plata; director del Archivo Nacional del Uruguay; autor de Vida del Brigadier General D. José Gervasio Artigas, fundador de la Nacionalidad Oriental y Elementos de Historia de la República Oriental del Uruguay."],["Mariano Demaría","calle","Mariano De María (1842 a 1921), jurisconsulto; ministro de Hacienda de la provincia de Buenos Aires en 1880; ministro de Hacienda de Luis Sáenz Peña; fundador de la Escuela de Agronomía y Veterinaria de Santa Catalina (La Plata); diputado nacional de 1884 a 1888."],["Democracia","plaza","Democracia: sistema político basado en el reconocimiento del principio de que toda autoridad emana del pueblo, y que se caracteriza por la participación de éste en la administración del Estado. Los ciudadanos ejercen de modo directo o mediato, eligiendo, generalmente por sufragio universal, representantes en quienes delegan su soberanía para el ejercicio de las funciones legislativas."],["Derechos del Hombre","plaza","Derechos del Hombre: homenaje a la igualdad de los hombres consagrada por la Declaración de Derechos del Hombre y del Ciudadano sancionada el 26 de agosto de 1789 por la Revolución Francesa y por la Declaración Universal de Derechos del Hombre por las Naciones Unidas el 10 de diciembre de 1948, donde se prescriben como derechos inalienables la libertad de pensamiento, de palabra y religión; la indiscriminación racial; el derecho al trabajo, a la propiedad, a la educación y a la participación en la prosperidad de la Nación."],["De los Derechos Humanos","paseo","De los Derechos Humanos: homenaje a los desaparecidos por causas políticas, gremiales y sociales durante la última dictadura militar."],["Derqui","avenida","Santiago Derqui (1809 a 1867), jurisconsulto; presidente de la República de 1860 a 1861; presidente del Congreso General Constituyente de 1853."],["Desaguadero","calle","Desaguadero: río de la provincia de Mendoza que sirve de límite entre esa provincia y la de San Luis."],["Nicolás Descalzi","calle","Nicolás Descalzi (1801 a 1857), marino y agrimensor de origen italiano; director técnico de la Sociedad de Navegación que buscaba una vía navegable entre Bolivia, Salta y los ríos Paraguay y Paraná; publica en 1831 la carta de navegación del río Bermejo; participa como astrónomo explorador para el conocimiento del Río Negro en la campaña al desierto de 1833."],["Deseado","calle","Deseado: río de la provincia de Santa Cruz."],["Vicente de Simone","calle","Vicente De Simone (?-1954), propulsor del bien público de Villa Lugano; fundador y presidente de la Asociación de Fomento y Biblioteca Popular El Progreso, directivo de la cooperativa El Hogar Obrero. D´ESPÓSITO, ARNALDO (calle). Ordenanza N° 27.101-1972, BM Nº 14.404. Arnaldo D´Espósito (1907 a 1945), pianista y compositor; autor de Rapsodia de Tango, Nocturno y Tres preludios y fugas; director de la Orquesta del Teatro Colón."],["Fortunato Devoto","calle","Fortunato Devoto (?-1917), comerciante; vecino de Almagro que realiza de su peculio las obras indispensables para facilitar el acceso al barrio desde el centro de la ciudad; su casa se encontraba en Mármol, entre Venezuela y México; dedicado al comercio había acrecentado su fortuna mediante inversiones de bienes inmuebles y rurales. Fallece en Buenos Aires el 6 de octubre de 1917(La Prensa, 7-10-1917, p. 9, col. 2.).7."],["Villa Devoto","barrio","Antonio Devoto (1832 a 1916), comerciante; fundador en 1889 de la villa que desde entonces lleva su nombre; donante de la iglesia de San Antonio; miembro fundador del Hospital Italiano."],["Diamante","calle","Diamante: río de la provincia de Mendoza que nace en el lago de su nombre y desagua en el Salado."],["Ana Díaz","calle","Ana Díaz (¿-?), acompaña a Juan de Garay en 1580 en la fundación de Buenos Aires y se constituye en la primera mujer propietaria de un solar en nuestra ciudad; su posesión estaba ubicada en la esquina sudoeste de las actuales Florida y Corrientes."],["Avelino Díaz","calle","Avelino Díaz (1800 a 1831), matemático; profesor de la cátedra de físicomatemáticas del Departamento de Estudios Preparatorios de la Universidad de Buenos Aires en 1821, y de la Geometría en 1829; autor de Lecciones elementales de Aritmética (1824), Lecciones elementales de Álgebra (1824) y Elementos de Geografía (1830); presidente del Departamento General de Topografía y Estadística en 1830."],["Coronel Díaz","avenida","Pedro José Díaz (1800 a 1857), militar; combate en Chacabuco, Cancha Rayada y Maipú; es el primer oficial patriota que ingresa en Lima y en el palacio de los virreyes y quien recibe de manos del Marqués de Montemira las llaves de la plaza; participa en las campañas de la Sierra y Puertos Intermedios; combate en la guerra contra Brasil."],["General César Díaz","calle","César Díaz (1812 a 1858), militar uruguayo; combate en el ejército argentino durante la guerra contra el Brasil; jefe de la División Oriental en la batalla de Caseros; es fusilado luego de un intento fallido de derrocar al gobierno de Pereira."],["Díaz Colodrero","calle","Pedro Alcántara Díaz Colodrero (1787 a 1859), jurisconsulto; participa en el pronunciamiento del coronel Berón de Astrada contra Rosas; diputado por Co- rrientes en el Congreso General Constituyente de 1853; gobernador delegado de Corrientes de diciembre de 1855 a enero de 1856."],["Ruy Díaz de Guzmán","calle","Ruy Díaz de Guzmán (¿1558?-1629), militar e historiador; autor de Historia Argentina del Descubrimiento, población y conquista de las Provincias del Río de la Plata, obra por la cual se lo considera como el primer historiador nacido en el Río de la Plata."],["Díaz Vélez","avenida","Eustoquio Antonio Díaz Vélez (1782 a 1856), general; combate durante las Invasiones Inglesas, en Suipacha, Las Piedras, Tucumán y Salta; teniente gobernador de Santa Fe de 1814 a 1815; gobernador interino de Buenos Aires de 1818 a 1820."],["Díaz Vélez","plaza","Eustoquio Antonio Díaz Vélez (1782 a 1856), general; combate durante las Invasiones Inglesas, en Suipacha, Las Piedras, Tucumán y Salta; teniente gobernador de Santa Fe de 1814 a 1815; gobernador interino de Buenos Aires de 1818 a 1820."],["Doctor Adolfo Dickmann","calle","Adolfo Dickmann (1882 a 1938), odontólogo y político; concejal socialista en Buenos Aires de 1919 a 1920; diputado nacional de 1922 a 1930 y de 1930 a 1936; autor de Los argentinos naturalizados en la política, Nacionalismo y socialismo y En defensa del petróleo nacional. 18 DE DICIEMBRE DE 1872 “CREACIÓN DE LA ESTACIÓN LINIERS” (espacio verde). Ley N° 891-2002, BO N° 1.544. 18 de diciembre de 1872: fecha del acta del directorio del Ferrocarril de la provincia por el que se resuelve imponer el nombre de Liniers al apeadero que se había acordado construir y que se inaugurará finalmente en septiembre de 1876 (información proporcionada por el historiador del transporte Alberto Bernades)."],["Clemente Diez de Medina","calle","Clemente Diez de Medina (1777 a 1848), funcionario; uno de los promotores de la fallida revolución del 25 de mayo de 1809 en Charcas; en 1810 se incorpora al ejército comandado por Castelli; intendente general de Policía en 1813."],["La Diligencia","calle","Diligencia: carruaje de cuatro ruedas arrastrado por diez o más caballos que se utilizaba para viajes y transporte de pasajeros; se llamó también galera."],["Julio Dimilta","plazoleta","Julio Dimilta (1912 a 1975), vecino de los barrios de Nueva Pompeya y Villa Soldati que lucha por el desarrollo y progreso de los mismos y de los derechos de sus vecinos."],["Dinamarca","calle","Dinamarca: país europeo. Capital: Copenhague."],["Jorge Di Pascuale","calle","Jorge Di Pascuale (1931 a 1976), dirigente gremial peronista; secretario general del Sindicato de Farmacia desde 1957 y secretario adjunto de la CGT. Por su militancia sufre persecución y exilio; es secuestrado el 29 de diciembre de 1976. Permanece desaparecido."],["Jorge Di Pascuale","espacio verde","Jorge Di Pascuale (1931 a 1976), dirigente gremial peronista; secretario general del Sindicato de Farmacia desde 1957 y secretario adjunto de la CGT. Por su militancia sufre persecución y exilio; es secuestrado el 29 de diciembre de 1976. Permanece desaparecido."],["Directorio","avenida","Directorio: poder ejecutivo creado por la Asamblea de 1813, que gobernó el país desde enero de 1814 hasta febrero de 1820."],["Carlos Di Sarli","plazoleta","Cayetano Di Sarli (1903 a 1960), pianista; director y compositor de Milonguero viejo, Bahía Blanca y Nido gaucho."],["Enrique Santos N° 18.520. Discépolo","plazoleta","Enrique Santos Discépolo (1901 a 1951), compositor, autor teatral, actor y poeta; autor de Cambalache, Cafetín de Buenos Aires, Esta noche me emborracho, Uno, y de las obras teatrales Blum, El organito y El hombre solo; se destaca como actor en Mateo y Levántate y anda."],["Tomás Di Taranto","espacio público","Tomás Di Taranto (1904 a 1985), artista plástico de origen italiano; recibe varios premios entre ellos el Primer Premio en el Salón de Luján en 1946; medalla de oro en el Salón de Aeronáutica en 1954; autor de Iglesia del Socorro y Vendedores de La Quiaca."],["Guillermo Divito","plazoleta","José Antonio Guillermo Divito (1914 a 1969), dibujante, creador de varios personajes de la historieta argentina como Oscar dientes de leche, El otro yo del doctor Merengue, Fúlmine y Fallutelli; en 1944 crea y dirige la revista Rico Tipo, hito fundamental de la revista de historieta humorística, en la que sus dibujos femeninos, las “chicas de Divito”, adquieren particular atención por sus insinuantes figuras."],["Doblas","calle","Francisco Gonzalo de Doblas (1780 a 1854), coronel; como comandante ge- neral, apoya en 1811 a las tropas que asedian Montevideo; en 1812 recluta en Misiones soldados para el Regimiento de Granaderos a Caballo que organizaba San Martín; comisario de Buenos Aires de 1813 a 1820. Gonzalo de Doblas (1744 a 1809), teniente coronel, padre del anterior; teniente gobernador de Candelaria en 1781; presenta al fin de su mandato la Memoria histórica, geográfica, política y económica sobre la provincia de Misiones de Indios Guaraníes; planea y da forma a la población de los Quilmes en la provincia de Buenos Aires; ejecuta un plan de defensa en la segunda invasión inglesa; comandante militar de Quilmes de 1807 a 1809. 12 DE OCTUBRE (calle). Ordenanza del 30-10-1914. 12 de Octubre de 1492: fecha del descubrimiento de América por Cristóbal Colón."],["Dolores","calle","Dolores: ciudad y partido de la provincia de Buenos Aires."],["El Domador","calle","Domador: oficio del hombre de campo que se dedica a amansar caballos."],["República Dominicana","calle","República Dominicana: estado de las Antillas. Capital: Santo Domingo."],["Hermana Alice Domon y Hermana Léonie Duquet","plazoleta","Léonie Reneé Duquet (1916 a 1977) y Alice Domon (1937 a 1977), monjas católicas francesas pertenecientes a la Congregación de las Misiones Extranjeras de París. Radicadas en la Argentina, se dedican a la catequesis y el trabajo social. Luego del golpe del 24 de marzo de 1976 participan activamente en las organizaciones de derechos humanos, por lo que son secuestradas en diciembre de 1977 en el operativo realizado en la Iglesia de la Santa Cruz. Arrojadas al mar con vida, los restos de Duquet (al igual que los de Esther Ballestrino de Careaga, María Ponce de Bianco y Azucena Villaflor de De Vincenti) son finalmente identificados por el Equipo Argentino de Antropología Forense, luego de haber sido encontrados en el cementerio de General Lavalle, cuando se exhuman siete cuerpos enterrados como NN que habían sido encontrados en las costas de San Bernardo y Santa Teresita entre diciembre de 1977 y enero de 1978. Los restos mortales de Léonie Reneé Duquet son sepultados el 25 de septiembre de 2005 en el predio de la Iglesia Santa Cruz. Alice Domon aún continúa desaparecida."],["Donado","calle","Agustín José Donado (1768 a 1831), funcionario; se encontraba al frente de la Imprenta de los Niños Expósitos cuando se entera de la llegada de un importante documento que traía la fragata inglesa Venerable y que le permite conocer el 18 de mayo de 1810 la situación en España; transmite así su información a Vieytes y Rodríguez Peña, iniciándose, a partir de ello, las jornadas de Mayo; diputado por San Luis en la Asamblea de 1813."],["Edgardo Donato","plazoleta","Edgardo Donato (1897 a 1963), violinista; compositor de A media luz, Muchacho y Julián. DON BOSCO véase BOSCO, DON."],["Don Cristóbal","calle","Don Cristóbal: batalla librada en la provincia de Entre Ríos el 10 de abril de 1840 entre las fuerzas de Lavalle y Echagüe en las cercanías del arroyo de ese nombre."],["Don Fulgencio","cantero central","Don Fulgencio: personaje que dio nombre a la historieta creada por Lino Palacio en 1932."],["Donizetti","calle","Cayetano Donizetti (1797 a 1848), compositor italiano; autor de las óperas Enrique de Borgoña, Lucrecia Borgia, Lucía de Lammermoor y Ana Bolena. DON ORIONE véase ORIONE, DON."],["Don Pepe","plaza","José Sciarrotta (1905 a 1998), filántropo; conocido en el barrio de Barracas por “Don Pepe”; colabora en la construcción de esta plaza y se hizo estimado por su noble gesto de entregar juguetes y golosinas a los niños."],["Don Segundo Sombra","calle","Don Segundo Sombra: novela de Ricardo Güiraldes publicada en 1926."],["Don Segundo Sombra","plaza","Don Segundo Sombra: novela de Ricardo Güiraldes publicada en 1926."],["Dorrego","avenida","Colección de Mapas Murales de la República Argentina. Ciudad y Distrito Federal de Buenos Aires. Publicado por Ángel Estrada y Cía., compilado y dibujado por Carlos Beyer, Buenos Aires, 1889."],["Coronel Nº 12.714. Dorrego","plaza","Manuel Dorrego (1787 a 1828), militar; combate en Tucumán y Salta; gobernador de Buenos Aires en 1827 acumula las funciones de ministro de Relaciones Exteriores; es derrocado por Lavalle y fusilado en los campos de Navarro el 13 de diciembre de 1828. 2 DE ABRIL DE 1982 (calle). Ordenanza N° 37.704-1982, BM N° 16.758. 2 de abril de 1982: fecha de la recuperación de las Islas Malvinas, Georgias y Sandwich del Sur para el patrimonio nacional. El 14 de junio del mismo año las fuerzas invasoras usurparon nuevamente este pedazo de tierra argentina."],["Luis María Drago","calle","Luis María Drago (1859 a 1921), jurisconsulto; ministro de Relaciones Exteriores en 1902, se opone a la intervención de países extranjeros en Venezuela para cobrar coercitivamente sus deudas públicas. Sus tesis denominadas La República Argentina y el caso de Venezuela y Cobro coercitivo de deudas públicas son conocidas internacionalmente con el nombre de Doctrina Drago."],["Dragones","calle","Dragones: regimiento de caballería que combatió durante las Invasiones Inglesas en 1806 y 1807."],["Arturo Antonio Dresco","calle","Arturo Antonio Dresco (1875 a 1961), escultor; profesor y vicedirector de la Academia Nacional de Bellas Artes; autor del Monumento a España y a Juan Larrea."],["Drumond","calle","Francisco Drummond (1803 a 1827), sargento mayor de marina de origen escocés; combate durante la guerra contra el Brasil al mando de la goleta Maldonado y del bergantín Independencia; es herido mortalmente en el combate de Monte Santiago."],["Juan Pablo Duarte","calle","Juan Pablo Duarte (1813 a 1878), organizador del movimiento de Independencia de Santo Domingo (República Dominicana) en 1844; su patria había sido invadida y sometida por Haití en 1822."],["Dublin","calle","Dublin: ciudad capital de Irlanda y del condado de su nombre."],["Alejandro Dumas","calle","Alejandro Dumas (1802 a 1870), escritor francés; autor de Los tres mosqueteros y El conde de Montecristo."],["Vito Dumas","calle","Vito Dumas (1900 a 1965), deportista; como nadador bate en 1925 el récord de permanencia en el agua; como navegante cruza el Atlántico en un bote a vela (1931 a 1932) y da la vuelta al mundo (1942 a 1943)."],["Santos Dumont","calle","Alberto Santos Dumont (1873 a 1932), aviador brasileño; precursor de la aeronavegación del país hermano."],["Henry Dunant","plaza","Henry Dunant (1828 a 1910), filántropo suizo; fundador de la Cruz Roja Internacional; comparte en 1901 el Premio Nobel de la Paz con Fréderic Passy."],["Dupuy","calle","Vicente Dupuy (1774 a 1843), coronel; combate durante las Invasiones Inglesas; teniente gobernador de San Luis de la Punta de 1814 a 1820, colabora en la formación del Ejército de los Andes; presidente del Departamento de la Costa Norte de Lima en 1821; asiste al sitio del Callao; gobernador político y militar de esa ciudad. DUQUET, HERMANA LÉONIE y DOMON, HERMANA ALICE véase DOMON Y HERMANA LÉONIE DUQUET, HERMANA ALICE. Notas."],["Ingeniero Carlos Echagüe","calle","Carlos Echagüe (1859 a 1907), ingeniero; miembro del grupo que inicia el servicio de energía eléctrica en Buenos Aires y en los trabajos sobre provisión de gas; jefe de la Dirección de Obras de Salubridad (luego Obras Sanitarias de la Nación); organizador de la entidad gremial La Fraternidad; presidente de la Sociedad Científica Argentina."],["Pedro Echagüe","calle","Pedro Echagüe (1821 a 1889), militar y escritor; combate en Sauce Grande, Don Cristóbal y Quebracho Herrado; fundador de los periódicos El Litoral de San Nicolás y El Riojano de La Rioja; autor de Apuntes de un proscripto, Ecos postreros, La Rinconada y Rosas y Urquiza en Palermo."],["Echauri","calle","Juan Francisco María de Echauri (?-1828), coronel; combate durante las Invasiones Inglesas, en Las Piedras, Tucumán y Salta; queda a cargo del gobierno de Tucumán durante el levantamiento del coronel Zelarrayán."],["Echeandía","calle","José María González de Echeandía (1794 a 1860), coronel uruguayo; actúa hasta 1814 en el Sitio de Montevideo; con el grado de capitán de ingenieros actúa en el Ejército Auxiliar del Perú, dictando clases de matemáticas; secretario militar durante el gobierno de Soler en 1820; director del Instituto Nacional de Enseñanza de Guerra de Montevideo."],["Echenagucía","calle","Mariano Salomé Echenagucía (1807 a 1869), coronel; combate durante la guerra contra el Brasil, en Caaguazú y Caseros; inspector de la frontera norte de Santa Fe en 1868 e inspector de Fronteras de la Nación en 1869."],["Vicente Anastasio de Echevarría","calle","Vicente Anastasio de Echevarría (1768 a 1857), jurisconsulto; enviado diplomático en la expedición de Belgrano al Paraguay; diputado por Buenos Aires al Congreso en 1817; miembro fundador del Instituto Histórico y Geográfico del Río de la Plata."],["Echeverría","calle","José Esteban Antonino Echeverría (1805 a 1851), poeta; autor de La Cautiva, El Matadero y el Dogma Socialista."],["Echeverría","plaza","José Esteban Antonino Echeverría (1805 a 1851), poeta; autor de La Cautiva, El Matadero y el Dogma Socialista."],["De la Economía","calle","Economía: homenaje a la ciencia que estudia la distribución de los bienes."],["República del Ecuador","plaza","Ecuador: país americano. Capital: Quito."],["Tomás A. Edison","avenida portuaria","Tomás Alva Edison (1847 a 1931), físico e inventor estadounidense; efectúa perfeccionamientos en la transmisión eléctrica, que revolucionan el telégrafo; inventa la lámpara eléctrica de filamento de carbón; perfecciona el micrófono y el gramófono; autor de Mi filosofía de la vida es el trabajo."],["Paloma Efrón","plazoleta","Paloma Efrón (1912 a 1977), cantante; periodista y actriz; intérprete de jazz; precursora en radio y televisión donde se destaca como periodista; fue conocida con el seudónimo de Blackie."],["Doctor Osvaldo Eguía","calle","Osvaldo Fermín Eguía (¿-?), médico; actúa durante la epidemia de fiebre amarilla de 1871 y diagnostica los primeros casos que aparecieron; director del Hospital de Alienados de 1871 a 1890."],["Manuel Eguía","calle","Manuel Eguía (?-1880), agrimensor; miembro del Departamento Topográfico en 1852; efectúa observaciones meteorológicas en Buenos Aires desde 1856 hasta 1875; profesor de la Facultad de Ciencias Físico-Matemáticas en 1874."],["Alberto Einstein","calle","Alberto Einstein (1879 a 1955), físico alemán; autor de la Teoría de la Relatividad; Premio Nobel de Física en 1921."],["De las Armas Ejército Argentino","plaza","De las Armas. Ejército Argentino: homenaje al Ejército y a las armas empuñadas por sus hombres para defender la Independencia desde los albores de nuestra nacionalidad."],["Ejército de los Andes","plaza","Ejército de los Andes: ejército creado y organizado por el general San Martín a partir del 6 de septiembre de 1814, ocasión en la que se hace cargo de las funciones de Gobernador Intendente de Cuyo, y con el cual consuma la Independencia de Chile. EL ALFABETO véase ALFABETO, EL. EL ALMA QUE CANTA véase ALMA QUE CANTA, EL. EL ARTESANO véase ARTESANO, EL."],["Elcano","avenida","Juan Sebastián Elcano (1476 a 1526), navegante español; participa en la expedición de Magallanes y, muerto éste en las Filipinas, asume el mando de la nao Victoria con la que arriba a España el 7 de septiembre de 1522, concluyendo así la proeza de dar por primera vez la vuelta al mundo."],["Elía","calle","José Eugenio de Elías (1760 a 1832), jurisconsulto; asesor letrado del gobierno de Montevideo, apoya la Revolución de Mayo; secretario del Congreso General Constituyente en 1817 cuando éste se instala en Buenos Aires; vicerrector de la Universidad de Buenos Aires en 1825 y 1826; diputado al Congreso de 1826. Juan Estanislao de Elías (1802 a 1870), militar, hijo del anterior; combate en la guerra contra el Brasil, en Navarro, Don Cristóbal, Quebracho Herrado y Los Laureles; autor de Memoria histórica sobre la campaña del Ejército Libertador (1839-41).4."],["Rufino de Elizalde","calle","Rufino de Elizalde (1822 a 1887), jurisconsulto; miembro fundador del Club del Progreso; presidente de la Comisión del Ferrocarril del Oeste en 1859; ministro de Relaciones Exteriores de Mitre. EL RESERO véase RESERO, EL."],["Rufino de Elizalde","plaza","Rufino de Elizalde (1822 a 1887), jurisconsulto; miembro fundador del Club del Progreso; presidente de la Comisión del Ferrocarril del Oeste en 1859; ministro de Relaciones Exteriores de Mitre. EL RESERO véase RESERO, EL."],["El Salvador","calle","El Salvador: país centroamericano. Capital: San Salvador. EMBAJADA DE ISRAEL “EN MEMORIA DEL ATENTADO” véase ISRAEL “EN MEMORIA DEL ATENTADO”, EMBAJADA DE."],["El Salvador","plazoleta","El Salvador: país centroamericano. Capital: San Salvador. EMBAJADA DE ISRAEL “EN MEMORIA DEL ATENTADO” véase ISRAEL “EN MEMORIA DEL ATENTADO”, EMBAJADA DE."],["Empedrado","calle","Empedrado: departamento, localidad y río de la provincia de Corrientes."],["Carlos Encina","calle","Carlos Encina (1838 a 1882), ingeniero y poeta; director general de Escuelas en 1872; decano de la Facultad de Ciencias Físicas, Exactas y Matemáticas; autor de Canto a Colón y La lucha de la idea."],["Padre Fernando Endorcia","cantero central","Fernando Endorcia (1921 a 1985), sacerdote; conocido como el cura “albañil”; tiene una destacada actuación en el barrio de Mataderos, dedica su vida a ayudar a los más humildes de la comunidad; crea la Iglesia y dirige el Colegio Nuestra Señora de Luján de los Patriotas. ENRIQUE “EL NAVEGANTE”, INFANTE DON (plazoleta). Ordenanza N° 14.636-1962, BM N° 11.930. Enrique “El Navegante” (1394 a 1460), príncipe de Portugal que emprende el descubrimiento de las costas africanas del Atlántico; descubre así la Isla de Madera en 1418; las islas Azores de 1432 a 1457; el Río del Oro en 1436 y Senegal en 1445."],["Ensenada","calle","Ensenada: ciudad y puerto de la provincia de Buenos Aires en el partido de La Plata."],["Provincia de Entre Ríos","cantero central","Entre Ríos: provincia de la República Argentina. Capital: Paraná."],["Epecuén","calle","Epecuén: laguna salada de la provincia de Buenos Aires."],["Epuyén","calle","Epuyén: lago, río y localidad de la provincia de Chubut."],["Erasmo","calle","Desiderio Erasmo (1467 a 1536), pensador y humanista holandés; precursor del liberalismo; sus obras fueron editadas por primera vez por Froben bajo el nombre de Opera omnia Desiderii Erasmi."],["Doctor Rodolfo Erausquin","plazoleta","Rodolfo Tomás Erausquin (1881 a 1945), médico, odontólogo, catedrático e investigador de origen español; obtiene distinciones por sus investigaciones sobre la membrana de nasmith y sobre embriología dentaria; profesor de la Universidad de Buenos Aires; director de la Revista Odontológica de 1917 a 1919; autor de Canalículos dentarios y Desarrollo del aparato dentario de los mamíferos."],["Ercilla","calle","Alonso de Ercilla y Zúñiga (1533 a 1594), poeta y militar español; autor de La Araucana."],["Erézcano","calle","Francisco de Erézcano (1794 a 1856), coronel de marina; combate en los bloqueos al puerto del Callao en 1819; participa en la expedición a Talcahuano y Valdivia en 1820; actúa en la segunda campaña de la Sierra sirviendo bajo las órdenes de Arenales en 1821; colabora en la preparación de la expedición a Puertos Intermedios."],["Doctor Carlos Alberto Erro","plazoleta","Carlos Alberto Erro (1903 a 1968), abogado, escritor y profesor; destacado en el campo de la filosofía, sociología y en las letras; autor de Tiempo lacerado, Medida del criollismo y El sujeto del derecho."],["Escalada","avenida","Antonio José de Escalada (1753 a 1821), funcionario; presidente de la Junta de Observación y Director Supremo interino en 1816; miembro de la Junta de Representantes de Buenos Aires en 1820. Francisco Antonio de Escalada (1749 a 1835), funcionario, hermano del anterior; gobernador interino de Buenos Aires en 1816; presidente del Cabildo, proclama la Jura de la Independencia en la plaza de la Victoria el 13 de septiembre de 1816. José María de Escalada (1787 a 1839), coronel, hijo del anterior; combate en el sitio de Montevideo y en la guerra contra el Brasil; presidente del Banco Nacional en 1831. Manuel de Escalada (1795 a 1871), general, hijo del primero, combate en San Lorenzo, Chacabuco, Maipú y en la guerra contra el Brasil; ministro de Guerra de Lavalle, Viamonte, Vicente López y Obligado. Mariano de Escalada (1796 a 1841), teniente coronel, hijo del primero; combate en San Lorenzo, Chacabuco y Maipú; edecán del general San Martín. Mariano José de Escalada (1799 a 1870), sacerdote, hijo de Francisco Antonio; obispo diocesano en 1855 y primer arzobispo de Buenos Aires en 1865. María Eugenia Escalada de De María (1781 a 1822), patricia, hija del primero; contribuye económicamente con el Primer Ejército Auxiliar en 1810 y con el del Alto Perú. Nieves Escalada de Oromí (1799 a 1867), patricia, hija del primero; miembro de la Sociedad Patriótica de Buenos Aires. Bernabé Antonio de Escalada (1780 a 1857), jurisconsulto, hijo del primero; diputado a la Legislatura de Buenos Aires en 1827; presidente de la Casa de Moneda de 1836; suscribe en 1847 la declaración contra Inglaterra y Francia. Homenaje conjunto a la familia Escalada. También es miembro de la familia doña María de los Remedios de Escalada de San Martín, a quien no se incluye aquí por poseer ella una calle con su nombre."],["Comandante Celedonio Escalada","calle","Emeterio Celedonio de Escalada y Palacios (1762 a 1819), militar; propagador de las ideas revolucionarias de Mayo; comandante militar de la villa de Santo Domingo de Soriano (Uruguay) desde 1811; combate en San Lorenzo; comandante general del Parque de Artillería de Buenos Aires en 1816."],["Remedios Escalada de San Martín","calle","María de los Remedios Escalada de San Martín (1797 a 1823), patricia; esposa del general José de San Martín."],["Doctor Florencio Escardó","espacio verde","Florencio Escardó (1904 a 1992); médico pediatra y escritor; titular de la cátedra de Pediatría en 1957; decano de la Facultad de Medicina en 1958 y vicerrector de la UBA. Su labor más importante transcurre en el Hospital de Niños Ricardo Gutiérrez, donde por 45 años ocupa diversos puestos. Concreta allí una reforma trascendental, que es la de internar a las madres con los pacientes. Hasta entonces las madres podían visitar a los hijos internados de día, entre las 17 y las 19, y luego los niños eran alimentados con mamaderas que colgaban de soportes metálicos sobre las cunas. Periodista de los diarios Crítica, Clarín, El Mundo y La Nación, firma sus columnas con los seudónimos de “Piolín de Macramé” y “Juan de Garay”. Escribe numerosos libros de pediatría y además, poemas, ensayos y tangos."],["Escobar","calle","Alonso de Escobar (1545-¿1612?), acompaña a Juan de Garay en la fundación de la ciudad de Buenos Aires en 1580; regidor del Cabildo de la misma."],["Escribano","calle","Bernardino Escribano (1790 a 1834), coronel; combate en San Lorenzo, Chacabuco, Curapaligüe, Gavilán, Talcahuano, Maipú y Bío-Bío; fundador de Fuerte Federación (hoy Junín) en 1828."],["Doctor Pedro Escudero","plazoleta","Pedro Escudero (1877 a 1963), médico dietólogo; fundador de los estudios sobre nutrición en el país; fundador y director del Instituto Municipal de la Nutrición, luego Instituto Nacional, y de la Escuela Municipal de Medicina en 1933; autor de Lecciones de Clínica Médica, Alimentación y Tratamiento de la Diabetes. ESCUELA LA BANDERITA véase BANDERITA, ESCUELA LA."],["De las Esculturas","paseo","De las Esculturas: se denomina con este nombre a las veredas de la avenida Boedo entre San Juan e Independencia, donde, tomando como modelo a la ciudad de Resistencia, el escultor Francisco Reyes y la Junta de Estudios Históricos del barrio de Boedo, inician en las décadas de 1980 y 1990 el emplazamiento de esculturas en la vía pública."],["Eslovaquia","espacio verde","República de Eslovaquia: país europeo. Capital: Bratislava."],["República de Eslovenia","calle","República de Eslovenia: país europeo. Capital: Ljubljana."],["Esmeralda","calle","Esmeralda: fragata española apresada por el almirante Cochrane en la rada del Callao el 5 de noviembre de 1820."],["Esnaola","calle","Juan Pedro Esnaola (1808 a 1878), músico; autor de Minué Federal y El pescador de Palermo; realiza en 1860 el arreglo del Himno Nacional aceptado oficialmente."],["España","avenida","España: país europeo. Capital: Madrid."],["España","parque","España: país europeo. Capital: Madrid."],["Espartaco","calle","Espartaco (113-71 a.C.), caudillo de los esclavos rebeldes de Roma derrotado y muerto por Marco Craso."],["Esparza","calle","Juan Miguel Esparza (?-1767), funcionario; regidor del Cabildo en 1750 y alcalde de primer voto en 1764. José de Esparza (¿-?), funcionario; regidor del Cabildo en 1729. Miguel Jerónimo Esparza (¿-?), funcionario defensor de menores en 1719. Martín Esparza (?-1807), sacerdote; formaba parte del convento de Santo Domingo y muere al ser atacado el edificio por los ingleses en 1807."],["General Gerónimo Espejo","calle","Gerónimo Espejo (1801 a 1889), general y escritor; combate en Chacabuco, Cancha Rayada, Maipú, en la toma de Lima en 1821, en la campaña de Puertos Intermedios y en la guerra contra el Brasil; autor de Apuntes históricos sobre la expedición libertadora al Perú y Recuerdos históricos. San Martín y Bolívar. Entrevista de Guayaquil."],["La Espiga","calle","Espiga: inflorescencia cuyas flores y luego los frutos están sentados a lo largo de un eje."],["Espinillo","calle","Espinillo: árbol o arbusto del género de las mimosas que abunda en el monte argentino."],["Espinosa","calle","Gervasio Espinosa (1796 a 1865), general; combate en Campichuelo, en el segundo sitio de Montevideo; comandante militar de Rojas de 1819 a 1820; combate en Navarro; representante en la Legislatura de Buenos Aires en 1853."],["Arzobispo Espinosa","calle","Mariano Antonio Espinosa (1844 a 1923), sacerdote; capellán de la expedición al desierto comandada por el general Julio A. Roca en 1879; arzobispo de Buenos Aires desde 1900 hasta su muerte."],["Coronel de Marina Tomás Espora","calle","Tomás Espora (1800 a 1835), coronel de marina; actúa en los bloqueos al Callao y en la toma de la Esmeralda; combate en la guerra contra el Brasil, comandando la nave insignia 25 de Mayo y la goleta Maldonado, entre otras; comandante general de Marina en 1828."],["Espronceda","calle","José de Espronceda y Delgado (1808 a 1842), poeta español; autor de El estudiante de Salamanca y El diablo mundo."],["Esquel","calle","Esquel: ciudad de la provincia del Chubut, capital del departamento de Futaleufú."],["Esquina","calle","Esquina: ciudad y departamento de la provincia de Corrientes."],["Esquiú","calle","Mamerto Esquiú (1826 a 1883), sacerdote; vicepresidente de la Convención Provincial que dicta la segunda constitución de Catamarca en 1855; obispo de Córdoba desde 1880."],["Estados Unidos","calle","Estados Unidos: país americano. Capital: Washington."],["Estero Bellaco","calle","Estero Bellaco: batalla librada por el general Mitre al mando del ejército aliado, el 2 de mayo de 1866, durante la guerra contra el Paraguay."],["Esteves Saguí","calle","Miguel Esteves Saguí (1814 a 1892), jurisconsulto; miembro de la Convención Constituyente del Estado de Buenos Aires en 1854; miembro de la Comisión Revisora de la Constitución Nacional en 1860; presidente de la Municipalidad de Buenos Aires; autor de Tratado elemental de procedimientos civiles en el Foro de Buenos Aires."],["Ingeniero José N° 11.425. Estévez","plaza","Denominación usual. José Estévez (1879 a 1942), ingeniero; director de Obras Públicas de la Municipalidad, autor de numerosas obras de urbanismo y saneamiento; participa de las aperturas de las avenidas 9 de Julio y Corrientes; presidente de Obras Sanitarias de la Nación."],["Manuel Estévez","calle","Manuel Estévez (1824 a 1893), político de origen español; juez de Paz (1858- 1859 y 1880); presidente de la Comisión Municipal de Higiene (1867) de Barracas al Sur (hoy Avellaneda); intendente de Barracas al Sur (1889)."],["Estivao","calle","Jacinto Estivao (1809 a 1846), coronel; combate en los ejércitos unitarios del general Fructuoso Rivera, contra el presidente Oribe, de 1836 a 1838; comandante de Colonia en 1842; muere en combate durante el movimiento riverista de 1846."],["Estocolmo","calle","Estocolmo: ciudad capital de Suecia y del condado de su nombre."],["Estomba","calle","Juan Ramón Estomba (1790 a 1829), coronel; combate en Cotagaita, Suipacha, Las Piedras, Tucumán, Salta, en las tomas de Lima y Callao, Junín y contra el indígena en la frontera sur de Buenos Aires; levanta en 1828 los fuertes de La Esperanza y Protectora Argentina, alrededor de los cuales nace Bahía Blanca; comandante general de la frontera sur en 1829."],["Estonia","calle","Estonia: estado báltico. Capital: Tallín."],["Estrada","calle","José Manuel Estrada (1842 a 1894), escritor y político; autor de El signo de la Confederación y El catolicismo y la democracia; fundador de La Revista Argentina; decano de la Facultad de Filosofía y Letras en 1875; rector del Colegio Nacional de Buenos Aires de 1876 a 1888; presidente de la Asociación Católica, funda el diario La Unión mediante el cual polemiza con los liberales."],["Juez Estrada","calle","Juan Bautista Estrada (1872 a 1924), jurisconsulto; juez de Comercio de la Capital Federal; presidente de la Sociedad de Ex Alumnos del Colegio del Salvador."],["Estrella Federal","calle","Estrella Federal: nombre vulgar con que se conoce en nuestro país la planta ornamental originaria de América Central denominada Euphorbia Pulchérrima, cuya inflorescencia bracteada ha sido tomada como símbolo del federalismo por su forma de estrella de color rojo."],["Euclides","calle","Euclides de Alejandría (¿-?), matemático griego; autor de Elementos de geometría y del postulado que lleva su nombre."],["Evita","plaza","Evita: diminutivo con el que se identifica popularmente a María Eva Duarte de Perón (1919 a 1952). Véase PERÓN, EVA (avenida y plazoleta). También se la recuerda en la plazoleta ABANDERADA DE LOS HUMILDES."],["Éxodo Jujeño","plaza","Éxodo Jujeño: homenaje a la hazaña que el pueblo de Jujuy protagoniza el 23 de agosto de 1812, cuando abandona su ciudad con un objetivo estratégico ante el avance de las fuerzas realistas del general Goyeneche. La medida fue decretada por Belgrano el 29 de julio de ese mismo año."],["Homero Expósito","cantero central","Homero Aldo Expósito (1918 a 1987), poeta y compositor; autor de Tristezas de la calle Corrientes, Margo, Afiches, Sexto piso, Trenzas, Yuyo verde y Ese muchacho Troilo; y junto a su hermano Virgilio, de Farol, Maquillaje y Naranjo en Flor."],["Petrona Eyle","calle","Petrona Eyle (1866 a 1945), médica y feminista; lucha por los derechos de la mujer; funda y sostiene la Liga contra la Trata de Blancas; participa en las campañas para la obtención del voto femenino; primera directora de la revista Nuestra Causa, órgano del movimiento femenino."],["Encarnación Ezcurra","calle","Encarnación Ezcurra de Rosas (1795 a 1838), patricia, esposa de Juan Manuel de Rosas; su intervención es decisiva en la llamada Revolución de los Restauradores en 1833."],["Ezeiza","calle","Juan Ramón Ezeiza (1798 a 1864), hacendado; participa en la Revolución del Sud en 1839; combate en Chascomús; juez de Paz del partido de Mar Chiquita en 1852."],["Gabino Ezeiza","calle","Gabino Ezeiza (1858 a 1916), poeta y payador; autor de los inmortales cantos Saludo a Paysandú, Salve y Libertador y de las obras teatrales Lucía Miranda y El cacique Mangore; su nombre encabeza la legión de los cultores del arte de la payada. Notas."],["Guillermo Facio Hebequer","plazoleta","Guillermo Facio Hebequer (1889 a 1935), dibujante, pintor y grabador uruguayo; miembro de los Artistas del Pueblo, grabadores y escultores anarquistas que proponen un “arte social”; representa en sus obras la vida cotidiana de los más humildes; autor de La huelga, En la fundición y Fin de Jornada."],["La Facultad","calle","Facultad: homenaje a cada una de las grandes divisiones de una universidad correspondiente a una rama del saber, y en la que se dan las enseñanzas de una carrera o de varias carreras afines."],["Facundo","calle","Facundo. Civilización y barbarie en las pampas argentinas: libro de Domingo Faustino Sarmiento publicado en 1845."],["Fernando Fader","calle","Fernando Fader (1882 a 1935), pintor; autor de La vida de un día, La comida de los cerdos, Los manilas, La tarde, Desnudo ante la estufa y Tierra mansa."],["José Fagnano","avenida","José Fagnano (1844 a 1916), sacerdote de origen italiano; integra en 1875 la primera expedición salesiana que llega a la Argentina; párroco de Patagones desde 1880; prefecto apostólico de la Patagonia Meridional en 1883; acompaña a Ramón Lista en su expedición a Tierra del Fuego en 1886 y reconoce el lago magallánico que lleva su nombre; establece en 1888 un centro misionero en las Islas Malvinas."],["Padre Fahy","calle","Antonio Domingo Fahy (1805 a 1871), sacerdote de origen irlandés; llega a Buenos Aires en 1844 para cubrir las necesidades espirituales de los inmigrantes de esa nacionalidad; fundador del Hospital Irlandés; fallece al ser contagiado por la fiebre amarilla, mientras auxiliaba a los enfermos en la epidemia de 1871."],["Coronel Ramón L. Falcón","calle","Ramón Lorenzo Falcón (1855 a 1909), militar; combate contra el aborigen de las fronteras sur de Córdoba y Buenos Aires; participa en la expedición al desierto de 1879; jefe de la Policía de la Ciudad de Buenos Aires y creador de la Escuela de Policía, muere junto con su ayudante Juan Alberto Lartigau en un atentado anarquista."],["Coronel Ramón L. Falcón","plaza","Ramón Lorenzo Falcón (1855 a 1909), militar; combate contra el aborigen de las fronteras sur de Córdoba y Buenos Aires; participa en la expedición al desierto de 1879; jefe de la Policía de la Ciudad de Buenos Aires y creador de la Escuela de Policía, muere junto con su ayudante Juan Alberto Lartigau en un atentado anarquista."],["Falucho","calle","Antonio Ruiz (?-1824), soldado patriota; apodado el Negro Falucho, era un esclavo liberto de don Antonio Ruiz, de quien tomó su nombre; combate en Tucumán, Salta, Vilcapugio, Ayohuma, Chacabuco, Maipú y en la Expedición Libertadora al Perú; muere fusilado el 7 de febrero de 1824 en la sublevación del Callao, cuando, haciendo guardia al pie de la Bandera, se resiste a que la misma sea sustituida por la enseña real española."],["Falucho","plazoleta","Antonio Ruiz (?-1824), soldado patriota; apodado el Negro Falucho, era un esclavo liberto de don Antonio Ruiz, de quien tomó su nombre; combate en Tucumán, Salta, Vilcapugio, Ayohuma, Chacabuco, Maipú y en la Expedición Libertadora al Perú; muere fusilado el 7 de febrero de 1824 en la sublevación del Callao, cuando, haciendo guardia al pie de la Bandera, se resiste a que la misma sea sustituida por la enseña real española."],["Falucho San Luis","calle","Falucho San Luis: nave de guerra española apresada en Colonia el 9 de enero de 1814; participa en el combate de Martín García; es recapturada por los realistas pero vuelve a la marina patriota al rendirse Montevideo."],["Famaillá","calle","Famaillá: último combate librado por el general Juan Lavalle el 19 de septiembre de 1841, donde es derrotado por Oribe."],["Famatina","calle","Famatina: departamento, localidad y sierra de la provincia de La Rioja."],["Faraday","calle","Miguel Faraday (1791 a 1867), físico y químico inglés; descubridor del benzol en el gas de alumbrado; dedicado a la electricidad, concibe la llamada “jaula de Faraday” y formula la ley de la electrólisis que lleva su nombre."],["Monseñor Hermenegildo Fazio","plazoleta","Hermenegildo Saverio Fazio (1904 a 1965), sacerdote; párroco de la Basílica de San Antonio de Padua (Villa Devoto) desde 1939 hasta 1965; atiende las necesidades espirituales en el Hospital Zubizarreta; Paulo VI le otorga, en 1963, el título honorífico de Monseñor (Camarero Secreto de Su Santidad)."],["Fecundidad","calle","Fecundidad: novela del escritor francés Emilio Zola, publicada en 1899."],["Teodoro Pablo Fels","calle","Teodoro Pablo Fels (1891 a 1969), aviador, es el primero que recibe un diploma que lo habilita como tal el 23 de mayo de 1912; es el primer aviador que atraviesa el Río de la Plata en 1913; el 2 de septiembre de 1917 conduce, también por primera vez, una valija postal por vía aérea desde Buenos Aires hasta Montevideo."],["Fernández","calle","Román Rosendo Fernández (1779 a 1858), coronel uruguayo; combate durante las Invasiones Inglesas en Montevideo y Buenos Aires; se pronuncia en 1811 por la Junta de Buenos Aires; combate en Las Piedras, en el sitio de Montevideo en 1814, en el Ejército Auxiliar del Alto Perú y en la guerra contra el Brasil; presidente de la Legislatura de Entre Ríos."],["Macedonio Fernández","calle","Macedonio Fernández (1874 a 1952), escritor; autor de No todo es vigilia la de los ojos abiertos, Papeles de recién venido, Adriana Buenos Aires y Una novela que comienza."],["Fernández Blanco","calle","Ángel Fernández Blanco (1778 a 1851), comerciante y funcionario; producida la Revolución de Mayo, forma las Milicias Patriotas Correntinas, una parte de las cuales integra el ejército de Belgrano que marcha al Paraguay; coopera económicamente con el general Belgrano; captura a los rebeldes de la sublevación de Arroyo de la China."],["Fernández de Enciso","calle","Juan Fernández de Enciso (¿-?), capitán; acompaña a Garay en la fundación de Buenos Aires en 1580; es nombrado procurador de la flamante ciudad."],["General Francisco Fernández de la Cruz","avenida","Francisco Fernández de la Cruz (1779 a 1835), militar; combate durante las Invasiones Inglesas; gobernador de Salta en 1813; jefe del Ejército del Norte en 1814 y del Ejército Auxiliar del Perú en 1819; ministro de Guerra y Marina de Martín Rodríguez, Las Heras y Rivadavia."],["Diego Fernández Espiro","calle","Diego Fernández Espiro (1862 a 1912), periodista y poeta; escribe crítica literaria en La Razón y política en Libre Palabra; autor de Espejismo y Patria."],["Baldomero Fernández Moreno","calle","Baldomero Fernández Moreno (1886 a 1950), poeta; autor de Ciudad, Versos de Negrita, San José de Flores y Parva."],["Ferrari","calle","José Ferrari (¿1785?-1841), hacendado; propietario de tierras sobre las costas del río Samborombón, actual partido de Brandsen, participa en el pronunciamiento de 1839 contra Juan Manuel de Rosas."],["Antonino M. Ferrari","calle","Antonino M. Ferrari (1856 a 1914), jurisconsulto; profesor universitario; diputado provincial; miembro del Directorio del Tribunal de Cuentas de la Provincia de Buenos Aires; presidente y fundador del banco El Hogar Argentino."],["Ferré","calle","Pedro Ferré (1788 a 1867), brigadier general; gobernador intendente y capitán general de Corrientes de 1824 a 1827, de 1827 a 1828, de 1830 a 1833 y de 1839 a 1843; diputado por Catamarca en el Congreso General Constituyente de 1853."],["Andrés Ferreyra","calle","Andrés Ferreyra (1863 a 1928), pedagogo; inspector general de escuelas de la Capital; autor del libro de lectura El Nene, Curso completo de idioma nacional y Aventuras de un niño."],["Ferrocarril","calle","Ferrocarril: recuerda al invento del ingeniero Jorge Stephenson, quien en 1814 construye la primera locomotora, reformándola al año siguiente. En nuestro país el primer servicio ferroviario se inaugura el 29 de agosto de 1857, entre la estación del Parque (plaza Lavalle) y Floresta."],["Coronel Apolinario Figueroa","calle","Apolinario Figueroa (1771 a 1842), militar; jefe de la Milicia Urbana de Salta en 1812; combate en Tucumán y Salta; gobernador de la provincia de Potosí en 1813 y 1815; colabora con Güemes en la defensa de la Frontera Norte."],["Presidente Figueroa Alcorta","avenida","José Figueroa Alcorta (1860 a 1931), jurisconsulto; vicepresidente de la República durante la presidencia del doctor Manuel Quintana y presidente de la Nación de 1906 a 1910."],["Filiberto","calle","Filiberto: combate librado durante la guerra contra el Brasil el 22 de febrero de 1828, por el coronel Ángel Pacheco en los potreros de Filiberto."],["Juan de Dios Filiberto","calle","Juan de Dios Filiberto (1885 a 1964), músico; creó y dirigió la primera Orquesta Folklórica Municipal; autor de Caminito, Quejas de bandoneón, El pañuelito y Clavel del aire."],["Paseo República de Filipinas","cantero central","Filipinas: estado del sudeste asiático. Capital: Manila."],["Presbítero Virgilio Filipo","cantero central","Virgilio Filipo (1896 a 1969), sacerdote; capellán del Orfelinato Regina Colle; párroco de la Inmaculada Concepción de Belgrano desde 1939; diputado nacional y adjunto eclesiástico a la presidencia de la Nación (1947 a 1948)."],["Finlandia","calle","Finlandia: país europeo. Capital: Helsinki."],["Carlos J. Finlay","avenida","Carlos Juan Finlay y Barres (1833 a 1915), médico y biólogo cubano; inicia investigaciones sobre la fiebre amarilla afirmando que la misma era transmitida por un mosquito, lo cual es el antecedente fundamental que permite a Walter Reed, al confirmar la hipótesis del cubano, iniciar una lucha más efectiva contra el mal."],["Doctor Enrique Finochietto","calle","Enrique Finochietto (1881 a 1948), médico; cirujano jefe del Hospital Argentino instalado en París durante la Primera Guerra Mundial; profesor suplente de Clínica Quirúrgica de la Facultad de Medicina de Buenos Aires; imagina y crea instrumentos y aparatos de cirugía, muchos adoptados universalmente, entre ellos: la cama ortopédica que lleva su nombre y el “fronto lux”, sistema de iluminación para cirugía; autor de Cirugía del colon y Cirugía del estómago y duodeno."],["Doctor Ricardo N° 18.523. Finochietto","plazoleta","Ricardo Finochietto (1888 a 1962), médico cirujano; dirige la Escuela Quirúrgica Municipal para graduados desde 1953; escribe importantes obras dentro de su especialidad; jefe de cirugía del Hospital Rawson."],["Francisco Fiorentino","plazoleta","Francisco Fiorentino (1905 a 1955), músico, compositor y cantor; actúa en la orquesta de Aníbal Troilo de 1937 a 1943, destacándose en sus interpretaciones de Tristezas de la calle Corrientes, Tinta roja y Barrio de tango; autor de En las noches y Pa´ qué seguir."],["Roberto Firpo","plazoleta","Roberto Firpo (1884 a 1969), pianista; compositor de La muchacha del arrabal, Sentimiento criollo, El talento, Toda la vida y El amanecer."],["Doctor Marcelo J. Fitte","calle","Marcelo J. Fitte (1895 a 1950), médico; se desempeña en los hospitales Muñiz, Rawson y Fernández; especialista en parálisis infantil, es el fundador de ALPI (Asociación de Lucha contra la Parálisis Infantil); autor de Asistencia social en la parálisis infantil y Tratamiento actual de la parálisis infantil."],["Fitz Roy","calle","Roberto Fitz Roy (1805 a 1865), almirante, astrónomo y geógrafo inglés; comandante del barco Beagle, explora las costas de la Patagonia y Tierra del Fuego entre 1828 y 1830; explora las costas magallánicas y la costa sudamericana entre 1831 y 1836, participando de esta expedición el sabio Carlos Darwin."],["Flor del Aire","calle","Flor del aire: nombre vulgar dado a plantas de la familia de las bromeliáceas, típicas de las selvas argentinas."],["Flores","barrio","Juan Diego Flores (¿1718?-1801), hacendado; compra estas tierras en 1776 y desde entonces las mismas se identifican con su apellido. Ramón Francisco Flores (1776 a 1825), hijo adoptivo de Juan Diego que, junto con Antonio Millán, es el fundador del pueblo que perpetúa el apellido de esta familia. El nombre tuvo consagración oficial al erigirse, en 1806, el curato de San José de Flores."],["Celedonio Esteban Flores","plazoleta","Celedonio Esteban Flores (1896 a 1947), poeta; autor de los tangos Mano a mano, Margot, Tengo miedo, Corrientes y Esmeralda y Si se salva el pibe y de la colección de versos Chapaleando barro."],["General Venancio Flores","calle","Venancio Flores (1803 a 1868), brigadier general uruguayo; presidente del Uruguay de 1854 a 1855 y de 1865 a 1868; combate en Sarandí, Cepeda y Pavón; jefe de las fuerzas orientales en la guerra contra el Paraguay."],["Floresta","barrio","Floresta: si bien aún existen dudas con respecto al origen de este nombre, se estima que proviene de un local de recreo allí existente y que quizás aludiera a las características del lugar en lo que hace a su vegetación. El nombre recibe su oficialización cuando el 29 de agosto de 1857 el Ferrocarril del Oeste, en su viaje inaugural, transforma la estación La Floresta en el punto final de su recorrido."],["Floresta","calle","Floresta: si bien aún existen dudas con respecto al origen de este nombre, se estima que proviene de un local de recreo allí existente y que quizás aludiera a las características del lugar en lo que hace a su vegetación. El nombre recibe su oficialización cuando el 29 de agosto de 1857 el Ferrocarril del Oeste, en su viaje inaugural, transforma la estación La Floresta en el punto final de su recorrido."],["Florida","calle","Florida: batalla librada en La Florida, Bolivia, el 25 de mayo de 1814 en la que el entonces coronel Álvarez de Arenales vence a los realistas."],["El Fogón","calle","Fogón: lugar donde se enciende el fuego en las cocinas de estancia y alrededor del cual se reúne la peonada al amanecer o en la noche y también durante los días de lluvia."],["Del Fomentista","calle","Del Fomentista: en reconocimiento a los vecinos que contribuyeron al progreso de los barrios por medio de las Sociedades de Fomento."],["Fonrouge","calle","Julio Nicolás José Fonrouge de Lesseps (1804 a 1876), coronel de marina de origen francés; combate en la guerra contra el Brasil y en Caseros; sirve en la Escuela de la Confederación; jefe del Resguardo de Concordia hasta 1872."],["Coronel Luis Jorge Fontana","calle","Luis Jorge Fontana (1846 a 1920), militar; naturalista del Museo Público de Buenos Aires; gobernador y jefe de las guarniciones militares del Chaco de 1876 a 1880; estudia las costas de los ríos Pilcomayo y Bermejo; fundador de la ciudad de Formosa en 1879; gobernador del Chubut en 1885 y descubridor del lago que lleva su nombre."],["Norma Fontenla","cantero central","Norma Fontenla (1929 a 1971), primera bailarina del Teatro Colón; recibe el premio de mejor bailarina en el Festival Internacional de París. Muere junto con ocho bailarines al caer el avión donde viajaba en la costa del Río de la Plata el 10 de octubre de 1971."],["León Fontova","plazoleta","León Fontova (1875 a 1949), violinista de origen español; fundador del Instituto Musical Fontova en 1904, de la Sociedad Argentina de Música de Cámara en 1911 y de la Asociación Filarmónica Argentina en 1920; autor de Canciones escolares y Método para violín."],["Forest","avenida","Carlos Forest (1787 a 1823), coronel de origen francés; combate durante la segunda invasión inglesa, en Las Piedras, Tucumán, Salta, Vilcapugio y Sipe- Sipe."],["Forja","cantero central","Fuerza de Orientación Radical de la Joven Argentina: movimiento político surgido de la Unión Cívica Radical y creado el 29 de junio de 1935 por Arturo Jauretche, Homero Manzi y otros, con la finalidad de reivindicar el ideario de Hipólito Yrigoyen; su primer presidente es el doctor Luís Dellepiane. Su proclama “somos una Argentina colonial, queremos ser una Argentina Libre” tendrá particular importancia entre la fecha de su creación y el año 1945, cuando muchos de sus miembros se integran al naciente movimiento peronista."],["Provincia de Formosa","cantero central","Formosa: provincia de la República Argentina. Capital: Formosa."],["Raquel Forner","parque","Raquel Forner (1902 a 1988), artista plástica; encara en su obra temas diversos, desde las series de la Guerra Civil Española y la Segunda Guerra Mundial hasta las series del Espacio, donde expresa su indagación sobre el cosmos; entre sus numerosas distinciones cabe destacar la medalla de oro en la Exposición Internacional de París (1937), el Primer Premio Nacional de Pintura en el XXXII salón Nacional de Bellas Artes (1942), el Premio Augusto Palanza otorgado por la Academia Nacional de Bellas Artes (1947) y el Gran Premio de Honor en el XLV Salón Nacional de Bellas Artes (1956). Casada con el escultor Alfredo Bigatti, en 1982 crea en su casa-taller de la calle Bethlem (ex Humberto I) 443, la Fundación Museo Forner-Bigatti. En ese mismo año su obra Origen de una nueva dimensión es destinada al edificio de la Organización de los Estados Americanos en la ciudad de Washington, EE.UU."],["Félix O. Fouiller","calle","Félix O. Fouiller (1882 a 1937), periodista y funcionario; secretario del intendente Cantilo; fundador y presidente de la Biblioteca Domingo F. Sarmiento de Villa Pueyrredón, barrio en el cual, junto con el de Villa Urquiza, desarrolla su labor ciudadana. Funda en 1931 el vespertino Tribuna Libre."],["Fournier","calle","César Fournier (1798 a 1828), marino de origen italiano; combate durante la guerra contra el Brasil; comandante del Juncal, se pierde en el Atlántico junto con su nave y la 25 de Mayo el 20 de septiembre de 1828."],["Fraga","calle","Manuel Fraga (1831 a 1866), coronel; combate en Caseros, Cepeda, Pavón y en la guerra contra el Paraguay, donde es herido mortalmente en el asalto de Curupaytí el 22 de septiembre de 1866."],["Fragata Céfiro","calle","Fragata Céfiro: nave a la que en 1815 se le acuerda patente de corso y que opera luego en la costa del Brasil; perteneció a la escuadra del almirante Brown."],["Fragata Halcón","calle","Fragata Halcón: nave perteneciente a la escuadra del almirante Brown; fue utilizada para la guerra de corso y comandada por Hipólito Bouchard en 1815 operando en el Pacífico."],["Fragata Hércules","calle","Fragata Hércules: nave de la escuadra del almirante Brown adquirida en 1813; combate en el sitio de Montevideo y posteriormente en el Pacífico."],["Fragata la Argentina","calle","Fragata La Argentina: nave armada para la guerra de corso en 1817 bajo el comando de Hipólito Bouchard, que opera en el Pacífico hasta 1819 y que circunda el globo terrestre."],["Fragata Presidente Sarmiento","calle","Fragata Presidente Sarmiento: nave construida en 1897 y que suplanta al buque escuela La Argentina. Zarpa en su primer viaje de instrucción en 1899 comandada por el capitán de fragata Onofre Betbeder y cumple su último viaje en 1938. Amarrada en Dársena Norte, fue declarada monumento histórico por Decreto N° 5.589 del 18 de julio de 1962."],["Fragata Trinidad","calle","Fragata Trinidad: nave perteneciente a la escuadra del almirante Brown comprada el 15 de marzo de 1814 y abandonada en el Pacífico en 1816."],["Fragata 25 de Mayo","calle","Fragata 25 de Mayo: buque jefe de la escuadra que comandaba el almirante Brown en 1826 durante la guerra contra el Brasil."],["Fragueiro","calle","Mariano Antonio Fragueiro (1795 a 1872), político; gobernador interino de Córdoba en 1831; ministro de Hacienda de Urquiza en 1853; gobernador de Córdoba de 1858 a 1860; director del Banco y de la Casa de la Moneda de Buenos Aires en 1861."],["Francia","plaza","Francia: país europeo. Capital: París."],["Enrique Mario Francini","plazoleta","Enrique Mario Francini (1916 a 1978), violinista y director; compositor de Óyeme, Triste flor de tango, Princesa del tango, Mañana iré temprano y Camuflage."],["Franco","calle","Pedro Franco (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Franklin","calle","Benjamín Franklin (1706 a 1790), político y físico estadounidense; inventor del pararrayos; autor de El camino de la riqueza y La ciencia del tío Ricardo."],["Fraternidad","calle","Fraternidad: homenaje a la unión y buena correspondencia entre los hermanos o entre los que se tratan como tales."],["Fray Mocho","plaza","Fray Mocho: seudónimo de José Ciriaco Álvarez (1858 a 1903), periodista y escritor. Funda en 1898 el semanario Caras y Caretas, del que es su primer director; autor de Cuentos y cuadros de la ciudad, Galería de ladrones de la Capital y Memorias de un vigilante, donde relata lo que conoció durante su actuación en la Policía como comisario de pesquisas."],["Capitán General Ramón Freire","calle","Ramón Freire (1788 a 1851), militar chileno; combate en Gavilán, Talcahuano, Cancha Rayada y Maipú; gobernador intendente de Concepción en 1819; Director Supremo de 1823 a 1826."],["French","calle","Domingo María Cristóbal French (1774 a 1825), general; combate durante las Invasiones Inglesas; actúa junto con Beruti en las jornadas de mayo acaudillando a sectores populares; actúa en Córdoba para reprimir la resistencia de Liniers."],["Osvaldo Fresedo","espacio verde","Osvaldo Fresedo (1897 a 1984), músico y compositor; conocido como “el Pibe de la Paternal”, se destaca como bandoneonísta. Forma su primer conjunto en 1918 con José María Rizzuti (piano), Julio de Caro y Rafael Rinaldi (violines); participa en 1933 en los filmes Tango y Los tres berretines. Graba con el trompetista Dizzy Gillespie el Preludio Nº."],["Coronel Marcelino E. Freyre","avenida","Marcelino E. Freyre (1846 a 1879), militar; combate en la guerra contra el Paraguay y en la lucha contra el aborigen; participa en la expedición al desierto encabezada por Adolfo Alsina en 1876, en el transcurso de la cual construye un fuerte cercano a la laguna de Monte, que sirve de base para la fundación del pueblo de ese nombre."],["Teniente General Eustoquio Frías","calle","Eustoquio Frías (1801 a 1891), militar; asiste a la campaña del Perú en 1820 y a las dos campañas de la Sierra; combate en Pichincha, Junín, Ayacucho, en la guerra contra el Brasil, Caseros y Pavón."],["Federico Froebel","plazoleta","Federico Guillermo Froebel (1782 a 1852), pedagogo alemán; establece en 1840 el primer jardín de infantes en Blankenburg."],["La Fronda","calle","La Fronda: nombre de la guerra civil que de 1648 a 1653 se desarrolla en Francia durante la minoría de Luis XV y el gobierno de Mazarino, emprendida por la alta nobleza y la burguesía contra el estado absolutista; toma su nombre de la honda que, denominada fronda, se usó en la lucha."],["Arturo Frondizi","Autopista","Arturo Frondizi (1908 a 1995), político; líder de la Unión Cívica Radical Intransigente (UCRI). Asciende a la Presidencia de la Nación de 1958 a 1962, año en que es depuesto por un golpe militar y encarcelado. Liberado en 1963, prosigue su actividad política y funda con Rogelio Frigerio el Movimiento de Integración y Desarrollo (MID)."],["El Fuerte","calle","Fuerte: recinto fortificado que poseía la ciudad de Buenos Aires y que ocupaba el actual predio de la Casa de Gobierno. Comenzó a ser demolido en 1854 para construir la Aduana y, en 1882, el general Roca hizo demoler lo que aún quedaba de él para concluir las obras de la actual Casa Rosada."],["Fuerza Aérea Argentina","plaza","Fuerza Aérea Argentina: fuerza creada por ley del 4 de enero de 1945. FULGENCIO, DON véase DON FULGENCIO."],["Julio César Fumarola","plaza","Julio César Fumarola (1941 a 1974), reportero gráfico, participa como dirigente de la Asociación de Periodistas; sus imágenes ilustran el semanario de actualidad 7 días. Es una de las primeras victimas de la organización paramilitar conocida como la Triple A, ya que es secuestrado el 5 de febrero de 1974 en su estudio de fotografía. Su cadáver con signos de tortura es encontrado cerca de las piletas de Ezeiza al día siguiente."],["Deán Funes","calle","Gregorio Funes (1749 a 1829), sacerdote; diputado por Córdoba en la Junta Gubernativa de 1810 y en el Congreso de Tucumán de 1816. Notas."],["Héctor Gagliardi","plazoleta","Héctor Francisco Gagliardi (1909 a 1984), poeta popular que canta con claridad y sentimiento a la ciudad de Buenos Aires; sus versos son, aún hoy, un documento que describe una época. Debuta en 1941 en Radio Belgrano con Azucena Maizani, Tito Tori y Antonio Volpe; recita infinidades de poemas, como Barrio Sur, El Viejo Almacén, Las comadres, El triste."],["General Martín de Gainza","calle","Martín de Gainza (1814 a 1888), militar; combate en Quebracho Herrado, Famaillá, Caaguazú y Pavón; ministro de Guerra y Marina de Sarmiento, crea durante su gestión el Colegio Militar y la Escuela Naval."],["Luis Gaitán","calle","Luis Álvarez Gaitán (?-1621), acompaña a Garay en la fundación de Buenos Aires en 1580; regidor del primer Cabildo porteño."],["Constantino Gaito","calle","Constantino Gaito (1878 a 1945), músico y compositor; autor de La sangre de las guitarras (romance gauchesco), La flor del Irupé (ballet), El ombú (poema sinfónico) y Ollantay."],["Galeno","calle","Claudio Galeno (131 a 201), médico y filósofo griego; considerado el primer médico de la antigüedad después de Hipócrates; inventor de la cuarta figura del silogismo."],["La Galera","calle","Galera: diligencia o carruaje para transportar personas, correspondencia o carga liviana. Uno de los primeros empresarios de galeras en Buenos Aires fue don Timoteo Gordillo. Subsistieron en esta provincia hasta 1920 cuando fueron desplazadas por el automóvil."],["Galicia","calle","Galicia: región del noroeste de España que se divide en las provincias de la Coruña, Lugo, Orense y Pontevedra."],["Galileo","calle","Galileo Galilei (1564 a 1642), astrónomo, físico y matemático italiano; establece el concepto de gravedad en especie (peso específico); determina el período de rotación del Sol; construye el anteojo que lleva su nombre, con el cual realiza importantes observaciones astronómicas."],["Gallardo","calle","Manuel Bonifacio Gallardo (1793 a 1862), jurisconsulto; presidente de la Academia de Jurisprudencia Teórico-Práctica durante varios períodos; miembro de la Corte Suprema de Justicia de la Confederación; primer asesor jurídico de la Municipalidad de Buenos Aires en 1857."],["Ángel Gallardo","avenida","Ángel Gallardo (1867 a 1934), naturalista; presidente de la Sociedad Científica Argentina; director del Museo de Historia Natural de Buenos Aires; presidente del Consejo Nacional de Educación; profesor de Historia Natural, Zoología y Botánica."],["Gallegos","calle","Gallegos: denominación con la que se identifica a los soldados del Tercio de Voluntarios de Galicia que, comandados por Pedro Antonio Cerviño, combaten durante las Invasiones Inglesas."],["Gallo","calle","Legajo 3, 1882. Obras Públicas). Pedro León Gallo (1782 a 1852), sacerdote; diputado por Santiago del Estero en el Congreso de Tucumán; vicepresidente y presidente del mismo en 1816 y 1819, respectivamente."],["Delfín Gallo","calle","Delfín Gallo (1845 a 1889), jurisconsulto y periodista; diputado nacional por Tucumán de 1872 a 1876 y de 1884 a 1888 y por Buenos Aires de 1876 a 1884; director del Ferrocarril del Oeste y del Ferrocarril del Pacífico; propicia y defiende la Ley N° 1.420 de Educación Común."],["Galván","calle","Elías Galván (1774 a 1844), general; combate durante las Invasiones Inglesas; tesorero general del Ejército en 1815; secunda al general Martín Rodríguez en su campaña al desierto; jefe interino de Policía en 1832."],["Juan Gálvez","cantero central","Juan Gálvez (1916 a 1963), automovilista; con su hermano Oscar dominan por más de una década el automovilismo argentino; entre 1950 y 1960 obtuvo 59 triunfos y cinco grandes premios; es considerado el primer estratega “científico” del volante en la Argentina."],["Manuel Gálvez","calle","Manuel Gálvez (1882 a 1962), escritor; autor de La maestra normal, Nacha Regules, Vida de don Juan Manuel de Rosas y Vida de Hipólito Yrigoyen."],["Gamarra","calle","Agustín Gamarra (1785 a 1841), mariscal peruano; combate en Salta, Tucumán, Huaqui y Vilcapugio; jefe del Estado Mayor de la segunda campaña de la Sierra; combate en Ayacucho; presidente del Perú de 1829 a 1833 y de 1838 a 1841, año en que muere en la batalla de Ingaví."],["Marcelo Gamboa","calle","Marcelo Fulgencio de Gamboa (1793 a 1861), jurisconsulto; juez de primera instancia en lo Civil de 1828 a 1830; abogado defensor de los hermanos Reinafé, acusados del asesinato de Juan Facundo Quiroga; diputado a la Legislatura porteña en 1852 y 1853; senador en 1854, 1856 y 1859."],["Gana","calle","Juan Pío Gana (?-1807), comerciante; muere luchando contra los ingleses en la Defensa de Buenos Aires en 1807. Es éste un nombre tradicional de Buenos Aires, pues entre 1808 y 1822 se denominó así la actual Balcarce."],["Gándara","calle","Leonardo Domingo de la Gándara (1785 a 1856), hacendado que actúa durante las Invasiones Inglesas y la Revolución de Mayo; participa de la Revolución del Sur en 1839; juez de Paz de Chascomús."],["Mahatma Gandhi","calle","Mohandas Karamchad Gandhi (1869 a 1948), religioso hindú; jefe del movimiento nacionalista de la India que consigue la independencia de su país en 1947."],["Doña Petrona C. de Gandulfo","espacio verde","Petrona Carrizo de Gandulfo (1896 a 1992), ecónoma; popularmente conocida como “Doña Petrona”, es la primera maestra de la gastronomía argentina; autora de El libro de Doña Petrona, que se convierte en una especie de biblia gastronómica en los países de habla castellana y de Las recetas económicas de Doña Petrona."],["Gaona","avenida","Pablo Ruiz de Gaona (¿1713?-1813), funcionario y comerciante; alcalde de segundo voto en 1774; alférez real en 1780. Es un nombre tradicional oficializado luego por la Municipalidad, ya que deviene de la propiedad que don Pablo Ruiz de Gaona poseía en lo que hoy es el barrio de Caballito y uno de cuyos límites era la actual avenida Díaz Vélez, denominada anteriormente Gaona, nombre que aún conserva ésta en su prolongación hacia el oeste. El lugar era conocido con el nombre de “Estanco de Gaona”.3."],["De las Garantías","calle","Garantías: nombre tradicional que tuvo la actual Rodríguez Peña entre 1822 y 1883, como homenaje a “los derechos fundamentales que forman la dignidad y la felicidad del vecindario bajo los gobiernos representativos. La libertad, la seguridad, la propiedad, el compromiso y empeño en que se constituyen estos gobiernos de protegerlos y sostenerlos. He aquí lo que entendemos por garantías” (Manual de Buenos Aires, transcripción paleográfica por Jorge Ochoa de Eguileor, Buenos Aires, Municipalidad, 1981)."],["Garay","plaza","Juan de Garay (1528 a 1583), general y conquistador español; fundador de las ciudades de Santa Fe en 1573 y de Buenos Aires en 1580."],["Agente Ceferino García","calle","Ceferino García (1905 a 1931), agente policial; muere trágicamente el 29 de enero de 1931 en un atentado del anarquista Severino Di Giovanni en el interior de un hotel de la calle Cangallo 1975."],["Almirante Manuel J. García","calle","Manuel José García Mansilla (1859 a 1910), marino; jefe del Estado Mayor de Marina de 1895 a 1897; director de la Escuela Naval de 1900 a 1901 y de 1909 a 1910."],["Coronel Pedro Andrés García","calle","Pedro Andrés García (1758 a 1833), militar y geógrafo; participa en la expedición al Río de la Plata del virrey don Pedro de Cevallos, combate durante las Invasiones Inglesas; efectúa en 1810 la expedición a las Salinas Grandes; levanta en 1822 la “Carta Esférica de la Provincia de Buenos Aires y Pampas del Sud hasta el establecimiento del Río Negro en la Costa Patagónica”."],["Juan Agustín García","calle","Juan Agustín García (1862 a 1923), jurisconsulto y escritor; autor de La ciudad indiana."],["Juan Agustín García","plaza","Denominación impuesta por el Banco Hipotecario Nacional, donante de esta plaza. Juan Agustín García (1831 a 1907), jurisconsulto, padre del autor de La Ciudad Indiana; director del Banco Nacional en 1885 y poco después primer director del Banco Hipotecario Nacional."],["Manuel García","calle","Manuel José García (1784 a 1848), jurisconsulto; ministro de Hacienda de Martín Rodríguez en 1821 y de Las Heras en 1824, con quien se desempeña también como ministro de Gobierno y Relaciones Exteriores; en 1827 viaja a Brasil para tramitar la paz con el Imperio; ministro de Hacienda de Viamonte en 1833."],["Martín García","avenida","Martín García: combate librado por el almirante Guillermo Brown el 17 de marzo de 1814 contra las fuerzas realistas; el triunfo de Brown le permitió ocupar la estratégica isla que lleva el nombre del despensero de la expedición de Juan Díaz de Solís en ella sepultado."],["Teodoro García","calle","Teodoro García (1840 a 1909), general; combate en Cepeda, Pavón y en la guerra contra el Paraguay; participa en la lucha contra el aborigen y en la campaña al Río Negro en 1879."],["García de Cossio","calle","José Simón García de Cossio (1770 a 1840), jurisconsulto; diputado por la ciudad de Corrientes en el primer congreso provincial convocado por el capitán Genaro Perugorría en 1814, que proclama la reincorporación de la provincia a Buenos Aires como estado federativo; diputado por Entre Ríos al Congreso de Arroyo de la China; ministro de Hacienda de Rondeau; colaborador de Francisco Ramírez y de Pedro Ferré."],["García del Río","avenida","Juan García del Río (1794 a 1856), diplomático y periodista colombiano; San Martín lo nombra secretario de Relaciones Exteriores en la campaña al Perú; ministro en el mismo ramo de gobierno al ser designado San Martín Protector del Perú; ministro de Relaciones Exteriores de Colombia durante el gobierno del general Rafael Urdaneta; ministro de Hacienda del presidente Flores de Ecuador y del general José de Obregoso del Perú."],["García del Río","cantero central","Juan García del Río (1794 a 1856), diplomático y periodista colombiano; San Martín lo nombra secretario de Relaciones Exteriores en la campaña al Perú; ministro en el mismo ramo de gobierno al ser designado San Martín Protector del Perú; ministro de Relaciones Exteriores de Colombia durante el gobierno del general Rafael Urdaneta; ministro de Hacienda del presidente Flores de Ecuador y del general José de Obregoso del Perú."],["Severo García Grande de Zequeira","calle","Severo García Grande de Zequeira (1793 a 1820), general; combate en Chacabuco, Cancha Rayada y Maipú; destinado a la guarnición de San Juan, comanda el Regimiento 1° de Cazadores y es muerto en la sublevación del 9 de enero de 1820."],["Federico N° 20.157. García Lorca","plazoleta","Federico García Lorca (1898 a 1936), poeta español; autor de El poema del cante jondo, Romancero gitano, Llanto por la muerte de Ignacio Sánchez Mejías, Yerma, Bodas de sangre y La casa de Bernarda Alba."],["Enrique García Velloso","plazoleta","Enrique García Velloso (1880 a 1938), dramaturgo y escritor; autor de Fruta picada, Los amores de la virreina, El tango en París, Gabino el mayoral, Historia de la literatura argentina y Memorias de un hombre de teatro."],["Carlos Gardel","calle","Carlos Gardel (1890 a 1935), cantor y compositor; figura máxima del tango y de la música popular rioplatense; autor e intérprete de Mi Buenos Aires querido, Volver, Cuesta abajo y El día que me quieras."],["Carlos Gardel","espacio verde","Carlos Gardel (1890 a 1935), cantor y compositor; figura máxima del tango y de la música popular rioplatense; autor e intérprete de Mi Buenos Aires querido, Volver, Cuesta abajo y El día que me quieras."],["Dúo Gardel-Razzano","espacio público","Dúo Gardel-Razzano: dúo formado por Carlos Gardel (1890 a 1935) y José Francisco Razzano (1887 a 1960) y que se presenta en 1913 en el célebre Armenonville de la avenida Alvear (Libertador) y Tagle. La primera grabación del dúo Gardel-Razzano se efectúa el 9 de abril de 1917. El dúo perdura hasta 1925, con un amplio repertorio de canciones populares."],["Garibaldi","calle","Ignacio Garmendia, con la Nueva División de Policía, por Pedro P. Uzal de 1879. José Garibaldi (1807 a 1882), general italiano; participa en Rio Grande do Sul en la revolución encabezada por el general Bento Gonçalves da Silva; actúa en Montevideo al frente de la Legión Italiana en la defensa de la plaza contra las fuerzas de Oribe; vuelto a Italia, participa en la lucha de unificación."],["Garmendia","avenida","José Ignacio Garmendia y Alurralde (1788 a 1864), funcionario y comerciante; representante de Tucumán en el Congreso de 1826; presidente del Banco Nacional de 1831 a 1836."],["Garro","calle","José de Garro (?-1702), militar español; gobernador del Río de la Plata de 1678 a 1682."],["La Garza","calle","Garza: nombre de varias aves ciconiformes de la familia de las Ardeidas que habitan en esteros y bañados."],["General Eugenio Garzón","calle","Eugenio Garzón (1796 a 1851), militar uruguayo; combate en Chacabuco y Maipú; participa en la primera Campaña de la Sierra; combate en Pasco, Pichincha; Zepita, Junín, Ayacucho y en la guerra contra el Brasil."],["Gascón","calle","Gazcón por Disposición del presidente de la Corporación Municipal, Torcuato de Alvear, del 6-3-1882. (Archivo Histórico Municipal, Legajo 3, 1882. Obras Públicas). Por Ordenanza N° 4.062 del 30-6-1930, su nombre actual. Esteban Agustín Gascón (1764 a 1824), jurisconsulto; presidente de la Real Audiencia de Charcas en 1813; gobernador intendente de Salta en el mismo año, diputado por Buenos Aires en el Congreso de Tucumán."],["Ramona Esther Gastiazoro de Brontes","espacio verde","Ramona Esther Gastiazoro de Brontes (1927 a 1977); a raíz del secuestro de su hijo Carlos, producido el 13 de mayo de 1975, junto a otras familias de militantes desaparecidos se moviliza en la Comisión Permanente de Solidaridad con el fin de reclamar por la aparición de sus familiares. Es secuestrada en su domicilio el 9 de marzo de 1977. Permanece desaparecida."],["El Gaucho","calle","Gaucho: poblador de la campaña rioplatense. Era jinete por excelencia y diestro en los trabajos de la ganadería y en el manejo del lazo; las boleadoras y el facón constituían sus elementos esenciales de trabajo."],["Gavilán","calle","Gavilán: triunfo del entonces coronel Las Heras, quien, con la ayuda de O´Higgins, vence a los realistas comandados por Ordóñez en el cerro de Gavilán, al noroeste de Concepción, Chile, el 4 y 5 de mayo de 1817."],["Gazeta de Buenos Ayres","calle","Gazeta de Buenos Ayres: nombre del periódico fundado por la Primera Junta de Gobierno el 2 de junio de 1810 y cuyo primer número apareció el jueves 7 del mismo mes."],["Gelly","calle","Juan Andrés Gelly (1792 a 1859), jurisconsulto paraguayo; participa en la Revolución de Mayo y en la Sociedad Patriótica de 1812; secretario político y militar del ejército Republicano en la guerra contra el Brasil; actúa en el Paraguay junto a Carlos Antonio López; fundador de la primera Escuela de Derecho de ese país."],["General Gelly y Obes","avenida","Juan Andrés Gelly y Obes (1815 a 1904), militar; ministro de Guerra de Mitre; interventor nacional en Corrientes en 1862; combate en la guerra contra el Paraguay; presidente del Consejo Supremo de Guerra y Marina de 1895 a 1904."],["Gená","calle","Gená: arroyo de la provincia de Entre Ríos."],["Gendarmería Nacional","calle","Gendarmería Nacional: cuerpo policiaco militarizado creado por Ley N° 12.367 promulgada el 28 de julio de 1938, cuyas misiones fundamentales son el velar por el mantenimiento y el resguardo de las fronteras y el mantenimiento del orden y de la seguridad pública."],["Gendarmería Nacional","plazoleta","Gendarmería Nacional: cuerpo policiaco militarizado creado por Ley N° 12.367 promulgada el 28 de julio de 1938, cuyas misiones fundamentales son el velar por el mantenimiento y el resguardo de las fronteras y el mantenimiento del orden y de la seguridad pública."],["Génova","calle","Génova: ciudad capital de la provincia de su nombre y de la región de Liguria, Italia."],["Alberto Gerchunoff","calle","Alberto Gerchunoff (1883 a 1950), narrador, ensayista y periodista; redactor de los diarios El Mundo y La Nación, autor de Los gauchos judíos."],["Fernando Ghio","plazoleta","Fernando Ghio (1880 a 1938), periodista y político de origen italiano; funda el primer periódico en el barrio de Mataderos, al que denomina El Ciclón, y después Nueva Era; concejal de la ciudad de Buenos Aires de 1932 a 1935."],["Capitán de Fragata Pedro Edgardo Giachino","calle","Pedro Edgardo Giachino (1947 a 1982), militar; primer soldado muerto en acción, durante la recuperación de las Islas Malvinas el 2 de abril de 1982."],["Doctor Genaro Giacobini","plazoleta","Genaro Giacobini (1889 a 1954), médico y político; dedicado a los problemas de higiene, es el fundador del partido Salud Pública y de la revista Lux; concejal capitalino en 1932."],["Gibraltar","calle","Gibraltar: peñón de la península Ibérica que desde 1704 pertenece políticamente a Gran Bretaña."],["Gibson","calle","Roberto Gibson (¿-?), marino británico; segundo comandante de la Hércules en el bloqueo y combate de Martín García y Montevideo en mayo de 1814."],["Francisco Gil","cantero central","Francisco Gil (1915 a 1997), librero de origen español. Desarrolla una intensa actividad en la librería El Ateneo y en la Sociedad Argentina de Escritores; promueve en el barrio de Nueva Pompeya peñas culturales, muestras artísticas y encuentros de historiadores. En el año 1997 la Secretaría de la Nación lo declara Librero Mayor de Buenos Aires."],["Gilardo Gilardi","calle","Gilardo Gilardi (1889 a 1963), músico, compositor, profesor y director de la orquesta del Teatro Colón; entre sus obras se destacan Ilse, La leyenda del urutaú, Gaucho con botas nuevas y Piruca y yo."],["Ángel M. Giménez","calle","Ángel Mariano Giménez (1878 a 1941), médico higienista y político socialista; difusor de la cultura en medios obreros a través de la Biblioteca Obrera, la Biblioteca Popular del Municipio y la Sociedad Luz; diputado nacional de 1914 a 1918, en 1932 y de 1934 a 1938; concejal por la Capital de 1919 a 1920 y de 1922 a 1930."],["Ginebra","calle","Ginebra: ciudad de Suiza, capital del estado de su nombre."],["Intendente Hernán M. Giralt","avenida","Hernán M. Giralt (1910 a 1965), empresario; intendente municipal de la ciudad de Buenos Aires de 1958 a 1962."],["Girardot","calle","Atanasio Girardot (1791 a 1813), coronel colombiano; colaborador de Simón Bolívar, muere en acción en Bárbula durante el sitio de Puerto Cabello."],["Giribone","calle","José Pipo Giribone (1824 a 1868), teniente coronel de origen italiano; combate en Caseros; jefe de la banda de música en el Regimiento 2 de Infantería de Línea, compone la marcha El Tala; organizador de la Sociedad Filarmónica Italiana; director de las bandas de las Guardias Nacionales en 1860; combate en Pavón y en la guerra contra el Paraguay, donde muere en el combate de Tuyu-Cué."],["Oliverio Girondo","cantero central","Oliverio Girondo (1891 a 1967), poeta; autor de Veinte poemas para ser leídos en el tranvía, Calcomanías, Espantapájaros (al alcance de todos), Interludio y En la masmédula."],["Doctor José Modesto Giuffra","calle","José Modesto Giuffra (1875 a 1944), abogado y político radical; director general de Correos y Telégrafos de 1916 a 1922; presidente del Comité Capitalino de la Unión Cívica Radical y de la Caja Nacional de Ahorro Postal; interventor nacional en Corrientes de 1918 a 1919."],["La Gloria","calle","La Gloria: paso y cerro de la Cordillera de los Andes en el límite argentinochileno, en la provincia de Mendoza."],["Ruperto Godoy","calle","Ruperto Godoy (1799 a 1873), político; gobernador de San Juan; representante de esa provincia en el Congreso de 1853."],["Godoy Cruz","calle","Legajo 3, 1882. Obras Públicas). Tomás Godoy Cruz (1791 a 1852), político; diputado por Mendoza en el Congreso de Tucumán; gobernador de esa provincia de 1820 a 1822 y en 1830."],["José Gola","pasaje peatonal","José Gola (1905 a 1939), actor teatral y cinematográfico; actúa en Nace un amor, Mañana es domingo, Fuera de la Ley y Hermanos."],["Goleta Fortuna","calle","Goleta Fortuna: nave comprada en 1814 para la escuadra argentina. Entra en servicio el 15 de enero de ese año y combate en Arroyo de la China y Martín García."],["Goleta Invencible","calle","Goleta Invencible: goleta comprada en 1811; combate en San Nicolás, donde es tomada por el enemigo; es recuperada en 1814 cuando cae Montevideo."],["Goleta Julia","calle","Goleta Julia: nave de propiedad del comandante Piedra Buena, bautizada con este nombre en homenaje a su esposa, doña Julia Dufour de Piedra Buena."],["Goleta Juliet","calle","Goleta Juliet: nave norteamericana comprada en 1814 para formar parte de la escuadra argentina que bloquea Montevideo."],["Goleta Maldonado","calle","Goleta Maldonado: nave comprada al comandante Fournier que la había capturado a la escuadra brasileña donde servía con el nombre de Leal Paulistana. Se incorpora a la escuadra nacional el 26 de septiembre de 1826."],["Goleta Manuelita","calle","Goleta Manuelita: nave con la que el comandante Luis Piedra Buena recorre las costas de la Patagonia, Tierra del Fuego e Islas Malvinas en 1858."],["Goleta Santa Cruz","calle","Goleta Santa Cruz: nave perteneciente al comandante Luis Piedra Buena."],["Goleta Sarandí","calle","Goleta Sarandí: nave estadounidense comprada en 1826 y que participa en la guerra contra el Brasil."],["Doctor Juan Ángel Golfarini","calle","Juan Ángel Golfarini (1838 a 1925), médico uruguayo; actúa durante la guerra contra el Paraguay; combate la epidemia de cólera de 1868 y la de fiebre amarilla de 1871; presidente del Concejo Deliberante de Buenos Aires en 1866; candidato a presidente del Uruguay en 1919."],["Indalecio Gómez","calle","Indalecio Gómez (1850 a 1920), jurisconsulto; cónsul argentino en Iquique, Chile, de 1879 a 1884; director del Banco de la Nación de 1890 a 1892; ministro del Interior de Roque Sáenz Peña, sostiene en el parlamento la implantación de la ley electoral de 1912."],["Juan Carlos Gómez","calle","Juan Carlos Gómez (1820 a 1884), jurisconsulto y periodista uruguayo; redactor de El Mercurio (Chile); ministro de Gobierno y Relaciones Exteriores del Uruguay en 1853; redactor de La Tribuna (Buenos Aires) y El Nacional (Montevideo); presidente de la Comisión Popular de Lucha contra la Fiebre Amarilla en 1871; presidente del Club del Progreso de 1872 a 1875 y de 1881 a 1884."],["Valentín Gómez","calle","José Valentín Gómez (1774 a 1839), sacerdote y político; diputado y presidente de la Asamblea de 1813; rector de la Universidad de Buenos Aires de 1826 a 1830; diputado por Buenos Aires en el Congreso Constituyente de 1824 a 1827."],["Manuel Gómez Carrillo","plazoleta","Manuel Gómez Carrillo (1883 a 1968), musicólogo; compositor y folclorista autor de Rapsodia santiagueña, La telesita y Fiesta criolla."],["Gómez de Fonseca","calle","José María Gómez de Fonseca (1799 a 1843), médico; vocal del Tribunal de Medicina en 1834; médico del Hospital General de Hombres y catedrático de Nosografía y Clínica Quirúrgica en 1836."],["Joaquín Gómez Somavilla","calle","Joaquín Gómez Somavilla (?-1807), teniente del Tercio de Montañeses que muere durante la Defensa de la ciudad ante la Segunda Invasión Inglesa. Es éste un nombre tradicional de Buenos Aires, ya que entre 1808 y 1822 se llamó “Somavilla” a las actuales Solís y Rodríguez Peña. GONÇALVES DÍAS (calle). Ordenanza del 25-10-1921 . Antonio Gonçalves Días (1823 a 1864), poeta brasileño; autor de Os Timbiras, Sextilhas de Frei Antão y Leonor de Mendoça."],["Adolfo Gonzáles Chaves","calle","Adolfo Gonzáles Chaves (1828 a 1887), hacendado; director del Ferrocarril del Oeste; vicegobernador de Buenos Aires en el gobierno de Dardo Rocha, de 1881 a 1884."],["Elpidio González","calle","Elpidio González (1875 a 1951), político; ministro de Guerra de Hipólito Yrigoyen en 1916; vicepresidente de la República de 1922 a 1928; ministro del Interior de Yrigoyen en su segunda presidencia."],["Gumersindo González","espacio verde","Gumersindo González (1914 a 1959), deportista y entrenador de atletismo; entre las décadas de 1930 y 1950 prepara a grandes deportistas en esa especialidad, entre ellos a Osvaldo Suárez y Noemí Simonetto."],["Ingeniero Agustín González","calle","Agustín González (1854 a 1917), ingeniero; secretario de Obras Públicas del intendente Torcuato de Alvear; subsecretario del Ministerio de Obras Públicas con los ministros Civit y Orma."],["Joaquín V. González","calle","Joaquín Víctor González (1863 a 1923), jurisconsulto y escritor; ministro de Interior, de Justicia e Instrucción Pública e interino de Relaciones Exteriores de Roca; ministro de Justicia e Instrucción Pública de Quintana, funda en 1905 la Universidad Nacional de La Plata; autor de Mis montañas y La tradición nacional."],["Julio Víctor González","calle","Julio Víctor González (1899 a 1955), jurisconsulto y escritor; profesor de Historia de las Instituciones Políticas Argentinas en la Facultad de Ciencias Jurídicas y Sociales de La Plata; autor de La Revolución Universitaria, Nacionalización del petróleo y Filiación histórica de la Revolución de Mayo."],["Roque González","calle","Roque González de Santa Cruz (1576 a 1628), sacerdote y beato; actúa en las misiones jesuíticas; fundador, junto con el padre Diego de Beroa, de las reducciones de Villa Encarnación, Concepción, San Javier, Yapeyú y otras; es muerto por los guaycurúes en 1628 junto con los padres Juan del Castillo y Alonso Rodríguez."],["González Catán","calle","Mauricio González Catán (1823 a 1895), médico; profesor suplente de Obstetricia de la Facultad de Medicina en 1859; profesor de Anatomía Topográfica; miembro de la Municipalidad de Buenos Aires; decano de la Facultad de Medicina en 1889."],["Almirante Ramón González Fernández","plaza","Ramón González Fernández (1867 a 1933), marino; comandante del acorazado General San Martín; jefe naval del Río de la Plata; autor de Cálculo de una tabla de tiro."],["Carlos Bernardo González Pecotche","plazoleta","Carlos Bernardo González Pecotche (1901 a 1963), filósofo y escritor; fundador de la logosofía; autor de Diálogo, Introducción al conocimiento logosófico, El mecanismo de la vida conciente y Logosofía ciencia y método."],["Raúl González Tuñón","plaza","Raúl González Tuñón (1905 a 1974), poeta; autor de El violín del diablo, La rosa blindada, La muerte derramada, El pequeño cementerio fusilado y La muerte en Madrid."],["Coronel José Olegario Gordillo","calle","José Olegario Gordillo (1811 a 1874), militar; combate durante la guerra contra el Brasil y en Navarro; gobernador delegado de La Rioja en 1857; combate en la guerra contra el Paraguay, donde es nombrado, en 1869, auditor del Ejército Argentino en Operaciones."],["Timoteo Gordillo","calle","Timoteo Cristóbal Gordillo (1814 a 1894), empresario; en 1857 trae de los Estados Unidos ciento cincuenta carros, cien coches de tiro y diversas máquinas con las que inicia una empresa de transporte entre Santa Fe y Córdoba; para ello traza caminos e instala postas que con el tiempo se convertirán en importantes poblaciones."],["Gorostiaga","calle","José Benjamín Gorostiaga (1823 a 1891), jurisconsulto; ministro de Hacienda de Buenos Aires en 1852; diputado por Santiago del Estero en el Congreso de 1853; ministro del Interior de Urquiza en 1854; presidente del Banco de la Provincia de Buenos Aires en 1869."],["Gorriti","calle","Obras Públicas). José Ignacio Gorriti (1770 a 1835), general; llamado “numen de la Revolución en el Norte” fue uno de los principales dirigentes de Salta en 1810; combate en Suipacha, Las Piedras, Tucumán y Salta; diputado por Salta al Congreso de Tucumán, gobernador interino de esa provincia en 1819 y 1821; gobernador propietario de 1821 a 1823 y de 1827 a 1829; gobernador delegado de 1825 a 1826 y en 1831."],["Juana Manuela Gorriti","calle-paseo","Juana Manuela Gorriti (1818 a 1892), escritora; funda la revista internacional La Alborada Argentina; autora de Sueños y realidades, Panoramas de la vida, El mundo de los recuerdos y El pozo de Yocci, obra por la cual se la considera como una de las precursoras de la novelística argentina."],["Doctor Benjamín A. Gould","plaza","Benjamín Apthorp Gould (1824 a 1896), astrónomo norteamericano; fundador del Astronomical Journal de Cambridge; dirige la construcción e instalación del Observatorio Nacional de Córdoba en 1871 y es su primer director hasta 1884; autor de Uranometría argentina, Catálogo general argentino y Fotografías cordobesas."],["Goya","calle","Goya: ciudad y departamento de la provincia de Corrientes."],["Pedro Goyena","avenida","Pedro Goyena (1843 a 1892), jurisconsulto y periodista; diputado nacional de 1873 a 1874, de 1880 a 1884 y de 1886 a 1890; redactor de La Nación Argentina, El Nacional y La Prensa; fundador y redactor del diario La Unión; escritor y ensayista, es autor de La Revolución de Mayo y La cuestión electoral."],["Roberto Goyeneche","avenida","Roberto Goyeneche (1926 a 1994), cantante; apodado “El Polaco”, debuta como vocalista en la orquesta de Raúl Kaplún; luego canta en las orquestas de Horacio Salgán y de Aníbal Troilo, para hacerlo luego como solista. En su vasto repertorio ha realizado interpretaciones antológicas de numerosos tangos, entre los que cabe mencionar, entre tantos, Naranjo en flor, Afiches, Garúa, Mi tango triste, Viejo ciego y Balada para un loco."],["Alfredo Gramajo Gutiérrez","calle","Alfredo Gramajo Gutiérrez (1893 a 1961), pintor; autor de La promesa, Un velorio de angelitos, Carnaval porteño y Día de elecciones en el Norte."],["Coronel Nicolás Granada","calle","Nicolás Eusebio Granada (1795 a 1871), militar; combate en Cepeda y Cañada de la Cruz; funda las colonias agrícolas que impulsan a los pueblos de Tapalqué, 25 de Mayo y 9 de Julio."],["Nicolás Granada","plaza","Nicolás Granada (1840 a 1915), escritor y periodista; fundador de la revista literario-musical La Lira en 1860; escribe en diarios de nuestro país y del Uruguay; autor de Atahualpa y ¡Al campo!"],["Nicolás Granada","calle","Nicolás Granada (1840 a 1915), escritor y periodista; fundador de la revista literario-musical La Lira en 1860; escribe en diarios de nuestro país y del Uruguay; autor de Atahualpa y ¡Al campo!"],["Paseo de los Granaderos","paseo","Granaderos: escuadrón de Granaderos a Caballo creado por el Triunvirato por despacho del 16 de marzo de 1812 y destinado al mando del entonces teniente coronel don José de San Martín. En lo que respecta a la calle, cabe señalar que si bien con el nombre de Granaderos de Fernando VII existió una fuerza militar que se creó durante la Segunda Invasión Inglesa, la nomenclatura de esta arteria recuerda al regimiento sanmartiniano, ya que así lo establece el informe de la Comisión Especial que redacta la Ordenanza del 27-11-1893, cuando dice: “al proyectar los nombres hemos tenido en vista armonizarlos en lo posible, entre sí y con los nombres antiguos”. Es necesario aclarar por ello, que el nombre anterior de esta calle era “San Martín”, lo que aclara el sentido de la actual denominación."],["Chabuca Granda","paseo","Isabel Granda y Larco (1920 a 1983), poetisa y cantante peruana; autora de La flor de canela y Misa criolla."],["Grand Bourg","plaza","Casa de Grand Bourg: casa que el general José de San Martín adquiere el 25 de abril de 1834 en la comuna de Evry, sobre el río Sena, a 25 kilómetros de París, y donde vivió hasta el 16 de marzo de 1848, cuando se traslada a Boulogne-Sur-Mer. La casa, que aún existe, fue vendida por el Libertador el 14 de agosto de 1849."],["Dora del Grande","cantero central","Agustina Dora del Grande (1909 a 1966), primera bailarina del Teatro Colón; docente y coreógrafa."],["Martín Grandoli","calle","Martín Grandoli (¿-?), funcionario; adhiere a la causa revolucionaria en mayo de 1810 y es elegido alcalde de barrio; síndico procurador en 1811, alcalde y regidor del Cabildo en 1815 y 1816."],["Guillermo Enrique Granville","calle","Guillermo Enrique Granville (1793 a 1836), marino de origen inglés; combate durante la guerra contra el Brasil, donde comanda la goleta Guanaco, el bergantín República y la goleta La Argentina."],["Grecia","calle","Grecia: país europeo. Capital: Atenas."],["Grecia","plaza","Grecia: país europeo. Capital: Atenas."],["Arquitecto Héctor Greslebin","plazoleta","Héctor Greslebin (1893 a 1971), arquitecto y arqueólogo; profesor de Historia de la Arquitectura de la Facultad de Arquitectura de Buenos Aires; profesor de Prehistoria y Arqueología y Protohistoria Americana en el Instituto Nacional del Profesorado Secundario; se desempeña honorariamente en el Museo Etnográfico de la Facultad de Filosofía y Letras y en el Bernardino Rivadavia; coautor del proyecto del Hospital Ramos Mejía; autor de Fisiografía y noticias preliminares sobre arqueología de la región de Sayane."],["Doctora Cecilia Grierson","plaza","Cecilia Grierson (1859 a 1934), médica; doctorada en 1889, es la primera mujer que recibe ese diploma en el país; fundadora y directora de la Escuela de Enfermeras y Masajistas; por su iniciativa se crean los servicios de primeros auxilios de la Asistencia Pública y del Consejo Nacional de Mujeres."],["Grito de Asencio","calle","Grito de Asencio: el 28 de febrero de 1811, los uruguayos Pedro José Viera y Venancio Benavídez pronunciaron a orillas del arroyo Asencio el grito de libertad y se levantaron en armas proclamando la caída del gobierno español. Este es el punto de partida de una serie de levantamientos patriotas que culminan en el combate de Las Piedras."],["Griveo","calle","Lázaro Griveo (¿-?), acompaña a Juan de Garay en la fundación de Buenos Aires en 1580."],["Padre Federico Grote","calle","Federico Grote (1853 a 1940), sacerdote de origen alemán; llega a Buenos Aires en 1884; fundador de los Círculos Católicos de Obreros y del diario El Pueblo; organiza gremialmente a los vendedores y repartidores de diarios."],["Paul Groussac","calle","Francisco Paul Groussac (1848 a 1929), historiador y crítico literario de origen francés; director de la Escuela Normal de Tucumán en 1878; director de la Biblioteca Nacional desde 1885; autor de Santiago de Liniers, conde de Buenos Aires y Mendoza y Garay."],["Comandante Andrés Guacurari Artigas","plazoleta","Andrés Guacurari Artigas (¿-?), militar, aborigen guaraní; adoptado por José Gervasio Artigas por lo que se lo conoce como Andresito Artigas; acompaña a Artigas en su campaña y defiende ante los portugueses la región de las Misiones, siendo tomado prisionero en 1819."],["Ciudad de Guadix","plazoleta","Guadix: ciudad de la provincia de Granada, España. Lugar donde nació Don Pedro de Mendoza, fundador de la Ciudad de Buenos Aires."],["Gual","calle","Manuel Gual (1749 a 1800), capitán venezolano; conspira a favor de la independencia en 1797 junto con José María España; descubierta la conspiración, España es ajusticiado en 1799 y poco después un asesino envenena a Gual en su casa de Trinidad."],["Gualeguay","calle","Gualeguay: río que nace en el departamento Federación al noroeste de la provincia de Entre Ríos y desemboca en el canal Ibicuy."],["Gualeguaychú","calle","Gualeguaychú: ciudad y departamento de la provincia de Entre Ríos."],["Guaminí","calle","Guaminí: ciudad y partido de la provincia de Buenos Aires."],["Guanahaní","calle","Guanahaní: nombre indígena de la primera isla americana en la que desembarcó Colón y a la que denominó San Salvador."],["Beato Luis Guanella","plazoleta","Luis Guanella (1842 a 1915), sacerdote italiano; fundador de la Congregación de las Siervas de la Caridad y de las Hijas de Santa María de la Providencia."],["Guaraní","calle","Guaraní: pueblo aborigen que en la época de la conquista habitaba la ribera de los ríos Paraná, Paraguay, Uruguay y el Río de la Plata en nuestro territorio, y que, dividido en muchas parcialidades, ocupa la costa atlántica sudamericana desde el norte de Brasil."],["Guardavidas Argentinos","paseo","Guardavidas Argentinos: homenaje a quienes ejercen esta profesión de rescate y primeros auxilios. Este paseo se encuentra en el mismo lugar donde funcionaban las dependencias de los guardavidas del Balneario Municipal de la Costanera."],["Guardia Nacional","calle","Guardia Nacional: institución militar creada por decreto del 8 de marzo de 1852; por ley del 22 de junio de 1857 se constituye en antecedente del servicio militar obligatorio al sancionarse que todos los argentinos debían enrolarse en ella y realizar ejercicios militares."],["Guardia Vieja","calle","Guardia Vieja: combate librado el 4 de febrero de 1817 en el que la columna del Ejército de los Andes al mando del general Las Heras toma el puesto realista de Guardia Vieja, situado en el fondo del valle del río Juncal, Chile."],["Guatemala","calle","Guatemala: república de América Central. Capital: Guatemala."],["Guatemala","plaza","Guatemala: república de América Central. Capital: Guatemala."],["Guayaquil","calle","Guayaquil: ciudad y provincia de la República de Ecuador."],["Guaymallén","calle","Guaymallén: localidad y departamento de la provincia de Mendoza."],["Guayquiraró","calle","Guayquiraró: río que sirve de límite entre las provincias de Corrientes y Entre Ríos."],["Guayrá","calle","Gobernación del Guayrá: nombre con que es fundada, en 1617, la gobernación del Paraguay. Dividida entonces del Río de la Plata, quedan trazados en líneas generales los límites de las actuales repúblicas del Paraguay y Argentina."],["Güemes","calle","Martín Miguel Juan de la Mata Güemes (1785 a 1821), general; combate durante las Invasiones Inglesas; producida la Revolución de Mayo, organiza en el norte la defensa contra los realistas; combate en Cotagaita, Suipacha y Puesto del Marqués; gobernador de Salta desde 1815; general en jefe del Ejército de Observaciones sobre el Perú en 1820."],["Güemes","plaza","Martín Miguel Juan de la Mata Güemes (1785 a 1821), general; combate durante las Invasiones Inglesas; producida la Revolución de Mayo, organiza en el norte la defensa contra los realistas; combate en Cotagaita, Suipacha y Puesto del Marqués; gobernador de Salta desde 1815; general en jefe del Ejército de Observaciones sobre el Perú en 1820."],["Macacha Güemes","calle","Magdalena Güemes de Tejada (1787 a 1866), patriota; conocida como La Macacha; era hermana del general Martín Miguel de Güemes. Luego de la Revolución de Mayo organiza las tareas de infraestructura del ejército patrio y desarrolla tareas de inteligencia."],["Cadete Jorge Güemes Torino","calle","Jorge Güemes Torino (?-1930), militar; cursa el tercer año en el Colegio Militar y participa en la revolución del 6 de septiembre de 1930, donde muere en un enfrentamiento en la zona de Congreso."],["La Guerra Gaucha","cantero central","La Guerra Gaucha: película dirigida por Lucas Demare en 1942, protagonizada por Enrique Muiño y Francisco Petrone."],["María Guerrero","calle-paseo","María Guerrero (1867 a 1928), actriz española; actúa por primera vez en Buenos Aires en el teatro Odeón en 1897 interpretando La niña boba, de Lope de Vega; visita posteriormente nuestro país en varias oportunidades destacándose en sus actuaciones en Doña María la brava, Malvaloca y La malquerida."],["Contraalmirante Martín Guerrico","calle","Martín Guerrico (1838 a 1929), marino; combate en la guerra contra el Paraguay; director de la Escuela Naval Teórico-Práctica en 1877; explora los ríos Negro y Neuquén."],["Intendente Guerrico","calle","José Guerrico (1863 a 1933), comerciante y funcionario; intendente municipal de Buenos Aires del 8 de septiembre de 1930 al 20 de febrero de 1932."],["Guevara","calle","José Guevara (1719 a 1806), sacerdote e historiador; sucede en 1751 al padre Pedro Lozano como historiador de la provincia jesuítica; autor de Historia del Paraguay. GUEVARA, ERNESTO “CHE” (cantero central). Ley Nº 1.427-2004, BO Nº 2.037. Ernesto Guevara de la Serna (1928 a 1967), médico y político; apodado “Che” por el modismo coloquial argentino; en 1955, conoce en México a Fidel Castro y a su hermano Raúl, quienes preparaban la expedición revolucionaria a Cuba. Se une al grupo como médico y desembarca en la isla en 1956 donde instalan la guerrilla en Sierra Maestra. Manda una de las dos columnas que salen de las montañas orientales hacia el Oeste y participa en la decisiva batalla por la toma de Santa Clara (1958). Ingresa en La Habana en 1959, cuando se pone fin a la dictadura de Batista. El nuevo régimen revolucionario le concede la nacionalidad cubana y es nombrado jefe de la Milicia y director del Instituto de Reforma Agraria (1959), luego presidente del Banco Nacional y ministro de Economía (1960) y, finalmente, ministro de Industria (1961). Representa a Cuba en varios foros internacionales. En 1965 renuncia a sus cargos y vuelve a tomar las armas para pelear en el Congo, África, y más tarde en Bolivia, donde es ejecutado el 9 de octubre de 1967, en la región de Valle Grande."],["Trinidad Guevara","avenida","Trinidad Guevara (1798 a 1873), actriz uruguaya; tuvo destacada actuación en el teatro argentino, siendo principal figura del Coliseo; actúa junto a otro gran actor de la época, Juan Aurelio Casacuberta."],["Guido","calle","Tomás Guido (1788 a 1866), brigadier general; participa en los primeros cónclaves revolucionarios en mayo de 1810; en 1811 viaja a Europa como secretario de Mariano Moreno; acompaña a San Martín en sus campañas de Chile y del Perú como secretario de Guerra y Marina y primer edecán; ministro plenipotenciario en el Brasil, suscribe con Balcarce el tratado de paz con el Imperio en 1828; ministro de Gobierno y Relaciones Exteriores en 1828, de Guerra y Relaciones Exteriores de 1829 a 1830 y en 1833; representante argentino en el Brasil de 1840 a 1851."],["Guido Spano","calle","Carlos Guido y Spano (1827 a 1918), poeta; autor de Hojas al viento, Ráfagas y Ecos lejanos."],["Nicolás Guillén","cantero central","Nicolás Guillén (1902 a 1989), poeta y periodista cubano; uno de los más importantes representantes de la literatura afrocubana; su obra se destaca por el contenido político y social; autor de Motivos del son, Songoro Cosongo y La paloma de vuelo popular."],["Guipúzcoa","calle","Guipúzcoa: provincia del norte de España. Capital: San Sebastián."],["Intendente Güiraldes","calle","Manuel J. Güiraldes (1857 a 1941), hacendado y funcionario; intendente municipal de Buenos Aires desde el 25 de enero de 1908 hasta el 12 de octubre de 1910."],["Ricardo Güiraldes","calle","Ricardo Güiraldes (1886 a 1927), escritor; autor de El cencerro de cristal, Cuentos de muerte y de sangre y Don Segundo Sombra."],["Guise","calle","Martín Jorge Guise (1780 a 1828), almirante de origen inglés; se incorpora en 1818 a la escuadra comandada por Cochrane; comandante de la Lautaro en 1819; actúa en la captura de la fragata Esmeralda y en las campañas de Puertos Intermedios; comandante de la goleta Pichincha, del bergantín Chimborazo y de la goleta Guayaquileña; muere heroicamente frente a Guayaquil en el buque insignia Presidente."],["Gurruchaga","calle","Francisco de Gurruchaga (1766 a 1846), jurisconsulto; diputado por Salta en la Junta Grande; organizador en 1811 de la primera escuadra de la Revolución; diputado en la Asamblea de 1813."],["Enrique Gustavino","calle","Enrique Gustavino (1895 a 1954), periodista y comediógrafo; autor de La mujer más honesta del mundo, La importancia de ser ladrón y Adriana y las cuatro."],["Gutenberg","calle","Juan Gensfleisch de Sulgeloch (1397 a 1468), impresor alemán conocido como Juan Gutenberg, ya que debe cambiar su apellido por problemas políticos; es el inventor de la imprenta."],["Doctor Avelino Gutiérrez","plazoleta","Avelino Gutiérrez (1864 a 1946), cirujano de origen español; director y jefe de la sala de Cirugía de Mujeres del Hospital Español; miembro de la Academia Nacional de Medicina; fundador de la Asociación de Cultura y Protección del Inmigrante Español."],["Eduardo Gutiérrez","calle","Eduardo Gutiérrez (1851 a 1889), escritor; autor de Juan Moreira, Hormiga Negra y Croquis y siluetas militares."],["Juan María Gutiérrez","calle","Juan María Gutiérrez (1809 a 1878), jurisconsulto; miembro fundador del Salón Literario en 1837; colabora en La Moda; fundador con Echeverría de la Asociación de Mayo; ministro de Gobierno de Vicente López en 1852; diputado por Entre Ríos en el Congreso de 1853; ministro de Relaciones Exteriores de la Confederación de 1854 a 1856; rector de la Universidad de Buenos Aires de 1861 a 1873."],["Ricardo Gutiérrez","calle","Ricardo Gutiérrez (1836 a 1896), médico y poeta; creador del Hospital de Niños y su director desde 1875 hasta el día de su muerte; precursor de la medicina psicosomática; autor de La fiebre salvaje, Lázaro, La victoria y El misionero."],["Ricardo Gutiérrez","plazoleta","Ricardo Gutiérrez (1836 a 1896), médico y poeta; creador del Hospital de Niños y su director desde 1875 hasta el día de su muerte; precursor de la medicina psicosomática; autor de La fiebre salvaje, Lázaro, La victoria y El misionero."],["Alfredo Guttero","calle","Alfredo Guttero (1882 a 1932), pintor; autor de La feria, Anunciación, Descendimiento y Verónica."],["Guzmán","calle","Gonzalo Martel de Guzmán (¿1554?-?), acompaña a Juan de Garay en la fundación de Buenos Aires en 1580, siendo el único hidalgo y noble de los pobladores; alcalde y alférez real de la flamante ciudad. Notas."],["Habana","calle","La Habana: ciudad capital de Cuba y de la provincia de su nombre."],["Presidente Eduardo Víctor Haedo","calle","Eduardo Víctor Haedo (1901 a 1970), profesor, escritor y político uruguayo; presidente de la República Oriental del Uruguay en 1961 y 1962."],["República de Haití","plaza","Haití: país americano. Capital: Puerto Príncipe."],["Basilio Hall","calle","Basilio Hall (1788 a 1844), viajero, marino y escritor inglés; autor de Extractos del diario escritos en las costas de Chile, Perú y México en los años 1820, 1821 y 1822, en el que dedica un importante capítulo al general José de San Martín y a su acción en la lucha por la Independencia."],["Hamburgo","calle","Hamburgo: ciudad capital del estado de su nombre en la República Federal Alemana."],["Doctor Gerardo Armauer Hansen","calle","Gerardo Armauer Hansen (1841 a 1912), científico noruego; descubre y aísla el basilo de la lepra, enfermedad que recibe por ello el nombre de Mal de Hansen."],["Paul Percy Harris","plazoleta","Paul Percy Harris (1868 a 1947), filántropo; fundador del Rotary Club Internacional."],["Hawai","calle","Hawai: archipiélago situado en el océano Pacífico; forma parte de la Polinesia y se convierte en el quincuagésimo estado de los Estados Unidos, el 12 de marzo de 1959. Su nombre se encuentra en la nomenclatura por cuanto estos dominios habrían sido los primeros que reconocieron la independencia argentina. Dicho episodio habría tenido lugar en 1818, mediante el tratado de paz y amistad allí celebrado entre Hipólito Bouchard y el rey Kamehameha 1°. Dicha versión figura en la Memoria del capitán José María Piris, y si bien fue aceptada por Mitre, su veracidad está en duda. (Véase Ángel Justiniano Carranza, Campañas Navales de la República Argentina, Buenos Aires, Secretaría de Estado de Marina, 1962)."],["Helguera","calle","Gerónimo de Helguera (1794 a 1838), teniente coronel; combate durante las invasiones inglesas, en Campichuelo, Tucumán, Salta, Vilcapugio y Ayohuma, edecán de Manuel Belgrano en 1819 y 1820, mantuvo con él una estrecha amistad. Diputado por Tucumán en el Congreso Constituyente de 1826. Federico Helguera (1824 a 1892), político; gobernador de Tucumán de 1871 a 1873 y de 1877 a 1878."],["Heredia","calle","Alejandro Heredia (¿1783?-1838), militar; combate en Las Piedras, Tucumán y Salta; diputado en el Congreso Constituyente de 1824 a 1826; gobernador de Tucumán de 1832 a 1838, realiza una importante obra en materia educativa, judicial y adminsitrativa. En 1837 es nombrado por Rosas en el comando en jefe del ejército en operaciones en la guerra contra la Confederación Peruano Boliviana. Felipe Heredia (1797 a 1852), militar; combate en Las Piedras, Tucumán y Salta; gobernador de Salta de 1836 a 1838; con motivo de la guerra contra la Confederación Peruano Boliviana, debe delegar el mando de su provincia ya que acompaña a su hermano Alejandro como segundo jefe del ejército de la Confederación; luego del asesinato de su hermano, deja el gobierno y emigra a Chile. Regresa a Buenos Aires en 1839 y Juan Manuel de Rosas lo nombra su edecán. Después de Caseros, Urquiza lo designa inspector del Resguardo en el puerto de Buenos Aires. Homenaje conjunto a los hermanos Heredia. HERMANA ALICE DOMON Y HERMANA LÉONIE DUQUET véase DOMON."],["Hermana Alice. Hermitte, Ingeniero Enrique M. y Hermana Léonie Duquet","calle","Enrique M. Hermitte (1871 a 1955), ingeniero civil y geólogo; director general de Minas, Geología e Hidrología de la Nación, interviene en el desarrollo inicial de la exploración y organización de la producción petrolera entre 1907 y 1911."],["Hernandarias","calle","Hernandarias de Saavedra y Sanabria (1560 a 1631), conquistador y funcio- nario; gobernador del Río de la Plata y Paraguay de 1592 a 1594, en 1595 y 1596, de 1598 a 1602, de 1602 a 1609 y de 1615 a 1617."],["José Hernández","calle","José Hernández (1834 a 1886), poeta; autor de El gaucho Martín Fierro."],["José Hernández","plazoleta","José Hernández (1834 a 1886), poeta; autor de El gaucho Martín Fierro."],["Rafael Hernández","calle","Rafael Hernández (1840 a 1903), ingeniero, político y escritor; hermano menor de José Hernández; funda y realiza el trazado de los pueblos de Tres Arroyos, Pringles, Pehuajó, Coronel Suárez y San Carlos de Bolívar; presidente de la Comisión Municipal de Belgrano, de 1880 a 1883; funda en Misiones, en 1883, las colonias Candelaria y Santa Ana; fundador del periódico El Progreso, de Belgrano; colabora en La Nación y La Tribuna."],["Rafael Hernández","plaza","Rafael Hernández (1840 a 1903), ingeniero, político y escritor; hermano menor de José Hernández; funda y realiza el trazado de los pueblos de Tres Arroyos, Pringles, Pehuajó, Coronel Suárez y San Carlos de Bolívar; presidente de la Comisión Municipal de Belgrano, de 1880 a 1883; funda en Misiones, en 1883, las colonias Candelaria y Santa Ana; fundador del periódico El Progreso, de Belgrano; colabora en La Nación y La Tribuna."],["Herrera","calle","Nicolás Herrera (1773 a 1835), sacerdote; participa en el Cabildo Abierto del 22 de mayo de 1810; redacta la Petición del Pueblo que en la mañana del 25 de Mayo es entregada al Cabildo y en la que se exige la disolución de la Junta Provisional presidida por Cisneros; provincial de la Orden Mercedaria en 1814; párroco de San José de Flores de 1824 a 1830."],["Herrera","plaza","José Cruz Herrera (?-1867), por Disposición del 12-9-1872 la Municipalidad acepta de sus herederos la donación de estos terrenos, que fueron de su propiedad."],["Luis Alberto Herrera","calle","Luis Alberto Herrera (1873 a 1959), político y escritor uruguayo; autor de numerosos trabajos de historia y política, entre ellos: La diplomacia oriental en el Paraguay y Antes y después de la Triple Alianza."],["Cristóbal M. Hicken","calle","Cristóbal María Hicken (1873 a 1933), naturalista; profesor de Física, Ciencias Naturales, Botánica, Mineralogía y Geología en varios colegios y facultades del país; estudioso de nuestras especies botánicas."],["Hidalgo","calle","Miguel Hidalgo y Castilla (1753 a 1811), sacerdote y poeta mexicano; se pronuncia en 1810 por la rebelión contra España y proclama la independencia de Nueva España; es vencido en la batalla del puente de Calderón y posteriormente fusilado."],["Bartolomé Hidalgo","calle","Bartolomé Hidalgo (1788 a 1822), poeta nacido en Montevideo; autor de Marcha Nacional Oriental, Diálogo entre Jacinto Chano, capataz de una estancia en las islas del Tordillo, y el gaucho Ramón Contreras de la Guardia del Monte y Relación que hace el gaucho Ramón Contreras a Jacinto Chano de todo lo que vio en las Fiestas Mayas de Buenos Aires, en el año 1822."],["Hidroavión Buenos Aires","cantero central","Hidroavión Buenos Aires: hidroavión tripulado por Bernardo Duggan, Eduardo Olivero y Ernesto Campanelli, que une por primera vez Nueva York con Buenos Aires el 13 de agosto de 1926."],["Hinojo","calle","Hinojo: localidad del partido de Olavarría, provincia de Buenos Aires."],["Hiroshima","calle","Hiroshima: Prefectura de Japón en la isla de Honshu. Sobre esta ciudad fue lanzada la primera bomba atómica el 6-8-1945, produciendo el mayor holocausto sobre la Tierra."],["Barón Mauricio de Hirsch","plazoleta","Mauricio de Hirsch (1831 a 1896), filántropo alemán; fundador de diversas instituciones de beneficencia; contribuye en 1891 a la fundación de la Jowish Colonization Association, la que fomenta el establecimiento de colonias judías en la Argentina."],["La Historia Oficial","cantero central","La historia oficial: película dirigida por Luis Puenzo y protagonizada por Héctor Alterio y Norma Aleandro; obtiene en 1985 el Premio Oscar a la mejor película extranjera."],["Paseo de la Historieta","canteros centrales","Historieta: homenaje a los creadores y dibujantes del humor gráfico argentino."],["Holanda","plaza","Holanda: denominación con la que se conoce a los Países Bajos. Capital: Amsterdam; la corte y el gobierno residen en La Haya."],["Holmberg","calle","Eduardo Kainnitz, Barón de Holmberg (1778 a 1853), coronel nacido en Tirol de antigua familia de Moravia; jefe del Estado Mayor del Ejército del Norte en lo concerniente a Artillería e Ingenieros; combate en Las Piedras y Tucumán; comandante de las baterías durante el sitio de Montevideo en 1813 y del Parque de Artillería durante la guerra contra el Brasil; funda un importante establecimiento forestal en su quinta ubicada en la intersección de las actuales Santa Fe y Scalabrini Ortiz."],["Homenaje a las Víctimas del Holocausto-Shoá","plaza","Holocausto-Shoá: homenaje a las víctimas judías del atroz genocidio llevado a cabo por el nazismo durante la Segunda Guerra Mundial. Shoah o shoá (literalmente catástrofe) es la palabra hebrea utilizada para referirse al Holocausto."],["Homero","calle","Homero (¿-?), poeta griego cuyo nombre es el símbolo de la epopeya helénica y a quien se le atribuyen La Ilíada y La Odisea; probablemente vivió entre los siglos XII y VII antes de nuestra era, aunque la crítica histórica y literaria han puesto en duda su existencia y la paternidad de sus obras."],["República de Honduras","plaza","Honduras: país centroamericano. Capital: Tegucigalpa."],["El Hornero","calle","Hornero: pájaro que toma su nombre popular de su actitud constructiva para modelar su nido. Nombre científico: Furnarius rufus."],["General Hornos","calle","Manuel Hornos (1807 a 1871), militar; combate en Sauce Grande, Quebracho Herrado, Famaillá, Caaguazú, Caseros, en la defensa de Buenos Aires durante el sitio de Hilario Lagos, Cepeda, Pavón y en la guerra contra el Paraguay."],["Hortiguera","calle","Rafael Hortiguera (1775 a 1838), coronel; combate durante la Primera Invasión Inglesa en Buenos Aires y en la defensa de Montevideo en 1807; combate en Las Piedras y Cepeda (1820); acompaña a Martín Rodríguez en su expedición al desierto; combate durante la guerra contra el Brasil, donde ejerce interinamente la jefatura del Estado Mayor General del Ejército en Operaciones en 1826."],["Doctor Bernardo Alberto Houssay","plaza","Bernardo Alberto Houssay (1887 a 1971), médico y fisiólogo; comparte el Premio Nobel de Medicina en 1947 por su descubrimiento de la función hormonal de la pituitaria."],["Hualfin","calle","Hualfin: distrito del departamento de Belén, provincia de Catamarca, cuyo nombre alude a la parcialidad indígena de ese mismo nombre."],["Huaura","calle","Huaura: distrito y valle del Perú, al noroeste de la capital, donde San Martín establece su cuartel general al llegar a ese lugar en noviembre de 1820."],["Hubac","calle","Ángel Hubac (1780 a 1820), coronel de origen francés; comandante de la balandra América que integra la escuadra de Azopardo y de la goleta Nuestra Señora del Carmen en 1811; jefe de la escuadrilla compuesta por los bergantines Belén y Aranzazu y la goleta Invencible en 1818; muere como consecuencia de las heridas recibidas en el combate de Colastiné."],["Hudson","calle","Damián Hudson (1808 a 1875), historiador y funcionario; redactor de El Nacional; jefe de la Oficina de Estadística Nacional al crearse la misma en 1868; autor de Recuerdos históricos sobre la provincia de Cuyo (1863 a 1871) y del Registro Estadístico de la República Argentina (1865 a 1875)."],["Guillermo Enrique Hudson","jardín","Guillermo Enrique Hudson (1841 a 1922), escritor y naturalista especializado en ornitología; autor de Sobre las aves del río Negro, en la Patagonia, La tierra púrpura que Inglaterra perdió, El naturalismo en el Plata y Pájaros del Plata."],["La Huella","calle","Huella: señal que deja el pie del hombre o del animal o de cualquier vehículo sobre la tierra donde ha pasado. Es también el nombre de una típica danza argentina."],["Huergo","calle","Delfín Bonifacio Huergo (1824 a 1886), jurisconsulto; diputado por San Luis en el Congreso de 1853; ministro diplomático en Portugal, Prusia y Cerdeña de 1855 a 1860 y en Bélgica de 1883 a 1886."],["Ingeniero Huergo","avenida","Luis Augusto Huergo (1837 a 1913), ingeniero; encargado del proyecto y construcción del ramal del Ferrocarril Pacífico (San Martín) de Buenos Aires a Villa Mercedes; director de las obras del Riachuelo, es suyo el proyecto del Dock Sud; presenta en 1881 un proyecto de puerto para Buenos Aires, y al adjudicarse la construcción del mismo a la empresa Madero renuncia como director de la obra, originando una gran polémica entre ambos proyectos."],["La Huerta","calle","Huerta: lugar donde se siembran legumbres y hortalizas y que se distingue de la quinta en que ésta se dedica preferentemente al cultivo de árboles frutales."],["Víctor Hugo","calle","Víctor Hugo (1802 a 1885), poeta, dramaturgo y novelista francés; autor de Hernaní, La leyenda de los siglos y Los miserables."],["Humahuaca","calle","Quebrada de Humahuaca: valle o quebrada que se extiende desde Ojo de Agua o desde Llulluchayoc hasta cerca de la ciudad de Jujuy, y departamento y localidad de la provincia de Jujuy."],["Humaitá","calle","Humaitá: fortaleza paraguaya que defendía el paso de ese nombre sobre el río Paraguay; se denomina así a una de las cuatro campañas en que se dividió la guerra del Paraguay."],["Humberto I","calle","Manuel Juan María Fernando Eugenio de Saboya, Humberto I (1844 a 1900), rey de Italia de 1878 a 1900 cuando muere asesinado por un anarquista."],["Humboldt","calle","Federico Guillermo Enrique Alejandro, barón de Humboldt (1769 a 1859), naturalista alemán; junto con Bonpland recorre el territorio americano realizando investigaciones en el campo de las ciencias naturales; descubridor de la corriente marítima que lleva su nombre; autor de Visión de las cordilleras y monumentos de los pueblos indígenas de América y Viajes a las regiones equinocciales del nuevo continente."],["Hungría","calle","Hungría: país europeo. Capital: Budapest."],["Hungría","espacio verde","Hungría: país europeo. Capital: Budapest."],["Huracán","cantero central","Huracán: nombre del globo aerostático con el cual Jorge Newbery bate el récord sudamericano de duración y distancia, al unir Belgrano con la localidad brasileña de Bagé en Rio Grande do Sul (Brasil) el 27 de diciembre de 1909."],["Húsares","calle","HÚSARES DE PUEYRREDÓN, REGIMIENTO 10 DE CABALLERÍA (plazoleta). Ordenanza N° 27.705-1973, BM N° 14.547. Húsares de Pueyrredón: regimiento de caballería que actúa durante las Invasiones Inglesas y la guerra de la Independencia. Denominado originariamente Húsares del Rey, por Decreto del 12 de agosto de 1819, toma el nombre de Húsares de Pueyrredón como homenaje a la destacadísima actuación que desarrolla bajo el mando de don Juan Martín de Pueyrredón durante las Invasiones Inglesas. Notas."],["Ibáñez","calle","Pedro Ibáñez (1776 a 1819), coronel; combate durante las Invasiones Inglesas y en la expedición al Paraguay de Belgrano, de quien es su primer edecán; se destaca en la batalla de Tacuarí; gobernador interino de Buenos Aires en noviembre de 1818."],["Juana de Ibarbourou","calle","Juana Fernández Morales de Ibarbourou (1895 a 1979), poetisa uruguaya; presidente de la Sociedad Uruguaya de Escritores (1950); sus obras: Las lenguas de diamante, Raíz salvaje, Romances del destino y Juan Soldado."],["Ibarrola","calle","Amadeo Ibarrola (¿1791?-1853), teniente coronel; combate durante el sitio de Montevideo; participa en la sublevación de Fontezuelas; combate contra los indios en Tapalqué. Mariano Ibarrola (1788 a 1858), coronel, hermano del anterior; combate durante las Invasiones Inglesas, en el primer sitio de Montevideo y en Las Piedras; participa en la campaña sobre Santa Fe en 1819 y en la expedición al desierto de Martín Rodríguez; jefe de la Frontera del Centro con asiento en Navarro y Lobos de 1824 a 1827."],["Rodrigo de Ibarrola","calle","Rodrigo de Ibarrola (¿-?), capitán; acompaña a Garay en la fundación de Buenos Aires en 1580."],["Iberá","calle","Iberá: laguna y esteros de la provincia de Corrientes."],["Icalma","calle","Icalma: paso de la Cordillera de los Andes que comunica Neuquén, Zapala y Aluminé con las localidades chilenas de Freire y Temuco."],["Paseo Marcela Brenda Iglesias","paseo","Marcela Brenda Iglesias (1990 a 1996), niña que fallece como consecuencia de un accidente fatal que se produce al caerse sobre ella una escultura emplazada en el Paseo de la Infanta el 5 de febrero de 1996."],["César Iglesias Paz","plazoleta","César Iglesias Paz (1881 a 1922), jurisconsulto y comediógrafo; autor de La conquista, El vuelo nupcial, La propia obra, El pecado original y Una deuda de dolor."],["Igualdad","calle","Igualdad: en homenaje al principio que reconoce los mismos derechos a todos los ciudadanos."],["Iguazú","calle","Iguazú: río de la provincia de Misiones, en cuyo recorrido se encuentran las célebres cataratas."],["Presidente Doctor Arturo Umberto Illia","autopista","Arturo Umberto Illia (1900 a 1983), médico; presidente de la Nación de 1963 a 1966."],["Inca","calle","Inca: autoridad principal del imperio incaico."],["De los Incas","avenida","Incas: nombre con que se denomina a la civilización aborigen que a la llegada de los españoles habitaba el Perú, Ecuador, Bolivia y el norte argentinochileno."],["Inclán","calle","Juan Alonso de Valdés e Inclán (¿-?), militar español; gobernador del Río de la Plata desde 1702 hasta 1708."],["Independencia","avenida","Independencia: recuerda la Declaración de la Independencia proclamada por el Congreso de Tucumán el 9 de julio de 1816."],["República de la India","calle","India: país asiático. Capital: Nueva Delhi."],["Las Indias","calle","Indias Occidentales: nombre con que se conocía al territorio americano en la época de la conquista española."],["Indio","calle","Indio: homenaje a los primitivos pobladores de la República Argentina y de América en general. Cabe señalar aquí que esta denominación fue otorgada con motivo de haber sido denominada “Elpidio González” la anterior calle “Indio”. Esta primera arteria de ese nombre, otorgado por ordenanza del 27-11-1893, recordaba en realidad a Punta Indio, accidente de la costa bonaerense del partido de Magdalena. No obstante, al discutirse la inclusión del nombre de “Elpidio González”, un concejal interpretó que “Indio” recordaba a los aborígenes de estas tierras y fue con ese sentido que propuso la restitución de este nombre y como tal se aprobó."],["Indoamericano","parque","Indoamericano: término con que (en lugar de Hispanoamérica, Iberoamérica o Latinoamérica) se reivindican los valores étnicos y culturales del pasado indígena de los pueblos colonizados por España y Portugal. En este caso se pretende valorizar y proteger la flora amenazada del área."],["República de Indonesia","calle","Indonesia: república de Asia insular. Capital: Yakarta."],["De la Industria","calle","Industria: se refiere al conjunto de las industrias del país y es un homenaje a este sector económico de la producción nacional."],["José Ingenieros","calle","José Ingenieros (1877 a 1925), médico y ensayista; secretario del Partido Socialista Obrero Internacional en 1895; redactor de La Vanguardia; director del Instituto de Criminología en 1907; presidente de la Sociedad Médica Argentina en 1909 y de la Sociedad de Psicología en 1910; autor de El hombre mediocre, Sociología argentina y La evolución de las ideas argentinas."],["Inglaterra","calle","Inglaterra: país situado en la isla de Gran Bretaña y con cuyo nombre se identifica popularmente a todo el Reino Unido. Capital: Londres."],["De los Inmigrantes","avenida y cantero central","Inmigrantes: recuerda a los inmigrantes que llegaron a nuestro país desde el período hispánico hasta la actualidad. Se otorgó este nombre al cumplirse el Centenario de la Ley N° 817 del 6 de octubre de 1876, por la cual quedó constituido el Departamento General de Inmigrantes."],["El Invencible de Forli","cantero central","El invencible de Forli: nombre del globo aerostático con el que el capitán José Silimbani y su esposa Antonieta Cimolini (procedentes ambos de la ciudad italiana de Forli) realizaban ascensiones circenses, ya que en el lugar de la barquilla poseía un trapecio. El 13 de marzo de 1904, ella pierde la vida al ser el globo arrastrado hacia el río por el viento."],["Segundo Iñigo Carrera","calle","Segundo Iñigo Carrera (1876 a 1928), funcionario y político socialista; estudioso de los problemas del trabajo; propulsor del movimiento gremialista y del cooperativista; cofundador de la cooperativa El Hogar Obrero."],["Irala","calle","Domingo Martínez de Irala (¿1509?-1556), conquistador español; llega al Río de la Plata con la expedición de don Pedro de Mendoza y asiste al establecimiento del asiento de Buenos Aires en 1536; despuebla Buenos Aires en 1541; gobernador del Río de la Plata de 1538 a 1542, de 1544 a 1547 y de 1548 a 1556."],["República Islámica del Irán","plaza","Irán: país asiático. Capital: Teherán."],["Iraola","avenida","Martín J. Iraola (1835 a 1877), funcionario; presidente de la Municipalidad de la Ciudad de Buenos Aires; miembro de la Comisión que crea el Parque 3 de Febrero; presidente del Club del Progreso."],["Brigadier General Tomás de Iriarte","plazoleta","Tomás de Iriarte (1794 a 1876), brigadier general; director de la Escuela de Artillería de 1818 a 1820; combate durante la guerra contra el Brasil, en Don Cristóbal, Sauce Grande y Quebracho Herrado. Redacta con Bartolomé Mitre el Código Militar; autor de numerosos trabajos, se destacan entre ellos sus Memorias."],["Irigoyen","calle","Matías de Irigoyen (1781 a 1839), general; diplomático ante la Corte de Ingla- terra nombrado por la Junta el 29 de mayo de 1810; combate durante el sitio de Montevideo en 1812; ministro de Guerra y Marina del Director Pueyrredón de 1817 a 1819. Miguel de Irigoyen (1764 a 1832), teniente coronel; edecán de Liniers durante la Reconquista de Buenos Aires en 1806; intendente de Policía en 1812 y 1820; gobernador delegado de Buenos Aires junto con Francisco Antonio de Escalada en 1816. Homenaje conjunto a los hermanos Irigoyen."],["Bernardo de Irigoyen","calle","Bernardo de Irigoyen (1822 a 1906), jurisconsulto; ministro de Relaciones Exteriores en 1875, de Interior en 1877, de Relaciones Exteriores y Culto en 1881 y nuevamente de Interior en 1882; gobernador de Buenos Aires de 1898 a 1902."],["Coronel Martín Irigoyen","plaza","Subdivisión por zonas de valor, de 1923. Martín Irigoyen (1857 a 1916), militar; combate en la guerra contra el Paraguay y en las campañas contra el indio; combate en 1880 en San José de Flores y en Corrales; actúa en la Frontera del Chaco entre 1882 y 1884; participa en las revoluciones de 1890, 1893 y 1905; actúa en las filas del radicalismo."],["Santos Irigoyen","calle","José Santos Irigoyen (?-1807), capitán del Tercio de Vizcaínos, muerto durante las Invasiones Inglesas. Es éste un nombre tradicional de Buenos Aires, ya que entre 1808 y 1822 se denominaron Irigoyen las actuales Santiago del Estero y Talcahuano."],["Irlanda","calle","Irlanda: país insular europeo. Capital: Dublin."],["Irlanda","plaza","Irlanda: país insular europeo. Capital: Dublin."],["Infanta Isabel","avenida","María Isabel Francisca de Asís de Borbón (1851 a 1931), Infanta de España; dos veces princesa de Asturias; representa al gobierno español en la celebración del Centenario de 1810."],["Isabel la Católica","calle","Isabel I, La Católica (1451 a 1504), reina de Castilla que rige los destinos de España junto con su esposo Fernando de Aragón, por lo que son conocidos como los Reyes Católicos. Decidida partidaria de los planes de Colón, lo ayuda en su empresa del descubrimiento de América."],["Islandia","calle","Islandia: país ubicado al noroeste de Europa. Capital: Reykiavik. ISLAS CANARIAS véase CANARIAS, ISLAS. ISLAS DE LA PATERNAL véase PATERNAL. ISLAS MALVINAS véase MALVINAS, ISLAS."],["Estado de Israel","avenida","Israel: país asiático. Capital: Jerusalén. La capital de Israel es Jerusalén. Tel Aviv, capital del distrito del mismo nombre, es la mayor ciudad y el centro industrial y administrativo más importante del país, pero la capital es Jerusalén. ISRAEL “EN MEMORIA DEL ATENTADO”, EMBAJADA DE (plazoleta). Ley N° 896-2002, BO Nº 1.545. Embajada de Israel: en memoria de las víctimas del atentado cometido contra la Embajada de Israel el 17 de marzo de 1992."],["Italia","calle","Capital de la República Argentina, con el trazado general de calles, confeccionado por el Departamento de Obras Públicas de la Municipalidad, año 1904."],["Italia","plaza","Italia: país europeo. Capital: Roma."],["De los Italianos","avenida","Italianos: homenaje a la inmigración italiana y a los aportes de la cultura de esa Nación, en ocasión de la visita del señor presidente de la República de Italia, don Giovanni Gronchi, primer jefe de un estado europeo que visita oficialmente nuestro país. Gronchi llegó a Buenos Aires el 10 de abril de 1961."],["Itaquí","calle","Itaquí: ciudad de Brasil, en el estado de Rio Grande do Sul, que se encuentra ubicada sobre el río Uruguay, frente a nuestra provincia de Corrientes."],["Iturri","calle","Francisco Xavier Iturri (1738 a 1822), sacerdote, historiador y geógrafo; autor de Historia Natural, Eclesiástica, y Civil del Virreinato de Buenos Aires junto con el padre Gaspar Xuárez, y de Descripción del Paraguay, Río de la Plata y Tucumán."],["Ituzaingó","calle","Ituzaingó: batalla librada durante la guerra contra el Brasil el 20 de febrero de 1827, entre las fuerzas del general Alvear y las del Marqués de Barbacena. Notas."],["Jacarandá","calle","Jacarandá: árbol de la familia de las bignoniáceas que crece en el Chaco y Formosa y cuyos ejemplares adornan muchas calles y plazas de la ciudad de Buenos Aires."],["Amadeo Jacques","calle","Amadeo Florentino Jacques (1813 a 1865), educador de origen francés; director del Colegio San Miguel de Tucumán de 1858 a 1860; director del Colegio Nacional de Buenos Aires de 1863 a 1865."],["Jáchal","calle","Jáchal: ciudad y departamento de la provincia de San Juan."],["Jamaica","plaza","Jamaica: estado americano de las Antillas. Capital: Kingston."],["Ana María Janer","calle","Ana María Janer (1800 a 1885), religiosa española; dedica su vida a la educación, asistencia sanitaria y social de los niños huérfanos y pobres; fundadora de la Congregación de Hermanas de la Sagrada Familia de Urgel."],["Juan Bautista Jantín","calle","Juan Bautista Fantín (?-1906), militar de origen francés; subteniente de Urbanos y edecán de Liniers, muere en las acciones de la Reconquista durante las Invasiones Inglesas. Es éste un nombre tradicional de la ciudad pues entre 1808 y 1822 se denominó “Fantín” la actual Marcelo T. de Alvear."],["Víctor Jara","cantero central","Víctor Jara (1938 a 1973), cantautor y director teatral chileno; uno de los principales exponentes del canto popular de Chile; detenido y asesinado en el Estadio Nacional de Santiago de Chile pocos días después del golpe de Estado del 11 de septiembre de 1973; autor de Paloma quiero cantarte, Plegaria a un labrador, Te recuerdo Amanda, entre otras composiciones."],["Jaramillo","calle","Gregorio Jaramillo (¿-?), es uno de los soldados que junto con Juan Manza- nares y José Santos Frías salva a Lamadrid en Culpina en enero de 1816. Por esa acción los tres soldados son ascendidos al grado de sargento."],["Jean Jaurés","calle","Jean Jaurés (1859 a 1914), político, profesor de filosofía y periodista francés; escribe en la Petite République y en L´Humanité; visita Buenos Aires en 1911; socialista doctrinario y opositor de la guerra es asesinado el 31 de julio de 1914."],["Arturo Jauretche","calle","Arturo Martín Jauretche (1901 a 1974), abogado; escritor y político; fundador de FORJA (Fuerza de Orientación Radical de la Joven Argentina); presidente del Banco Provincia de Buenos Aires de 1946 a 1950; autor de Los profetas del odio, La yapa, FORJA y la década infame, Manual de zonceras argentinas y El medio pelo en la sociedad argentina. JAVIER CABRINI, SANTA FRANCISCA véase CABRINI, SANTA FRANCIS-."],["Doctor Eduardo Ca Javier. Jenner","calle","Eduardo Jenner (1749 a 1823), médico y naturalista inglés; descubridor de la vacuna antivariólica."],["Pedro de Jerez","calle","Pedro de Jerez (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Jorge","calle","José Nicolás Jorge (1786 a 1866), coronel de marina de origen griego; combate en Arroyo de la China y en el sitio de Montevideo en 1814; comandante del falucho San Luis en 1817; combate en Colastiné, en la guerra contra el Brasil, en Don Cristóbal y en Sauce Grande."],["José Bonifacio","calle","José Bonifacio de Andrada y Silva (1763 a 1838), político y escritor brasileño; ministro de Relaciones Exteriores de Don Pedro I; tutor de Don Pedro II; prócer de la Independencia brasileña."],["Gaspar Melchor de Jovellanos","calle","Gaspar Melchor de Jovellanos (1744 a 1811), escritor, estadista y jurisconsulto español; autor de Ley Agraria y Reglamento del Colegio Imperial de Calatrava; ministro de Gracia y Justicia en 1797; representante de Asturias ante la Junta Central."],["Juan Xxiii","plazoleta","Ángelo Giuseppe Roncalli, Juan XXIII (1881 a 1963), sacerdote; Papa de la Iglesia Católica de 1958 a 1963; da a luz las encíclicas Mater et Magistra, Aeterna Dei Sapientia y Pacem in terris."],["Juana de Arco","calle","Juana de Arco (1412 a 1431), santa y mártir francesa; es quemada viva por los ingleses acusada de herejía."],["Sor Juana Inés de la Cruz","calle","Sor Juana Inés de la Cruz: nombre religioso de Juana de Asbaje y Ramírez de Cantillana (1651 a 1685); religiosa mexicana que cultivó sus excelentes facultades naturales y escribió numerosos sonetos, romances y letrillas. Sus obras fueron publicadas en tres tomos en 1689, 1691 y 1700; entre sus opúsculos cabe mencionar Carta Atenagórica, El mártir del Sacramento y Divino Narciso."],["Benito Juárez","calle","Benito Juárez (1806 a 1872), estadista mexicano; presidente de la República en 1861, 1867 y 1872."],["Jufré","calle","Juan Jufré (¿1516?-1578), conquistador español; traslada la ciudad de Mendoza a su actual emplazamiento el 28 de marzo de 1562; fundador de San Juan el 13 de junio del mismo año."],["Provincia de Jujuy","cantero central","Jujuy: provincia de la República Argentina. Capital: San Salvador de Jujuy."],["Juncal","calle","Juncal: combate naval librado en el río Uruguay el 8 y 9 de febrero de 1827, durante la guerra contra el Brasil, en el que la escuadra del almirante Brown derrota a las fuerzas enemigas."],["Villa Juncal","calle","Villa Juncal: primitiva denominación de este sector de la ciudad. Este nombre, que recuerda el combate de Juncal, es asignado por el ferrocarril a una estación que iba a ser inaugurada en 1908, entre las actuales Caracas, Gavilán, Ingeniero Agustín González y las vías, a escasos quinientos metros de donde se encuentra esta calle. Alrededor de esta proyectada estación comienzan a promocionarse los remates de tierras en la zona con el nombre de Villa Juncal."],["Junín","calle","Junín: batalla librada el 6 de agosto de 1824 en la pampa de Junín (Perú) durante la guerra de la Independencia, entre el ejército patriota al mando del general Simón Bolívar y el realista al mando del General José Canterac."],["Juramento","calle","Juramento: río que con el nombre de Pasaje nace en el borde de la Puna, en Salta, y atraviesa luego Santiago del Estero y Santa Fe para desembocar en el Paraná con el nombre de Salado. En sus márgenes, el 13 de febrero de 1813, Belgrano presta juramento de obediencia a la Asamblea General Constituyente y hace jurar la bandera por sus tropas, bautizando a este curso fluvial con el nombre de Río del Juramento."],["General Agustín P. Justo","plaza","Agustín Pedro Justo (1876 a 1945), militar y político; presidente de la República de 1932 a 1938."],["Juan B. Justo","avenida","Juan Bautista Justo (1865 a 1928), médico y político; fundador de La Vanguardia en 1894; redactor de la Declaración de Principios y de los estatutos del Partido Socialista; publica en Madrid la primera versión española de El Capital de Carlos Marx; fundador de la cooperativa El Hogar Obrero; diputado nacional en 1912, 1916 y 1922; senador nacional en 1924; autor de Teoría y Práctica de la Historia."],["Juvenilia","plazoleta","Juvenilia: libro de Miguel Cané publicado en 1884 donde relata los recuerdos de su vida escolar. Notas."],["Frida Kahlo","cantero central","Frida Kahlo (1907 a 1954), artista plástica mexicana; autora de El nacimiento, Autorretrato de Tehuana, Mi niña y yo, Autorretrato con collar, Autorretrato con monos y Autorretrato en la frontera entre México y Estados Unidos; esposa de Diego Rivera, alojan en su “Casa Azul” a León Trotsky durante dos años."],["Arquitecto René Karman","plaza","René Karman (1875 a 1951), arquitecto de origen francés; profesor de la Facultad de Ciencias Exactas y de la de Arquitectura y Urbanismo de la Universidad de Buenos Aires; ejecuta las ampliaciones de los hospitales Álvarez y Alvear; gana los concursos para la construcción del Palacio Municipal de Montevideo y de la Caja Nacional de Ahorro Postal de Buenos Aires. KASÜ-MAPÚN, RINCÓN VERDE véase RINCÓN VERDE KASÜ-MAPÚN."],["Tomás Katari","plazoleta","Tomás Katari (¿1735/1740?-1781), líder de la rebelión indígena en el Alto Perú que en 1777 se opone al corregidor y a los caciques nombrados por éste, ya que limitaban el acceso de los indios más pobres a las tierras comunales. Viaja a Buenos Aires para entrevistarse con el virrey quien lo reconoce como cacique del pueblo Macha, no obstante lo cual, al retornar a su tierra, es detenido y pierde la vida el 15 de enero de 1781."],["Helen Keller","plazoleta","Helen Adams Keller (1880 a 1968), escritora estadounidense; ciega, sorda y muda de nacimiento, supera todos sus impedimentos gracias a la maestra Ana Mansfield Sullivan (1866 a 1936), doctorándose en Letras, Leyes y Medicina; autora de Historia de mi vida, Optimismo, La canción de la pared de piedra, Diario de Helen Keller y Maestra Ana Sullivan."],["John F. Kennedy","calle","John Fitzgerald Kennedy (1917 a 1963), político estadounidense, presidente de los Estados Unidos de Norteamérica desde 1961; muere asesinado el 22 de noviembre de 1963."],["King","calle","Juan King (1800 a 1857), marino de origen irlandés; combate durante la guerra contra el Brasil; comandante del bergantín goleta Vigilante y de la fragata 25 de Mayo en 1841, y del bergantín General Belgrano en 1844."],["Del Kiosco de la Floresta","plazoleta","Del Kiosco de la Floresta: recreo o pulpería, hito fundacional del futuro barrio, adonde llega el primer servicio ferroviario del país el 29 de agosto de 1857."],["Doctor Roberto Koch","plazoleta","Roberto Koch (1843 a 1910), médico y microbiólogo alemán; descubridor del bacilo de la tuberculosis en 1882; realiza una ardua tarea en Egipto y en la India por combatir el cólera descubriendo el vibrio de esta enfermedad en 1884; Premio Nobel de Medicina en 1905."],["Doctor Alejandro Korn","calle","Alejandro Korn (1860 a 1936), médico psiquiatra y filósofo; profesor de Historia de la Filosofía de la Facultad de Filosofía y Letras de Buenos Aires; director del Hospital para Alienados Melchor Romero de 1897 a 1916; autor de Las influencias filosóficas en la evolución nacional y La libertad creadora."],["Ingeniero Julio Krause","calle","Julio Krause (1858 a 1923), ingeniero; jefe de la Sección Hidrología y Perforaciones de la División Minas, Geología e Hidrología del Ministerio de Agricultura de la Nación, coordina en 1907 los trabajos que permiten el descubrimiento de petróleo en Comodoro Rivadavia."],["Ingeniero Otto Krause","plazoleta","Otto Krause (1856 a 1920), ingeniero civil; profesor; director de la Escuela Industrial de la Nación que hoy lleva su nombre; decano de la Facultad de Ciencias Exactas, Físicas y Naturales en 1906."],["Arquitecto Juan Kurchan","plaza","Juan Kurchan (1913 a 1972), arquitecto; egresado de la UBA, completa su formación en París donde trabaja con Le Corbusier. En 1938 participa en la creación del grupo Austral del que también forman parte los arquitectos Antonio Bonet y Jorge Ferrari Hardoy. En ese mismo año diseña junto a ellos la silla BKF, que obtiene en 1940 el Premio de la Comisión Nacional de Cultura y el Primer Premio de la Comisión Nacional de Bellas Artes. En 1941, junto a Ferrari Hardoy, proyecta y construye la casa de departamentos de O’Higgins 2319, la que sirve como ensayo de un conjunto de principios que se realizan plenamente en el edificio de vivienda colectiva de la calle Virrey del Pino 2446. Director de Urbanismo de la Municipalidad de Buenos Aires en 1952. En 1953, construye el edificio de departamentos de Saturnino Segurola 1310, en el Partido de Vicente López, donde vive desde entonces."],["Estado de Kuwait","cantero central","Kuwait: país del Golfo pérsico. Capital: Al Kuwait. Notas."],["Lacarra","calle","Martín Paulino Lacarra (1777 a 1858), coronel; combate durante las Invasiones Inglesas y en el sitio de Montevideo; comandante político y militar de Patagones desde 1824, interviene durante el ataque del Imperio del Brasil contra Carmen de Patagones en 1827. LA CASA DEL ÁNGEL véase CASA DEL ÁNGEL, LA."],["La Constancia","calle","La Constancia: localidad del partido de Ayacucho, provincia de Buenos Aires."],["Federico Lacroze","avenida","Federico Lacroze (1835 a 1899), industrial; inaugura en 1870 una línea de tranvías a caballo junto con su hermano Julio, que con el tiempo se transformará en la poderosa empresa Lacroze de transporte tranviario; en 1887 inaugura el servicio del Tranvía Rural, más tarde Ferrocarril Central de la Provincia y luego Ferrocarril General Urquiza. LA CUMPARSITA véase CUMPARSITA, LA."],["Ladines","calle","José María Ladines (1786 a 1839), comerciante; en su casa de la calle Cuyo (hoy Sarmiento) 115 se celebraban reuniones que conspiraban contra el gobierno de Juan Manuel de Rosas; considerado cómplice del doctor Manuel Maza es detenido y liberado poco después por falta de pruebas."],["Lafayette","calle","María José Pablo Motier, marqués de Lafayette (1757 a 1834), general francés; en 1777 se traslada a América del Norte transformándose en uno de los principales actores de la independencia de los Estados Unidos de América."],["Gregorio de Laferrere","calle","Gregorio de Laferrere (1867 a 1913), escritor y comediógrafo; autor de ¡Jettatore!, Locos de verano, Bajo la garra y Las de Barranco."],["Lafinur","calle","Juan Crisóstomo Lafinur (1797 a 1824), poeta y filósofo; profesor de Filosofía en el Colegio de la Unión del Sud; vicepresidente de la Sociedad Lancasteriana, propugna la implantación de este método de enseñanza; colabora en El Censor, El Curioso y El Americano y en El Mercurio, El Observador Chileno y El Despertador Americano de Santiago de Chile; autor de Canto elegíaco a la muerte de Belgrano, Oda a la jornada de Maipo y Oda a la Libertad de Lima."],["Monseñor Fermín Lafitte","plaza","Fermín Emilio Lafitte (1888 a 1959), sacerdote; párroco de San Nicolás de Bari en 1920; obispo de Córdoba en 1924 y primer arzobispo de la misma en 1934; arzobispo de Buenos Aires y primado de la Argentina."],["Gabriel Lafond","calle","Gabriel Pedro María Lafond de Lurcy (1801 a 1876), viajero francés; autor de Quince años de viajes alrededor del mundo y Viaje alrededor del mundo y naufragios célebres, donde se ocupa extensamente de la entrevista entre Bolívar y San Martín; es el primero a quien San Martín confía los pormenores de lo tratado en la entrevista de Guayaquil."],["La Fontaine","calle","Jean de La Fontaine (1621 a 1695), escritor francés; célebre por sus Fábulas, que son modelo en su género. LA FRONDA véase FRONDA, LA."],["Lafuente","calle","Juan Bautista de Lafuente (1776 a 1862), teniente coronel; combate durante las Invasiones Inglesas; capitán del Tercio Cívico de la Guardia Nacional de Infantería en 1814. Enrique Lafuente (1815 a 1850), comerciante, jurisconsulto y político, hijo del anterior; miembro del Salón Literario; miembro fundador de la Asociación de Mayo y del Club de los Cinco; combate en Don Cristóbal. LA GALERA véase GALERA, LA. LA GLORIA véase GLORIA, LA."],["Lagos","calle","Hilario Lagos (1806 a 1860), general; combate durante la guerra contra el Brasil y en la lucha contra el aborigen; en Quebracho Herrado, Famaillá y Caseros; comandante en jefe del Departamento Centro con sede en Luján, se pronuncia contra el gobierno de Buenos Aires separado de la Confederación, el 1° de diciembre de 1852, sitiando la ciudad; combate en Cepeda."],["Alberto Lagos","plazoleta","Alberto Lagos (1885 a 1960), escultor y profesor; autor de varias obras, entre ellas Al Inmigrante y Guillermo Udaondo."],["Luis Lagos García","calle","Luis Lagos García (1844 a 1907), jurisconsulto; convencional nacional en 1898 cuando se reforman los artículos 37 y 87 de la Constitución; autor de Economía política y El ansiado nombramiento político; propicia y defiende la Ley N° 1.420 de Educación Común."],["Lagrange","calle","José Luis Lagrange (1736 a 1813), astrónomo y matemático francés; creador del cálculo de variaciones y de la teoría de las libraciones de la luna y de los satélites de Júpiter; descubridor de la serie de Lagrange. LA GUERRA GAUCHA véase GUERRA GAUCHA, LA."],["Laguna","calle","Julián Laguna (1782 a 1835), brigadier general uruguayo; combate en las Piedras, en el sitio de Montevideo y en la guerra contra el Brasil. Nicolás Valerio Laguna (1772 a 1838), jurisconsulto; diputado por Tucumán en la Asamblea de 1813; gobernador intendente de esa provincia de 1823 a 1824 y de 1827 y 1828. Homenaje conjunto a los hermanos Laguna."],["La Haya","calle","La Haya: ciudad de los Países Bajos (Holanda) en la que reside la corte y el gobierno. LA HISTORIA OFICIAL véase HISTORIA OFICIAL, LA."],["Ciudad de Lakewood","plazoleta","Lakewood: ciudad de los Estados Unidos de Norteamérica en el estado de California. Se le otorga este nombre a esta plazoleta en acto de reciprocidad por existir en esta ciudad norteamericana un busto y una plaza con el nombre del general San Martín."],["Ingeniero Germán Ave Lallemant","cantero central","Germán Ave Lallemant (1835 a 1910), geólogo de origen alemán; radicado en la Argentina; se establece en San Luis; rector del Colegio Nacional de San Luis; autor de Memoria descriptiva de la provincia de San Luis e Índice alfabético de la flora puntana; funda el primer periódico marxista que aparece en la Argentina, El Obrero, en 1890."],["La Mar","calle","José La Mar y Cortázar (1776 a 1830), general ecuatoriano; combate en Junín y Ayacucho; presidente del Perú de 1827 a 1829."],["Emilio Lamarca","calle","Emilio Lamarca (1844 a 1922), jurisconsulto; autor de El Decálogo y Economía Política; directivo del Primer Congreso Católico Nacional en 1884; director de La Unión de 1882 a 1886; iniciador y fundador de las cajas rurales."],["Andrés Lamas","calle","Andrés Lamas (1817 a 1891), político, diplomático e historiador uruguayo; jefe político de Montevideo en 1843; ministro de Hacienda en 1844; ministro plenipotenciario en el Brasil, participa en los tratados de octubre de 1851 con el fin de deponer a Juan Manuel de Rosas; nuevamente ministro de Hacienda en 1875."],["Lambaré","calle","Lambaré: jefe guaraní cuya tribu dominaba las inmediaciones de la actual ciudad de Asunción del Paraguay y con cuyo nombre se identificaba al lugar. Se enfrenta en 1536 con la expedición española de Juan de Ayolas."],["Pacífico Víctor Lambertucci","cantero central","Pacífico Víctor Lambertucci (1891 a 1976), músico, pianista, compositor y director; integra distintos conjuntos musicales; compositor de El espectro, Alma Criolla y Amarrete. Su gran éxito llega con Carne de cabaret, con letra de Luís Roldán, tango que es grabado por Carlos Gardel."],["Rosa Lamorte de Lombardo","espacio verde","Rosa Lamorte de Lombardo (1952 a 1977) militante peronista; dictaba clases de actividades prácticas a niños carecientes en el Club Social y Deportivo Corrales; es secuestrada el 28 de abril de 1977, a pocos metros de su casa. Permanece desaparecida."],["Lancheros del Plata","calle","Lancheros del Plata: recuerda a los conductores, patrones y tripulantes de la lanchas de tráfico de los puertos, quienes fueron el nexo obligado entre el buque de ultramar y los muelles del Riachuelo, de la Aduana Nueva o de las Catalinas hasta el momento en que se construye el puerto de Buenos Aires."],["Marie Langer","calle","Marie Lisbeth Glas Hausser de Langer (1910 a 1987), médica psicoanalista austriaca; es una de las fundadoras de la Asociación Psicoanalítica Argentina en 1942 y de la Asociación Argentina de Psicología y Psicoterapia de Grupo en 1957, a las que preside en reiteradas ocasiones; preside también la Federación Argentina de Psiquiatras; es profesora de la Cátedra de Psicología Médica de la Facultad de Medicina; autora de Maternidad y Sexo, Fantasías eternas a la luz del psicoanálisis, Memoria, historia y diálogo psicoanalítico y Aspectos teóricos y clínicos."],["Lanín","calle","Lanín: cerro de la provincia del Neuquén situado en el Parque Nacional de su nombre."],["Julieta Lanteri","calle","Julieta Lanteri de Renshaw (1873 a 1932), médica de origen italiano; propulsora de los derechos femeninos; es una de las primeras mujeres que obtiene la carta de ciudadanía argentina; forma parte de las primeras organizaciones feministas como el Centro de Universitarias Argentinas; con Raquel Camaña funda la Liga Pro Derechos de la Mujer y del Niño. En 1906, integra el Centro Feminista del Congreso Internacional del Libre Pensamiento que se hace en Buenos Aires y con otras feministas, como Raquel Camaña, Elvira Rawson de Dellepiane, Petrona Eyle y Cecilia Grierson reclaman por los derechos cívicos femeninos en la Argentina. Poco después, el Concejo Deliberante porteño sanciona una Ordenanza donde especifica que está prohibido el voto de la mujer porque el empadronamiento se basa en el registro del servicio militar. A raíz de esto, Julieta Lanteri se presenta ante el registro militar de Capital Federal solicitando ser enrolada y acude directamente al ministro de Guerra y Marina. En 1919, se postula a una banca en el Congreso como diputada, convirtiéndose así en la primera mujer candidata en la Argentina. Al no ser legalizada para ingresar al Parlamento organiza en la plaza Flores el primer simulacro de votación callejera y congrega a más de dos mil personas, llamando la atención de las feministas en el mundo. A principios de 1920, el senador Dr. Juan B. Justo la incluye en su lista del Partido Socialista junto a Alicia Moreau de Justo. En 1920 se presenta como candidata a diputada por el Partido Feminista Nacional del que había sido fundadora."],["Lanús","calle","Anacarsis Lanús (1818 a 1888), comerciante y político; segundo jefe de Policía de Buenos Aires en 1853; constructor de la primera empresa de servicios de agua corriente de Montevideo en 1871; ayuda económicamente a Eduardo Madero en la construcción del puerto de Buenos Aires."],["Lanza","calle","José Miguel Lanza (1779 a 1828), general boliviano; combate en Cotagaita, Suipacha, Huaqui, Tucumán y Salta; luego de Ayacucho, toma la ciudad de La Paz el 25 de enero de 1825; muere en esa ciudad, tres años más tarde, al sofocar un motín militar. Victorio Lanza (1777 a 1812), caudillo boliviano, hermano del anterior; es tomado prisionero y decapitado por los realistas en 1812."],["Lapacho","calle","Lapacho: árbol de la América meridional, de la familia de las bignoniáceas; su madera fuerte e incorruptible se emplea en construcción y en ebanistería."],["Provincia de la Pampa","cantero central","La Pampa: provincia de la República Argentina. Capital: Santa Rosa."],["Ciudad de la Paz","calle","La Paz: ciudad capital administrativa de Bolivia y del departamento de su nombre."],["Laplace","calle","Pedro Simón, marqués de Laplace (1749 a 1827), matemático y astrónomo francés; descubridor de la invariabilidad de los ejes mayores de las órbitas planetarias, de la teoría de los satélites de Júpiter y de la primera teoría cosmogónica moderna, llamada de Kant-Laplace."],["La Plata","avenida","La Plata: ciudad capital de la provincia de Buenos Aires."],["Laprida","calle","Obras Públicas.) Francisco Narciso de Laprida (1786 a 1829), jurisconsulto; diputado por San Juan en el Congreso de Tucumán y presidente del mismo durante el mes de julio de 1816, firma como tal la declaración de la Independencia; gobernador interino de San Juan en 1818."],["La Rábida","avenida","La Rábida: antiguo convento franciscano de la provincia de Huelva, España, donde halla refugio Cristóbal Colón y en el cual el prior Juan Pérez congrega a varios peritos con el fin de estudiar el proyecto del célebre navegante. Los tripulantes de las tres naves cumplen allí sus deberes religiosos el 2 de agosto de 1492, víspera de la partida, y también allí se reúnen al regresar de América el 10 de marzo de 1493. Se lo considera el primer monumento colombino del mundo."],["Cadete Carlos Larguía","calle","Carlos Larguía (1910 a 1930), militar; cursaba el tercer año en el Colegio Militar cuando muere en un enfrentamiento en la zona de Congreso durante la revolución del 6 de septiembre de 1930."],["Provincia de la Rioja","cantero central","La Rioja: ciudad y provincia de la República Argentina."],["Doctor José Ignacio de la Roza","calle","José Ignacio de La Roza (1788 a 1834), jurisconsulto; teniente de gobernador de San Juan de 1815 a 1820, colabora con San Martín en la formación del Ejército de los Andes."],["Crisólogo N° 17.460. Larralde","plazoleta","Crisólogo Larralde (1902 a 1962), periodista y político radical de amplia trayectoria; integra el bloque de Convencionales Constituyentes, que participa en la redacción del artículo 14 bis de la Constitución Nacional en 1957."],["Dámaso Larrañaga","calle","Dámaso Antonio de Larrañaga (1771 a 1848), sacerdote uruguayo; combate en Montevideo durante las Invasiones Inglesas; producida la Revolución de Mayo apoya la adhesión de la Banda Oriental con la Primera Junta; crea la Biblioteca Pública de Montevideo en 1816."],["Larraya","calle","Isidoro Larraya (1790 a 1831), coronel uruguayo; combate durante el sitio de Montevideo, en Saucecito, Cañada de la Cruz, San Nicolás, Pavón y Gamonal; participa junto a Martín Rodríguez en la campaña al desierto de 1821; combate durante la guerra contra el Brasil y en Oncativo y La Tablada."],["Larrazábal","calle","Mariano de Larrazábal (1789 a 1822), coronel; combate durante las Invasiones Inglesas, Chacabuco, Talcahuano, Cancha Rayada, Maipú y en la campaña al Perú, donde muere en 1822."],["Larrea","calle","Publicado en la Memoria de la Municipalidad de la Ciudad de Buenos Aires correspondiente a los años 1856 y 1857, Buenos Aires, Imprenta del Orden, San Martín 5 y Buen Orden 155, 1858. Juan Larrea (1782 a 1847), comerciante; vocal de la Primera Junta; diputado por Córdoba en la Asamblea de 1813."],["Elena Larroque de Roffo","calle","Elena Larroque de Roffo (1883 a 1924), benefactora y científica; colabora con su esposo, el doctor Ángel H. Roffo, en sus estudios sobre el cáncer; autora de El diagnóstico de los tumores malignos; fundadora de la Liga Argentina contra el Cáncer y promotora del Instituto del Cáncer."],["Elena Larroque de Roffo","plazoleta","Elena Larroque de Roffo (1883 a 1924), benefactora y científica; colabora con su esposo, el doctor Ángel H. Roffo, en sus estudios sobre el cáncer; autora de El diagnóstico de los tumores malignos; fundadora de la Liga Argentina contra el Cáncer y promotora del Instituto del Cáncer."],["Larsen","calle","Juan Mariano Larsen (1821 a 1894), educador y filólogo de origen francés; fundador de La Revista del Plata y El Investigador; estudioso de las lenguas aborígenes americanas; presidente de la Sociedad Geográfica Argentina; autor de América Precolombina, o sea noticias sobre algunas interesantes ruinas y sobre los viajes en América anteriores a Colón y Etnología Americana. Primeros pobladores de América."],["Teniente de Navío Cándido de Bm N° 7.633. Lasala","plazoleta","Cándido Francisco José de Lasala (1770 a 1807), marino; combate durante las Invasiones Inglesas y fallece el 5 de julio de 1807 en la Defensa de Buenos Aires. Es éste un nombre tradicional de la ciudad, pues entre 1808 y 1822 se denominaron “Lasala” las actuales Chacabuco y Maipú."],["San Juan Bautista de la Salle","calle","Juan Bautista de La Salle (1652 a 1719), sacerdote francés; fundador de la Congregación de Hermanos de las Escuelas Cristianas dedicada a la enseñanza."],["Lascano","calle","Benito Lascano (1778 a 1836), sacerdote; cura rector de la Catedral de Córdoba en 1810; rector de la Universidad de Córdoba; diputado en el Congreso de Tucumán cuando se traslada a Buenos Aires; vicario apostólico de Córdoba en 1830 y Obispo titular de la misma en 1836."],["Las Casas","calle","Bartolomé de Las Casas (¿1484?-1566), sacerdote dominico español; notable defensor de los derechos de los indios durante la época de la conquista; autor de Brevísima relación de la destrucción de las Indias."],["Las Flores","calle","Las Flores: ciudad y partido de la provincia de Buenos Aires."],["General Juan Gregorio de las Heras","parque","Juan Gualberto Gregorio de Las Heras (1780 a 1866), militar; combate durante las Invasiones Inglesas, en Cucha-Cucha y Membrillar; comanda la Primera División del Ejército de los Andes en el cruce de la Cordillera combatiendo en Potrerillo y Guardia Vieja; combate en Chacabuco, Curapaligüe, Gavilán, Cancha Rayada y Maipú; jefe del Estado Mayor del Ejército Expedicionario al Perú; gobernador de Buenos Aires de 1824 a 1826."],["Almirante Augusto Lasserre","calle","Augusto Lasserre (1826 a 1906), marino; combate en la escuadra de Coe que sitia Buenos Aires en 1853; comanda en 1884 la División Expedicionaria al Atlántico Sur; jefe de la Segunda División Naval."],["Lastra","avenida","Domingo Lastra (1795 a 1839), hacendado; es uno de los jefes del movimiento revolucionario de los Libres del Sur; muere en la batalla de Chascomús."],["Latinoamérica","plazoleta","Latinoamérica: homenaje a las naciones de América cuya colonización fue realizada por países latinos, especialmente España y Portugal."],["Unidad Latinoamericana","plaza","Unidad Latinoamericana: homenaje a los lazos que unen a todos los pueblos latinoamericanos."],["Laureles Argentinos","calle","Laureles Argentinos: nombre de un club fundado por los vecinos de Villa del Parque en 1947 y que se transforma en el centro de reunión del barrio. Al establecerse su sede en este pasaje que carecía de denominación, la costumbre popular le asignó el nombre del club, circunstancia ésta que, a pedido de los vecinos, se oficializó por parte de la Municipalidad."],["Pedro Laurenz","plazoleta","Pedro Blanco Acosta (1902 a 1972), músico, bandoneonista; compositor de Risa Loca, Como dos extraños, Vieja amiga. Es conocido por su seudónimo de Pedro Laurenz."],["Lausana","calle","Lausana: ciudad de Suiza, capital del estado de Vaud."],["Lautaro","calle","Logia Lautaro: organización formada en Buenos Aires poco después de la llegada de San Martín en 1812 cuyo principal objetivo era luchar por la emancipación americana."],["Lavadero","calle","Lavadero: nombre tradicional que alude a los lavaderos que en el plano mencionado de 1866 aparecen sobre esta arteria y que se encontraban dedicados con seguridad al lavado de lanas, actividad ésta que era tradicional en la zona de Barracas."],["General Lavalle","plaza","Juan Galo de Lavalle (1797 a 1841), militar; combate en Chacabuco, Cancha Rayada, Maipú, Pisco, Nazca, Cangallo, Jauja, Pasco, Riobamba y durante la guerra contra el Brasil; gobernador de Buenos Aires de 1828 a 1829; comanda la expedición que pretende derrocar a Rosas siendo vencido en Quebracho Herrado y Famaillá."],["Lavalleja","calle","Juan Antonio Lavalleja (1784 a 1853), brigadier general uruguayo; organizador y jefe de la expedición de los Treinta y Tres Orientales; combate durante la guerra contra el Brasil; miembro del Triunvirato que sucede al presidente Giró en 1853."],["Lavardén","calle","Manuel José de Lavardén (1754-¿1809?), poeta; autor de Siripo (tragedia), Oda al Río Paraná y Nuevo aspecto del comercio del Río de la Plata."],["Benjamín J. Lavaysse","calle","Benjamín J. Lavaysse (¿1823?-1854), sacerdote; diputado por Santiago del Estero en el Congreso General Constituyente de 1853."],["Lavoisier","calle","Antonio Laurent de Lavoisier (1743 a 1794), químico francés; es considerado uno de los creadores de la química moderna; enuncia la ley de conservación de la materia; formula la ley de la termodinámica; descubridor del oxígeno, establece que el aire es una mezcla de este gas con el nitrógeno."],["El Lazo","calle","Lazo: uno de los elementos más indispensables del recado del gaucho, cuya utilidad es fundamental en el manejo de las haciendas."],["De la Lealtad","cantero central","De la Lealtad: homenaje al 17 de octubre de 1945, cuando se escribe una importante página de la participación política y del ascenso social de los sectores populares argentinos; ese día una concentración popular consigue la liberación del coronel Juan Domingo Perón y con la palabra “lealtad” se alude a la fidelidad popular del pueblo hacia quien luego sería presidente de la República."],["Moisés Lebensohn","calle","Moisés Lebensohn (1907 a 1953), periodista y político; fundador del movimiento de Intransigencia y Renovación de la Unión Cívica Radical en 1943; preside la Comisión Nacional en 1952."],["Tomás A. Le Breton","calle","Tomás Alberto Le Breton (1868 a 1959), jurisconsulto y diplomático; diputado nacional de 1914 a 1920; embajador en los Estados Unidos de 1919 a 1922; senador nacional en 1922; ministro de Agricultura de 1922 a 1925; miembro de la Corte Permanente de Arbitraje de La Haya en 1938; embajador en Gran Bretaña de 1938 a 1941."],["Doctor Honorio Leguizamón","calle","Honorio Leguizamón (1848 a 1921), médico y periodista; escribe en El Pueblo Argentino, la revista América y en La Prensa; rector del Colegio Nacional de Concepción del Uruguay de 1880 a 1886; director de la Escuela de Profesores de Buenos Aires de 1889 a 1893; concejal por la parroquia de la Piedad en 1901."],["Martiniano Leguizamón","calle","Martiniano Leguizamón (1858 a 1935), escritor e historiador; autor de Montaraz, Calandria, Recursos de la tierra, Alma nativa y El supuesto retrato de Garay; colabora en la Crónica y La Razón; director del Boletín Oficial y jefe del Registro Civil de la capital."],["Doctor Onésimo N° 3.681-2. Leguizamón","plaza","Onésimo Leguizamón (1839 a 1886), jurisconsulto; redactor en jefe del diario La Prensa de 1872 a 1873; ministro de Justicia, Culto e Instrucción Pública de Avellaneda; presidente del Primer Congreso Pedagógico Americano en 1882; presidente de la Suprema Corte de Justicia de 1877 a 1882; fundador del diario La Razón en 1886; propicia y defiende la Ley N° 1.420 de Educación Común."],["Leipzig","calle","Leipzig: ciudad de Alemania, célebre por su universidad."],["Leiva","calle","Manuel Leiva (1794 a 1879), funcionario y periodista; diputado por Santa Fe en el Congreso de 1853 y vicepresidente primero del mismo; senador por la misma provincia en el Congreso de la Confederación Argentina en 1854; presidente del senado nacional de 1859 a 1860."],["Mario Jorge de Lellis","espacio público","Mario Jorge de Lellis (1922 a 1967), poeta; escribe varios libros de poemas; entre sus obras figuran Flores del silencio, Litoral de la angustia y Ciudad sin tregua."],["Doctor Luis Federico Leloir","espacio verde","Luis Federico Leloir (1906 a 1987), bioquímico de origen francés; se destaca por sus estudios de enzimología y, en particular, sobre las función de las glándulas suprarrenales; director del Instituto de Investigaciones Bioquímicas de la Fundación Campomar y del Departamento de Bioquímica de la Universidad de Buenos Aires; recibe el Premio Nobel de Química en 1970 por su contribución al estudio de la acción de las enzimas."],["General Juan Gregorio Lemos","calle","Juan Gregorio Lemos (1764 a 1822), militar; administrador de la Aduana de Mendoza desde 1812, colabora con San Martín solventando los gastos del Ejército de los Andes; intendente de ese Ejército desde 1818."],["Bernardo de León","calle","Bernardo de León (?-1638), funcionario; regidor del Cabildo; durante el gobierno de Diego de Góngora se desempeña como Depositario y Procurador General de la Ciudad; fue también Mayordomo de Propios, Alférez Real y en 1635 Fiel Ejecutor."],["Leones","calle","Combate de la Cañada de los Leones: combate librado en octubre de 1857 entre los indios del cacique Coliqueo y las fuerzas del coronel Emilio Mitre."],["Leopardi","calle","Jacobo Leopardi (1798 a 1837), poeta italiano; autor de A Italia, Sobre el Monumento de Dante, El pájaro solitario y A Silvia."],["Alfredo Le Pera","plazoleta","Alfredo Le Pera (1904 a 1935), periodista y comediógrafo; colaborador literario de Carlos Gardel; fallece en Medellín en el accidente de avión en el cual Carlos Gardel también pierde la vida el 24 de junio de 1935; autor de Golondrinas, Volver, Cuesta abajo, Arrabal amargo."],["Lerma","calle","Hernando de Lerma (1550 a 1598), conquistador español; gobernador del Tucumán de 1580 a 1584; fundador de Salta en 1582."],["Letonia","calle","República de Letonia: estado del norte de Europa. Capital: Riga."],["Teniente General Nicolás Levalle","calle","Nicolás Levalle (1840 a 1902), militar; combate en Cepeda, Pavón, en la guerra contra el Paraguay y en diversas campañas contra el aborigen; participa en 1879 en la campaña al Río Negro comandada por Roca; ministro de Guerra y Marina en 1886, 1887, de 1890 a 1892 y en 1897."],["Doctor Ricardo Levene","calle","Ricardo Levene (1885 a 1959), historiador y profesor universitario; presidente de la Academia Nacional de la Historia; director del Archivo de la Provincia de Buenos Aires; director y colaborador de la Historia de la Nación Argentina publicada por la Academia Nacional de la Historia y de la Historia de la Provincia de Buenos Aires y formación de sus pueblos; autor de Investigación acerca de la historia económica del Virreinato e Historia del Derecho Argentino."],["Doctor Roberto Levillier","calle","Roberto Levillier (1886 a 1969), historiador y diplomático; autor de Historia Argentina, Nueva crónica de la conquista del Tucumán y Don Francisco de Toledo, supremo organizador del Perú; embajador en México de 1935 a 1937 y en el Uruguay de 1938 a 1941."],["Lezama","parque","José Gregorio Lezama (1802 a 1889), comerciante y filántropo; dueño de las tierras donde se construye este parque. Máximo Gregorio Lezama y Álzaga (1851 a 1878), hijo del anterior. Doña Ángela Álzaga de Lezama vende a la Municipalidad las tierras donde se encuentra este parque en una módica suma con la condición de que el parque llevase el nombre de su marido y de su hijo. (Enrique Álzaga, “Historia del parque Lezama”. En La Nación, 8-11-1987, 4ta. sección, p. 6.)."],["Lezica","calle","Juan Antonio Lezica (1812 a 1874), coronel; combate en Yeruá, Don Cristóbal, Sauce Grande, Quebracho Herrado, Caseros, Pavón y en la guerra contra el Paraguay."],["República del Líbano","calle","Líbano: país del Asia Menor. Capital: Beirut."],["Libertad","calle y plaza","Libertad: homenaje a la libertad del hombre en general y en modo particular a nuestra libertad política."],["Del Libertador","avenida","Libertador General José de San Martín: homenaje al General San Martín, Libertador de la Argentina, Chile y Perú."],["Antonio Vespucio Liberti","calle","Antonio Vespucio Liberti (?-1976), dirigente deportivo; presidente del Club River Plate de 1933 a 1939, 1943 a 1952 y 1960 a 1967; durante su mandato se inaugura en 1938 el estadio que hoy lleva su nombre."],["Tomás Liberti","calle","Tomás Liberti (1836 a 1904), industrial y benefactor de origen italiano; llega a nuestro país en 1875 y se establece en el barrio de La Boca; instala en San Fernando la primera fábrica de aguas gaseosas, la que se transforma más tarde en La Destiladora del Norte; promotor de la Sociedad de Bomberos Voluntarios de la Boca."],["Libres","calle","Paso de los Libres: ciudad y departamento de la provincia de Corrientes. Cabe señalar aquí que existe otra calle de la ciudad que con el nombre de Paso de los Libres recuerda a esta localidad correntina."],["Libres del Sud","plaza","Libres del Sur: fuerzas del sur de la provincia de Buenos Aires que en 1839 se sublevan contra el gobierno de don Juan Manuel de Rosas. Son derrotadas en la batalla de Chascomús el 7 de noviembre de ese mismo año."],["Doctor Félix Liceaga","Patio de recreación","Félix Juan Cruz Liceaga (1887 a 1963), médico pediatra; preside el Consejo Escolar XI y en 1929 es designado por el presidente Yrigoyen vocal del Consejo Nacional de Educación, del cual es vicepresidente; diputado nacional desde 1946 a 1950."],["Lillo","avenida","Miguel Ignacio Lillo (1862 a 1931), naturalista; jefe de la Oficina Química Municipal de Tucumán de 1892 a 1931; profesor de la Universidad de Tucumán; director honorario del Museo de Historia Natural de esa provincia; autor de Flora Tucumana, Apuntes sobre la fauna de la provincia de Tucumán, Aves de la fauna tucumana y Descripción de la plantas nuevas pertenecientes a la flora argentina."],["Lima","calle","Lima: ciudad capital del Perú."],["Doctor Vicente Solano Lima","plaza","Vicente Solano Lima (1901 a 1994), abogado y político; comisionado Municipal de San Nicolás (1931); vicepresidente de la Nación en 1973."],["Félix Lima","plaza","Félix Lima (1880 a 1943), escritor y periodista; autor de Con los nueve y Pedrín; redactor de El siglo, El País, El Diario, Caras y Caretas y Fray Mocho."],["Río Limay","calle","Limay: afluente del Río Negro, que nace en el Nahuel Huapi y que sirve de límite entre las provincias de Río Negro y Neuquén."],["Lincoln","avenida","Proyecto del Trazado de Calles de Villa Devoto aprobado por Resolución del 13-4-1889. (Archivo Histórico Municipal, Carpeta N° 6.478-1889). Abraham Lincoln (1809 a 1865), político norteamericano; presidente de los Estados Unidos de 1860 a 1865, cuando es asesinado por un sudista."],["Liniers","barrio","Este nombre proviene de la estación del ferrocarril, que fue denominada así el 18 de diciembre de 1872."],["Virrey Liniers","calle","Santiago de Liniers y Bremond (1753 a 1810), militar y marino; virrey del Río de la Plata de 1807 a 1809; héroe de la Reconquista y Defensa de Buenos Aires durante las Invasiones Inglesas."],["Linneo","calle","Carl von Linné (1707 a 1778), naturalista sueco; autor de Systema naturae, donde establece las bases de la taxonomía natural botánica en función de los órganos sexuales de las plantas y desarrolla la nomenclatura binaria; autor de Fundamenta Botánica."],["Dante A. Linyera","plazoleta","Dante A. Linyera: seudónimo del poeta y periodista Francisco Bautista Rímoli (1902 a 1938); autor de Seamos hermanos, Boedo, Mi amigo en el otro barrio, As de bastos, Sueño de amor y Pajarito; escribe en Crítica y Noticias Gráficas; director de la revista La canción moderna."],["Lisboa","calle","Lisboa: ciudad capital de Portugal y del distrito de su nombre."],["Coronel Ramón Lista","calle","Ramón Lista (1789 a 1855), militar; combate en Chacabuco, Curapaligüe, Gavilán, Talcahuano y en las campañas al Perú, en los inicios de la guerra contra el Brasil y en Caseros."],["El Litoral","calle","Litoral: se denomina así a la región de nuestro país que se encuentra sobre los ríos Paraná y Uruguay y que comprende a las provincias de Buenos Aires, Corrientes, Entre Ríos, Misiones, Santa Fe, Chaco y Formosa."],["Lituania","calle","Lituania: república del norte de Europa. Capital: Vilna."],["Liverpool","calle","Liverpool: ciudad y puerto del Reino Unido de Gran Bretaña."],["Ricardo Llanes","cantero central","Ricardo Llanes (1897 a 1980) seudónimo de Martín Llanes; escritor, periodista e historiador de la ciudad de Buenos Aires; autor de Recuerdos de Buenos Aires, El barrio de Flores, El barrio de Almagro, El barrio de San Cristóbal, El barrio de Parque de los Patricios, Teatros de Buenos Aires y Dos notas porteñas, Avenida de Mayo e Historia de la calle Florida."],["Llavallol","calle","Felipe Llavallol (1802 a 1874), comerciante y político; gobernador interino de Buenos Aires en 1856; primer presidente de la Bolsa de Comercio en 1855; gobernador provisorio de Buenos Aires de 1859 a 1862; presidente del Banco de la Provincia de Buenos Aires en 1864."],["Poeta Ricardo E. Lleras","espacio verde","Ricardo Enrique Lleras (1913 a 1969), poeta, escritor, periodista y crítico de arte; autor de las obras de teatro Novios por mensualidades; Médico para enamorados y El hombre que dijo ¡no!; sus poesías están compiladas en el libro titulado Final."],["Llerena","calle","Juan Llerena (1825 a 1900), jurisconsulto; diputado por San Luis en el Congreso de 1853; miembro fundador del Banco Nacional; autor de Fisiografía y meteorología de los mares del globo y Una excursión en el pasado geológico y arqueológico de San Luis."],["Llorente","calle","Antonio Llorente (1828 a 1872), coronel; combate en 1852 en la Defensa de Buenos Aires durante el sitio de Hilario Lagos, en Pavón y en Cañada de Gómez."],["Lobería","calle","Lobería: partido de la provincia de Buenos Aires."],["Lobos","calle","Lobos: ciudad y partido de la provincia de Buenos Aires."],["Doctor Eleodoro Lobos","calle","Eleodoro Lobos (1862 a 1923), jurisconsulto y periodista; director del diario La Prensa; ministro de Hacienda de Figueroa Alcorta y de Agricultura de Roque Sáenz Peña; decano de la Facultad de Ciencias Económicas; autor del proyecto de organización del Departamento de Inmigración en 1899."],["Logroño","calle","Logroño: ciudad y provincia de España."],["Lomas de Zamora","calle","Lomas de Zamora: ciudad y partido de la provincia de Buenos Aires."],["Francisco Lomuto","plazoleta","Francisco Lomuto (1893 a 1950), pianista, compositor; autor de Muñequita, Sombras nada más, Nunca más."],["Teniente General Eduardo Lonardi","plaza","Eduardo Lonardi (1896 a 1956), militar; dirige la revolución del 16 de septiembre de 1955 en Córdoba; presidente provisional de la República en ese año."],["Londres","calle","Londres: ciudad capital del Reino Unido de Gran Bretaña."],["Brigadier Estanislao López","plazoleta","Estanislao López (1786 a 1838), militar, gobernador de Santa Fe desde 1818; en agosto de 1819 establece para su provincia el primer estatuto constitucional sancionado en nuestro país; firma los tratados del Pilar, del Cuadrilátero y el Pacto Federal de 1831, antecedentes fundamentales de la organización nacional."],["Cándido López","calle","Cándido López (1840 a 1902), pintor; autor de El mendigo y Retrato del general Mitre; participa en la guerra contra el Paraguay donde pierde el brazo derecho; se dedica a pintar escenas de esa guerra tras educar a su mano izquierda para la pintura. Nacen así los óleos Batalla de boquerón, Ataque de la primera columna brasileña a Curupaytí y Ataque de la tercera columna argentina a Curupaytí, entre otros."],["Carlos Antonio López","calle","Carlos Antonio López (1792 a 1862), político paraguayo; presidente de la República desde 1844 hasta 1862; durante su gestión el Paraguay se convierte en potencia de primer orden del escenario americano."],["Juan Pablo López","calle","Juan Pablo López (1792 a 1886), teniente general; gobernador de Santa Fe desde 1838 hasta 1842 y de 1856 a 1859; combate en Caseros, Cepeda y Pavón."],["Mariscal Francisco Solano López","calle","Francisco Solano López (1826 a 1870), militar y estadista paraguayo; mediador en la guerra civil argentina entre Buenos Aires y la Confederación en 1859, participa en las negociaciones que culminan en el Pacto de San José de Flores; presidente del Paraguay desde 1862, conduce a su pueblo durante la guerra de la Triple Alianza, donde muere al frente de sus hombres en la última batalla de la guerra en Cerro Corá el 1° de marzo de 1870."],["Vicente López y Planes","plaza","Capital de la República Argentina, levantado por el Departamento Topográfico de la Municipalidad, año 1895. Confirmada por Decreto N° 11.585-1956, BM N° 10.457. Vicente López y Planes (1784 a 1856), jurisconsulto y poeta; diputado por Buenos Aires en la Asamblea de 1813; autor de las estrofas del Himno Nacional Argentino; presidente provisional en 1827; gobernador de Buenos Aires en 1852."],["Vicente Fidel López","calle","Vicente Fidel López (1815 a 1903), jurisconsulto e historiador; ministro de Instrucción Pública en 1852; ministro de Hacienda de Carlos Pellegrini; rector de la Universidad de Buenos Aires en 1873; autor de Historia de la República Argentina, Crónica de la Revolución de Mayo y Autobiografía; dirige la publicación de los Acuerdos del Extinguido Cabildo de Buenos Aires (1569 a 1643)."],["Pedro López Anaut","calle","Pedro López Anaut (1876 a 1934), médico y político; se desempeña en los hospitales Durand y Ramos Mejía; Comisionado Municipal de 1917 a 1918, diputado nacional de 1920 a 1924 por la Unión Cívica Radical."],["Carlos López Buchardo","calle","Carlos López Buchardo (1881 a 1948), músico; miembro fundador y director del Conservatorio Nacional de Música y Arte Escénico; director fundador de la Escuela Superior de Bellas Artes de la Universidad de La Plata; autor de Vidala, Canción del carretero, Cinco canciones argentinas, Campera y Gauchos."],["Francisco López Merino","calle","Francisco López Merino (1904 a 1928), poeta; autor de Canciones interiores y otros poemas, Tono menor y Las Tardes."],["Francisco López Torres","plazoleta","Francisco López Torres (1839 a 1871), periodista, escritor y político; autor de La Huérfana de Pago Largo, La Virgen de Lourdes y Dayla; combate en la guerra contra el Paraguay, ministro de Gobierno de la provincia de Mendoza de 1867 a 1870; fundador y director de La Discusión de Buenos Aires; víctima de la epidemia de fiebre amarilla."],["Félix Lora","calle","Félix Lora (1863 a 1940), rematador de origen italiano; dona importantes sumas de dinero a la Municipalidad para distintas obras y especialmente para la construcción de un asilo o albergue nocturno para ancianos que lleva su nombre en Paseo Colón y Humberto I."],["Lorea","plaza","Manifestación de los nombres con que vulgarmente se conocen las calles y plazas de esta ciudad, y su correspondencia con los que le son propios desde su traza y con los que se les ponen nuevamente, alusivos a las gloriosas acciones de su Reconquista y Defensa, conseguidos contra las armas británicas, la primera el 12 de agosto de 1806 y la segunda el 7 de julio de 1807. Buenos Ayres 30 de junio de 1808. Dispuesto de orden del Excmo. Sr. Virrey, por el Sargento Mayor de Brigada del Real Cuerpo de Ingenieros del Exército, y Edecán de S.E. D. Mauricio Rodríguez de Berlanga. Impreso en Buenos Ayres en la Real Imprenta de Niños Expósitos."],["Isidro Lorea","calle","Isidro Lorea (?-1807), constructor tallista e industrial; dueño de dos manzanas de tierra entre las actuales Rivadavia, Hipólito Yrigoyen, San José y Virrey Cevallos, instala en ellas en 1783 una plaza de carretas; ejecuta en 1785 el Altar Mayor de la Catedral; muere como consecuencia de las heridas recibidas durante la Defensa de Buenos Aires ante las Invasiones Inglesas en 1807."],["Carola Lorenzini","calle","Carolina Elena Lorenzini (1899 a 1941), aviadora y deportista; es la primera instructora de vuelo en América del Sur; establece el récord femenino de altura en 1935, y es pionera en cruzar sola el Río de la Plata; la llamaban “la aviadora gaucha”; en 1925 es campeona de atletismo; practica natación, tenis, hockey, pelota paleta y remo; incursiona en el motociclismo y es una excelente domadora de potros; en 1941 recibe la patente que la habilita para los vuelos en servicio público; fallece realizando una maniobra acrobática en Morón."],["Virrey Loreto","calle","Nicolás Francisco Cristóbal del Campo, Marqués de Loreto (¿1740?- 1803), militar y funcionario español; virrey del Río de la Plata desde 1784 hasta 1789. LOS ANDES véase ANDES, LOS."],["Combate de los Pozos","calle","Los Pozos: combate librado por la escuadra argentina comandada por el almirante Brown frente al puerto de Buenos Aires el 11 de junio de 1826, durante la guerra contra el Brasil."],["Loyola","calle","Martín García Oñez de Loyola (1548 a 1598), militar español; gobernador de Chile, ordena al general Luis Jufré de Loaysa y Meneses la fundación de la ciudad de San Luis en 1594."],["Pedro Lozano","calle","Pedro Lozano (1697 a 1752), sacerdote e historiador; autor de Historia de la Conquista de la Provincia del Paraguay, Río de la Plata y Tucumán, Diccionario Histórico Índico e Historia de las Revoluciones del Paraguay."],["Esteban de Luca","calle","Esteban José Mariano de Luca y Patrón (1786 a 1824), poeta y militar; combate durante las Invasiones Inglesas, director de la Fábrica de Fusiles de Buenos Aires en 1815 y de la Fábrica de Armas del estado en 1816; autor de Marcha Patriótica, A la victoria de Chacabuco, A la muerte del general Belgrano y A la libertad de Lima."],["Lucero","calle","José Cecilio Lucio Lucero (1791 a 1867), coronel; combate en Chacabuco, Curapaligüe, Gavilán, Cancha Rayada, Maipú, en la campaña al Perú, Junín, Ayacucho y La Tablada."],["Luchter","calle","Edición 1931-1932. Rodolfo Luchter (¿-?), vecino que dona los terrenos por donde se traza esta calle."],["Villa Lugano","barrio","Este barrio se denomina así desde 1908 cuando José Soldati funda la villa que con ese nombre recuerda a su ciudad natal. Lugano: ciudad de Suiza, vecina a Italia."],["Lugo","calle","Lugo: ciudad y provincia de España."],["Lugones","calle","Lorenzo Lugones (1796 a 1868), coronel; combate en Las Piedras, Tucumán, Salta, Vilcapugio, Puesto del Marqués, Venta y Media, Sipe-Sipe, La Tablada y Ciudadela; autor de Recuerdos históricos sobre las campañas del Ejército Auxiliador del Perú en la guerra de la Independencia, en esclarecimiento de las Memorias Póstumas del brigadier general don José María Paz."],["Leopoldo Lugones","calle","Leopoldo Lugones (1874 a 1938), poeta, escritor y ensayista; autor de Lunario sentimental, Romances del Río Seco y La guerra gaucha; fundador y primer presidente de la Sociedad Argentina de Escritores."],["Mayor Arturo Pedro Luisoni","calle","Arturo Pedro Luisoni (1871 a 1935), militar; oficial superior del Ejército Argentino, es el autor de la iniciativa de dotar al Ejército de la llamada “cuarta arma”; inventor del primer proyectil aéreo nacional, al que denomina “aerobala”; secretario honorario de la Comisión Central Recolectora de Fondos Pro Flotilla Aeromilitar Argentina."],["Luján","calle","Pedro Luján (?-1536), conquistador español; sobrino de don Pedro de Mendoza, participa en 1536 en la primera fundación de Buenos Aires; muere en el combate de Corpus Christi el 15 de junio del mismo año. Cabe señalar que si bien la Versión Taquigráfica de la sesión del Concejo Deliberante N° 73 del 4 de agosto de 1939, en que se sanciona esta ordenanza, menciona a Luján con el nombre de Diego, se trata de un error por cuanto el único individuo de este apellido que viajó con Mendoza fue Pedro (véase Enrique Udaondo, Diccionario Biográfico Colonial Argentino, Buenos Aires, Huarpes, 1945).17."],["Nuestra Señora de Luján","plazoleta","Nuestra Señora de Luján: advocación de la Virgen María, declarada Patrona de la República Argentina, Paraguay y Uruguay en 1887, y cuya catedral, ubicada en la provincia de Buenos Aires, es uno de los más importantes centros de peregrinación de la República."],["Luna","calle","Fernando de Mendoza de Mate de Luna (¿-?), funcionario español gobernador de Tucumán desde 1681 hasta 1686; funda la ciudad de Catamarca el 5 de julio de 1683."],["Pelagio B. Luna","plazoleta","Pelagio Baltasar Luna (1867 a 1919), jurisconsulto; fundador y director del diario El Independiente; vicepresidente de la República de 1916 a 1919, integra la fórmula junto con Hipólito Yrigoyen."],["Luna de Enfrente","espacio verde","Luna de Enfrente: libro de Jorge Luis Borges, publicado en 1925."],["Abraham J. Luppi","calle","Abraham J. Luppi (1867 a 1910), industrial; vecino del barrio de Nueva Pompeya, se interesa por su adelanto y mejoramiento; fundador de la Sociedad de Socorros Mutuos y de la primera escuela con que contó el barrio."],["Villa Luro","barrio","Pedro Luro (1820 a 1890), hacendado de origen vasco francés; coopera en la fundación de Mar del Plata, dueño de la Sociedad Pedro Luro e Hijos, que posee tierras en esta zona de Buenos Aires donde en 1911 se inaugura la estación ferroviaria que recibe el nombre de Villa Luro en su homenaje."],["Luxemburgo","calle","Luxemburgo: estado europeo. Capital: Luxemburgo."],["Mariscal Toribio de Luzuriaga","plazoleta","Toribio de Luzuriaga (1782 a 1842), militar peruano; combate durante las Invasiones Inglesas; gobernador de Corrientes en 1812; gobernador intendente y comandante general de Cuyo de 1816 a 1820; presidente del departamento de Huaylás, Perú."],["Lynch","calle","Francisco Lynch (1795 a 1840), coronel de marina; combate durante el sitio de Montevideo; actúa en el Ejército Auxiliar del Perú; combate durante la guerra contra el Brasil."],["Marta Lynch","calle","Marta Lynch (1925 a 1985), escritora; autora de las novelas La alfombra roja, Al vencedor, El cruce del Río, Un árbol de manzanas, Cuentos tristes y Cuentos multicolores."],["Félix Lynch Arribálzaga","calle","Félix Lynch Arribálzaga (1854 a 1894), naturalista; miembro de la Academia Argentina de Ciencias y Letras; autor de Dicteriología Argentina. Notas."],["Antonio Machado","calle","Antonio Machado y Ruiz (1875 a 1939), poeta español; autor de Soledades, Campos de Castilla y La Guerra; en 1927 es elegido miembro de la Real Academia de la Lengua Española; escribe con su hermano Manuel obras de teatro poético, como La Lola se va a los puertos."],["Machain","calle","José Ildefonso de Machain (1778 a 1849), militar paraguayo; acompaña a Belgrano en su campaña al Paraguay."],["Francisco Antonio Maciel","calle","Francisco Antonio Maciel (1757 a 1807), comerciante y militar uruguayo; muere heroicamente en Montevideo durante la Segunda Invasión Inglesa."],["Madariaga","calle","Juan Madariaga (1809 a 1879), general; combate en Caseros; encabeza junto con el general Pirán la revolución que el 11 de septiembre de 1852 separa a Buenos Aires de la Confederación Argentina. Joaquín Madariaga (1799 a 1848), general, hermano del anterior; combate en Caaguazú; gobernador de Corrientes de 1843 a 1847."],["Doctor Juan Madera","calle","Juan de Dios Madera (1782 a 1829), médico; cirujano primero de la Expedición Auxiliadora del Perú, participa en Cotagaita, Suipacha y Huaqui; médico del Regimiento de Granaderos a Caballo en 1813 y de la Casa de Niños Expósitos."],["Francisco Maderna","calle","Francisco Maderna (?-1807), militar; teniente del Tercio de Montañeses, muere durante las Invasiones Inglesas. Es éste un nombre tradicional de la ciudad, ya que entre 1808 y 1822 se denominaron “Maderna” las actuales Montevideo y Virrey Cevallos."],["Osmar Maderna","cantero central","Osmar Héctor Maderna (1918 a 1951), pianista y director; compositor de Concierto de la Luna, Rapsodia de tango y Lluvia de estrellas."],["Madero","calle","Francisco Bernabé Madero (1816 a 1896), hacendado y político; participa en la Revolución del Sud en 1839; combate en Don Cristóbal, Sauce Grande, El Tala y Quebracho Herrado; fundador del pueblo de Maipú; vicepresidente de la Nación de 1880 a 1886, acompañando al presidente general Julio A. Roca."],["Eduardo Madero","avenida","Eduardo Madero (1833 a 1894), empresario; concibe la realización del puerto de Buenos Aires desde 1861, concretándose su proyecto en la década del ochenta, cuando preside y dirige los trabajos del mismo hasta la construcción del dique Nº 3; autor de Historia del puerto de Buenos Aires. MADERO, PUERTO véase PUERTO MADERO."],["De las Madres","plazoleta","Madres: homenaje a las madres argentinas."],["La Madreselva","calle","Madreselva: arbusto sarmentoso caprifoliáceo de hojas ovaladas y flores olorosas. MADRE TERESA DE CALCUTA véase TERESA DE CALCUTA, MADRE."],["Madrid","calle","Madrid: ciudad capital de España y de la provincia de su nombre."],["De los Maestros","jardín","Maestros: homenaje a los maestros de escuela primaria."],["Mafalda","plaza","Mafalda: personaje que da nombre a la historieta creada por Joaquín Lavado (Quino) en 1964."],["Pedro Maffia","cantero central","Pedro Mario Maffia (1900 a 1967), bandoneonísta; titular de la Cátedra de bandoneón del Conservatorio Municipal Manuel de Falla; compositor de La mariposa, Amurado y Sentencia."],["Juan Maffioli","plazoleta","Luis Juan Maffioli (?-1932), músico y pintor; violinista del Teatro Colón; escenógrafo del desaparecido Teatro Sarmiento."],["Agustín Magaldi","calle","Agustín Magaldi (1903 a 1938), cantor y compositor de tango; conocido como “la voz sentimental del tango”, es el autor de Delirios, Sonia, Vagabundo, Allá en el bajo y La que nunca tuvo novio, escritas la mayoría en colaboración con Pedro Noda, con quien actuó en un renombrado dúo."],["Agustín Magaldi","plazoleta","Agustín Magaldi (1903 a 1938), cantor y compositor de tango; conocido como “la voz sentimental del tango”, es el autor de Delirios, Sonia, Vagabundo, Allá en el bajo y La que nunca tuvo novio, escritas la mayoría en colaboración con Pedro Noda, con quien actuó en un renombrado dúo."],["Magallanes","calle","Fernando de Magallanes (1480 a 1521), navegante y descubridor; descubre el estrecho que lleva su nombre en la célebre expedición que, concluida por Juan Sebastián Elcano, da por primera vez la vuelta al mundo."],["Alejandro Magariños Cervantes","calle","Alejandro Magariños Cervantes (1825 a 1893), jurisconsulto, poeta y periodista uruguayo; ministro de Relaciones Exteriores y de Hacienda del presidente Lorenzo Battle en 1868 y 1869; rector de la Universidad de Montevideo en 1878; autor de Estudios históricos, políticos y sociales sobre el Río de la Plata, Horas de melancolía, Carmurú, Violetas y ortigas y Palmas y ombúes."],["Magdalena","calle","Magdalena: ciudad y partido de la provincia de Buenos Aires."],["Juez Magnaud","calle","Pablo Magnaud (1848 a 1926), jurisconsulto y magistrado francés; presidente del tribunal de Chateau-Thierry, se lo conocía como “el Buen Juez”; autor de la Ley del perdón y El delito necesario."],["Maimónides","plazoleta","Moshe Ben Maimón, conocido como Maimónides (1135 a 1204), médico, filósofo humanista y educador judío-español; considerado el rabino más importante de la Edad Media, y junto a Tomás de Aquino y Dante las inteligencias más destacadas de su época; autor de La guía de los descarriados y Abalatal-Hairin, explicación filosófica del judaísmo."],["Maipú","calle","Maipú: batalla librada en Chile entre el ejército argentino-chileno al mando del general José de San Martín y el realista al mando de Osorio, el 5 de abril de 1818, que asegura la independencia de Chile."],["Maitén","calle","Maitén: Arroyo que nace en la Cordillera de los Andes, en la provincia de Río Negro, y desemboca en la margen derecha del Río Chubut."],["Azucena Maizani","calle peatonal","Azucena Josefa Maizani (1900 a 1969), cantante de tango, llamada cariñosamente “La ñata Gaucha”; compositora de La canción de Buenos Aires y Pero yo sé."],["Malabia","calle","José Severo Feliciano Malabia (1787 a 1849), jurisconsulto; diputado por Charcas en el Congreso de Tucumán y presidente del mismo en 1818."],["Málaga","calle","Málaga: provincia de España en la región de Andalucía."],["Carlos Malagarriga","plazoleta","Carlos Malagarriga (1858 a 1936), periodista y jurisconsulto español; reside durante cincuenta años en la Argentina; autor de Código Penal Anotado, Instituciones Penales Argentinas y Procedimiento Criminal Argentino."],["Malasia","calle","Malasia: estado del SE. asiático. Capital: Kuala Lumpur."],["Antonio Malaver","plaza","Antonio E. Malaver (1835 a 1897), jurisconsulto; ministro de Gobierno de Emilio Castro en la provincia de Buenos Aires de 1869 a 1872, habilita el cementerio de la Chacarita y proyecta la Ley Orgánica Municipal; procurador general de la Nación de 1890 a 1892."],["Maldonado","calle","Maldonado: arroyo que cruza la ciudad de Buenos Aires de oeste a este siguiendo la dirección de la actual avenida Juan B. Justo y que se encuentra entubado bajo la misma."],["Martín A. Malharro","calle","Martín A. Malharro (1865 a 1911), pintor; dibujante de La Nación en 1894; autor de los óleos El corsario de La Argentina, Las parvas, El arado, En plena naturaleza y Paisaje y del libro El dibujo en la escuela primaria."],["Combatientes de Malvinas","calle","Combatientes de Malvinas: homenaje a los que defendieron la soberanía Argentina en el Atlántico Sur en 1982."],["De las Malvinas","paseo","De las Malvinas: homenaje a los caídos en la Guerra del Atlántico Sur en 1982."],["Islas Malvinas","plaza","Islas Malvinas: archipiélago situado en el océano Atlántico al este del estrecho de Magallanes. Ocupado por Gran Bretaña desde 1833, pertenecen por derecho a la República Argentina."],["Managua","calle","Managua: ciudad capital de Nicaragua y del departamento de su nombre."],["Manco Cápac","calle","Manco Cápac I (¿-?), funda a mediados del siglo X la dinastía de los incas."],["Mandisobí","calle","Mandisoví: localidad del departamento de Federación, provincia de Entre Ríos. Su pueblo fue fundado por Belgrano el 16 de noviembre de 1810."],["Eduarda Mansilla","cantero central","Eduarda Mansilla de García (1838 a 1892), escritora y periodista; el nombre de su primer hijo, Daniel, le sirve para firmar su primera novela El médico de San Luis que aparece en 1860, y con igual firma publica Lucía Miranda, inspirada en un episodio de la conquista del Río de la Plata; con el seudónimo de Alvar publica gran número de crónicas entre 1871 y 1872 en El Plata Ilustrado de Buenos Aires; en 1881 se estrena su obra La marquesa de Altamira."],["General Lucio Norberto Mansilla","calle","Lucio Norberto Mansilla (1790 a 1871), militar; combate durante las Invasiones Inglesas; en Chacabuco y en Curapaligüe; gobernador de Entre Ríos de 1821 a 1824; diputado en el Congreso de 1824; combate en la guerra contra el Brasil; jefe de Policía de Buenos Aires de 1833 a 1835; jefe de las fuerzas patriotas en el combate de la Vuelta de Obligado."],["Lucio V. Mansilla","cantero central","Lucio Victorio Mansilla (1831 a 1913), militar, periodista, político y escritor; autor de Una excursión a los indios ranqueles, Entre Nos y Canseries de los jueves."],["Juana Manso","calle","Juana Paula Manso de Noronha (1819 a 1875), maestra y escritora; autora de Los misterios del Plata y Compendio de la historia de las Provincias Unidas del Río de la Plata (1862), que fue el primer libro didáctico de historia argentina; dirige los Anales de la Educación Común."],["Manzanares","calle","Juan Manzanares (¿-?), uno de los tres soldados que junto con Gregorio Jaramillo y José Santos Frías salvan a Lamadrid en Culpina en enero de 1816; por esa acción los tres fueron ascendidos a sargento."],["Homero Manzi","calle","Homero Manzi: seudónimo de Homero Manzioni (1907 a 1951), poeta; autor de Malena, Milonga sentimental, Barrio de tango, Che bandoneón, Sur, Milonga del 900, y Definiciones para esperar mi muerte; elabora con Ulyses Petit de Murat los guiones de las películas La guerra gaucha, Su mejor alumno y El viejo Hucha; presidente de SADAIC."],["Homero Manzi","plazoleta","Homero Manzi: seudónimo de Homero Manzioni (1907 a 1951), poeta; autor de Malena, Milonga sentimental, Barrio de tango, Che bandoneón, Sur, Milonga del 900, y Definiciones para esperar mi muerte; elabora con Ulyses Petit de Murat los guiones de las películas La guerra gaucha, Su mejor alumno y El viejo Hucha; presidente de SADAIC."],["Manzoni","calle","Alejandro Manzoni (1785 a 1873), escritor italiano; autor de Los novios, Carmañota y Los Adelchi."],["Maracaibo","calle","Maracaibo: ciudad de Venezuela ubicada sobre la costa del lago del mismo nombre."],["Doctor Esteban Laureano Maradona","plazoleta","Esteban Laureano Maradona (1895 a 1995), médico rural. En 1935 se radica en Formosa y se establece en Estanislao del Campo. Dedica su vida a atender y educar a las colectividades de matacos, mocovíes, tobas y pilagás. En 1948 funda una colonia indígena que bautiza con el nombre de Juan Bautista Alberdi. Con su tarea logra erradicar de ese rincón del país los flagelos de la lepra, el mal de Chagas, la tuberculosis y el cólera. Es autor de varios libros, la mayoría inéditos, sobre etnografía, lingüística, mitología indígena, zoología, botánica e historia. Es distinguido en varias oportunidades con premios nacionales e internacionales, entre ellos el de Médico Rural Iberoamericano, en 1981, y el Premio Estrella de la Medicina para la Paz de la Organización de las Naciones Unidas en 1987."],["Base Marambio","plazoleta","Base Marambio: base Aérea en el Continente Antártico establecida en 1969; debe su nombre al vicecomodoro Gustavo A. Marambio, desaparecido junto con la tripulación del avión Cruz del Sur el 19 de diciembre de 1951, en una misión en la zona del Mar Antártico."],["Arturo Marasso","plazoleta","Arturo Marasso (1890 a 1970), escritor y poeta; colabora en la revista Nosotros y en La Nación; autor de La canción olvidada, Bajo los astros, La rama intacta, Rubén Darío y su creación poética y Joaquín V. González."],["María Catalina Marchi","calle","María Catalina Marchi (1887 a 1973), educadora francesa; especializada en el Sistema Braille; periodista; funda la primera biblioteca para ciegos en Sud América y varios hogares para ciegos, entre ellos, el Vicente Castro Cambón."],["Mar del Plata","calle","Mar del Plata: ciudad de la provincia de Buenos Aires, cabecera del partido de General Pueyrredón."],["Mar Dulce","calle","Mar Dulce: nombre que Juan Díaz de Solís le da al Río de la Plata en 1516, por se este curso de agua “tan espaciosa y no salada”."],["La Marea","calle","Marea: movimiento periódico y alternativo de ascenso y descenso de las aguas del mar."],["Leopoldo Marechal","calle","Leopoldo Marechal (1900 a 1970), poeta, narrador, dramaturgo y ensayista; autor de Adán Buenosayres; El banquete de Severo Arcángelo, Megafón o la Guerra y Días como flechas."],["Eleodoro Marenco","plazoleta","Eleodoro Ergasto Marenco (1914 a 1996), pintor, escultor y dibujante; sus obras reflejan la vida y costumbres del hombre del campo argentino a través de su historia. Ilustrador de las ediciones de Equitación gaucha en la Pampa y Mesopotamia, Fausto y Martín Fierro."],["José Mármol","calle","José Mármol (1817 a 1871), poeta; autor de Cantos del peregrino, Amalia y Armonías."],["Marsella","calle","Marsella: ciudad de Francia."],["José Martí","calle","José Martí (1853 a 1895), poeta cubano; héroe de la independencia cubana; autor de Amor con amor se paga y Asala (teatro) y El presidio político en Cuba, Ismaelillo y versos libres, Amistad funesta y Versos sencillos."],["José Martí","plaza","José Martí (1853 a 1895), poeta cubano; héroe de la independencia cubana; autor de Amor con amor se paga y Asala (teatro) y El presidio político en Cuba, Ismaelillo y versos libres, Amistad funesta y Versos sencillos."],["Brigadier General Don Enrique Martínez","plazoleta","Enrique Martínez (1789 a 1870), general uruguayo; combate durante las Invasiones Inglesas, en Guardia Vieja, Chacabuco, Curapaligüe, Gavilán, Talcahuano, Maipú y en la expedición al Perú; ministro de Guerra del gobernador Balcarce en 1833."],["Juan Esteban Martínez","calle","Juan Esteban Martínez (1846 a 1909), jurisconsulto; vicegobernador de Corrientes en 1877, presidente del Superior Tribunal de Justicia en 1886; senador nacional en 1891; gobernador de Corrientes en 1897 y 1905."],["Mateo J. Martínez","calle","Mateo J. Martínez (1813 a 1872), coronel; combate en Don Cristóbal, Sauce Grande, Quebracho Herrado, Cepeda, Pavón y en la guerra contra el Paraguay; actúa durante la epidemia de fiebre amarilla en 1871."],["Plácido Martínez","calle","Plácido Martínez (1844 a 1879), coronel; combate en la guerra contra el Paraguay; jefe del batallón de Guardias Nacionales Goya durante la rebelión de López Jordán; redactor del periódico La Patria, de Goya, Corrientes."],["Regís Martínez","cantero central","Regís Martínez (1809 a 1862), político; representante por la provincia de La Rioja al Congreso General Constituyente en 1853; senador de 1854 a 1857."],["Víctor Martínez","calle","Víctor Martínez (1823 a 1901), jurisconsulto; diputado a la Legislatura de Buenos Aires en 1852, 1855 y 1863; senador en 1868 y presidente de la Cámara en 1871 y 1872; director del Banco de la Provincia de Buenos Aires; presidente de la Caja de Conversión de 1891 a 1892."],["Martínez Castro","calle","Marcelino Martínez Castro (1807 a 1886), hacendado; participa en la revolución de los Libres del Sud en 1839; autor de Memoria de los Acontecimientos de 1839."],["Martínez de Hoz","calle","Miguel Florencio Martínez de Hoz (1832 a 1868), coronel; actúa en las fronteras de Buenos Aires en la lucha contra el aborigen; combate en la guerra contra el Paraguay donde muere en acción."],["Ezequiel Martínez Estrada","cantero central","Ezequiel Martínez Estrada (1895 a 1964), poeta, narrador, dramaturgo y ensayista; primer premio Municipal de Poesía en 1927; autor de Radiografía de la Pampa, La cabeza de Goliat y Microscopía de Buenos Aires."],["Martínez Rosas","calle","Juan Martínez de Rosas (1758 a 1886), jurisconsulto y funcionario; trabaja en Chile por la emancipación desde 1810; segundo vocal de la Primera Junta de Gobierno el 18 de septiembre; redactor del Despertador Americano; presidente de la Junta Regional de Gobierno de Concepción en 1811, domina el sur chileno."],["Doctor Gustavo Martínez Zuviría","calle","Gustavo Martínez Zuviría (1883 a 1962), jurisconsulto y escritor con el seudónimo de Hugo Wast; autor de Alegre, Flor de durazno, Valle negro, Desierto de piedra, Lucía Miranda, Fuente sellada y La casa de los cuervos; interventor nacional en Catamarca en 1941; ministro de Justicia e Instrucción Pública de la Nación de 1943 a 1944; director de la Biblioteca Nacional."],["Martín Fierro","calle","Martín Fierro: poema gauchesco de José Hernández cuya primera parte aparece en 1872; en 1879 aparece la segunda con el título de La vuelta de Martín Fierro."],["Martín Fierro","plaza","Martín Fierro: poema gauchesco de José Hernández cuya primera parte aparece en 1872; en 1879 aparece la segunda con el título de La vuelta de Martín Fierro."],["Martín Pescador","calle","Martín Pescador: nombre vulgar que se aplica a varias especies de aves del orden de los corachoformes y de la familia Alcedinidae. MÁRTIRES PALOTINOS véase PALOTINOS, MÁRTIRES."],["Herminio N° 20.212. Masantonio","plazoleta","Herminio Masantonio (1916 a 1956), deportista; se destaca como futbolista del Club Atlético Huracán y fue uno de los centrodelanteros más notables de nuestro fútbol."],["Villa de Masnou","calle","Masnou: municipio y villa de España, en la provincia de Barcelona. Se otorga este nombre en carácter recíproco ya que esta villa catalana posee sendas calles con los nombres de Buenos Aires y República Argentina."],["Mason","calle","Guillermo Roberto Mason (1790 a 1843), comandante de marina y sargento mayor de infantería, de origen norteamericano; comandante de la fragata Heroína en 1821; combate en la guerra contra el Brasil al frente de las naves Congreso Nacional e Ituzaingó."],["Padre Lorenzo Massa","canteros centrales","Lorenzo Massa (1882 a 1949), sacerdote salesiano de vasta labor en la Patagonia, donde estudia el origen y las necesidades de los aborígenes; su dedicación a la elevación moral y física de la juventud lo lleva, desde su capilla San Antonio, a la fundación del Club San Lorenzo el 1º de abril de 1908."],["Ítalo Masuelli","plazoleta","Ítalo Masuelli (?-1984) dirigente sindical de Gas del Estado y posteriormente del Sindicato de Perfumistas y Afines; funda la Sociedad de Fomento del Barrio General San Martín, a través de la cual promueve actividades socioculturales reconocidas por el vecindario."],["Mataco","calle","Mataco: aborigen del Chaco."],["De los Nº 2.776. Mataderos","plaza","Mataderos: el barrio comienza a denominarse así desde 1889 cuando el 14 de abril se coloca la piedra fundamental de los nuevos mataderos que se inauguran en 1901. La plaza perpetúa también este nombre tradicional."],["Matanza","calle","La Matanza: partido de la provincia de Buenos Aires que limita con la Capital."],["Matheu","calle","Domingo Matheu (1765 a 1831), comerciante; combate durante las Invasiones Inglesas; vocal de la Primera Junta de Gobierno."],["Matheu","plaza","Domingo Matheu (1765 a 1831), comerciante; combate durante las Invasiones Inglesas; vocal de la Primera Junta de Gobierno."],["Leonie Mathis","cantero central","Leonie Mathis (1883 a 1952), artista plástica de origen francés; se destaca por su vasta obra de reconstrucción histórica, que permite recuperar escenas de la vida política y cultural de nuestro pasado; en el Museo Histórico de Buenos Aires Cornelio de Saavedra una sala permanente exhibe sus obras."],["Teniente Benjamín Matienzo","calle","Benjamín Matienzo (1891 a 1919), militar; fallece piloteando el aeroplano Newport el 28 de mayo de 1919 en la Cordillera de los Andes; es uno de los precursores de nuestra aviación."],["Matorras","calle","Gerónimo Matorras (1720 a 1775), comerciante, funcionario y militar; regidor del Cabildo de Buenos Aires en 1758; alférez real en 1760; gobernador del Tucumán de 1769 a 1770 y de 1772 a 1775, realiza en 1774 una expedición al Gran Chaco Gualumba."],["Gregoria Matorras de San Martín","calle","Gregoria Matorras de San Martín (1738 a 1813), patricia; madre del general José de San Martín."],["Gerardo Matos Rodríguez","cantero central","Gerardo Hernán Matos Rodríguez (1900 a 1948), músico uruguayo; pianista; compositor de La Cumparsita y Che papusa, oí."],["Giácomo Matteoti","calle","Giácomo Matteoti (1885 a 1924), político italiano; secretario del Partido Socialista, es secuestrado y asesinado por un grupo fascista."],["José de Maturana","calle","José de Maturana (1884 a 1917), poeta; autor de Cromos, Lucila, Poemas de color, A las doce, El balcón de la vida, Se alquila una pieza, La flor silvestre y Canción de primavera."],["Maturín","calle","Maturín: ciudad de Venezuela, capital del estado de Monagas."],["Maure","calle","José Antonio Maure (1796 a 1872), coronel; combate en Cucha-Cucha, Membrillar, Rancagua, Chacabuco, Cancha Rayada, Maipú, en la campaña libertadora del Perú, Mirabé, Zepita, Junín y Ayacucho."],["De Mayo","avenida","Desde 1884 comienza a conocérsela con su actual nombre. Mayo de 1810: homenaje a las jornadas que culminaron el 25 de ese mes con la instalación de la Primera Junta de Gobierno."],["De Mayo","plaza","Desde 1884 comienza a conocérsela con su actual nombre. Mayo de 1810: homenaje a las jornadas que culminaron el 25 de ese mes con la instalación de la Primera Junta de Gobierno."],["Maza","calle","Obras Públicas). Juan Agustín Maza (1784 a 1830), jurisconsulto; diputado por Mendoza en el Congreso de Tucumán; vicepresidente del mismo en diciembre de 1816 y presidente en noviembre de 1817."],["Doctor Salvador Mazza","plazoleta","Salvador Mazza (1886 a 1946), médico; en 1916, viaja a Europa para perfeccionarse en enfermedades infecciosas y conoce entonces a su colega brasileño Carlos Chagas, quien recientemente había descubierto el agente microbiano de la tripanosomiasis americana. En 1926 la Facultad de Medicina de la UBA establece la Misión de Estudios de Patología Regional Argentina, llamada coloquialmente misión Mazza ya que Mazza es su director. La MEPRA, con sede central en Jujuy, funciona en el famoso “E.600”, un laboratorio y hospital móvil instalado en un tren. Así puede trasladarse por la extensa red ferroviaria, llegando incluso a Bolivia y Chile. En ese mismo año realiza los primeros diagnósticos de tripanosomiasis americana y leishmaniasis tegumentaria americana en la Argentina. La labor principal de Mazza en este punto fue el ataque al vector de la tripanosomiasis americana, la vinchuca, y alerta a las autoridades sobre las precarias condiciones económicas, educativas e higiénicas de las poblaciones rurales y urbanas del norte argentino. En 1942 se contacta con el escocés Alexander Fleming con el objeto de organizar la producción de penicilina en la Argentina y un año después obtiene junto a su equipo la primera producción argentina del antibiótico."],["Mburucuyá","calle","Mburucuyá: planta trepadora que se encuentra principalmente en los montes de la Argentina, Brasil y Paraguay y en otros países cálidos del globo. Se la conoce también como “pasionaria” o “flor de la pasión”."],["Coronel Benito Meana","calle","Benito Meana (1844 a 1913), militar; combate en Pavón, Lomas Blancas, en la guerra contra el Paraguay y en la lucha contra el aborigen; participa en la campaña al Río Negro con Roca en 1879."],["Médanos","calle","Médanos: punta de la provincia de Buenos Aires sobre el Océano Atlántico, al sur del cabo San Antonio."],["Medeyros","calle","Juan Medeyros (1795 a 1886), teniente coronel; combate durante la guerra contra el Brasil y en la defensa de Buenos Aires durante el sitio de Hilario Lagos."],["De los Médicos","paseo","Médicos: homenaje a las figuras del quehacer médico asistencial que sobresalen por su relevante trayectoria en el campo de la medicina y sus valiosos conocimientos en el campo de las ciencias."],["Medina","calle","Eustaquio Medina (?-1836), coronel; combate en Suipacha, Las Piedras, Tucumán, Salta, Vilcapugio, Ayohuma, Sipe-Sipe y Castañares; gobernador de Jujuy en 1835 y 1836. Manuel Medina (1789 a 1820), coronel; combate durante las Invasiones Inglesas, en Chacabuco, Curapaligüe, Gavilán y Maipú. Nicolás Medina (1789 a 1829), coronel; combate en Chacabuco, Curapaligüe, Gavilán, Talcahuano, Maipú, en la campaña al Perú, Pasco, en la guerra contra el Brasil y en la lucha contra el aborigen, donde muere en la acción de Viscacheras."],["Medrano","calle","Legajo 3, 1882. Obras Públicas). Pedro Medrano (1769 a 1840), jurisconsulto; diputado por Buenos Aires en el Congreso de Tucumán, y primer presidente del mismo."],["Melgar","calle","Mariano Melgar (1791 a 1815), poeta peruano; autor de la oda Al autor del mar y de los célebres yaravíes; tomado prisionero en la batalla de Umachiri es fusilado al día siguiente por las tropas realistas."],["Melián","calle","José Antonio Melián (1784 a 1857), coronel; combate durante las Invasiones Inglesas, en la expedición de Belgrano al Paraguay, en la Banda Oriental, Chacabuco y Maipú."],["Melincué","calle","Melincué: localidad del departamento de General López, provincia de Santa Fe."],["Carlos F. Melo","calle","Carlos Francisco Melo (1873 a 1931), jurisconsulto y político; diputado nacional por la Unión Cívica Radical en 1916; director de la Biblioteca Nacional desde 1928; fundador y director del diario La Argentina; autor de Espumas, Piedras rotas y Las aguas de Mara."],["Virrey Melo","calle","Pedro Melo de Portugal y Villena (1733 a 1797), militar; virrey del Río de la Plata desde 1795 hasta 1797."],["Membrillar","calle","Membrillar: combate y victoria del ejército argentino-chileno al mando del coronel Las Heras y el general O´Higgins sobre los realistas comandados por el general Gainza, obtenida el 20 de marzo de 1814."],["De la Memoria","parque","De la Memoria: homenaje a los detenidos-desaparecidos y asesinados por el terrorismo de Estado durante los años 1970 e inicios de la década de 1980, hasta la recuperación del Estado de Derecho."],["Méndez","calle","Juan Antonio Méndez (¿-?), coronel; combate durante la guerra contra el Brasil, en Navarro, Don Cristóbal, Sauce Grande y Quebracho Herrado."],["Agustín Méndez","calle","Agustín Méndez (1841 a 1905), empresario; instala junto con sus hermanos Nicanor y Teófilo el segundo servicio de tranvías a caballo de Buenos Aires, inaugurado oficialmente el 27 de febrero de 1870 entre la calle 25 de Mayo y plaza Miserere; colabora activamente en la lucha contra la epidemia de fiebre amarilla."],["Nicanor Méndez","calle","Nicanor Méndez (1846-?), empresario; junto con sus hermanos Agustín y Teófilo funda en 1870 el segundo servicio de tranvías a caballo."],["Méndez de Andés","calle","Manuel Méndez de Andés (1846 a 1897), filántropo e industrial del tabaco, de origen español; miembro del Concejo Deliberante de Buenos Aires por la parroquia de San José de Flores; contribuye con importantes donaciones durante los terremotos de San Juan y La Rioja en 1894."],["Provincia de Mendoza","cantero central","Mendoza: ciudad y provincia de la República Argentina."],["Don Pedro de Mendoza","avenida","Pedro de Mendoza (1487 a 1537), conquistador español; adelantado del Río de la Plata y fundador de la primitiva Buenos Aires en 1536."],["Menéndez y Pelayo","calle","Marcelino Menéndez y Pelayo (1856 a 1912), polígrafo y catedrático español; director de la Biblioteca Nacional desde 1898; autor de Historia de las ideas estéticas de España, Antología de poetas hispanoamericanos y Orígenes de la novela."],["Doctor Emir Eduardo Mercader","cantero central","Emir Eduardo Mercader (1900 a 1964), médico, periodista y poeta; diputado nacional de 1940 a 1943, de 1948 a 1952 y de 1960 a 1962; director de la Clínica Antirreumática Privada que lleva su nombre; con el seudónimo de Pancho Talera escribe en Correo de la Tarde, Crítica, Esto es y La Lógica."],["Del Mercado Modelo","plazoleta","Mercado Modelo: nombre del antiguo mercado modelo que fue construido en 1884, siendo demolido en 1894 para dar paso a la Avenida de Mayo."],["Mercedes","calle","Mercedes: ciudad y partido de la provincia de Buenos Aires. MERCÉ “LA ARGENTINA”, ANTONIA (cantero central). Ordenanza N° 45.305- 1991, BM N° 19.182. Antonia Mercé (1890 a 1936), bailarina; intérprete de la danza hispana fue conocida como “la Argentina”; primera bailarina del Teatro Real de Madrid."],["La Mesopotamia","calle","Mesopotamia: región argentina ubicada entre los ríos Uruguay y Paraná que comprende las provincias de Corrientes, Entre Ríos y Misiones."],["Metán","calle","Metán: ciudad y departamento de la provincia de Salta."],["El Método","calle","El Método: obra del pedagogo suizo Juan Enrique Pestalozzi, aparecida en 1826."],["República de México","plaza","México: país americano. Capital: México."],["Rabino Marshall Meyer","espacio verde","Marshall T. Meyer (1930 a 1993), rabino de origen norteamericano; funda en 1962 el Seminario Rabínico Latinoamericano. En 1983 funda el Movimiento Judío por los Derechos Humanos y es miembro de la CONADEP (Comisión Nacional sobre la Desaparición de Personas). El documento final elaborado por esta comisión se llama Nunca más, nombre propuesto por el rabino Meyer en memoria del grito enarbolado durante el levantamiento del Ghetto de Varsovia. La Argentina le otorga la medalla de la Orden del Libertador General San Martín, máxima condecoración que se entrega a un extranjero."],["Padre Mario Luis Migone","calle","Mario Luis Migone (1863 a 1937), sacerdote uruguayo; director del Colegio Salesiano de Viedma; secretario de monseñor Cagliero; se desempeña en las Islas Malvinas desde 1905 hasta el día de su muerte; autor de 33 años de vida malvinera."],["Miguel Ángel","calle","Miguel Ángel Buonarotti (1475 a 1564), pintor, escultor y arquitecto italiano; autor de Baco ebrio, La Piedad, David, Moisés, Sagrada Familia, de la bóveda de la Capilla Sixtina y del Juicio Final en la pared del altar de la misma."],["Migueletes","calle","Migueletes: escuadrón de caballería que actuó durante las Invasiones Inglesas en 1806 y 1807."],["Milán","calle","Milán: ciudad y provincia de Italia."],["Antonio Millán","plazoleta","Antonio Millán (1753 a 1830), apoderado de don Ramón Francisco Flores y cofundador del pueblo de San José de Flores, hoy barrio homónimo."],["Capitán Domingo Alejo Millán","plazoleta","Domingo Alejo Millán (1797 a 1824), militar; combate en Salta, Vilcapugio, Ayohuma, Puesto del Marqués y Venta y Media, donde cae prisionero; asiste a la toma de Lima y participa en la campaña de Puertos Intermedios; vuelto a caer prisionero tras la sublevación del Callao en 1824, junto con Prudán, declaran haber sido ellos quienes encubren la fuga de Estomba y Luna, por lo que son fusilados."],["Miller","calle","Guillermo Miller (1795 a 1861), general de marina, de origen inglés; combate en Cancha Rayada, en la expedición al Callao de 1819 y en el bloqueo a su puerto, y en la toma de Pisco; organizador de la Legión Peruana de la Guarda; combate en Junín y Ayacucho; gobernador político y militar del Callao en 1837."],["Milton","calle","Juan Milton (1608 a 1674), poeta inglés; autor de El alegre, El pensativo y El paraíso perdido."],["Miñones","calle","Miñones: regimiento de infantería formado durante las Invasiones Inglesas."],["Miraflores","calle","Miraflores: pueblo de la provincia de Catamarca. En sus inmediaciones, el 18 de octubre de 1831 la vanguardia del general Aráoz de Lamadrid, al mando del mayor Juan José Guesi, vence a las fuerzas de Facundo Quiroga al mando de Juan de Dios Vargas."],["Miralla","calle","José Antonio Miralla (¿1789?-1825), poeta argentino precursor de la Independencia cubana; autor del soneto La pretensión por despedida y Breve descripción de las fiestas celebradas en la capital de los reyes del Perú, con motivo de las promoción del Excmo. Señor doctor don José Baquijano y Carrillo, Conde de Vista Florida al Supremo Consejo de Estado, con una regular colección de poesías relativas al mismo objeto."],["Miramar","calle","Miramar: ciudad de la provincia de Buenos Aires, cabecera del partido de General Alvarado."],["Miranda","calle","Francisco Miranda (1750 a 1816), militar y político venezolano; precursor de la independencia americana; diputado por el distrito de Pao en el Congreso de 1811 que declara la Independencia de Venezuela; vencido por los realistas es encarcelado en Cádiz, donde fallece el 14 de julio de 1816."],["El Mirasol","calle","Mirasol: ave acuática del orden de las zancudas que vive en bañados y lagunas del litoral."],["Miravé","calle","Miravé: pueblo del Perú en cuyos alrededores tuvo lugar el combate del mismo nombre del 22 de mayo de 1821 en el curso de la primera expedición de Puertos Intermedios dispuesta por San Martín. Las fuerzas patriotas estaban al mando de Miller."],["Miriñay","calle","Miriñay: río de la provincia de Corrientes que nace en los esteros de su nombre y desagua en el río Uruguay."],["Miró","calle","Cipriano Miró (1797 a 1890), teniente general; combate en Pasco, en la toma del Callao, Pichincha, en la expedición de Puertos Intermedios y en la guerra contra el Brasil."],["De la Bo N° 51. Misericordia","plaza","Nuestra Señora de la Misericordia: homenaje a la capilla y colegio que con este nombre desarrolla su labor en esta zona de Mataderos desde 1872."],["El Misionero","calle","El Misionero: poesía de Ricardo Gutiérrez que exalta la conquista espiritual de América."],["Provincia de Misiones","cantero central","Misiones: provincia de la República Argentina. Capital: Posadas."],["Gabriela Mistral","calle","Gabriela Mistral: seudónimo de la poetisa chilena Lucila Godoy Alcayaga (1889 a 1957); autora de Desolación, Tala, Oración de la maestra, Himno al árbol y Rondas para niños; Premio Nobel de Literatura en 1945."],["Villa General Mitre","barrio","Bartolomé Mitre: (1821 a 1906), militar, político e historiador; gobernador de Buenos Aires de 1860 a 1862; presidente de la República de 1862 a 1868; jefe del Ejército Aliado en la guerra contra el Paraguay; fundador del diario La Nación, autor de Historia de Belgrano y de la Independencia argentina e Historia de San Martín y la emancipación sudamericana."],["Emilio Mitre","calle","Emilio Mitre (1853 a 1909), ingeniero; proyecta y dirige la construcción del edificio del diario La Nación; director de este diario desde 1894."],["Teniente General Emilio Mitre","plaza","Emilio Mitre (1824 a 1893), militar; combate en Caseros, Sierra Chica, Cepeda, Pavón y en la guerra contra el Paraguay."],["Mocoretá","calle","Mocoretá: río de la provincia de Corrientes."],["Moctezuma","calle","Moctezuma II (1466 a 1520), noveno rey de México."],["Madre María Ana Mogas","sector parque","María Ana Mogas Fonticuberta (1827 a 1886), religiosa española; fundadora de la congregación de las Religiosas Franciscanas Misioneras; desarrolla una acción comunitaria relevante en el campo de la enseñanza y de la salud, comprometida con su fe y caridad cristiana."],["Francisco Alejandro N° 7.525. Mohr","cantero central","Alejandro Francisco Mohr (1870 a 1934), funcionario municipal; concejal de 1918 a 1922; sobre la base de su trabajo se inicia la construcción de los mercados municipales y del Mercado General de Ganados; miembro del directorio del Banco Municipal."],["Moldes","calle","José Moldes (1785 a 1824), coronel; teniente gobernador y subdelegado de la Real Hacienda de Mendoza de 1810 a 1811; combate en Tucumán; diputado por Salta y Jujuy en la Asamblea de 1813 y vicepresidente de la misma; diputado por Salta en el Congreso de Tucumán."],["De los Molfetteses","plazoleta","Molfetteses: homenaje a los inmigrantes italianos originarios de Molfetta, provincia de Bari, en Apulia, distrito de Barletta. MOLIÈRE (calle). Ordenanza del 27-11-1893. Molière: seudónimo de Juan Bautista Poquelín (1622 a 1673), dramaturgo francés; autor de El enfermo imaginario, El misántropo, El avaro y El burgués gentilhombre."],["Molina","calle","José Agustín Molina (1773 a 1838), sacerdote; prosecretario del Congreso de Tucumán; colabora con fray Cayetano Rodríguez en El Redactor; obispo de Camaco en 1836. Mardoqueo Molina (1829 a 1883), político, gobernador de Catamarca de 1876 a 1879. Samuel Molina (1812 a 1880), político, hermano del anterior; gobernador de Catamarca de 1859 a 1862."],["Carlos Molina Arrotea","calle","Carlos Molina Arrotea (1851 a 1908), jurisconsulto; miembro fundador de la Sociedad Estímulo Literario y de la revista Nueva Generación; presidente de la Cámara de Apelaciones en lo Civil; autor de Elocuencia y Sentencias y autos interlocutorios."],["Florencio Molina Campos","paseo peatonal","Florencio Molina Campos (1891 a 1959), artista plástico; refleja en sus obras temas del campo argentino y de la vida de gauchos y paisanos; cultiva el terreno de la pintura, el dibujo, la ilustración y la caricatura; en 1941 es contratado por Walt Disney como supervisor de películas de dibujo animado; como caricaturista llega a su consagración popular con los famosos almanaques de Alpargatas, que aparecieron desde 1931 hasta 1934 y de 1940 a 1945."],["Doctor Luciano Florencio Molinas","paseo","Luciano Florencio Molinas (1888 a 1973), jurisconsulto; gobernador por Santa Fe desde 1932 hasta 1936; sucesor de Lisandro de la Torre en el partido Demócrata Progresista."],["Mom","calle","Pedro Mom (1785 a 1869), capitán de marina de origen belga; combate en 1811 en San Nicolás donde cae prisionero; comandante de la sumaca Gálvez en 1815 y del falucho San Martín, con el que participa en la expedición de Viamonte a Santa Fe; establece con su goleta Mosca un servicio regular entre Buenos Aires y Montevideo."],["Policarpo Mom","calle","Policarpo Mom (1830 a 1923), funcionario; administrador del diario La Prensa de Belgrano en 1874; presidente de la Biblioteca Popular de Belgrano; juez de Paz y presidente de la Municipalidad de ese partido entre 1869 y 1873."],["Mompox","calle","Fernando de Mompox y Zayas (¿-?), jurisconsulto y funcionario; participa en la revolución comunera de Asunción en el período 1725-1735."],["Mónaco","calle","Mónaco: principado independiente de Europa."],["Monasterio","calle","Ángel Monasterio (1777 a 1817), coronel; inspector de las Escuelas Militares en 1811; instala en Buenos Aires en 1812 una fábrica de cañones en la iglesia de la Residencia; maestre general del Ejército Auxiliar del Perú en 1814."],["Ricardo Monner Sans","calle","Ricardo Monner Sans (1853 a 1927), educador, escritor y filólogo; autor de Oraciones, rimas y cantares, Pinceladas históricas, Minucias lexicográficas, Notas al castellano en la Argentina, Disparates usuales en la conversación diaria, Asnología, Perrología y Gatología."],["Monroe","calle","Jaime Monroe (1751 a 1831), político estadounidense; presidente de los Estados Unidos de Norteamérica de 1817 a 1825, es conocido por la doctrina política que lleva su nombre y que se resume en la frase “América para los americanos”."],["Fernando de Montalvo","calle","Fernando de Montalvo (1530 a 1604), funcionario; aboga en 1579 por la repoblación de Buenos Aires; actúa en ésta durante la administración de Torres de Navarrete."],["Montañeses","calle","Montañeses: denominado también Cántabros, es un regimiento formado por don José de Oyuela luego de la Reconquista de Buenos Aires en 1806."],["Monte","calle","Monte: ciudad y partido de la provincia de Buenos Aires."],["Monteagudo","calle","José Bernardo Monteagudo (1789 a 1825), doctor en teología y periodista; interviene en la insurrección de Chuquisaca y La Paz en 1809; director de La Gazeta en 1811; director del Grito del Sud; diputado por Mendoza en la Asamblea de 1813 y redactor de la misma; auditor de guerra del Ejército de los Andes; ministro de Gobierno y Relaciones Exteriores del Perú en 1822."],["Monte Ararat","plazoleta","Monte Ararat: región y monte de Armenia donde, según el relato bíblico, se detiene el Arca de Noé después del diluvio universal, conformando la cuna de la nueva humanidad."],["Bo Nº 2.776. Monte Castro","plaza","Monte Castro: debido a la fisonomía arbolada que tenía el lugar se lo conoce desde 1703, cuando adquiere estas tierras don Pedro Fernández de Castro, como chacra de Castro o montes de Castro."],["Monte Dinero","calle","Monte Dinero: cerro de la provincia de Santa Cruz, en el límite argentinochileno."],["Montenegro","calle","Nicanor Montenegro (?-1831), militar; es fusilado en San Nicolás de los Arroyos el 28 de octubre de 1831, luego de la batalla de Ciudadela y de la capitulación del gobernador Mariano Fragueiro ante el general López."],["Victoriano E. Montes","calle","Victoriano E. Montes (1855 a 1917), educador; fundador y primer director de la Escuela Mixta de Dolores (provincia de Buenos Aires); director de la Escuela Normal de Profesores de la Capital Federal; autor de La Frase, Parónimos de la lengua castellana y La tejedora de Ñandutí."],["Padre Montes Carballo","calle","Vicente Montes Carballo (1766-?), sacerdote; párroco de la Villa de Luján desde 1797, secunda a Pueyrredón durante las Invasiones Inglesas; obtiene en 1808 el beneficio del Evangelio en la Catedral de Buenos Aires; apoya a Saavedra en el Cabildo Abierto del 22 de mayo de 1810."],["Manuel A. Montes de Oca","avenida","Manuel Augusto Montes de Oca (1831 a 1882), médico; catedrático titular de anatomía y fisiología en 1858; miembro fundador de la Asociación Médica Bonaerense; diputado nacional de 1862 a 1866; actúa durante la guerra contra el Paraguay y la epidemia de fiebre amarilla de 1871; ministro de Relaciones Exteriores de Avellaneda en 1878."],["Montesquieu","calle","Carlos Luis de Secondat, barón de Montesquieu (1689 a 1755), filósofo y escritor francés; autor de Espíritu de las leyes, Defensa del espíritu de la leyes, Cartas persas y Consideraciones sobre las causas de la grandeza de los romanos y su decadencia."],["Montevideo","calle","Montevideo: ciudad capital del Uruguay y del departamento de su nombre."],["Montiel","calle","Montiel: bosques de la provincia de Entre Ríos."],["Montreal","calle","Montreal: ciudad de Canadá."],["Montserrat","barrio","Nuestra Señora de Montserrat: patrona de Cataluña que se venera en el santuario y monasterio benedictino de su nombre, donde se encuentra la imagen titular de esta virgen llamada La Moreneta. Se identifica a este barrio con su nombre desde 1769 cuando se crea la parroquia de Nuestra Señora de Montserrat."],["Presidente Pedro Montt","avenida","Pedro Montt (1848 a 1910), político chileno; presidente de Chile desde 1906, visita nuestra ciudad en 1910 con motivo de las celebraciones del Centenario de la Revolución de Mayo."],["Lola Mora","plaza","Lola Mora: seudónimo de Dolores Mora de la Vega (1866 a 1936), escultora; autora de la Fuente de las Nereidas, los bajorrelieves de la Casa de Tucumán y del monumento a Nicolás Avellaneda en la ciudad del mismo nombre."],["Juan Mora Fernández","calle","Juan Mora Fernández (1784 a 1854), político costarricense, presidente de Costa Rica de 1824 a 1833. MORãES, VINICIUS DE (cantero central). Ley N° 644-2001, BO N° 1.303. Vinicius de Mello Morães (1913 a 1980), poeta brasileño; es uno de los protagonistas del movimiento de la Bossa Nova; comparte sus creaciones con los más destacados músicos de su tiempo; autor de Garota de Ipanema, Tarde em Itapuã, Regra treis, São demais os perigos dessa vida, entre otras composiciones. De su obra en prosa se destaca Para viver um grande amor."],["Pedro Morán","calle","Pedro Morán (¿1545?-1628), capitán; acompaña a Garay en la fundación de Buenos Aires en 1580."],["General Francisco Morazán","plazoleta","Francisco Morazán (1792 a 1842), general guatemalteco; paladín de la República Federal de las Provincias Unidas del Centro de América; jefe de Honduras de 1827 a 1828, de El Salvador en 1832 y de 1839 a 1840, y de Costa Rica en 1842; presidente de las Provincias Unidas en 1829 y de 1830 a 1840."],["Alicia Moreau de Justo","avenida","Alicia Moreau de Justo (1885 a 1986); médica; periodista y dirigente política; esposa del doctor Juan B. Justo; dirigió la revista Humanidad Nueva y el semanario socialista La Vanguardia desde 1956 hasta 1962; autora de La mujer en la democracia, El socialismo según la definición de Juan B. Justo y Qué es el socialismo en la Argentina."],["Carlos Morel","calle","Carlos Morel (1813 a 1894), pintor y litógrafo; autor de Mercado de carretas en la Plaza Montserrat, Payada en una pulpería, La calle larga de Barracas, Una hora antes de partir y del álbum Usos y costumbres del Río de la Plata."],["Morelos","calle","José María Morelos y Pavón (1765 a 1815), patriota y sacerdote mexicano; lucha por la independencia de su país junto con Hidalgo; creador del primer Congreso y capitán general, decreta el reparto de tierras entre los indígenas; hecho prisionero y fusilado en Tezmalaca el 5 de noviembre de 1815."],["Mariano Moreno","plaza","Mariano Moreno (1778 a 1811), jurisconsulto; secretario de la Primera Junta de Gobierno."],["Enrique B. Moreno","calle","Enrique B. Moreno (1846 a 1923), militar y diplomático; combate durante la guerra contra el Paraguay; jefe de la Policía de Buenos Aires en 1874; embajador argentino en Uruguay, Brasil, Italia, Suiza, Bélgica y Holanda."],["José María Moreno","avenida","José María Moreno (1835 a 1882), jurisconsulto; subsecretario de Guerra y Marina de 1865 a 1868; diputado nacional de 1872 a 1876; vicegobernador de Buenos Aires de 1878 a 1880 y gobernador de la misma en este último año."],["Perito Moreno","avenida-autopista","Francisco Pascasio Moreno (1852 a 1919), explorador, geógrafo y antropólogo; estudioso del sur patagónico; bautiza al lago Argentino y al volcán Fitz Roy; fundador de los Anales y de la Revista del Museo de La Plata; fundador y director de dicho Museo; donante y creador del Parque Nacional Nahuel Huapi."],["Moreto","calle","Agustín Moreto y Cavana (1618 a 1669), dramaturgo y sacerdote español; autor de El desdén con el desdén, El valiente justiciero y El lindo de don Diego."],["Morlote","calle","Lorenzo José Morlote (1786 a 1815), capitán; combate en el Ejército Auxiliar del Perú; muere en acción durante la batalla de Sipe-Sipe el 29 de noviembre de 1815."],["Morón","calle","Morón: ciudad y partido de la provincia de Buenos Aires."],["William C. Morris","calle","William C. Morris (1844 a 1932), educador de origen inglés; fundador de las Escuelas e Institutos Filantrópicos Argentinos y del Hogar El Alba."],["William C. Morris","plazoleta","William C. Morris (1844 a 1932), educador de origen inglés; fundador de las Escuelas e Institutos Filantrópicos Argentinos y del Hogar El Alba."],["Morse","calle","Samuel Finley Breese Morse (1791 a 1872), físico norteamericano; en 1843 establece el telégrafo entre Washington y Baltimore, inventando también el alfabeto que lleva su nombre."],["General Enrique Mosconi","plazoleta","Enrique C. A. Mosconi (1877 a 1940), general; director del Servicio Aeronáutico del Ejército; director general de Yacimientos Petrolíferos Fiscales de 1922 a 1930; autor de El petróleo argentino 1922-30 y la ruptura de los trusts petrolíferos inglés y norteamericano el 1° de agosto de 1929."],["Moscú","calle","Moscú: ciudad capital de Rusia."],["Martín de Moussy","calle","Víctor Martín de Moussy (1810 a 1869), naturalista francés; autor de Almanaque Nacional de la Confederación Argentina, Minerales de la provincia de La Rioja, Descripción geográfica y estadística de la Confederación Argentina y Memoria sobre la cordillera de los Andes y sus actuales caminos."],["Mozart","calle","Wolfgang Amadeo Mozart (1756 a 1791), músico austriaco; autor de Idomeneo, Las bodas de Fígaro, Don Juan, La flauta mágica y Réquiem."],["Padre Carlos N° 20.213. Mugica","parque","Carlos Francisco Sergio Mugica (1930 a 1974), sacerdote; a fines de 1954 comienza a colaborar pastoralmente con el padre Iriarte en las misiones a conventillos y casas de la parroquia Santa Rosa de Lima. Al enterarse del nacimiento del Movimiento de Sacerdotes por el Tercer Mundo, envía su adhesión incondicional e inicia su colaboración en el Equipo Intervillas, fundado el 2 de agosto de 1968 por el padre Jorge Goñi, también cura villero. Debido a su activa militancia social y política recibe varias amenazas de muerte y diversos ataques e intentos de asesinato. Finalmente, el 11 de mayo de 1974 es emboscado y asesinado en la puerta de la iglesia de San Francisco Solano en el barrio de Villa Luro, Buenos Aires, donde acababa de celebrar misa."],["Enrique Muiño","pasaje peatonal","Enrique Muiño (1881 a 1956), actor; uno de los más grandes protagonistas de la escena nacional que desarrolla un estilo de actuación porteño y personal en los ámbitos del teatro y del cine; se ha destacado en Así es la vida, La guerra gaucha y Su mejor alumno."],["Mujeres Argentinas","parque","Mujeres Argentinas: homenaje a las mujeres que se han destacado en todos los ámbitos en general."],["José Pío Mujica","calle","José Pío Mujica (?-1807), militar; capitán de artilleros urbanos, muere durante las Invasiones Inglesas. Es éste un nombre tradicional de Buenos Aires pues entre 1808 y 1822 se denominaron “Mujica” las actuales calles Paraná y Presidente Luis Sáenz Peña."],["Manuel Mujica Láinez","plaza","Manuel Mujica Láinez (1910 a 1984), novelista, cuentista, ensayista y poeta; sus obras: La casa, Canto de Buenos Aires, Misteriosa Buenos Aires, Bomarzo y El unicornio."],["Munich","calle","Munich: ciudad de Alemania, capital del estado de Baviera."],["Muñecas","calle","José Ildefonso de las Muñecas (¿1776?-1816), sacerdote; cura de la catedral de Cuzco, se destaca en la insurrección del Perú en 1809; caudillo de las Republiquetas, es derrotado en Achocalla y Humachiri, pero logra no obstante resistir hasta que es tomado prisionero y asesinado el 7 de mayo de 1816."],["Muñiz","calle","Francisco Javier Muñiz (1795 a 1871), médico y naturalista; descubre en Chascomús por primera vez en el mundo, los restos del gliptodonte Daypus Giganteus; actúa durante la guerra contra el Brasil al frente del cuerpo médico sanitario; inicia en Luján estudios de paleontología argentina descubriendo restos de numerosas especies; autor de Descripción y curación de la fiebre escarlatina; presidente de la Facultad de Medicina hasta 1862; participa en la guerra contra el Paraguay; víctima de la fiebre amarilla mientras lucha contra la epidemia en 1871."],["Francisco Mura","cantero central","Francisco Mura (1901 a 1972), atleta y preparador físico de origen italiano; figura destacada del atletismo; obtiene la medalla de oro en los Juegos Olímpicos de Londres en 1948; fue preparador físico del club San Lorenzo."],["Murature","calle","José Murature (1804 a 1880), coronel de marina de origen italiano; combate durante la guerra contra el Brasil al mando del cúter Luisa; interviene en la defensa de Buenos Aires durante el sitio de Hilario Lagos y es designado en 1853 jefe de la escuadra porteña; combate en la guerra contra el Paraguay comandando el Guardia Nacional."],["Murcia","calle","Murcia: región, provincia y ciudad del sudeste de España."],["Murguiondo","calle","Prudencio Murguiondo (1770 a 1826), coronel; combate durante las Invasiones Inglesas; teniente coronel del cuerpo de Cántabros de Montevideo, se subleva en 1810 en apoyo de la Revolución de Mayo y es detenido al fracasar la revuelta; combate en el sitio y rendición de Montevideo."],["Murillo","calle","Pedro Domingo Murillo (1756 a 1810), patriota boliviano; encabeza el levantamiento de La Paz en 1809; derrotado por Goyeneche en Irupana es ejecutado el 29 de enero de 1810."],["Mutualismo","calle","Mutualismo: sistema de solidaridad de servicios mutuos que se ha implantado en nuestro país en escuelas y asociaciones de carácter privado."],["Carolina Muzzili","calle","Carolina Muzzili (1889 a 1917), escritora, periodista y política socialista; inspectora del Departamento Nacional del Trabajo; preocupada por el trabajo de la mujer obtiene un premio por una monografía sobre el tema en la Exposición de Gante y otro en la Internacional de San Francisco en 1915. Notas."],["Naciones Unidas","calle","Organización de las Naciones Unidas: denominación del más alto organismo internacional creado cuando estaba por finalizar la Segunda Guerra Mundial como sucesor de la Sociedad de las Naciones. Su constitución definitiva tuvo lugar en la conferencia de San Francisco de California, que comenzó el 25 de abril de 1945. La Carta Mundial fue aprobada el 26 de junio de ese año."],["Naciones Unidas","plaza","Organización de las Naciones Unidas: denominación del más alto organismo internacional creado cuando estaba por finalizar la Segunda Guerra Mundial como sucesor de la Sociedad de las Naciones. Su constitución definitiva tuvo lugar en la conferencia de San Francisco de California, que comenzó el 25 de abril de 1945. La Carta Mundial fue aprobada el 26 de junio de ese año."],["Nahuel Huapi","calle","Nahuel Huapi: lago de las provincias de Neuquén y Río Negro."],["Namuncurá","calle","Manuel Namuncurá (1811 a 1908), cacique voroga; hijo de Juan Calfucurá; interviene en los conflictos políticos del país, y lucha por conservar el modo de vida tradicional de sus ancestros; se rinde ante las fuerzas nacionales el 21 de marzo de 1884 y es premiado por el gobierno otorgándosele los despachos de coronel."],["Ceferino Namuncurá","plazoleta","Ceferino Namuncurá (1886 a 1905), religioso; hijo del cacique Manuel Namuncurá, se dedicó al estudio eclesiástico muriendo en fama de santo en Roma el 11 de mayo de 1905. Es beatificado el 11 de noviembre de 2007."],["Doctor Rómulo S. Naón","avenida","Rómulo S. Naón (1876 a 1941), jurisconsulto y político; intendente municipal de la ciudad de Buenos Aires desde el 20 de febrero hasta el 19 de noviembre de 1932; ministro de Justicia e Instrucción Pública de Figueroa Alcorta en 1908."],["Juan José Naón","calle","Juan José Naón (1856 a 1920), médico; profesor de anatomía descriptiva desde 1888, impone la enseñanza práctica sobre el cadáver; participa del movimiento universitario de 1906, renunciando por ello a su cátedra."],["Nápoles","calle","Nápoles: ciudad y provincia de Italia."],["Natal","calle","Natal: ciudad de Brasil, capital del estado de Río Grande do Norte."],["Navarra","plazoleta","Navarra: región del Norte de España; capital: Pamplona."],["Navarro","calle","Julián Navarro (1777 a 1854), sacerdote; bendice el 27 de febrero de 1812, la primera bandera argentina que Belgrano enarbola a orillas del Paraná; participa en el combate de San Lorenzo; capellán del Ejército de los Andes; diputado al Congreso Nacional de Chile en 1828. Octaviano Navarro (1826 a 1884), general; gobernador de Catamarca de 1856 a 1859 y de 1873 a 1875; interventor nacional en Santiago del Estero en 1861 y de La Rioja en 1868."],["Miguel Navarro Viola","calle","Miguel Navarro Viola (1830 a 1890), jurisconsulto y político; se destaca por su prédica contra la guerra del Paraguay y publica El despotismo del estado de sitio de la República Argentina en 1866 y 1867; preside la Legislatura de Buenos Aires en 1874 y 1875; diputado nacional en 1882; fundador de los periódicos El padre Castañeda, El Plata científico y literario y La Unión; editor de la Revista de Buenos Aires; autor de Ocios juveniles y Atrás del Imperio."],["La Nave","calle","Nave: embarcación de cubierta y con velas, lo cual la distinguía de los barcos; se distinguía de las galeras por no tener remos."],["General Benito Nazar","plaza","Benito Nazar (1801 a 1886), militar; combate en la guerra contra el Brasil y en la defensa de Buenos Aires en 1852; ministro de Guerra de Llavallol en 1860; inspector y comandante general de Armas de la República de 1865 a 1874. Los terrenos donde se encuentra esta plaza eran de propiedad del general Nazar y fueron donados a la Municipalidad por su hija, María J. Nazar (La Razón, 21-6-1913, p. 3, col. 5)."],["Nazarre","calle","Alejo Nazarre (1760-?), funcionario; ministro contador interino de Mendoza en 1810, trabaja para lograr la colaboración de los indios en el movimiento emancipador; teniente gobernador de Mendoza en 1812 y 1813; participa en el Cabildo que elige gobernador a San Martín en 1815."],["Nazca","avenida","Nazca: combate librado el 15 de octubre de 1820 cerca de Nazca, Perú, donde las fuerzas patriotas mandadas por el Coronel Manuel Rojas vencen a las realistas."],["Necochea","calle","Mariano Necochea (1792 a 1849), general; combate en San Lorenzo, del Tejar, Venta y Media, Sipe-Sipe, Chacabuco, Talcahuano, Cancha Rayada y Maipú; gobernador de Lima en 1824; combate en Junín; director de la Casa de Moneda del Perú en tres oportunidades."],["José Neglia","cantero central","José Neglia (1929 a 1971), primer bailarín del Teatro Colón; muere trágicamente el 10 de octubre de 1971, al caer el avión en el que viajaba en la costa del Río de la Plata."],["Julio Jorge Nelson","plazoleta","Julio Jorge Nelson: seudónimo de Julio Isaac Rosofsky (1913 a 1976), periodista y comentarista de tangos; actúa en radio y televisión; director de la revista Yo te canto Buenos Aires, autor de Margarita Gauthier y Carriego."],["Profesor Ernesto Nelson","plazoleta","Ernesto Nelson (1873 a 1959), educador; inspector general de enseñanza secundaria, normal y especial; autor de Hacia la Universidad futura, La protección social a la salud del niño, El analfabetismo en la República Argentina y La delincuencia juvenil."],["El Nene","calle","El nene: libro de lectura publicado por el profesor Andrés Ferreyra que supera a la Cartilla de Marcos Sastre y con el que aprenden a leer varias generaciones de argentinos."],["Nepper","calle","Juan Neper (1550 a 1617), matemático inglés; inventor de los logaritmos llamados neperianos."],["De las Nereidas","plazoleta","Fuente de las Nereidas: obra realizada por la escultora argentina Lola Mora (1866 a 1936); en 1903 se inaugura oficialmente en el Paseo de Julio; en 1918 la fuente fue trasladada a su emplazamiento actual, en el Balneario Sur; declarado Sitio de Interés Cultural por Ordenanza N° 49.292-1995, Decreto N° 658."],["Pablo Neruda","cantero central","Pablo Neruda seudónimo de Neftalí Reyes (1904 a 1973), poeta chileno; Premio Nobel de Literatura en 1971; autor de Veinte poemas de amor y una canción desesperada; Canto general, Fin del mundo y del libro de memorias Confieso que he vivido."],["Padre Juan Bautista Neumann","calle","Juan Bautista Neumann (1659 a 1703), sacerdote jesuita de origen austriaco; construye en el siglo XVII la primera prensa tipográfica con la que contó el país en las Reducciones Jesuíticas de Misiones."],["Provincia de Neuquén","cantero central","Neuquén: provincia de la República Argentina. Capital: Neuquén."],["Nevada","calle","Nevada: sierra de la provincia de Chubut."],["Jorge Newbery","calle","Jorge Newbery (1875 a 1914), ingeniero; precursor de la aeronáutica argentina; director general de Alumbrado de la Municipalidad de Buenos Aires; miembro fundador del Aero Club Argentino en 1908 y presidente del mismo en 1909; director de la Escuela de Aviación Militar en 1812; fallece el 1° de marzo de 1914 en Los Tamarindos, Mendoza, en un accidente aéreo cuando se proponía cruzar la cordillera de los Andes."],["Jorge Newbery","parque y centro deportivo","Jorge Newbery (1875 a 1914), ingeniero; precursor de la aeronáutica argentina; director general de Alumbrado de la Municipalidad de Buenos Aires; miembro fundador del Aero Club Argentino en 1908 y presidente del mismo en 1909; director de la Escuela de Aviación Militar en 1812; fallece el 1° de marzo de 1914 en Los Tamarindos, Mendoza, en un accidente aéreo cuando se proponía cruzar la cordillera de los Andes."],["Newton","calle","Isaac Newton (1642 a 1727), físico y matemático inglés; descubre al mismo tiempo que Leibniz el cálculo diferencial e integral; establece la ley de gravitación universal."],["Nicaragua","calle","Nicaragua: república de América central. Capital: Managua."],["Nicaragua","plaza","Nicaragua: república de América central. Capital: Managua."],["Nuestra Señora de las Nieves","plaza","Nuestra Señora de las Nieves: advocación de la Virgen María considerada patrona de la Ciudad de Buenos Aires desde 1611."],["Nigeria","plazoleta","Nigeria: república africana. Capital: Lagos."],["La Niña","calle","La Niña: una de las tres carabelas que en agosto de 1492 partieron del puerto de Palos de Moguer y que el 12 de octubre de 1492 participa en el descubrimiento de América."],["Niza","calle","Niza: ciudad del sur de Francia, capital del departamento Alpes Marítimos."],["Doctor Alfredo Nobel","plaza","Alfredo Nobel (1833 a 1896), ingeniero químico e industrial sueco; descubridor de la dinamita; al morir establece con su fortuna los premios que llevan su nombre."],["Roberto Noble","plazoleta","Roberto Jorge Noble (1904 a 1969), jurisconsulto y político; legislador diplomático y periodista; funde y dirige el diario Clarín."],["Nogoyá","calle","Nogoyá: ciudad y departamento de la provincia de Entre Ríos."],["Noruega","calle","Noruega: país europeo. Capital: Oslo. NUESTRA SEÑORA DEL ROSARIO véase ROSARIO, NUESTRA SEÑORA DEL. NUEVA POMPEYA véase POMPEYA, NUEVA."],["Noruega","plaza","Noruega: país europeo. Capital: Oslo. NUESTRA SEÑORA DEL ROSARIO véase ROSARIO, NUESTRA SEÑORA DEL. NUEVA POMPEYA véase POMPEYA, NUEVA."],["Nueva York","calle","Nueva York: ciudad de los Estados Unidos de Norteamérica."],["Nueva Zelandia","calle","Nueva Zelandia: estado insular del Océano Pacífico, Oceanía. Capital: Wellington. 9 DE JULIO (avenida). Ordenanza N° 3.978 del 27-6-1930. 9 de Julio de 1816: fecha de la declaración de nuestra Independencia."],["Numancia","calle","Numancia: nombre de un regimiento de línea compuesto por colombianos y venezolanos que participa en la guerra de la independencia americana primero al servicio realista y que, desde 1820, cuando es sublevado por los capitanes Herrera y Tomás de Heres, se incorpora a las fuerzas patriotas. Llevaba este nombre en homenaje a la histórica ciudad española de Numancia, célebre por su heroica resistencia ante el cerco impuesto por las fuerzas romanas de Publio Escipión Emiliano, quien en el año 132 a.C. debió arrasar la ciudad para poder conquistarla."],["Núñez","barrio","Florencio Emeterio Núñez (1834 a 1900), funcionario; dueño de la empresa Núñez y Cía., funda el pueblo de Saavedra, hoy barrio del mismo nombre, el 27 de abril de 1873; el mismo día se inaugura, la estación ferroviaria que lleva su nombre por haber sido él el donante de los terrenos para la misma; desde entonces se identifica a este barrio con su apellido."],["Núñez","calle","Ignacio Núñez (1792 a 1846), funcionario y periodista; prosecretario del congreso de Tucumán; redactor del Argos de Buenos Aires, El Centinela y El Nacional; acompaña a Rivadavia a Londres en 1825 y en su carácter de secretario de la delegación firma el Tratado de Amistad, Comercio y Navegación y el consiguiente reconocimiento de la independencia argentina por parte de Inglaterra."],["Alvar Núñez","calle","Alvar Núñez Cabeza de Vaca (1507 a 1559), conquistador español, adelantado del Río de la Plata; llega a Asunción en 1542 y permanece hasta 1544 cuando un motín lo envía prisionero a España."],["Obrero Roberto Núñez","calle","Roberto Núñez (?-1951), obrero gráfico; se desempeñaba en el diario La Prensa y muere trágicamente el 27 de febrero de 1951 en un enfrentamiento político. Notas."],["El Ñandú","calle","Ñandú: voz guaraní que designa al ave corredora del orden de las reiformes llamada corrientemente avestruz americano."],["Ñandutí","calle","Ñandutí: voz guaraní que designa al tejido criollo que imita al de cierta telaraña; primitivamente fue trabajado por las mujeres del Paraguay y está generalizado hoy en toda América del Sur para toda clase de ropa blanca."],["Manuel Obarrio","calle","Manuel Obarrio (1836 a 1918), jurisconsulto; intendente municipal interino de la ciudad de Buenos Aires en 1906 y 1907; secretario general de la Convención del Estado de Buenos Aires que debía revisar la Constitución Nacional en 1860; profesor y decano de la Facultad de Derecho; presidente de la Comisión Municipal de Buenos Aires de 1901 a 1907; director del Banco Hipotecario Nacional."],["Pedro Miguel Obligado","plazoleta","Pedro Miguel Obligado (1892 a 1967), jurisconsulto y escritor; autor de Gris, El ala de sombra, El hilo de oro, La tristeza de Sancho, El canto perdido, La isla de los cantos y Melancolía."],["Rafael Obligado","avenida costanera","Rafael Obligado (1851 a 1920), poeta; autor de Santos Vega y de las leyendas El yaguarón, La luz mala y La Salamanca."],["Vuelta de Obligado","calle","Vuelta de Obligado: recodo que forma el río Paraná entre San Pedro y Ramallo, donde el 20 de noviembre de 1845 las fuerzas de la Confederación, al mando del general Lucio Norberto Mansilla se baten contra la escuadra anglo-francesa. El sitio fue declarado Lugar Histórico por Decreto N° 120.411 del 21 de mayo de 1942. O´BRIEN (calle). Ordenanza del 27-11-1893. Juan Thomomd O´Brien (1786 a 1861), general de origen irlandés; combate durante el sitio de Montevideo en 1813 y 1814, en Chacabuco, Cancha Rayada, Maipú, en la expedición al Perú y en la toma de Lima."],["Doctor Gabriel Ocampo","espacio público","Gabriel Ocampo (1798 a 1882), jurisconsulto; ministro de Gobierno de La Rioja en 1820; diputado por Colchagua y secretario del Congreso Constituyente de Chile que sanciona la Constitución de 1823; redactor del Código de Comercio de Chile en 1865."],["Victoria Ocampo","calle","Victoria Ocampo (1890 a 1979), escritora; fundadora y directora de la Revista Sur; autora de Testimonios."],["Oceanía","calle","Oceanía: uno de los cinco continentes en que se halla dividida la Tierra."],["Enrique Ochoa","calle","Enrique Ochoa de Zuazola (1803 a 1867), empresario y comerciante; construye con su peculio en 1859 el puente Alsina sobre el Riachuelo en el lugar conocido como Paso de Burgos. Ese puente fue el antecesor del actual, construido por el gobierno en 1910 y bautizado luego Teniente General José Félix Uriburu. 8 DE MARZO, DÍA INTERNACIONAL DE LA MUJER (espacio verde). Ley N° 565-2001, BO N° 1.186. 8 de Marzo Día Internacional de la Mujer: el Día Internacional de la Mujer es instituido, sin fecha fija, en la Conferencia Internacional de Mujeres Socialistas celebrada en Copenhague en 1910, a propuesta de la socialista alemana Clara Zetkin, quien toma como referencia para ello el antecedente del Día de la Mujer que las socialistas norteamericanas llevaban a cabo desde 1908 para reivindicar el sufragio femenino. En 1917, como reacción ante los millones de muertos en la guerra, las mujeres rusas eligen el domingo 23 de febrero del calendario juliano (8 de marzo en el gregoriano) para declararse en huelga en demanda de “pan y paz”, tras lo que, una semana después, se produce la abdicación del zar Nicolás II, en lo que será uno de los hitos del camino que culminará en la Revolución Rusa, con lo que la fecha precisa del 8 de marzo adquiere una connotación destacada."],["Elsa O’connor","pasaje peatonal","Elsa O’Connor nombre artístico de Elsa Asunción Celestino (1906 a 1947), actriz; obtiene en 1943 el premio municipal por su actuación en Himeneo, de Bourdet, que se representa en el Odeón; actúa en las películas La que no perdonó, El loco Serenata, Frontera sur, La casa de los cuervos, El deseo y El camino del infierno."],["Jacinto Oddone","plazoleta","Jacinto Oddone (1881 a 1968), político; funda en 1903 la Sociedad de Obreros Torneros en Madera; miembro del Partido Socialista; es diputado provincial en Buenos Aires; Intendente Municipal del partido Avellaneda en 1920; diputado nacional en 1922, 1932 y 1942; autor de Las comunidades religiosas en la República Argentina, Historia del socialismo argentino, Gremialismo proletario argentino y La lucha de clases."],["Héctor Oesterheld","espacio verde","Héctor Germán Oesterheld (1919 a 1977), escritor de ciencia ficción y guionista; creador de la historieta El Eternauta; guionista de las revistas Rayo Rojo, Cinemisterio y Misterix; entre sus historietas figuran El sargento Kirk, Ermil Pike, La guerra de los Antartes y Bull Rocket; en 1977 es detenido y su nombre integra la lista de desaparecidos. O´GORMAN (calle). Ordenanza del 28-10-1904. Miguel Gorman (1749 a 1819), médico de origen irlandés; primer médico en la expedición al Río de la Plata de Pedro de Cevallos; protomédico general y alcalde mayor de todos los facultativos de medicina, cirugía, farmacia y flebotomía desde 1779; miembro de la Junta de Sanidad en 1807. O´HIGGINS (calle). Ordenanza del 27-11-1893. Bernardo O´Higgins (1778 a 1842), capitán general, prócer máximo de la independencia chilena; participa en el movimiento revolucionario del 18 de septiembre de 1810; diputado por Concepción al Primer congreso de Chile en 1811; combate en Querecheguas, Rancagua y Chacabuco; director de Chile de 1817 a 1823; combate en Cancha Rayada y Maipú."],["Ohm","calle","Jorge Simón Ohm (1787 a 1854), físico alemán; descubre las leyes sobre corrientes eléctricas que llevan su nombre."],["Virrey Olaguer y Feliú","calle","Antonio Olaguer y Feliú (1742-¿1810?), militar español; virrey del Río de la Plata de 1797 a 1799."],["Coronel Manuel José Olascoaga","calle","Manuel José Olascoaga (1835 a 1911), militar y geógrafo; combate en Pavón; confecciona la memoria y plan de defensa contra los indios de 1862; secretario de Roca durante su actuación como ministro de Guerra, organiza y ejecuta junto con éste la campaña al Río Negro; autor de Estudio Topográfico de La Pampa y Río Negro; gobernador de Neuquén de 1885 a 1891; funda Chos Malal."],["Olavarría","calle","José Valentín de Olavarría (1801 a 1845), coronel; combate en Chacabuco, Talcahuano, Cancha Rayada, Maipú, en la Campaña de la Sierra con Arenales, en la de Puertos Intermedios de 1823, en Junín, Ayacucho y en la guerra contra el Brasil. Nicolás de Olavarría (1797-¿1827?), militar, hermano del anterior; combate en Cotagaita, Suipacha, Huaqui, Tucumán, Salta, Vilcapugio, Ayohuma y del Tejar, donde cae prisionero. Rafael de Olavarría (1795 a 1827), militar, hermano del anterior; combate en Cotagaita, Suipacha, Huaqui, Tucumán, Salta, Vilcapugio, Ayohuma, Sipe-Sipe y en la guerra contra el Brasil."],["Diego de Olavarrieta","calle","Diego de Olavarrieta (?-¿1619?), capitán, acompaña a Garay en la fundación de Buenos Aires en 1580; regidor de la misma."],["Olaya","calle","José Olaya (1787 a 1823), patriota aborigen peruano; enviado por el general Sucre para conducir comunicaciones a la plaza del Callao, ocupada por los enemigos; es tomado prisionero y torturado para revelar el nombre de los comprometidos; por su silencio es ajusticiado el 29 de junio de 1823."],["Olazábal","calle","Benito de Olazábal (1805 a 1855), teniente coronel; combate durante la guerra contra el Brasil; edecán del gobernador de 1831 a 1833. Félix de Olazábal (1797 a 1841), general; combate en Chacabuco, Cancha Rayada, Maipú, Pichincha y en la guerra contra el Brasil. Gerónimo de Olazábal (1801 a 1864), coronel; combate en Cepeda, Cañada de la Cruz y en la guerra contra el Brasil. Manuel de Olazábal (1800 a 1872), coronel; combate en Chacabuco, Gavilán, Talcahuano, Cancha Rayada, Maipú, en la guerra contra el Brasil; edecán de los presidentes Urquiza y Derqui. Homenaje conjunto a los hermanos Olazábal."],["Oliden","calle","Manuel Luis de Oliden (1783 a 1868), jurisconsulto y funcionario; gobernador intendente de Buenos Aires de 1815 a 1818; ministro de Gobierno y Hacienda durante los gobiernos de Soler y Sarratea."],["Domingo Olivera","plaza","Domingo Olivera (1798 a 1866), hacendado y funcionario; colabora en los periódicos El Argos de Buenos Aires, El Censor, El Centinela y El Mensajero Argentino; secretario de la Sociedad Rural Argentina en 1826; dueño de la estancia Los Remedios (hoy parque Avellaneda) desde 1828 se dedica a la cría ovina; juez de Paz del partido de San José de Flores."],["Eduardo Olivera","plazoleta","Eduardo Olivera (1827 a 1910), hacendado y político, hijo de Domingo; fundador de la Sociedad Rural Argentina y propulsor de la industria agrícola ganadera de nuestro país; editor de los Anales de la Sociedad Rural; interventor de la provincia de Buenos Aires en 1893."],["Olivieri","calle","Silvino Olivieri (1820 a 1856), coronel de origen italiano; combate en Caseros; jefe de la Legión Italiana que defiende a Buenos Aires durante el sitio de Hilario Lagos; crea en 1856 la colonia agrícola-militar de Bahía Blanca."],["Olivos","calle","Olivos: ciudad del partido de Vicente López, provincia de Buenos Aires."],["Olleros","calle","Juan José Olleros (1794 a 1857), coronel; combate en Chacabuco, Gavilán, Talcahuano, Cancha Rayada y Maipú; interviene en la Revolución del Sur en 1839; combate en don Cristóbal, Sauce Grande y Caaguazú."],["Ambrosio Olmos","calle","Ambrosio Olmos (¿-?), vecino de la ciudad que dona las tierras para la formación de esta calle."],["De los Olmos","plaza","Olmos: árboles de la familia de las ulmáceas que pueblan este espacio verde."],["Juan Francisco Olmos","calle","Juan Francisco Olmos (¿1800?-1867), coronel; acompaña a Martín Rodríguez en su campaña al Desierto en 1824 y a Juan Manuel de Rosas en la suya de 1833; combate en don Cristóbal, Quebracho Herrado y Famaillá; acompaña los restos de Lavalle hasta Potosí; combate en Caseros y San Gregorio."],["Ombú","calle","Ombú: combate librado durante la guerra contra el Brasil el 15 de febrero de 1827 entre las fuerzas del general Lucio Norberto Mansilla y las del general Marqués de Barbacena."],["Paseo de los Ombúes","paseo","Ombú: arbusto de América meridional de la familia de las Fitolacáceas. Es éste un nombre tradicional que tiene su origen en la existencia de estos árboles plantados en las aceras de esta avenida."],["Oncativo","calle","Oncativo: combate librado entre las fuerzas del general José María Paz y las del brigadier general Facundo Quiroga el 25 de febrero de 1830. 11 DE JUNIO DE 1580 (plazoleta). Ordenanza N° 21.975-1966, BM N° 12.973. 11 de Junio de 1580: fecha de la fundación de la ciudad de la Trinidad y puerto de Santa María de los Buenos Aires, por Juan de Garay. 11 DE NOVIEMBRE DE 1859 (plazoleta). Ordenanza N° 10.062-1938, BM N° 5.356. 11 de Noviembre de 1859: fecha en que se firma el pacto de San José de Flores o Pacto Unión, por el cual Buenos Aires se declara “parte integrante de la República Argentina”. 11 DE SEPTIEMBRE DE 1888 (calle). 11 de Septiembre en el Plano de Proyecto de Traza del Pueblo de Belgrano levantado por el Departamento Topográfico de la Provincia de Buenos Aires y aprobado por su gobierno el 6 de diciembre de 1855. Por Ordenanza N° 44.645-1990, BM N° 18.938, su nombre actual. 11 de septiembre de 1888: fallecimiento de Domingo Faustino Sarmiento, día elegido para conmemorar el Día del Maestro."],["Clemente Onelli","cantero central","Clemente Onelli (1864 a 1924), naturalista italiano; antropólogo y zoólogo; director del Jardín Zoológico de Buenos Aires de 1904 a 1924."],["Cesário Onzari","cantero central","Cesário Onzari (1903 a 1964), futbolista del club Huracán; autor del primer gol directo desde un tiro de esquina ocurrido el 1° de octubre de 1924, jugando para el seleccionado argentino, en la cancha del Club Sportivo Barracas, contra el seleccionado de Uruguay. El gol recibió el nombre de olímpico ya que la selección uruguaya había obtenido ese año el campeonato en los Juegos Olímpicos de Francia."],["Oporto","calle","Oporto: ciudad de Portugal, capital del distrito de su nombre."],["Organización Estados Americanos","plazoleta","Organización Estados Americanos (OEA): homenaje a este organismo creado con la carta de Bogotá firmada en 1948 por todas las naciones de América, con la finalidad de garantizar la seguridad del Continente contra cualquier agresión, y fomentar su desarrollo cultural y económico."],["Brigadier General Don Manuel Oribe","plazoleta","Manuel Ceferino Oribe y Viana (1792 a 1857), militar uruguayo; organiza y toma parte en la expedición de los 33 Orientales en 1825; combate en Ituzaingó y Camacuá en 1828; presidente de la República Oriental del Uruguay de 1835 a 1838; triunfa en Quebracho Herrado, Famaillá y Arroyo Grande."],["Teniente Manuel Félix Origone","calle","Manuel Félix Origone (1891 a 1913), aviador; muere en un accidente aéreo durante un viaje entre El Palomar y Mar del Plata organizado por el profesor alemán Enrique Lübbe, el 19 de enero de 1913."],["Don Orione","plazoleta","Luis Orione (1872 a 1940), sacerdote italiano; fundador de la Pequeña Obra de la Divina Providencia; visita la Argentina en 1922 y 1934 e inicia numerosas obras, entre ellas el Cotolengo de Cláypole."],["Irene Orlando","jardín","Irene Orlando (1913 a 1977), psicóloga; como consecuencia de su lucha por la vida y la libertad de su hijo Mario Tempone, secuestrado y desaparecido en 1976, comienza a frecuentar a las madres en igual situación que se reunían en la iglesia Santa Cruz. Es secuestrada el 8 de diciembre de 1977. Permanece desaparecida."],["Orma","calle","Francisco Mariano Orma (1777 a 1841), comerciante; combate durante las Invasiones Inglesas; participa en el Cabildo Abierto del 22 de mayo de 1810."],["Fray Justo Santa María de Oro","calle","Oro por Disposición del presidente de la Corporación Municipal, Torcuato de Alvear del 6-3-1882. (Archivo Histórico Municipal, Legajo 3, 1882, Obras Públicas). Por Decreto N° 1.507- 1965, BM N° 12.527, su nombre actual. Justo Santa María de Oro (1772 a 1836), sacerdote; diputado por San Juan en el Congreso de Tucumán; vicario apostólico de Cuyo desde 1828 y primer obispo de esa diócesis en 1834."],["Nicasio Oroño","calle","Nicasio Oroño (1823 a 1904), político; diputado en la Convención Constituyente de Santa Fe para la reforma de la Constitución en 1860, gobernador de Santa Fe de 1865 a 1868; senador nacional en 1868."],["Ortega","calle","Capital de la República Argentina confeccionado por el Departamento de Obras Públicas de la Municipalidad. Año 1904. Rufino Ortega (1816 a 1861), coronel; participa en la revolución del Sur en 1839; combate en Chascomús, Don Cristóbal, Sauce Grande, San Calá, Angaco, Cepeda y Pavón, donde muere en batalla."],["Rodolfo Ortega Peña","cantero central","Rodolfo Ortega Peña (1936 a 1974), abogado, político, periodista, historiador y profesor universitario; diputado nacional (1973), defensor de detenidos políticos durante el gobierno de Lanusse; fue asesinado por la Triple A el 31 de julio de 1974."],["José Ortega y Gasset","calle","José Ortega y Gasset (1883 a 1955), filósofo, ensayista, catedrático español; fundador de la Revista de Occidente; autor de Meditaciones del Quijote, La rebelión de las masas, Espíritu de la letra y Mocedades."],["Carlos Ortiz","calle","Carlos Ortiz (1870 a 1910), poeta y periodista; autor de Rosas del crepúsculo, El poema de las mieses y El grito de los fuertes."],["Ciriaco Ortiz","plazoleta","Ángel Ciriaco Ortiz Barrionuevo (1904 a 1970), bandoneonista, autor de Negrucha, Entre copa y copa, Nena, Cuando estés muy lejos y Soledad."],["Francisco J. Ortiz","calle","Francisco J. Ortiz (1840 a 1932), jurisconsulto y político; ministro general de Salta durante los gobiernos de Cleto Aguirre y José B. Dávalos de Molina; autor de dos paráfrasis de las versiones salteñas de la Zamba de Vargas; ministro de Relaciones Exteriores y Culto en 1883 y 1884, propicia y defiende la Ley N° 1.420 de Educación Común."],["Presidente Roberto M. Ortiz","calle","Roberto M. Ortiz (1886 a 1942), jurisconsulto; presidente de la República de 1938 a 1940, cuando renuncia por motivos de salud."],["Ortiz de Ocampo","calle","Francisco Ortiz de Ocampo (1771 a 1840), general; combate durante las Invasiones Inglesas; manda en 1810 la primera expedición al Alto Perú; gobernador intendente de Córdoba en 1814 y 1815 y gobernador a cargo de Mendoza en 1815; gobernador de La Rioja en 1816 y 1820."],["Rodrigo Ortiz de Zárate","calle","Rodrigo Ortiz de Zárate (1552-¿1592?), capitán; acompaña a Garay en la fundación de Buenos Aires en 1580; alcalde del primer Cabildo porteño."],["Villa Ortúzar","barrio","Santiago Francisco de Ortúzar (1822 a 1897), propietario de tierras en este sector de la ciudad; su casa se encontraba en la manzana de Giribone, Heredia, 14 de Julio y Álvarez Thomas; en la esquina de Heredia y Giribone poseía grandes palomares y por ellos se conoce al lugar como “el palomar de Ortúzar”; posteriormente vende lotes para la formación de la villa que perpetúa su nombre y participa en numerosas acciones favorables a su desarrollo."],["Villa Ortúzar","plazoleta","Santiago Francisco de Ortúzar (1822 a 1897), propietario de tierras en este sector de la ciudad; su casa se encontraba en la manzana de Giribone, Heredia, 14 de Julio y Álvarez Thomas; en la esquina de Heredia y Giribone poseía grandes palomares y por ellos se conoce al lugar como “el palomar de Ortúzar”; posteriormente vende lotes para la formación de la villa que perpetúa su nombre y participa en numerosas acciones favorables a su desarrollo."],["Oruro","calle","Oruro: sierra, ciudad y departamento de Bolivia."],["Osaka","calle","Osaka: ciudad de Japón, capital de la provincia de su nombre en la isla de Honshu."],["Oslo","calle","Oslo: ciudad capital de Noruega."],["Osorio","calle","Manuel Luis Osorio (1808 a 1879), general brasileño; combate en la guerra del Brasil contra la Argentina, en Caseros y en la guerra contra el Paraguay donde asume como general en jefe el comando de las tropas imperiales."],["Ostende","calle","Ostende: ciudad de Bélgica en la provincia de Flandes Occidental."],["Otamendi","calle","Fernando Otamendi (1800 a 1866), hacendado y funcionario; actúa en la revolución del Sur en 1839 y, muerto el capitán López Calvento en la batalla de Chascomús, asume el mando de las fuerzas; diputado a la Legislatura de Buenos Aires en 1859 y senador en 1861 y 1866."],["Otero","calle","Francisco de Paula Otero (1786 a 1854), general; gesta el pronunciamiento de la división de Huancavélica que engrosa las tropas de Arenales; gobernador intendente de Tarma, Jauja, Concepción y Huancayo en 1820; combate en Junín y Ayacucho."],["Ottawa","calle","Ottawa: ciudad capital de Canadá."],["Owen","calle","Roberto Owen (1771 a 1858), sociólogo y economista inglés; fundador del cooperativismo, se lo considera uno de los más destacados representantes del socialismo utópico."],["Beato Federico Ozanam","calle","Federico Ozanam (1813 a 1853), escritor católico francés; fundador de las Conferencias de San Vicente de Paul; autor de Los poetas franciscanos en Italia en el siglo XIII y Una peregrinación al país del Cid. Notas."],["Regina Pacini de Alvear","calle","Regina Pacini de Alvear (1871 a 1965), cantante portuguesa, dedicada al arte lírico; esposa de Marcelo T. de Alvear, presidente de la Nación de 1922 a 1928."],["Pacheco","calle","Ángel Pacheco (1795 a 1869), general; combate en San Lorenzo, Chacabuco, Talcahuano, Cancha Rayada, Maipú y en la guerra contra el Brasil; participa en 1833 en la campaña al desierto de Juan Manuel de Rosas al mando de la vanguardia; combate en Quebracho Herrado."],["José Andrés Pacheco de Melo","calle","Pacheco de Melo por Disposición del Presidente de la Corporación Municipal, Torcuato de Alvear, del 6-3-1882. (Archivo Histórico Municipal, Legajo 3, 1882, Obras Públicas). Por Ordenanza N° 15.730-1959, BM N° 11.255, su nombre actual. José Andrés Pacheco de Melo (1779-?), sacerdote; diputado por Chichas en el Congreso de Tucumán y presidente del mismo en abril de 1818."],["Padilla","calle","Manuel Ascencio Padilla (1774 a 1816), coronel boliviano; junto con su esposa, doña Juana Azurduy, interviene en las revoluciones de Chuquisaca y La Paz en 1809; combate en Huaqui, Tucumán, Salta, Vilcapugio y Ayohuma; es muerto al ser hecho prisionero tras el encuentro de La Laguna el 14 de septiembre de 1816."],["Ernesto Padilla","plazoleta","Ernesto E. Padilla (1873 a 1951), jurisconsulto y político; gobernador de Tucumán de 1913 a 1917; ministro de Justicia e Instrucción Pública durante la presidencia de José Félix Uriburu de 1930 a 1931."],["Manuel Padilla","calle","Manuel Padilla (1821 a 1862), jurisconsulto; diputado por Jujuy en el Congreso Constituyente de 1853."],["General José Antonio Páez","plazoleta","José Antonio Páez (1790 a 1873), general venezolano; caudillo de los llaneros durante la guerra de la independencia; vencedor en las Queseras del Medio y Bailadores; combate en Boyacá y Carabobo; jefe supremo de la Capitanía General de Venezuela en 1827; muerto Bolívar en 1830, desintegra la Gran Colombia y forma la República de Venezuela; es presidente de la misma de 1830 a 1835 y de 1839 a 1843."],["Angelina Pagano","pasaje peatonal","Angelina Augusta Civani Pagano (1888 a 1962), actriz; actúa en Norteamérica y Europa con la compañía de Elenora Dusse, con Ferrucio Garavaglia en el teatro Victoria en 1903, y en 1904 en el Apolo con los hermanos Podestá; se desempeña también junto a su esposo, Francisco Ducasse, y con Guillermo Battaglia; profesora del Conservatorio Lavardén de la Municipalidad de Buenos Aires."],["José León Pagano","calle","José León Pagano (1875 a 1964), autor teatral, ensayista y crítico; profesor de la Academia Nacional de Bellas Artes y en la Facultad de Filosofía y Letras; autor de El arte de los argentinos, La balada de los sueños y El hombre que volvió a la vida."],["Coronel Pagola","calle","Manuel Vicente Pagola (1781-¿1841?) coronel uruguayo; combate durante las Invasiones Inglesas; durante el primer sitio de Montevideo, en Cepeda (1820) y Cañada de la Cruz; encabeza el movimiento del 1° de octubre de 1820."],["Pailebot Davison","calle","Pailebot Davison: embarcación en la que el comandante Luis Piedra Buena recorre las islas Malvinas, cabo de Hornos y todo el sur argentino entre 1847 y 1849 y en el que adquiere gran experiencia naval."],["Aimé Painé","calle","Olga Elisa Painé (1944 a 1987), cantante mapuche; toma el nombre tehuelche Aimé en reemplazo de Olga Elisa; estudia canto y música con Blanca Parodi y guitarra con Roberto Lara; integra durante algunos años el Coro Polifónico Nacional; desarrolla desde su juventud una gran actividad como difusora de los cantos y tradiciones de su etnia, realizando una vasta tarea de recopilación por las regiones australes de la Argentina y Chile."],["De Pakistán","plaza","Pakistán: estado del Asia. Capital: Islamabad."],["Alfredo L. Palacios","plazoleta","Alfredo Lorenzo Palacios (1878 a 1965), jurisconsulto y político; presidente de la Universidad Nacional de La Plata; diputado nacional en 1904; senador nacional de 1932 a 1943; embajador argentino en el Uruguay en 1955; autor de Por las mujeres y los niños que trabajan, El nuevo derecho y La justicia social."],["Palermo","barrio","Juan Domínguez Palermo (¿-?), funcionario y comerciante; antiguo propietario de estas tierras, las que compra en 1609; desde entonces comienza a identificárselas con su apellido,."],["Palermo Viejo","plaza","Palermo Viejo: nombre con que se conoce actualmente al sector del barrio de Palermo limitado por la avenida Córdoba, Godoy Cruz, Charcas y Julián Álvarez; característico por sus actividades comerciales y culturales."],["Palestina","calle","Palestina: región de SO de Asia, en el extremo Oriental del Mediterráneo."],["Juan León Palliere","calle","Juan León Palliere (1823 a 1887), pintor de origen francés nacido en Brasil; recorrió nuestro país y dejó la más abundante documentación gráfica de la vida argentina entre 1855 y 1866; autor de Álbum Palliere, Escenas americanas. Reproducción de cuadros, acuarelas y bosquejos, Pisadora de Maíz, La porteña en el templo y Tropa de carretas en la Pampa."],["Athos Palma","calle","Athos Palma (1891 a 1951), músico; director del Teatro Colón; autor de Jardines, Los hijos del sol y Accla; escribe Teoría razonada de la música y Tratado completo de armonía."],["Palmar","calle","Palmar: combate librado durante la guerra contra el Paraguay el 21 de julio de 1866 entre las fuerzas de los aliados y las paraguayas."],["Las Palmas","calle","Las Palmas: canal del río Paraná por el que ingresa en el río de la Plata el brazo Paraná de las Palmas."],["Olof Palme","calle","Olof Palme (1927 a 1986), político sueco; presidente del Partido Socialdemócrata de Suecia; ocupó el cargo de primer ministro en varias oportunidades; mantiene a lo largo de su vida una lucha permanente en favor de los derechos humanos, la consolidación de la paz y la justicia social. Es asesinado en circunstancias, hasta hoy, no esclarecidas."],["Palos","calle","Puerto de Palos: villa y puerto de España, hoy cegado, en la provincia de Huelva, desde donde partió Colón el 3 de agosto de 1942 en su histórico viaje del descubrimiento de América. Se lo conoce también como Palos de Moguer o de la Frontera."],["Mártires Palotinos","calle","Mártires Palotinos: homenaje a la memoria de los religiosos padres Alfredo Leaden, Pedro Duffau y Alfredo Kelly y los seminaristas Salvador Barbeito y Emilio Barletti, de la Orden de los Hermanos Palotinos que fueron asesinados el 4 de julio de 1976 por la dictadura militar."],["Palpa","calle","Palpa: primer combate que libró en el Perú la Expedición Libertadora el 7 de octubre de 1820 al mando del teniente coronel Rufino Guido."],["El Pampero","cantero central","El Pampero: nombre del globo aerostático en el que desaparecieron, perdidos en el mar durante un vuelo, Eduardo Newbery y Eduardo Romero el 17 de octubre de 1908."],["El Pampero","calle","Pampero: viento impetuoso, frío, seco y purificador que corre desde el sudoeste en la pampa central y en la provincia de Buenos Aires."],["Panamá","calle","Panamá: república de América Central. Capital: Panamá."],["Paracas","calle","Paracas: puerto en la bahía peruana del mismo nombre donde desembarcó la expedición libertadora de San Martín el 8 de septiembre de 1820."],["República de Paraguay","plazoleta","Paraguay: país sudamericano. Capital: Asunción."],["Paraná","calle","Paraná: río que nace en el Brasil y desemboca en el río de la Plata. Es el mayor de América del Sur después del Amazonas."],["Pareja","calle","Alonso Pareja (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Parera","calle","Blas Parera (1776 a 1840), músico; director de la orquesta del Teatro Coliseo de 1803 a 1805; combate durante las Invasiones Inglesas; compone en 1813 la música del Himno Nacional."],["Batalla del Parí","calle","Batalla del Parí: batalla en la costa del arroyo Parí, Bolivia, donde el coronel Ignacio Warnes es derrotado y muerto heroicamente en combate durante la guerra de Republiquetas, el 21 de noviembre de 1816."],["París","calle","París: ciudad capital de Francia."],["Parker","calle","Enrique Guillermo Parker (?-1826), capitán de marina de origen inglés; combate durante la guerra contra el Brasil como segundo comandante del buque insignia 25 de Mayo y como comandante del bergantín Congreso Nacional, con el que participa en el ataque a la Colonia del Sacramento donde es gravemente herido; fallece como consecuencia de ello el 27 de marzo de 1826."],["Paroissien","calle","Diego Paroissien (1784 a 1827), médico de origen inglés; cirujano en la Expedición al Alto Perú en 1810; por sus méritos obtiene la primera carta de ciudadanía otorgada en el país el 25 de noviembre de 1811; médico del Ejército Auxiliar del Perú; director de la Fábrica de Pólvora de Córdoba en 1812 y 1815; cirujano mayor del Ejército de los Andes en 1816; participa en Chacabuco, Cancha Rayada y Maipú; edecán de San Martín y cirujano mayor de la Expedición Libertadora del Perú. PARQUE AVELLANEDA véase AVELLANEDA, PARQUE. PARQUE CHAS véase CHAS, PARQUE."],["Del Parque","calle","Del Parque: nombre tradicional que anteriormente tenían las actuales plaza y calle Lavalle en razón de encontrarse durante el siglo pasado el Parque de Artillería en la manzana donde hoy se encuentra el edificio de Tribunales."],["Villa del Parque","barrio","Del Parque: nombre que se adopta para la estación del Ferrocarril Buenos Aires al Pacífico (hoy General San Martín) inaugurada en 1907 y que alude al vecino parque o quinta de Agronomía."],["Parques Nacionales Argentinos","plaza","Parques Nacionales Argentinos: son llamadas así las extensas zonas del territorio nacional notables por su riqueza vegetal y animal autóctonas y por sus bellezas naturales, que el Estado declaró reserva nacional. Se originan en la donación realizada en 1903 por el perito Francisco P. Moreno que permite el nacimiento del parque Nahuel Huapi."],["Violeta Parra","cantero central","Violeta Parra (1917 a 1967), poeta, compositora y cantante chilena; investiga, recupera e interpreta el folclore de su país; autora de Gracias a la vida, Volver a los diecisiete, Rin del angelito, Run Run se fue pal norte, Casamiento de negros, entre otras composiciones."],["Parral","calle","Parral: combate librado en Chile el 27 de mayo de 1818 en la villa de ese nombre, entre las fuerzas realistas del comandante Manuel Bulnes y las patriotas del capitán de Granaderos Miguel Cajaravilla."],["Florencio Parravicini","pasaje peatonal","Florencio Parravicini (1876 a 1941), actor y autor teatral y cinematográfico argentino. Actúa junto a José J. Podestá en 1906, y al año siguiente forma su propia compañía. Se destaca por sus papeles en las obras teatrales Panete, El cabo Scamione y Cristóbal Colón en la Facultad de Medicina. Es protagonista de los filmes Hasta después de muerta, Los muchachos de antes no usaban gomina, Tres anclados en París, Carnaval de antaño y Melgarejo. Considerado “el gran cómico argentino” por la ocurrencia de sus chistes que improvisaba con particular histrionismo. Es concejal de Buenos Aires de 1926 a 1930."],["Pasco","calle","Pasco: batalla librada en las inmediaciones de la ciudad de Pasco, Perú, el 6 de diciembre de 1820 entre las fuerzas realistas del general O´Reyly y las patriotas del general Álvarez de Arenales. PASEO DE LA VIDA véase VIDA, PASEO DE LA."],["Paso","calle","Publicado en la Memoria de la Municipalidad de la Ciudad de Buenos Aires correspondiente a los años 1856 y 1857. Buenos Aires, Imprenta del Orden, San Martín 5 y Buen Orden 155, 1858."],["Juan José Paso","plaza","Juan José Paso (1758 a 1833), jurisconsulto; secretario de la Primera Junta de Gobierno; miembro de los dos Triunviratos; instala la Asamblea General Constituyente de 1813; diputado por Buenos Aires en el Congreso de Tucumán."],["Paso de los Libres","calle","Paso de los Libres: ciudad y departamento de la provincia de Corrientes situada sobre el río Uruguay. Véase LIBRES."],["Darwin Passaponti","cantero central","Darwin Passaponti (1928 a 1945), militante peronista; muerto trágicamente a los 17 años durante los sucesos ocurridos el 17 de octubre de 1945."],["Pasteur","calle","Luis Pasteur (1822 a 1895), biólogo francés; descubridor del método de atenuar el virus de la rabia y de la vacuna contra esa enfermedad."],["Patagones","calle","Publicado en la memoria de la Municipalidad de la Ciudad de Buenos Aires correspondiente a los años 1856 y 1857. Buenos Aires, Imprenta del Orden, San Martín 5 y Buen Orden 155, 1858. Carmen de Patagones: ciudad de la provincia de Buenos Aires."],["La Patagonia Rebelde","cantero central","La Patagonia Rebelde: película dirigida por Héctor Olivera en 1974, basada en el libro de Osvaldo Bayer sobre las huelgas y posteriores fusilamientos en la Patagonia."],["Paternal","barrio","La Paternal: nombre de una Sociedad de Seguros, propietaria de terrenos en este barrio, que construye en el mismo casas para obreros y que gestiona se le otorgue su nombre a la estación Chacarita, cosa que se materializa en 1904, momento desde el cual comienza a identificarse a esta zona con esta denominación. PATERNAL, LA ISLA DE LA (espacio verde) Ley Nº 970-2002, BO Nº 1.614. La Isla de la Paternal: se denomina así por encontrarse en el barrio del mismo nombre y por las características aisladas de este lugar, donde se encontraba el llamado Albergue Warnes."],["Patoruzú","cantero central","Patoruzú: protagonista de la historieta creada por Dante Raúl Quinterno, que aparece por primera vez en el diario Crítica en 1928 y que en 1936 comienza a publicarse como revista."],["Los Patos","calle","Los Patos: paso de la Cordillera de los Andes por el que cruza la segunda división del Ejército Libertador del general San Martín, que comanda el general Soler, el 17 de enero de 1817 con el objeto de libertar a Chile."],["Patricias Argentinas","avenida","Patricias Argentinas: homenaje a las mujeres que en la época de la Independencia cooperaron con el triunfo de la emancipación política de esta parte del continente."],["Regimiento I Patricios","plazoleta","Regimiento de Patricios: cuerpo de infantería de actuación distinguida durante las Invasiones Inglesas, en la Revolución de Mayo y durante la guerra de la Independencia."],["Patrón","calle","Matías Patrón (1784 a 1822), jurisconsulto; participa en el Cabildo Abierto del 22 de mayo de 1810; diputado por Buenos Aires en 1817 en el Congreso de Tucumán trasladado a esta ciudad."],["Paunero","calle","Wenceslao Paunero (1805 a 1871), general, combate durante la guerra contra el Brasil, La Tablada, Oncativo, Tonelero, Caseros, Cepeda y Pavón; gobernador delegado de Córdoba en 1862; dirige la lucha contra las montoneras y vence a don Ángel Vicente Peñaloza en Las Playas; combate en la guerra contra el Paraguay. PAVLOVSKY, ROSA (cantero central), Ley Nº 1.429-2004. BO Nº 2.037. Rosa Pavlovsky de Rosemberg (1863 a 1936); médica de origen ruso; participa como enfermera en los servicios médicos creados para enfrentar en Mendoza la epidemia de cólera de 1886. Se dedica a la pediatría en su consultorio privado y en el Hospital Francés, donde es designada jefa del Servicio de Pediatría; miembro de varias academias científicas del país y el extranjero. Es condecorada por el gobierno francés con la Legión de Honor."],["Pavón","calle","Pavón: batalla en la que el general Bartolomé Mitre al mando del ejército porteño vence a las fuerzas de la Confederación mandadas por el general Urquiza el 17 de septiembre de 1861."],["Roberto J. Payró","calle","Roberto Jorge Payró (1867 a 1928), narrador y dramaturgo; autor de Entre amigos, Antígona, El casamiento de Laucha, El triunfo de los otros, Violines y toneles, Sobre las ruinas, Pago chico y El falso inca."],["Paysandú","calle","Paysandú: ciudad y departamento de la República Oriental del Uruguay."],["Paseo de la Paz","plaza","De la Paz: este paseo fue realizado por los vecinos y constituye un homenaje al ideal de paz entre los pueblos."],["General Paz","avenida","José María Paz (1791 a 1854), militar; combate en Las Piedras, Tucumán, Salta y en la guerra contra el Brasil; gobernador de Córdoba de 1829 a 1831; vencedor en La Tablada, Oncativo y Caaguazú; defiende a Buenos Aires durante el sitio de Hilario Lagos."],["General Paz","parque","José María Paz (1791 a 1854), militar; combate en Las Piedras, Tucumán, Salta y en la guerra contra el Brasil; gobernador de Córdoba de 1829 a 1831; vencedor en La Tablada, Oncativo y Caaguazú; defiende a Buenos Aires durante el sitio de Hilario Lagos."],["Doctor José C. Paz","plaza","José Camilo Paz (1842 a 1912), periodista; fundador de los diarios El Inválido Argentino en 1867 y La Prensa en 1869; autor de El hombre y el ciudadano."],["Marcos Paz","calle","Marcos Paz (1811 a 1868), jurisconsulto; gobernador de Tucumán de 1858 a 1860; gobernador interino de Córdoba en 1862; vicepresidente de la República durante la presidencia de Mitre de 1862 a 1868."],["José Pazos","calle","José Pazos (?-1807), militar; capitán y edecán de don Javier de Elío, muerto durante las Invasiones Inglesas. Es éste un nombre tradicional de Buenos Aires pues entre 1808 y 1822 se denominaron “Pazos” las actuales San José y Uruguay."],["Paz Soldán","calle","Mariano Felipe Paz Soldán (1821 a 1886), jurisconsulto, historiador y geógrafo peruano; autor de Atlas del Perú, Historia del Perú independiente, Geografía argentina, Atlas de la República Argentina e Historia de la guerra del Pacífico."],["María Antonia Bm N° 7.254. Paz y Figueroa","espacio verde","María Antonia de la Paz y Figueroa (1730 a 1799), religiosa; beata fundadora de la Santa Casa de Ejercicios de Buenos Aires en 1793."],["Pedernera","calle","Juan Esteban Pedernera (1796 a 1886), teniente general; combate en Chacabuco, Cancha Rayada, Maipú, Ica, en la guerra contra el Brasil, Navarro, La Tablada, Oncativo, Ciudadela y Famaillá; acompaña los restos de Lavalle hasta Potosí; gobernador de San Luis en 1859; combate en Cepeda; vicepresidente de la República durante la presidencia de Derqui de 1860 a 1861. PEDERNERA, TENIENTE CORONEL FEDERICO A. J. Y PITA, CORONEL HERNÁN C. véase PITA, CORONEL HERNÁN C. y PEDERNERA, TENIENTE."],["Manuela Coronel Federico A. J. Pedraza","calle","Manuela Pedraza (¿-?), patriota; fue condecorada con el grado de Alférez por su valiente actuación durante las Invasiones Inglesas en 1806; se la llamaba Manuela la Tucumana o la Tucumanesa."],["Pehuajó","calle","Pehuajó: ciudad y partido de la provincia de Buenos Aires."],["Peiping","calle","Peiping: nombre que se le dio a la ciudad de Pekín, capital de China, cuando se trasladó a Nankin la capital de esa nación en 1928."],["Carlos Pellegrini","calle","Carlos Pellegrini (1846 a 1906), jurisconsulto; vicepresidente de la República durante la presidencia de Juárez Celman de 1886 a 1890 y presidente de la República de 1890 a 1892."],["Carlos Pellegrini","plaza","Carlos Pellegrini (1846 a 1906), jurisconsulto; vicepresidente de la República durante la presidencia de Juárez Celman de 1886 a 1890 y presidente de la República de 1890 a 1892."],["Carlos E. Pellegrini","calle","Carlos Enrique Pellegrini (1800 a 1875), ingeniero y pintor de origen italiano nacido en Francia; autor de Fiestas Mayas, Cielito, Media caña, del álbum Recuerdos del Río de la Plata; planea y dirige la construcción del primitivo Teatro Colón de Plaza de Mayo; proyecta el Mercado del Plata; es el padre del presidente Carlos Pellegrini."],["Ángel Peluffo","calle","Ángel Peluffo (1842 a 1922), horticultor uruguayo; establece en nuestro país una de la primeras casas de plantas y semillas; miembro fundador del Banco Popular Argentino. PENA, JOSÉ LUIS (sendero), Ordenanza Nº 51.579-1997, BO Nº 219. José Luis Pena (1892 a 1978), periodista, economista y astrónomo; diputado nacional por el Partido Socialista de 1924 a 1928 y de 1932 a 1936; concejal de la ciudad de 1938 a 1941 y de 1958 a 1962, propulsa la creación del Planetario de la Ciudad de Buenos Aires que se inaugura el 13 de junio de 1967."],["José Penelón","pasaje peatonal","José Fernando Penelón (1891 a 1954), obrero gráfico; funda y dirige los periódicos La Internacional y La Correspondencia Sudamericana; principal protagonista de la creación del Partido Socialista Internacional (1918), luego Partido Comunista; funda el Partido Concentración Obrera; concejal de la ciudad de Buenos Aires de 1921 a 1924, 1927 a 1930, 1932 a 1935 y de 1938 a 1941."],["Peña","calle","Luis José de la Peña (1796 a 1871), educador; ministro de Relaciones Exteriores de Urquiza en la Confederación en 1852; diplomático en Brasil y Paraguay; director general de Escuelas en 1865. Juan Andrés de la Peña (1799 a 1864), educador, hermano del anterior; miembro del Consejo de Instrucción Pública en 1855 y 1858."],["Doctor David Peña","calle","David Peña (1862 a 1930), jurisconsulto e historiador; fundador de los diarios Nueva Época (Santa Fe) y La Época (Rosario) y de la Revista Argentina (Rosario); autor de Juan Facundo Quiroga, Defensa de Alberdi, Historia de las leyes de la Nación Argentina y La materia religiosa en la política argentina. PEPE, DON véase DON PEPE."],["Pepirí","calle","Pepirí: río que sirve de límite este de la provincia de Misiones y el Brasil."],["Perdriel","calle","Gregorio Ignacio Perdriel (1785 a 1832), coronel; combate en las Invasiones Inglesas, en la expedición al Paraguay de Belgrano, Salta, Vilcapugio y Ayohuma; gobernador intendente de Cuyo en 1815; gobernador de la fortaleza de Buenos Aires en 1818; jefe de la Policía de Buenos Aires de 1827 a 1828 y de 1829 a 1832, año en que muere víctima del cólera."],["El Peregrino","calle","Cantos de Peregrino: obra de José Mármol publicada en 1846."],["Carlos H. Perette","calle","Carlos Humberto Perette (1915 a 1992), abogado y político; diputado nacional de 1952 a 1955 y de 1958 a 1962; vicepresidente de la Nación en el gobierno de Arturo Illía de 1963 a 1966; senador por Entre Ríos entre 1973 y 1976, y embajador en el Uruguay de 1983 a 1989."],["Pereyra","calle","Capital de la República Argentina, confeccionado por el Departamento de Obras Públicas de la Municipalidad. Año 1904. Bartolomé Pereyra (¿-?), vecino que cede los terrenos para la apertura de esta calle y cuya donación es aceptada por Resolución del 23-6-1898. Por Resolución del 11-7-1898 se acepta también su cesión de tierras para abrir las calles Garay, Inclán y Salcedo."],["Leonardo Pereyra","parque","Leonardo Pereyra (1834 a 1899), hacendado; fue uno de los fundadores de la Sociedad Rural Argentina y presidente de la misma; donó el terreno donde hoy se levanta el parque Pereyra Iraola en las cercanías de La Plata."],["Pereyra Lucena","calle","Capital de la República Argentina. Confeccionado por el Departamento de Obras Públicas de la Municipalidad, Año 1904, su nombre actual. Felipe Pereyra Lucena (1789 a 1811), teniente coronel; combate durante las Invasiones Inglesas, en Cotagaita, Suipacha y Yuraycoragua, donde el 18 de junio de 1811 es herido; fallece dos días después. Su nombre se encuentra inscripto en la Pirámide de Mayo."],["Comisario Joaquín Valentín Pérez","calle","Joaquín Valentín Pérez (?-1944), bombero; se desempeñaba en la Dirección de Bomberos y murió cumpliendo con su deber el 5 de julio de 1944 mientras luchaba contra el incendio producido en la Manufactura Algodonera Argentina."],["Gregoria Pérez","calle","Gregoria Ignacia Pérez y Larramendi de Denis (1764 a 1823), patricia; es la primera en colaborar con sus bienes en la campaña libertadora, al donarlos al general Belgrano por intermedio de Valentín Denis, su hijo mayor, en la Bajada del Paraná, en noviembre de 1810."],["José Julián Pérez","calle","José Julián Pérez (1770 a 1840), jurisconsulto; representante de Tarija ante la Junta de Buenos Aires en 1810; secretario de Gobierno y Relaciones Exteriores del Primer Triunvirato y miembro del segundo."],["Pascual Pérez","plazoleta","Pascual Pérez (1926 a 1977), deportista; primer boxeador que obtuvo un título mundial para la Argentina en 1953."],["Roque Pérez","calle","José Roque Pérez (1815 a 1871), jurisconsulto; ministro de Relaciones Exteriores en 1852; presidente de la Comisión Municipal de Buenos Aires en 1869; director de la Academia de Jurisprudencia en 1870; presidente de la Comisión Popular contra la epidemia de fiebre amarilla de 1871; muere víctima del mal."],["Melchor Pérez de Holguín","plazoleta","Melchor Pérez de Holguín (¿1660-1732?), pintor boliviano; entre sus obras se encuentran numerosas reliquias religiosas como El Juicio Final (1706), Triunfo de la Iglesia (1708, parroquia de San Lorenzo, en Potosí), Entrada del Virrey Arzobispo Morcillo en Potosí (1718) San Mateo (1724), Virgen de la Merced, La peregrina, San Francisco de Asís (1693, Museo de la Moneda, Potosí) y San Pedro de Alcántara en éxtasis (1701, Museo Nacional de Arte)."],["Benito Pérez Galdós","avenida","Benito Pérez Galdós (1843 a 1920), novelista español; autor de Marianela, Fortunata y Jacinta, Tristana, La loca de la casa, Mariucha y Santa Juana de Castilla."],["Vicente Pérez Rosales","calle","Vicente Pérez Rosales (1807 a 1886), escritor chileno; autor de Recuerdos del pasado, Diccionario del entrometido y Ensayo sobre Chile."],["Pergamino","calle","Pergamino: ciudad y partido de la provincia de Buenos Aires."],["Peribebuy","calle","Peribebuy: pueblo fortificado tomado por los aliados al mando del general brasileño Conde D´Eu y del argentino Luis María Campos durante la guerra contra el Paraguay, el 12 de agosto de 1869."],["De los Periodistas","plazoleta","Periodistas: homenaje al periodismo argentino y a los hombres y mujeres que se dedicaron a esa labor."],["Luis Perlotti","espacio verde","Luis Perlotti (1890 a 1969), escultor y docente de origen uruguayo; trabaja diversos materiales como madera, cerámica, yeso, bronce, mármol. Entre su vasta obra figuran las tituladas El tambor de Tacuarí, Monumento a los Libres del Sur, La tejedoras, Alfonsina Storni. En su casa-taller funciona el museo de esculturas que lleva su nombre."],["Pernambuco","calle","Pernambuco: estado del Brasil. Capital: Recife."],["Eva Perón","avenida","María Eva Duarte de Perón (1919 a 1952), esposa del Gral. Juan Domingo Perón; se dedicó a actividades sociales y políticas; organizó la rama femenina del partido peronista; presidente de la Fundación Ayuda Social Eva Duarte de Perón."],["Eva Perón","plazoleta","María Eva Duarte de Perón (1919 a 1952), esposa del Gral. Juan Domingo Perón; se dedicó a actividades sociales y políticas; organizó la rama femenina del partido peronista; presidente de la Fundación Ayuda Social Eva Duarte de Perón."],["Teniente General Juan Domingo Perón","calle","Juan Domingo Perón (1895 a 1974), militar; presidente de la Nación Argentina de 1946 a 1952, de 1952 a 1955 y de 1973 a 1974."],["Perrault","calle","Carlos Perrault (1628 a 1703), escritor francés; autor de Barba Azul, Caperucita Roja y La Cenicienta. Claudio Perrault (1613 a 1688), médico, botánico y arquitecto francés; construye la columnata del Louvre y el Observatorio de París; comprueba la existencia de la savia elaborada en las plantas; autor de Mecánica de los animales domésticos. Homenaje conjunto a los hermanos Perrault."],["República del Perú","plaza","Perú: república de América del Sur. Capital: Lima."],["Pescadores","calle","Pescadores: combate librado el 27 de noviembre de 1820 entre los realistas al mando del coronel Valdés y los patriotas al mando del teniente Juan Pascual Pringles, en la punta de Pescadores sobre el Pacífico."],["Pestalozzi","calle","Juan Enrique Pestalozzi (1746 a 1827), pedagogo suizo; idea y practica la enseñanza mutua llamada por los ingleses “sistema de Lancaster”, autor de Las veladas de un solitario, El método y El canto del cisne."],["Alejandro Petion","plazoleta","Alejandro Sabés (1770 a 1818), militar y político haitiano conocido por Alejandro Petion; fue el fundador de la República de Haití y proclamado presidente vitalicio en 1816."],["Emilio Pettoruti","calle","Emilio Pettoruti (1892 a 1971) artista plástico; entre sus obras se destacan los óleos Gruta Azul, El quinteto, La del abanico verde y Copa verde-gris."],["Astor Piazzola","paseo","Astor Piazzolla (1921 a 1992), bandoneonista, compositor y director; es el artífice de la renovación vanguardista del tango, al que enriqueció con elementos clásicos y del jazz. Autor de Adiós nonino, Balada para un loco, Chiquilín de Bachín; la serie de las Estaciones (Verano Porteño, Otoño Porteño, Invierno Porteño y Primavera Porteña); la Serie del Ángel (Introducción al ángel, Milonga del ángel, Muerte del ángel y Resurrección del ángel); Revirado, Fracanapa, Calambre, Buenos Aires Hora Cero, Decarísimo, Michelangelo ´70, Fugata, Libertango y Suite Troilana, entre otros."],["Picheuta","calle","Picheuta: paso y fortín de la Cordillera de los Andes en el camino de Uspallata a Juncal, donde se enfrentaron realistas y patriotas el 24 de enero de 1817."],["Pichincha","calle","Pichincha: batalla librada en el Ecuador el 24 de mayo de 1822 entre las fuerzas realistas mandadas por Aymerich y las patriotas comandadas por el general Antonio José de Sucre, que asegura la libertad de América meridional. PICHÓN RIVIÈRE, ENRIQUE (plazoleta). Ley N° 643-2001, BO Nº 1.303. Enrique Pichón Rivière (1907 a 1977), psiquiatra y psicoanalista de origen francés; trabaja en el Hospital José T. Borda; funda en 1942 la Asociación Psicoanalítica Argentina (APA) y la Escuela de Psicología Social."],["Pico","calle","Blas José Pico (1783 a 1868), general; combate durante las Invasiones Inglesas y en el sitio de Montevideo; gobernador interino de Entre Ríos en 1814; jefe de Policía de Buenos Aires en 1852."],["Piedra Buena","avenida","Luis Piedra Buena (1833 a 1883), comandante de marina; recorre nuestro sur desde mediados del siglo pasado realizando numerosos salvamentos y asegurando nuestra soberanía en el comando de numerosas embarcaciones."],["Piedras","calle","Piedras: victoria del general Belgrano sobre los realistas a orillas del río Piedras el 3 de septiembre de 1812."],["Pieres","calle","José Antonio Pieres (1787-?), coronel; combate durante las Invasiones Inglesas, en las Piedras, Vilcapugio, Ayohuma, en la guerra contra el Brasil, Don Cristóbal, Sauce Grande y Quebracho Herrado. Juan Inocencio Pieres (1794 a 1849), sargento mayor; combate en el Cerrito y en la rendición de Montevideo en 1814; comandante interino de Martín García en 1827. Homenaje conjunto a los hermanos Pieres."],["Ciudad de Pigüé","cantero central","Pigüé: ciudad cabecera del partido de Saavedra, provincia de Buenos Aires; se otorga este nombre como homenaje a esta ciudad al cumplir su 75º aniversario."],["Pila","calle","Pila: partido de la provincia de Buenos Aires."],["Pilar","calle","Pilar: ciudad y partido de la provincia de Buenos Aires."],["Pilcomayo","calle","Pilcomayo: río que nace en Potosí, Bolivia, y desemboca en el río Paraguay, sirviendo de límite entre el Paraguay y la Argentina."],["Pillado","calle","Antonio Pillado (1809 a 1879), historiador y periodista; fundador de El Conservador de Montevideo; secretario tesorero de la Municipalidad de Buenos Aires de 1856 a 1858; administrador del Asilo de Mendigos de la Recoleta de 1858 a 1859; autor de Diccionario de Buenos Aires."],["Mariscal José Pilsudski","plazoleta","José Pilsudski (1867 a 1935), militar y estadista polaco; presidente de Polonia de 1919 a 1922; ministro de guerra desde 1928, se encarga de la presidencia en 1930; contribuye a la proclamación de la nueva constitución firmada por su sucesor el presidente Moscicki."],["Pinedo","avenida","Agustín Pinedo (1810 a 1880), bibliófilo y publicista argentino. Sobre esta personalidad no han podido ser ubicados más que estos resumidos datos mencionados en la versión taquigráfica de la sesión del Concejo Deliberante que sanciona la Ordenanza del 30-10-1914."],["Intendente Pinedo","calle","Federico Pinedo (1855 a 1928), jurisconsulto; ministro de Instrucción Pública en 1906; intendente municipal de la ciudad de Buenos Aires desde el 20 de junio de 1893 hasta el 20 de agosto de 1894."],["León Pinelo","calle","Antonio de León Pinelo (1596 a 1660), jurisconsulto, humanista, funcionario e historiador; autor de Discurso sobre la importancia, forma y disposición de la recopilación de Leyes de las Indias Occidentales, Bulario índico, El paraíso en el Nuevo Mundo y Memorial sobre el comercio del Río de la Plata."],["Virrey del Pino","calle","Joaquín del Pino (1729 a 1804), militar; virrey del Río de la Plata de 1801 a 1804."],["La Pinta","calle","La Pinta: una de las tres carabelas que participa en el viaje de Cristóbal Colón que descubre América."],["Pinto","calle","Manuel Guillermo Pinto (1783 a 1853), brigadier general; combate durante la Defensa de Buenos Aires, en Cotagaita, Suipacha y Huaqui; gobernador de Buenos Aires en 1852 y 1853. 12."],["Pinzón","calle","Martín Alonso Pinzón (1440 a 1493), marino; comandante de La Pinta en el viaje de Cristóbal Colón, que descubre América en 1492. Vicente Yáñez Pinzón (?-1515), marino; comandante de La Niña en el viaje de Colón, que descubre América en 1492. Homenaje a los hermanos Pinzón."],["Doctor Norberto Piñero","plazoleta","Norberto Piñero (1858 a 1938), jurisconsulto; promueve la creación de escuelas de educación técnica y crea la Sociedad de Educación Industrial; ministro de Hacienda de 1906 a 1910; funda el Colegio de Abogados de Buenos Aires; autor de Nociones de derecho general, civil y político y La enseñanza técnica. PIONEROS DE LA ANTARTIDA ARGENTINA véase ANTARTIDA ARGEN-."],["Pioneros de La. Pipet, Matías Tina","cantero central","Matías Pipet (1828 a 1886), grabador de origen francés; crea el primer sello postal adhesivo en nuestro país, cuya primera circulación tuvo lugar el 21 de agosto de 1856 en la provincia de Corrientes."],["Pirán","calle","José María Pirán (1804 a 1871), general; combate durante la guerra contra el Brasil, en Cagancha y Caseros; junto con Juan Madariaga es uno de los dirigentes que encabeza la revolución del 1l de septiembre de 1852."],["Los Pirineos","calle","Los Pirineos: sistema orográfico que divide a España de Francia."],["Comisario General Juan Ángel Pirker","paseo","Juan Ángel Pirker (1934 a 1989), policía; jefe de la Policía Federal Argentina, desde 1986 hasta su sorpresivo fallecimiento; a lo largo de su carrera, recibe varias distinciones, entre ellas el premio a la conducta, en 1954, y la Orden de Caballero de San Martín de Tours, en 1988."],["Pirovano","calle","Ignacio Pirovano (1844 a 1895), médico; actúa durante la epidemia de cólera de 1867 y la de fiebre amarilla de 1871; profesor de Histología y Anatomía Patológica desde 1876, profesor de Medicina Operatoria y Clínica Quirúrgica desde 1879."],["Victor Pissarro","calle","Víctor Pissarro (1891 a 1937), pintor y músico; autor de Retrato de Niña, Desnudo, Paisaje y Retrato de Celia Pissarro. PITA, CORONEL HERNÁN C. y PEDERNERA, TENIENTE CORONEL FE-."],["Derico A. J.","jardín","Hernán Carlos Pita (?-1990), militar; segundo jefe del Regimiento de Infantería I Patricios. Federico Alberto José Pedernera (?-1990), militar; jefe de operaciones del Regimiento de Infantería I Patricios. Homenaje conjunto a quienes pierden la vida durante los acontecimientos del 3 de diciembre de 1990, al intentar recuperar el Regimiento que había sido copado por un grupo de militares sublevados."],["Doctor Eduardo Pittaluga","calle","Eduardo Pittaluga (1862-?), médico; concejal de la ciudad de Buenos Aires de 1894 a 1900; precursor de la legislación obrera y defensor de los hospitales municipales."],["Pi y Margall","calle","Francisco Pi y Margall (1824 a 1901), jurisconsulto y escritor español; presidente de la República en 1873; autor de Las nacionalidades e Historia general de América."],["Alejandra Pizarnik","plazoleta","Alejandra Pizarnik (1936 a 1972), poetisa y escritora; autora de La tierra más ajena, Alta mar, Los trabajos y las noches y Árbol de Diana."],["Pizarro","calle","Bartolomé Pizarro (1777 a 1812), coronel; comandante del Regimiento de Pa- tricios de Cochabamba desde 1811; combate en Huaqui; en 1812 es tomado prisionero en la defensa de Cochabamba y fusilado el 4 de julio de 1812."],["Francisco Pizarro","calle","Francisco Pizarro (1478 a 1541), conquistador español; conquista el Perú; fundador de la ciudad de los Reyes, hoy Lima, en 1535."],["Pizzurno","calle","Carlos H. Pizzurno (1871 a 1948), pedagogo; fundador del Instituto Nacional de Enseñanza Primaria y Secundaria y director del mismo de 1890 a 1902; autor de El Argentino y Lecciones de Historia Argentina. Juan Tomás Pizzurno (1869 a 1945), pedagogo; colabora en el Instituto Nacional fundado por sus hermanos; presidente de los Consejos Escolares XII y XVIII de la Capital; miembro fundador de la Casa de Auxilios y de la Sociedad de Educación de Ramos Mejía. Pablo A. Pizzurno (1865 a 1940), pedagogo; director de la Escuela Superior José Manuel Estrada en 1887; fundador en 1890 del Instituto Nacional de Enseñanza Primaria y Secundaria; autor de La fiesta del árbol, Pininos y La escuela primaria. Homenaje conjunto a los hermanos Pizzurno."],["Planes","calle","Miguel Gregorio Planes (1789 a 1838), coronel; combate durante las Invasiones Inglesas, en el sitio de Montevideo de 1811 a 1814, en la Campaña al Alto Perú, Cepeda, Pavón, Gamonal y en la guerra contra el Brasil."],["Plaza","calle","Hilarión de la Plaza (1800 a 1871), coronel, combate en Chacabuco, Talcahuano, Maipú, en los sitios de Lima y el Callao, Zepita y en la guerra contra el Brasil. José María de la Plaza (1795 a 1857), general; combate en Chacabuco, Gavilán, Talcahuano, Maipú, Pasco, Junín y Ayacucho. Pedro Regalado de la Plaza (1787 a 1856), coronel; combate durante las Invasiones Inglesas, Tucumán, Salta, Chacabuco y Maipú."],["Doctor Victorino de la Plaza","calle","Victorino de la Plaza (1840 a 1919), jurisconsulto; vicepresidente de la República durante la presidencia de Roque Sáenz Peña de 1910 a 1913; presidente provisional hasta 1914, concluye como primer magistrado el período gubernamental hasta 1916."],["Plumerillo","calle","Plumerillo: campo próximo a la ciudad de Mendoza donde San Martín hizo instalar el campamento militar del Ejército de los Andes en 1815."],["Plus Ultra","calle","Plus Ultra: hidroavión en el que el aviador español Ramón Franco, acompañado por Julio Ruíz de Alda, Juan Manuel Durán y Pablo Rada, realiza entre el 22 de enero y el 10 de febrero de 1926 su famoso vuelo transatlántico entre Palos de Moguer y Buenos Aires."],["Plutarco","calle","Plutarco (46-120), escritor griego de Queronea; autor de Vidas Paralelas."],["Jose J. Podestá","calle","José J. Podestá (1858 a 1937), actor teatral uruguayo; se instala en Buenos Aires en 1882; en 1884 representa por primera vez el Juan Moreira de Eduardo Gutiérrez; actúa en El Payador, Ensalada criolla, Nazareno y La piedra del escándalo; autor de Medio siglo de farándula (memorias)."],["Pablo Podestá","calle","Pablo Podestá (1875 a 1923), actor dramático uruguayo; actúa en Barranca abajo, Los muertos, Alma gaucha, Facundo y El Arlequín."],["De los Poetas","jardín","De los Poetas: espacio del Rosedal del parque 3 de Febrero, tradicionalmente conocido con este nombre ya que se han emplazado bustos de destacados exponentes de la poesía."],["Pola","calle","Policarpa Salavarrieta (1792 a 1817), patriota colombiana conocida con el sobrenombre de La Pola, que fue fusilada en Bogotá durante la lucha por la independencia."],["Policía Federal Argentina","plazoleta","Policía Federal Argentina: homenaje al cuerpo de policía creado por decreto del 24-12-1943."],["Práctico Poliza","calle","Francisco Poliza (1861 a 1931), práctico marino de origen italiano que muere al negarse a abandonar el vapor Anglia, confiado a su pericia, que naufraga como consecuencia de un choque producido en aguas del Paraná contra otra embarcación."],["Polonia","calle","Polonia: país europeo. Capital: Varsovia."],["Ingeniero César Manuel Polledo","plazoleta","César Manuel Polledo (1902 a 1978), ingeniero civil y empresario; presidente y uno de los fundadores de la Cámara Argentina de la Construcción."],["Teniente Coronel Gregorio Pomar","calle","Gregorio Pomar (1892 a 1954), militar y político; edecán del presidente Hipólito Yrigoyen; encabeza en 1931 en Corrientes un levantamiento radical a raíz de la anulación de las elecciones en la provincia de Buenos Aires; diputado nacional en 1946."],["Nueva Pompeya","barrio","Nuestra Señora del Rosario de Pompeya: advocación de la Virgen María que se venera en el célebre santuario de la provincia de Nápoles en Italia, y bajo cuya dedicación nació en 1896 la primitiva capilla levantada por los padres capuchinos que dio desde entonces el nombre al barrio."],["Nueva Pompeya","plaza","Nueva Pompeya: homenaje al vecindario de este barrio."],["Aníbal Ponce","calle","Aníbal Ponce (1898 a 1938), escritor y psicólogo; miembro fundador del Colegio Libre de Estudios Superiores; autor de La gramática de los sentimientos, El viento en el mundo, Diario íntimo de una adolescente, Apuntes de viaje."],["María Ponce de Bianco","espacio verde","María Eugenia Ponce de Bianco (1924 a 1977), es la madre de Alicia Hilda, secuestrada en su casa el 30 de abril de 1976. Por tal motivo se contacta con otras madres que se encontraban en la misma situación y con quien forma el grupo fundacional de las Madres de Plaza de Mayo. Es secuestrada el 8 de diciembre de 1977 en la Iglesia de la Santa Cruz. Sus restos fueron finalmente identificados por el Equipo Argentino de Antropología Forense (EAAF), encontrados en el cementerio de General Lavalle, cuando se exhumaron siete cuerpos enterrados como NN después de haber sido encontrados en las costas de San Bernardo y Santa Teresita entre diciembre de 1977 y enero de 1978. A través de análisis de ADN pudo confirmarse que tres de esos cadáveres eran los de Esther Ballestrino de Careaga, María Ponce de Bianco y Azucena Villaflor de De Vincenti."],["Manuel Porcel de Peralta","calle","Manuel Porcel de Peralta (1823 a 1892), médico; actúa durante la guerra contra el Paraguay y durante la epidemia de fiebre amarilla de 1871; profesor de Clínica Médica desde 1874; decano de la Facultad de Medicina; concejal en Buenos Aires en 1880 y presidente de ese cuerpo en 1885."],["Portela","calle","Ireneo Portela (1802 a 1861), médico, presidente del Consejo de Higiene en 1852; ministro de Gobierno de Buenos Aires en 1854; miembro de las Convenciones Constituyentes de 1854 y 1860."],["La Porteña","calle","La Porteña: recuerda a la locomotora de ese nombre que fue la primera máquina ferroviaria que se introdujo en el país en 1857 y que el 29 de agosto de ese mismo año realizó su primer viaje entre la estación del Parque y Floresta."],["Portillo","calle","Cordón del Portillo: cordón montañoso que sigue en línea sur-sureste entre la cabecera del río Las Tunas y el tramo transversal del Tunuyán. Su paso más importante es el Portillo."],["Porto Alegre","plaza","Porto Alegre: ciudad del Brasil, capital del estado de Río Grande do Sul."],["Portugal","calle","Portugal: país europeo. Capital: Lisboa."],["Portugal","plaza","Portugal: país europeo. Capital: Lisboa."],["Posadas","calle","Gervasio Antonio Posadas (1757 a 1833), estadista; diputado por Córdoba en la Asamblea de 1813; miembro del Segundo Triunvirato; Director Supremo de 1814 a 1815."],["Doctor Alejandro Posadas","calle","Alejandro Posadas (1870 a 1902), médico; dicta en 1900 el curso oficial de Cirugía General en el Hospital de Clínicas; es el primer profesional que cuenta con un aparato de Rayos X en su servicio; jefe de la sala segunda del Hospital Teodoro Álvarez."],["Posta","calle","Posta: casa o lugar donde se hacía el relevo de los caballos y donde se proporcionaba descanso a los viajeros de las galeras o diligencias."],["Posta de Hornillos","calle","Posta de Hornillos: lugar de Jujuy a 100 kilómetros al sur de La Quiaca vinculado con la actuación de don Martín Miguel de Güemes."],["Potosí","calle","Potosí: ciudad de Bolivia capital del departamento del mismo nombre ubicada en la vertiente del cerro. Las minas de plata la transformaron en la ciudad más importante del Altiplano en el siglo XVI. POZOS, COMBATE DE LOS véase LOS POZOS, COMBATE DE."],["Francisco Pracánico","cantero central","Francisco Pracánico (1898 a 1971), pianista; compositor de Enfundá la mandolina, Corrientes y Esmeralda y Si se salva el pibe."],["Praga","calle","Praga: ciudad capital de Checoslovaquia y de la provincia de Bohemia Central."],["Arquitecto Alberto Prebisch","plaza","Alberto Horacio Prebisch (1898 a 1970), arquitecto; encabeza el movimiento de renovación de la arquitectura y el urbanismo en nuestro país; entre sus obras se destacan el Obelisco y los cines Gran Rex y Atlas de Buenos Aires; académico y presidente de la Academia Nacional de Bellas Artes; ocupa el cargo de intendente municipal de la ciudad de Buenos Aires entre 1962 y 1963; decano de la Facultad de Arquitectura y Urbanismo de la Universidad de Buenos Aires en el período de 1968 a 1970."],["Prefectura Naval Argentina","calle","Prefectura Naval Argentina: homenaje a la institución guardiana de los mares, ríos, canales y puertos nacionales; creada por Ley N° 3.445 del 29 de octubre de 1896."],["Prefectura Naval Argentina","plazoleta","Prefectura Naval Argentina: homenaje a la institución guardiana de los mares, ríos, canales y puertos nacionales; creada por Ley N° 3.445 del 29 de octubre de 1896."],["Primera Junta","calle","Primera Junta: primer gobierno patrio surgido de la Revolución del 25 de Mayo de 1810. 1° DE MAYO (calle). Ordenanza N° 12.220-1940, BM N° 6.093. 1° DE MAYO (plaza). Ordenanza N° 889 del 14-4-1925, BM N° 330. 1° de Mayo: homenaje al Día Internacional del Trabajo. Cabe señalar que en el caso de la calle, los fundamentos de la Ordenanza N° 12.220 establecen que con esta denominación se recuerda igualmente la fecha en que se firma la Constitución Argentina de 1853."],["Primera Junta","plaza","Primera Junta: primer gobierno patrio surgido de la Revolución del 25 de Mayo de 1810. 1° DE MAYO (calle). Ordenanza N° 12.220-1940, BM N° 6.093. 1° DE MAYO (plaza). Ordenanza N° 889 del 14-4-1925, BM N° 330. 1° de Mayo: homenaje al Día Internacional del Trabajo. Cabe señalar que en el caso de la calle, los fundamentos de la Ordenanza N° 12.220 establecen que con esta denominación se recuerda igualmente la fecha en que se firma la Constitución Argentina de 1853."],["Juan Bautista Prímoli","calle","Juan Bautista Prímoli (1673 a 1747), arquitecto y religioso jesuita; proyecta y dirige la construcción del Cabildo de Buenos Aires en 1719; con el jesuita Andrés Blanqui construye las iglesias de San Francisco, San Telmo, del Pilar y la Merced."],["Coronel Pringles","plaza","Juan Pascual Pringles (1795 a 1831), militar; combate en Pescadores, en la ocupación de Lima y en el asedio del Callao, en Pasco, Junín, Ayacucho y en la guerra contra el Brasil; gobernador de San Luis en 1829."],["Enrique Prins","calle","Enrique Prins (1873 a 1943), médico, músico y pintor; jefe de sala del Hospital Carlos G. Durand; autor de los óleos Paisaje y El Recodo."],["Prisioneros de la Tierra","cantero central","Prisioneros de la Tierra: película dirigida por Mario Soffici en 1939, protagonizada por Ángel Magaña y Francisco Petrone."],["Luca Prodan","plazoleta","BO Nº 2.974 Luca George Prodan (1953 a 1987), músico, cantante y compositor; nacido en Italia; de madre escocesa, se radica en la Argentina en 1981; es el líder de la banda de rock Sumo y autor de Mañana en el Abasto."],["El Profeta de la Pampa","calle","El Profeta de la Pampa: obra de don Ricardo Rojas aparecida en 1945, y que se refiere a Domingo Faustino Sarmiento."],["Del Progreso","calle","Progreso: nombre tradicional que alude al mejoramiento y modernidad de las condiciones de vida del país. Diversas calles de la ciudad se denominaron de esta manera. Entre ellas las actuales Pedro Echagüe de 1893 a 1922, Pinzón de 1882 a 1893, Bogotá hasta 1893 y la avenida de los Incas hasta 1904."],["Prometeo","calle","Prometeo: personaje de la mitología griega que roba el fuego del cielo para uso de los hombres por lo que es castigado por Zeus quien lo encadena a una roca; es libertado por Hércules."],["Las Provincias","calle","Provincias: homenaje a las provincias que componen la República Argentina."],["Provincias Unidas","calle","Provincias Unidas del Río de la Plata: primera denominación oficial de la República Argentina al constituirse el Triunvirato ejecutivo el 23 de septiembre de 1811."],["Teniente Manuel Silvestre Prudán","calle","Manuel Silvestre Prudán (1800 a 1824), militar; combate en Vilcapugio; cae prisionero tras la sublevación de El Callao en 1824 y junto con Millán, declaran haber sido ellos quienes encubren la fuga del comandante Estomba y de Luna, por lo que son fusilados."],["Carlos de la Púa","plazoleta","Carlos de la Púa: seudónimo de Carlos Raúl Muñoz del Solar (1898 a 1950), poeta; autor de El sapo violeta y La crencha engrasada."],["Puán","calle","Puán: ciudad y partido de la provincia de Buenos Aires."],["Giácomo Puccini","plazoleta","Giácomo Puccini (1858 a 1924), compositor italiano; autor de La Bohéme, Tosca y Madame Butterfly."],["General Manuel Puch","calle","Manuel Puch (?-1870), militar; combate en Salta, Vilcapugio, Ayohuma, y Oncativo; participa en 1839 en la Coalición del Norte; gobernador de Salta en 1856 y 1857."],["Puente del Inca","calle","Puente del Inca: puente natural utilizado por los Incas, ubicado en el departamento de Las Heras, Mendoza, sobre el río Las Cuevas."],["Puerto Argentino","paseo/espigón","Puerto Argentino: nombre que recibe el 21 de abril de 1982, la ciudad de Puerto Stanley, la más importante de las Islas Malvinas, y con el que aún se la conoce en la Argentina."],["Puerto Madero","barrio","Puerto Madero: nuevo barrio de la ciudad que nace luego del cierre de las operaciones del viejo puerto de Buenos Aires concebido y concretado por Eduardo Madero (véase). El 28-1-1889 se habilita la Dársena Sur, y sucesivamente el Dique 1 (31-1-1890), el Dique 2 (28-9- 1890), el Dique 3 (31-3-1892), el Dique 4 y la Dársena Norte (7-3-1897)."],["Puerto Príncipe","calle","Puerto Príncipe: ciudad capital de Haití y del distrito de su nombre."],["Villa Pueyrredón","barrio","Este nombre data de 1907, cuando se denominó así a la estación Kilómetro 14 del Ferrocarril Central Argentino, hoy Bartolomé Mitre."],["Pueyrredón","avenida","Juan Martín de Pueyrredón (1777 a 1850), brigadier general; organiza en 1806 la resistencia contra las Invasiones Inglesas; gobernador delegado de Córdoba en 1810; comandante en Jefe del Ejército del Norte en 1811 y 1812; miembro del primer Triunvirato; diputado por San Luis en el Congreso de Tucumán; Director Supremo de 1816 a 1819."],["Pueyrredón","plaza","Juan Martín de Pueyrredón (1777 a 1850), brigadier general; organiza en 1806 la resistencia contra las Invasiones Inglesas; gobernador delegado de Córdoba en 1810; comandante en Jefe del Ejército del Norte en 1811 y 1812; miembro del primer Triunvirato; diputado por San Luis en el Congreso de Tucumán; Director Supremo de 1816 a 1819."],["Doctor Carlos Alberto Pueyrredón","plazoleta","Carlos Alberto Pueyrredón (1887 a 1962), jurisconsulto; intendente municipal de la ciudad de Buenos Aires desde el 6 de diciembre de 1940 hasta el 11 de junio de 1943; presidente de la Academia Nacional de la Historia; autor de En tiempos de los virreyes y La campaña de los Andes."],["Doctor Honorio Pueyrredón","avenida","Honorio Pueyrredón (1876 a 1945), jurisconsulto; ministro de Agricultura de la Nación en 1916 y de Relaciones Exteriores y Culto de 1917 a 1922; embajador en los Estados Unidos en 1922; elegido gobernador de Buenos Aires en 1931, los comicios son anulados por el gobierno provisional."],["Prilidiano Pueyrredón","calle","Prilidiano Pueyrredón (1823 a 1870), pintor e ingeniero; construye en Olivos la mansión de Miguel Azcuénaga (hoy residencia presidencial); técnico asesor de la Municipalidad de Buenos Aires; autor de Retrato de Manuelita Rosas, Gauchos, Lavanderas del Bajo Belgrano, Un alto en el camino y La siesta."],["Pujol","calle","Juan Gregorio Pujol (1817 a 1861), jurisconsulto; gobernador de Corrientes de 1852 a 1860."],["Pumacahua","calle","Mateo García Pumacahua (1748 a 1815), cacique y caudillo peruano; presidente interino de la Real Audiencia de Cuzco en 1812 abraza la causa de la independencia; encabeza y organiza la revolución de esa ciudad en 1814; es vencido en Humanchiri o Santa Rosa, tomado prisionero y decapitado."],["Puna","calle","Puna: altiplano del noroeste argentino a 3.500 metros sobre el nivel del mar que continúa el altiplano de Bolivia y que ocupa la parte occidental de Jujuy, Salta y Catamarca."],["Punta Arenas","calle","Punta Arenas: ciudad y puerto de Chile, capital de la provincia de Magallanes, donde se celebró el 15 de febrero de 1899 la entrevista entre el presidente argentino general Julio A. Roca y el chileno don Federico Errázuriz Echaurre, después de solucionarse el conflicto de límites entre ambas naciones."],["Liborio Pupillo","paseo","Liborio Pupillo (1916 a 1992), político y empresario vinculado a la industria de la carne; vecino del barrio de Mataderos, es uno de los fundadores del Movimiento de Renovación y Cambio, corriente interna de la Unión Cívica Radical; diputado nacional entre 1983 y 1987 y concejal de la Ciudad de Buenos Aires en 1991."],["Comodoro Py","calle","Luis Py (1819 a 1884), marino; combate durante la guerra contra el Paraguay; manda la escuadra que en 1878 realiza la expedición al sur patagónico; actúa durante la revolución de 1880. Notas."],["Ingeniero José N. Quartino","avenida","José N. Quartino (?-1948), ingeniero; secretario de Obras Públicas de la Municipalidad de Buenos Aires durante la intendencia de Joaquín Llambías; dirige las obras del Balneario Municipal, del primer tramo de la avenida Tristán Achával Rodríguez y de la canalización del arroyo Cildáñez."],["Quebracho","calle","Quebracho: árbol característico del norte argentino y de América, en general muy apreciado por su madera durísima e incorruptible."],["La Quena","calle","Quena: voz quechua que designa a la flauta pentatónica utilizada por los aborígenes para acompañar sus cantos; es el más famoso de los instrumentos musicales originarios de América del Sur."],["Querandíes","calle","Querandíes: aborígenes de la región pampeana que habitaban el territorio de la actual provincia de Buenos Aires al iniciarse la conquista del Río de la Plata."],["Querol","calle","Agustín Querol y Subirats (1860 a 1909), escultor español; autor del monumento del general Urquiza (Paraná) y del monumento donado a la Nación por la colectividad española denominado “La Carta Magna y las cuatro regiones argentinas” (popularmente conocido por Monumento de los Españoles)."],["Quesada","calle","Dionisio Quesada (1793 a 1879), coronel; combate en los sitios de Montevideo; edecán de los directores Pueyrredón, Soler y Rondeau; combate en Cepeda, Cañada de la Cruz, San Nicolás, Gamonal y en el sitio de Buenos Aires de 1852. Juan Isidro Quesada (1802 a 1876), coronel; combate durante las Invasiones Inglesas, en el segundo sitio de Montevideo, Sipe-Sipe, en la toma de Lima, Junín, Ayacucho y en la guerra contra el Brasil; edecán de Rosas y Balcarce; combate contra el indio, en Caseros y Cepeda; es sobrino de Juan José. Juan José Quesada (1790 a 1832), coronel, hermano del primero; combate en Las Piedras, en el segundo sitio de Montevideo, en Sipe-Sipe y en la guerra contra el Brasil. Sixto Quesada (1800 a 1840), coronel, hermano de Dionisio y de Juan José; combate en Sipe-Sipe, Cepeda, en la expedición al desierto de Martín Rodríguez, en la guerra contra el Brasil y en Navarro."],["Quevedo","calle","Francisco de Quevedo y Villegas (1580 a 1645), escritor español; autor de El buscón, Los sueños y Letrillas, jácaras y romances."],["El Quijote","calle","Don Quijote de la Mancha: novela cumbre de don Miguel de Cervantes Saavedra y de la literatura española."],["Quilmes","calle","Quilmes: ciudad y partido de la provincia de Buenos Aires. 15 DE NOVIEMBRE DE 1889 (calle). Ordenanza del 23-5-1912. 15 de Noviembre de 1889: fecha en que fue proclamada la República del Brasil, constituyéndose un gobierno provisorio presidido por el mariscal Deodoro da Fonseca, acompañado por Quintino Bocayuva, Floriano Peixoto y Ruy Barbosa."],["De Flora Nativa Benito Quinquela Martín","Parque","El parque lleva en su nombre el aditamento de “flora nativa” porque está ornamentado con especies vegetales nativas. La única excepción a ello son los perales que recuerdan la plantación de estas especies realizada en este lugar en el siglo XIX. Benito Quinquela Martín (1890 a 1977), artista plástico; es el pintor del Riachuelo y de la Boca, en sus cuadros transmite el trabajo, el dolor y la alegría del puerto; entre sus obras se destacan Carnaval en la Boca, Cargadores de carbón y Escenas de trabajo."],["Quintana","calle","Hilarión de la Quintana (1774 a 1841), general; combate durante las Invasiones Inglesas; teniente de gobernador de Tucumán en 1814 y gobernador interino de Salta; edecán del general San Martín en 1817; combate en Chacabuco; Director Supremo de Chile por delegación de O´Higgins en 1817, hace declarar la independencia del país trasandino y crea su bandera; combate en Cancha Rayada y Maipú."],["José de la Quintana","calle","José de la Quintana (1810 a 1881), jurisconsulto; diputado por Jujuy en el Congreso de 1853 junto con Manuel Padilla; gobernador de esa provincia de 1859 a 1861."],["Presidente Quintana","avenida","Manuel Quintana (1835 a 1906), jurisconsulto; presidente de la República de 1904 a 1906, cuando al fallecer, el 12 de marzo, es sucedido por su vicepresidente, Dr. José Figueroa Alcorta."],["Lidoro J. Quinteros","avenida","Lidoro J. Quinteros (1848 a 1907), político; diputado nacional de 1874 a 1882, actúa en los sucesos de 1880 que culminaron en la federalización de la ciudad de Buenos Aires; gobernador de Tucumán de 1887 a 1889."],["Quirno","calle","Norberto de Quirno y Echandía (1776 a 1849), comerciante español; combate durante las Invasiones Inglesas con el grado de capitán de la Tercera Compañía del Batallón Voluntarios de Cántabros; poseedor de una chacra en Flores, donde hoy se encuentra esta calle, es el primero que organiza en nuestro país la industria lechera."],["Doctor Norberto Quirno Costa","calle","Norberto Quirno Costa (1844 a 1915), jurisconsulto, ministro de Relaciones Exteriores durante la presidencia de Juárez Celman de 1886 a 1889; ministro del Interior del mismo presidente de 1889 a 1890 y del presidente Uriburu de 1896 a 1897; vicepresidente de la República de 1898 a 1904."],["Adán Quiroga","plazoleta","Adán Quiroga (1863 a 1904), jurisconsulto, poeta, arqueólogo y periodista; fundador de El Combate de Catamarca y El Nacional de Tucumán; autor de Flores del aire (poesía), Calchaquí. Historia de la conquista del noroeste y La Cruz en América."],["Bm N° 14.862. Quiroga, Brigadier General Juan Facundo N° 29.499-1974","calle","Juan Facundo Quiroga (1788 a 1835), militar y político; gobernador de La Rioja en 1823 cuando derroca a Dávila, y desde entonces caudillo máximo de su provincia; vencedor en la Tala y Ciudadela."],["Horacio Quiroga","calle","Horacio Quiroga (1878 a 1937), escritor uruguayo; autor de Cuentos de amor, de locura y de muerte, Cuentos de la selva, Los desterrados, Anaconda y El desierto."],["Rosita Quiroga","plazoleta","Rosa Rodríguez Quiroga de Capiello (1901 a 1984), cantante y compositora; son suyos los tangos De estirpe criolla y Carta brava. Heredera directa del payador, se expresa en su canto con la misma cadencia arrabalera con la que hablaba."],["Quirós","calle","Pedro de Quirós (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Quito","calle","Quito: ciudad capital del Ecuador y de la provincia de Pichincha. Notas."],["Intendente Francisco Rabanal","avenida","Francisco Rabanal (1906 a 1982), político; intendente de Buenos Aires de 1963 a 1966."],["Itzhak Rabin","plazoleta","Ytzhak Rabin (1922 a 1995), militar israelí; combate en la primera guerra árabeisraelí; primer ministro de Israel en dos oportunidades; entabla las negociaciones que conducen a los acuerdos de Oslo firmados en Washington el 13 de septiembre de 1993, al cabo de las cuales, Arafat regresa a Gaza como titular de un gobierno autónomo con autoridad inicialmente sobre la Franja de Gaza y Jericó. Firma también el Tratado de Paz alcanzado con el rey Hussein de Jordania, el 26 de octubre de 1994. Sus esfuerzos fueron reconocidos con la concesión, junto a Yasser Arafat y a Shimon Peres, del Premio Nóbel de la Paz de 1994. En 1995 al retirarse de una asamblea por la paz, bajo el lema Sí a la paz no a la Violencia, es asesinado."],["Elsa Rabinovich de Levenson","vereda peatonal y jardín","Elsa Rabinovich de Levenson (1911 a 1977), madre de Bernardo Levenson asesinado el l9 de mayo de 1976; es detenida el 17 de febrero de 1977. Fue vista por última vez en la Escuela de Mecánica de la Armada. Permanece desaparecida."],["Teniente General Eduardo Racedo","calle","Eduardo Racedo (1843 a 1918), militar; combate en Pavón y en la guerra contra el Paraguay; marcha con Roca en la expedición al Río Negro de 1879; gobernador de Entre Ríos en 1883; ministro de Guerra y Marina en dos oportunidades. RADIOAFICIONADOS VOLUNTARIOS VETERANOS DE GUERRA (espacio verde). Ley Nº 1.418-2004, BO Nº 2.032. Radioaficionados Voluntarios Veteranos de Guerra: homenaje a los radioaficionados integrantes de la red de observadores del aire por su desempeño en el conflicto del Atlántico Sur de 1982."],["Teniente General Eduardo Racedo","plazoleta","Eduardo Racedo (1843 a 1918), militar; combate en Pavón y en la guerra contra el Paraguay; marcha con Roca en la expedición al Río Negro de 1879; gobernador de Entre Ríos en 1883; ministro de Guerra y Marina en dos oportunidades. RADIOAFICIONADOS VOLUNTARIOS VETERANOS DE GUERRA (espacio verde). Ley Nº 1.418-2004, BO Nº 2.032. Radioaficionados Voluntarios Veteranos de Guerra: homenaje a los radioaficionados integrantes de la red de observadores del aire por su desempeño en el conflicto del Atlántico Sur de 1982."],["Rafaela","calle","Rafaela: ciudad cabecera del departamento de Castellanos, provincia de Santa Fe."],["Romeo Raffo Bontá","plazoleta","Romeo Raffo Bontá (1880 a 1954), vecino del barrio de Villa del Parque, donde vivió desde 1902 hasta el día de su muerte; trabaja por el mejoramiento de la ciudad y es el iniciador de la campaña destinada a establecer el 11 de junio como Día del Vecino, celebración instituida por la Asociación Vecinal de Villa del Parque en 1946 y aceptada por la Municipalidad en 1959."],["María Raggio de Battini","cantero central","María Raggio de Battini (1863 a 1937), maestra y directora de la primera Escuela de Niñas categoría infantil Nº 9, conocida como Escuela de la Recova habilitada el 15 de septiembre de 1897 en el ala sur de la recova del edificio de la administración del Mercado de Hacienda del barrio de Mataderos."],["Ramallo","calle","Nicasio Ramallo (?-1823), teniente coronel; combate en Chacabuco, Cancha Rayada, Maipú, Chillán, Bío-Bío y en la expedición al Perú."],["Carlos María Ramírez","calle","Carlos María Ramírez (1848 a 1898), jurisconsulto, escritor y político uruguayo; participa en el movimiento revolucionario de 1886; autor de Los palmares y Los amores de María."],["Comodoro Ceferino Ramírez","calle","Ceferino Ramírez (1837 a 1893), marino; combate en Pavón y en la guerra contra el Paraguay; comandante del acorazado Los Andes, participa en 1879 en la campaña del Río Negro; a cargo del Villarino conduce a Buenos Aires los restos del general San Martín; participa de 1883 a 1884 en la campaña del Chaco."],["Eugenio Ramírez","calle","Eugenio Ramírez (¿-?), teniente coronel; combate en Chacabuco y Maipú. Eugenio F. Ramírez (1855 a 1910), médico, hijo del anterior; director de la Asistencia Pública e inspector del Departamento Nacional de Higiene; ministro de Gobierno de Corrientes durante el gobierno de Manuel Derqui. Eugenio Ramírez (?-1926), teniente coronel, hijo del anterior; actúa como diplomático; inspector de Caballería del Ejército. Homenaje conjunto a los tres familiares."],["General Francisco Ramírez","plazoleta","José Francisco Ramírez (1786 a 1821), militar y político; vencedor en Cepeda; jefe supremo de la República de Entre Ríos desde 1820."],["Juan Ramírez de Velazco","calle","Juan Ramírez de Velasco (?-1597), conquistador español; gobernador del Tucumán de 1584 a 1593; fundador de la ciudad de La Rioja en 1591. RAMÓN y CAJAL (calle). Ordenanza N° 1.697 del 30-6-1926, BM N° 838. Santiago Ramón y Cajal (1852 a 1934), médico histólogo y escritor español; autor de Manual de Histología y técnica micrográfica; Premio Nobel de Medicina (compartido con C. Golgi) en 1906 por su investigación acerca de la estructura del sistema nervioso; autor de Recuerdos de mi vida, Charlas de café y El mundo visto a los ochenta años. Cabe señalar en este caso que este homenaje fue realizado en vida del prestigioso médico."],["Ramos Mejía","calle","Ildefonso Raimundo Ramos Mejía (1759 a 1854), comerciante y funcionario; gobernador provisorio de Buenos Aires en 1820; auxilia económicamente al general Belgrano en víspera de su muerte; diputado al Congreso de 1826."],["Doctor José María Ramos Mejía","avenida","José María Ramos Mejía (1849 a 1914), médico y escritor; director de la Asistencia Pública de Buenos Aires; presidente del Departamento Nacional de Higiene y del Consejo Nacional de Educación; fundador y presidente del Círculo Médico Argentino; promotor de la enseñanza de la psiquiatría en el país; autor de Las neurosis de los hombres célebres, Rosas y su tiempo y La locura en la historia."],["Ramsay","calle","Roberto Ramsay (1773 a 1854), almirante inglés; comandante del bergantín Mistletoe y de las fuerzas navales de S.M. Británica en el Río de la Plata, garantiza en 1810 la libre navegación mereciendo por ello el reconocimiento de la Junta; interviene en 1811 en la resolución que evita el bombardeo de la escuadra española."],["El Rancho","calle","Rancho: nombre de la vivienda campesina cuya construcción varía de acuerdo con los materiales más abundantes de cada lugar."],["Ranqueles","calle","Ranqueles: parcialidad de araucanos que tuvieron su hábitat en el sur de San Luis."],["El Rastreador","calle","Rastreador: recuerda a los gauchos que por poseer capacidad para ello se dedicaban a seguir el rastro dejado por personas o por animales."],["Rastreador Fournier","calle","Rastreador Fournier: patrullero naval argentino que naufragó al sur de Punta Arenas (Chile) el 21 de septiembre de 1949 perdiendo la vida setenta y siete personas."],["Rauch","calle","Federico Rauch (1790 a 1829), coronel de origen alemán; combate en 1823 contra los indios en el partido de Rojas; en 1825 realiza una expedición a Tandil; combate en las Vizcacheras, donde es derrotado y decapitado por los indios el 29 de marzo de 1829."],["Raulet","calle","Pedro RauIet (¿1790?-¿1850?), coronel de origen francés; uno de los fundadores de la Orden del Sol de Perú en 1821, luego de haber actuado en el Ejército de los Andes, en Chile y Perú."],["Raulíes","calle","Raulíes: paso de la Cordillera de los Andes en la provincia de Río Negro, constituye uno de los límites entre la Argentina y Chile."],["Doctor Emilio Ravignani","calle","Emilio Ravignani (1886 a 1954), historiador y jurista; creador y director del Instituto de Investigaciones Históricas de la Facultad de Filosofía y Letras de Buenos Aires; subsecretario de Hacienda de la Municipalidad de 1922 a 1927; diputado nacional de 1936 a 1940, 1940 a 1943 y 1946 a 1950; autor de Historia del Derecho Argentino; Historia Constitucional de la República Argentina y Asambleas constituyentes argentinas."],["Profesora Marina Margarita Ravioli","cantero central","Marina Margarita Ravioli (1901 a 1977), educadora; maestra normal nacional y profesora Superior en Letras; directora desde 1937 del Instituto de Forma- ción Docente para Maestras Jardineras de la Argentina (actual ISPEI Sara Chamberlain de Eccleston)."],["Rawson","calle","Guillermo Rawson (1821 a 1890), médico; diputado por San Juan al Congreso de Paraná en 1854; senador en 1862; ministro del Interior de Mitre; inaugura en 1873 el primer curso de Higiene Pública; autor de Estadística vital de la ciudad de Buenos Aires."],["Elvira Rawson de Dellepiane","avenida-boulevard","Elvira Rawson de Dellepiane (1867 a 1954), médica, profesora de higiene, fundó en 1916 la primera colonia para niños débiles de Uspallata (Mendoza); médica inspectora del Departamento Nacional de Higiene de 1907 a 1908; propulsora de los derechos femeninos."],["José Razzano","plazoleta","José Razzano (1887 a 1960), cantor y compositor uruguayo; conocido como El Oriental; formó un renombrado dúo con Carlos Gardel; autor de Café de los Angelitos y Camino del Tucumán."],["Villa Real","barrio","Villa Real: esta denominación es impuesta por el ferrocarril Buenos Aires al Pacífico (luego San Martín), por Decreto del 18 de marzo de 1909, a la estación ubicada en Irigoyen y Tinogasta, demolida en 1995. Sobre el motivo por el cual se elige el nombre de Real, la Dirección General de Vías de Comunicación del Ministerio de Obras Públicas señala que es “el de una conocida quinta existente en sus cercanías”. Se trata de “la casa del Virrey”, como se denominaba a la propiedad de Juan Pedro de Córdova donde se albergó el virrey Sobremonte al producirse la Invasión Inglesa de 1806, antes de dirigirse hacia Córdoba. La casa es la misma que poseyera anteriormente don Pedro Fernández de Castro, cuyo nombre se perpetúa en el vecino barrio de Monte Castro. En la edición anterior de este libro mencionamos una nueva hipótesis relacionada con la fábrica de cigarrillos Amministrazione Autónoma del Monopolio di Tabacchi que debe ser descartada por anacrónica."],["Gustavo Rearte","pasaje peatonal","Gustavo Rearte (1932 a 1973), dirigente sindical; obrero en la fábrica Siam y después en Jabón Federal; secretario general del Sindicato de Jaboneros y Perfumeros; tras la caída del general Perón en 1955, lucha desde la clandestinidad, en la llamada resistencia peronista. Es uno de los fundadores de la Juventud Peronista en 1957; participa en la toma del frigorífico Lisandro de la Torre y escribe el documento de Huerta Grande que marca un hito en la historia del movimiento obrero."],["El Recado","calle","Recado: conjunto de piezas que constituyen el apero de montar."],["Paseo de la Recoleta","plazoleta","Recoleta: esta denominación proviene del Convento de los Padres Recoletos y su iglesia anexa de Nuestra Señora del Pilar, inaugurada el 12 de octubre de 1732."],["Reconquista","calle","La Reconquista por Orden del Gobernador de Buenos Aires del 9 de octubre de 1848. En el Plano Administrativo de la Capital del Estado Argentino de Buenos Ayres por el ingeniero Nicolás Grondona, Año 1856, su nombre actual. Reconquista: recuerda la gloriosa Reconquista de Buenos Aires de la dominación británica llevada a cabo el 12 de agosto de 1806."],["Recuerdos de Provincia","calle","Recuerdos de Provincia: obra de Domingo Faustino Sarmiento publicada a fines de 1850."],["Teniente Coronel Casimiro Recuero","calle","Casimiro Recuero (1802 a 1850), militar; combate en Chile en 1818, en Perú en 1820 y en Ecuador en 1823; asiste a la toma de Lima y a las batallas de Miravé, lca, Pichincha, Torata y Moquegua."],["El Refrán","calle","Refrán: recuerda al dicho agudo y sentencioso de uso común."],["Horacio Rega Molina","plazoleta","Horacio Rega Molina (1899 a 1957), poeta y periodista; autor de La hora encantada, El poema de la lhvia, La víspera del buen amor, Azul de mapa, La posada del león y Sonetos de mi sangre. REGIMIENTO DE PATRICIOS véase PATRICIOS, REGIMIENTO DE. REGIMIENTO 10 DE CABALLERÍA HÚSARES DE PUEYRREDÓN véase HÚSARES DE PUEYRREDÓN, REGIMIENTO 10 DE CABALLERÍA. REGIMIENTO I PATRICIOS véase PATRICIOS, REGIMIENTO I. REGIÓN BASILICATA véase BASILICATA, REGIÓN."],["Remedios","calle","Remedios: nombre tradicional que se remonta al siglo XVIII, cuando la Hermandad de la Santa Caridad erigió un oratorio consagrado a Nuestra Señora de los Remedios. En 1828, secularizada la Hermandad, don Domingo Olivera adquirió la vieja quinta e instaló en ella su chacra Los Remedios, cuyo núcleo ocupaba lo que es hoy el Parque Avellaneda."],["Renacimiento","calle","Renacimiento: época que comienza a mediados del siglo XV que despertó en Occidente un vivo entusiasmo por el estudio de la antigüedad clásica y que se caracteriza por el florecimiento de las manifestaciones artísticas y del pensamiento."],["Renán","calle","Ernesto Renán (1823 a 1892), historiador y filósofo francés; autor de El Anticristo, Averroes y el averroísmo, Historia General e Historia del pueblo de Israel."],["Renque Curá","calle","Renque Curá (¿-?), cacique pampa, hermano de Calfucurá y tío de Manuel Namuncurá; conduce una confederación de tribus de tamaño similar a la de su hermano; sus fuerzas son derrotadas el 5 de diciembre de 1883."],["Nicolás N° 19.010. Repetto","plazoleta","Nicolás Repetto (1871 a 1965), médico y político; autor de Lecciones de cirugía craneana, Hombres y problemas argentinos, Los socialistas y el ejército; diputado nacional de 1913 a 1924, de 1926 a 1930, de 1931 a 1940 y de 1942 a 1943. REPÚBLlCA (calle). Decreto del 22-9-1931, BM N° 2.679. República: forma de gobierno representativo en la que el poder reside en el pueblo, personificado éste en un presidente no hereditario. Se refiere a la forma de gobierno de nuestro país. REPÚBLlCA, DE LA (plaza). Mensaje del Intendente Municipal del 2-4-1929, BM N° 1.779, confirmada por Ordenanza N° 27.387-1973, BM N° 14.467. República: en conmemoración de la unidad de la República consagrada con la federalización de Buenos Aires el 21 de septiembre de 1880. REPÚBLICA SOCIALISTA DE VIETNAM véase VIETNAM."],["El Resero","plazoleta","El Resero: homenaje al hombre del campo especializado en las tareas de apartar y conducir el ganado destinado al mercado de hacienda, frigorífico o matadero. Es una voz de formación popular derivada de la palabra res. El nombre de esta plazoleta se relaciona con la escultura El Resero, de Emilio Jacinto Sarniguet, inaugurada el 25 de mayo de 1934."],["Reservistas Argentinos","avenida","Reservistas Argentinos: soldados que una vez terminado el servicio militar obligatorio, forman la guardia pasiva durante diez años."],["Resurrección","calle","Resurrección: recuerda la Resurrección de Cristo."],["Retiro","barrio","Retiro: se conoce así a esta zona de Buenos Aires desde principios del siglo XVIII, cuando el gobernador Agustín de Robles instala la Casa del Retiro en la esquina de las actuales Arenales y Maipú."],["Villa Riachuelo","barrio","Riachuelo: esta villa nace con este nombre en 1888, cuando la Sociedad de Tierras General Pobladora obtiene terrenos en la zona para rectificar el cauce del Riachuelo."],["Teniente General Pablo Bm N° 6.075-6. Riccheri","plaza","Pablo Riccheri (1859 a 1936), militar; ministro de Guerra de Roca de 1900 a 1904, es suyo el proyecto de servicio militar obligatorio sancionado como ley en 1901; creador de la Escuela de Mecánica; adquiere Campo de Mayo y Campo Los Andes."],["Gustavo Riccio","calle","Gustavo Riccio (1900 a 1927), poeta; autor de Un poeta de la ciudad y Gringo Purayhei."],["Coronel Rico","calle","Manuel Leoncio Rico (1798 a 1841), militar; participa en la Revolución del Sud en 1839; combate en Chascomús y en San Calá, donde cae prisionero y es fusilado poco después."],["General Rafael de Riego y Nuñez","plazoleta","Rafael de Riego y Núñez (1785 a 1823), militar español; en 1820 se subleva en Cabezas de San Juan con el ejército que debía venir a América para combatir los movimientos de independencia; es derrotado tres años más tarde y posteriormente ejecutado."],["Riestra","avenida","Norberto de la Riestra (1820 a 1879), economista y político; jefe de la casa bancaria inglesa Nicholson-Green en 1850; ministro de Hacienda de Buenos Aires con Obligado, Alsina y Mitre; miembro del Directorio del Ferrocarril del Oeste en 1863; vicegobernador de Buenos Aires en 1864."],["Riglos","calle","Marcos José de Riglos (1719 a 1791), funcionario; trabaja activamente en la fundación de la Casa de Expósitos durante el gobierno del virrey Vértiz, regidor y alcalde del Cabildo de Buenos Aires."],["Rincón","calle","Rincón: batalla librada en el Rincón de las Gallinas, en territorio uruguayo, el 24 de septiembre de 1825 durante la guerra contra el Brasil, entre las fuerzas dirigidas por el comandante uruguayo Rivera y el coronel brasileño Jardim."],["Rincón Verde-Kasú Mapún","plazoleta","Rincón Verde-Casú Mapún: traducción literal al mapuche de “tierra verde”. De acuerdo con Wilhelm de Moesbach, Padre Ernesto, Diccionario Español Mapuche, Buenos Aires, Siringa Libros, 1984 y Wilhelm de Moesbach, P. E.; Meyer Rusca, Walterio; Vúletin, Alberto y Suárez, Eduardo, Nuevo diccionario mapuche español, nombres propios mapuches, topónimos del Neuquén y mitologías patagónicas, Neuquén, Siringa Libros 1993, la grafía correcta es Carü Mapú. Esta denominación surge a raíz del pedido de la comunidad educativa de la Escuela Nº 23 del Distrito Escolar Nº 11, cuyos alumnos transformaron este espacio abandonado en un jardín. Además, como habían estudiado las diversas culturas aborígenes de nuestro país, solicitaron incorporar las señaladas palabras en lengua mapuche."],["Riobamba","calle","Riobamba: combate librado en Ecuador el 21 de abril de 1822 entre las tropas realistas y los granaderos a caballo mandados por Lavalle. RÍO COLORADO véase COLORADO, RÍO."],["Río Cuarto","calle","Río Cuarto: ciudad y departamento de la provincia de Córdoba, situada sobre el río del mismo nombre."],["Río de Janeiro","calle","Río de Janeiro: antigua capital de Brasil, hoy ciudad capital del estado de Guanabara."],["Río Grande","calle","Río Grande do Norte: estado de Brasil; capital: Natal. Río Grande do Sul: estado del Brasil; capital: Porto Alegre. Homenaje a los dos estados de la república hermana. RÍO LIMAY véase LIMAY, RÍO."],["Provincia de Río Negro","cantero central","Río Negro: provincia de la República Argentina. Capital: Viedma."],["Río Piedras","calle","Río Piedras: localidad del departamento de Metán, Salta, que toma su nombre del río pedregoso en cuya margen se libró en 1812 el combate entre la vanguardia del Ejército del Norte y los realistas. RÍO SALADO véase SALADO, RÍO."],["Buenaventura Risso Patrón","calle","Buenaventura Risso Patrón (1811 a 1884), sacerdote; obispo de Salta desde 1860; impulsa la difusión del catolicismo por medio de la prensa y surgen así El Creyente (Catamarca), La Esperanza (Salta), La Fe (Jujuy) y El Fiel Católico (Santiago del Estero)."],["Rivadavia","avenida","Bernardino de la Trinidad González Rivadavia (1780 a 1845), político; presidente de la Argentina de 1826 a 1827."],["Rivadavia","parque","Bernardino de la Trinidad González Rivadavia (1780 a 1845), político; presidente de la Argentina de 1826 a 1827."],["Comodoro Martín Rivadavia","avenida","Martín Rivadavia (1852 a 1901), marino; combate durante la guerra contra el Paraguay; comanda en 1888 la corbeta La Argentina en su primer viaje de instrucción; ministro de Marina de Roca en 1898, es el autor de la ley de servicio militar para la Armada."],["Doctor Rodolfo Rivarola","calle","Rodolfo Rivarola (1857 a 1942), jurisconsulto y escritor; autor de Fernando en el Colegio, Instituciones del Derecho Civil, Partidos políticos unitario y federal. Ensayo de política, La condena condicional y Enciclopedia de la Constitución Argentina."],["Pantaleón Rivarola","calle","Pantaleón Rivarola (1757 a 1821), poeta y profesor de filosofía; precursor de la lírica argentina, es el autor de La Heroica Defensa y Romance heroico en que se hace relación de la gloriosa Reconquista de la ciudad de Buenos Aires."],["Doctor Alfredo Rivas","plazoleta","Alfredo Rivas (1898 a 1952), médico y político; presidente de la octava circunscripción capitalina de la Unión Cívica Radical en 1954; miembro de la mesa directiva del Comité de la Capital; autor de Síndrome secundario de Marfan y Elongación de cono terminal de médula espinal."],["General Rivas","calle","Ignacio Rivas (1827 a 1880), general; combate en Caseros, Tapalqué, Pavón y en la guerra contra el Paraguay; comandante en jefe de la Frontera Sur, Costa Sur y Bahía Blanca, vence a Calfucurá en San Carlos."],["Diego Rivera","cantero central","Diego Rivera (1886 a 1957) artista plástico mexicano; es uno de los protagonistas del movimiento de muralistas de su país, cuya influencia se propaga en toda América; su temática es de contenido social e indigenista; trabaja en diversos edificios públicos, como el Palacio Nacional donde queda inconcluso un imponente mural épico sobre la historia de México, o la obra La tierra fecunda en la Escuela Nacional de Agricultura de Chapingo."],["Doctor Pedro Ignacio Rivera","calle","Pedro Ignacio Rivera (1753 a 1833), jurisconsulto boliviano; diputado por Mizque en la Asamblea de 1813 y en el Congreso de Tucumán."],["General Fructuoso Rivera","calle","Fructuoso Rivera (1788 a 1854), militar uruguayo; combate en Las Piedras y en los sitios de Montevideo; firma en 1821 el acta de incorporación del Uruguay al Brasil; presidente del Uruguay de 1830 a 1834 y de 1839 a 1843."],["Rivera Indarte","calle","José Rivera Indarte (1814 a 1845), poeta y periodista; colabora en La Gaceta Mercantil; fundador de El Investigador de Montevideo; autor de Rosas y sus opositores y Tablas de sangre."],["Agustín Rivero Astengo","plazoleta","Agustín Rivero Astengo (1896 a 1951), escritor; autor de Ánfora llena, Aguas hondas, Fronda otoñal, Hombre de la organización nacional, Memoria histórico-militar del capitán José María Guerra, Carlos Pellegrini, Kierkegaard y Remansos."],["Francisco Antonio Rizzuto","plazoleta","Francisco Antonio Rizzuto (1883 a 1965), empresario de origen italiano; fundador del Instituto de Informes Comerciales VERITAS y de la revista del mismo nombre en 1919 y 1931, respectivamente, del Instituto Americano de Investigaciones Económicas, Jurídicas y Sociales en 1946 y de la Liga Pro Comportamiento Humano en 1964; autor de Autorretrato al pastel y Espigas de oro."],["Robertson","calle","Guillermo Parish Robertson (1792-?), viajero, escritor y comerciante escocés. Juan Parish Robertson (1792 a 1843), viajero, escritor y comerciante escocés. Homenaje a los hermanos cuyas obras representan valiosos testimonios de la primera mitad del siglo XIX; son autores de La Argentina en los primeros años de la Revolución y Cartas de Sudamérica."],["Juan Francisco de la Robla","calle","Juan Francisco de la Robla (1774 a 1842), sacerdote uruguayo; capellán castrense durante las Invasiones Inglesas; párroco de Nuestra Señora de Guadalupe en Canelones; diputado al Congreso de la Florida en 1825 y presidente del mismo, suscribe las Leyes Fundamentales."],["Coronel Roca","avenida","José Segundo Roca (1800 a 1866), militar; combate en Jauja, Pasco, Pichincha, Zepita, Trujillo, Junín y en las guerras contra el Brasil y el Paraguay."],["Presidente Julio A. Roca","parque","Julio Argentino Roca (1843 a 1914), general; comanda en 1879 la expedición al desierto; presidente de la República de 1880 a 1886 y de 1898 a 1904. Con respecto a la avenida, la Ley N° 1.682 de 2005 adopta en forma oficial el nombre popular de Diagonal Sur con el que esta avenida es conocida desde que en la década de 1910 se concreta su trazado diagonal que se destaca por quebrar el tradicional cuadriculado de las calles de Buenos Aires."],["Rocamora","calle","Tomás de Rocamora (1740 a 1819), coronel; fundador de Gualeguay, Gualeguaychú y Concepción del Uruguay en 1783; teniente de gobernador de Misiones en 1810."],["Rocha","calle","Antonio Rocha (¿-?), vecino propietario de las tierras de este lugar de La Boca y con cuyo nombre se identifica al recodo del Riachuelo conocido como Vuelta de Rocha desde 1635. Es en este lugar donde precisamente nace esta calle y del cual toma su denominación según la versión de Paul Groussac. El origen de este nombre, no obstante, aún suscita controversias y don Antonio J. Bucich, en su libro Origen y evolución de la nomenclatura boquense, menciona otras versiones aunque sin inclinarse por ninguna."],["Dardo Rocha","calle","Dardo Rocha (1838 a 1921), jurisconsulto; gobernador de Buenos Aires de 1880 a 1884; fundador de la ciudad de La Plata."],["Rochdale","calle","Rochdale: ciudad de Inglaterra en el condado de Gran Manchester donde se produjeron las primeras experiencias de cooperativismo obrero. Es un importante centro industrial y textil."],["Rodney","calle","César Augusto Rodney (1772 a 1824), diplomático norteamericano; comisionado por su gobierno en 1818 para estudiar si convenía reconocer la Inde- pendencia de las Provincias Unidas del Río de la Plata, informa al gobierno en favor de tal reconocimiento; nombrado ministro plenipotenciario en Buenos Aires, fallece en esta ciudad."],["José Enrique Rodó","calle","José Enrique Rodó (1872 a 1917), escritor uruguayo; autor de Ariel, Motivos de Proteo y El mirador de Próspero."],["Alonso Rodríguez","calle","Alonso Rodríguez (1598 a 1628), sacerdote español; se desempeña en las misiones jesuitas del Paraguay y es asesinado por los aborígenes en 1628 junto con los padres Roque González y Juan del Castillo; fue beatificado en 1934."],["Fray Cayetano Rodríguez","calle","Cayetano José Rodríguez (1761 a 1823), sacerdote; diputado en la Asamblea de 1813 y en el Congreso de Tucumán, donde fue su redactor y el autor del Acta de la Declaración de la Independencia."],["General Manuel A. Rodríguez","calle","Manuel A. Rodríguez (1880 a 1936), militar; ministro de Guerra de la Nación durante la presidencia de Justo."],["Ignacio Fermín Rodríguez","calle","Ignacio Fermín Rodríguez (1790 a 1856), educador; director de la escuela de la Patria de San Juan en 1816; fue maestro de Domingo Faustino Sarmiento."],["Martín Rodríguez","calle","Martín Rodríguez (1771 a 1845), general; gobernador de la provincia de Buenos Aires de 1820 a 1824; comanda la expedición al desierto de 1823."],["Martín Rodríguez","plaza","Martín Rodríguez (1771 a 1845), general; gobernador de la provincia de Buenos Aires de 1820 a 1824; comanda la expedición al desierto de 1823."],["Petronila Rodríguez","plazoleta","Petronila Rodríguez (1815 a 1882), donante de los terrenos donde se construyó la capilla del Carmen, el colegio adyacente y el edificio que hoy ocupa el Ministerio de Educación y que anteriormente fuera sede del Consejo Nacional de Educación."],["Cabo de Patricios Orencio Pío Rodríguez","plazoleta","Orencio Pío Rodríguez (¿-?), cabo del tercio de Patricios; actúa valientemente y es herido durante la Reconquista de Buenos Aires en 1806. Es éste un nombre tradicional de la ciudad pues entre 1808 y 1822 se denominó Pío Rodríguez la actual avenida Santa Fe."],["Doctor José de Paula y Rodríguez Alves","calle","José de Paula y Rodríguez Alves (1884 a 1944), diplomático brasileño; embajador en la Argentina; vicepresidente de la Conferencia de la Paz del Chaco."],["Rodríguez Peña","calle","Nicolás Rodríguez Peña (1775 a 1853), militar y comerciante; actúa activamente durante la Revolución de Mayo; miembro del segundo Triunvirato; presidente del Consejo de Estado en 1813 y gobernador delegado de la Provincia Oriental en 1814."],["Rodríguez Peña","plaza","Nicolás Rodríguez Peña (1775 a 1853), militar y comerciante; actúa activamente durante la Revolución de Mayo; miembro del segundo Triunvirato; presidente del Consejo de Estado en 1813 y gobernador delegado de la Provincia Oriental en 1814."],["Roentgen","avenida","Guillermo Conrado Roentgen (1845 a 1923), físico alemán; descubridor de los rayos que llevan su nombre o rayos X; Premio Nobel de Física en 1901."],["Doctor Ángel H. Roffo","calle","Ángel H. Roffo (1882 a 1947), médico oncólogo; presidente de la Sociedad Internacional de Investigaciones contra la Tuberculosis y el Cáncer de París; autor de El Cáncer, La Química del Cáncer y Mortalidad por cáncer en la ciudad de Buenos Aires."],["Aviador Enrique Adrián Roger","calle","Enrique Adrián Roger (1888 a 1960), deportista, aviador, precursor de la aviación argentina; se inició en el motociclismo y el automovilismo; fundó y dirigió la primera revista especializada llamada La Argentina Automovilística entre 1908 y 1912."],["Coronel Rohde","calle","Jorge Rohde (1854 a 1903), militar de origen alemán; participa en 1879 en la campaña al Río Negro; explora en 1881 Bariloche, el Río Limay y el Nahuel Huapi; participa en 1883 en la campaña de los Andes; confecciona en 1885 el nuevo mapa del Gran Chaco y en 1889 los mapas de La Pampa, Río Negro y Neuquén; publica el Gran Mapa de la República Argentina."],["Rojas","calle","José María Rojas (1791 a 1852), teniente coronel; combate durante las Invasiones Inglesas; director del Parque de Artillería de 1815 a 1822. Juan Antonio Rojas (1787 a 1820), coronel; vencedor en Mojón y San Pedrito; participa en el combate del Bañado; muere en la defensa de Salta ante la invasión de los españoles en 1820. Juan Ramón Rojas (1784 a 1824), coronel y escritor; combate durante las Invasiones Inglesas y en el sitio de Montevideo en 1812; fundador de la Sociedad del Buen Gusto del Teatro; autor de A las provincias del interior oprimidas. Manuel Patricio Rojas (1792 a 1857), coronel; combate en Cotagaita, Suipacha, Tucumán, Salta, Pasco y Nazca; gobernador de Pasco. Paulino Rojas (1796 a 1835), coronel; combate en Chacabuco, Curapaligüe, Talcahuano, Maipú, Junín, Ayacucho y en la guerra contra el Brasil. Homenaje conjunto a los guerreros de la Independencia."],["Diego de Rojas","calle","Diego de Rojas (?-1544), capitán español; cumpliendo órdenes del gobernador del Perú parte de Cuzco en 1543 con el propósito de descubrir y conquistar las tierras que conformarán luego la gobernación del Tucumán; muere en un combate contra los indios Juríes."],["Doctor Ricardo Rojas","calle","Ricardo Rojas (1882 a 1957), escritor; autor de El país de la selva, Historia de la Literatura Argentina, Ollantay, El Santo de la Espada y El profeta de la Pampa."],["Belisario Roldán","avenida","Belisario Roldán (1873 a 1922), poeta; autor de La senda encantada, Letanías de la tarde y Bajo la toca de lino (poesías), El rosal de las ruinas, El puñal de los troveros y El burlador de mujeres (teatro), Cuentos de amargura (cuento) y Discursos completos."],["Belisario Roldán","plazoleta","Belisario Roldán (1873 a 1922), poeta; autor de La senda encantada, Letanías de la tarde y Bajo la toca de lino (poesías), El rosal de las ruinas, El puñal de los troveros y El burlador de mujeres (teatro), Cuentos de amargura (cuento) y Discursos completos."],["Roma","calle","Roma: ciudad capital de Italia y de la provincia de su nombre."],["Roma","plaza","Roma: ciudad capital de Italia y de la provincia de su nombre."],["Romero","calle","Florencio O. Romero (1840 a 1868), coronel; combate en Cepeda, Pavón y en la guerra contra el Paraguay, muriendo como consecuencia de las heridas recibidas en el combate de Lomas Valentinas."],["Doctor José Luis Romero","plazoleta","José Luís Romero (1909 a 1977), historiador; dirige el Centro de Estudios de Historia Social; miembro del grupo argentino de la Academia Internacional de Historia de las Ciencias y de la Academia de Ciencias de Buenos Aires; secretario de la Sociedad Argentina de Escritores; autor de Las ideas políticas en la Argentina; Latinoamérica: las ciudades y las ideas; Mitre: un historiador frente al destino nacional y El desarrollo de las ideas en la sociedad argentina del siglo XX."],["Domingo Romero","calle","Domingo Romero (1797 a 1866), funcionario; participa en la fundación del pueblo, hoy barrio, de Belgrano; primer juez de paz del mismo desde el 1° de enero de 1857 hasta enero de 1858."],["Francisco Romero","calle","Francisco Romero (1891 a 1962), filósofo, pensador y pedagogo español; autor de Filosofía Contemporánea, Filosofía de ayer y hoy, El hombre y la cultura y Estudios de historia de las ideas."],["Sargento Eduardo Romero","calle","Eduardo Romero (?-1908), sargento que junto con Eduardo Newbery realiza el vuelo en que el globo Pampero se pierde en el mar con sus dos tripulantes el 17 de octubre de 1908."],["Rondeau","calle","José Rondeau (1773 a 1844), general; combate durante las Invasiones Inglesas; jefe de las fuerzas patriotas en la Banda Oriental en 1811; general en jefe del Ejército del Alto Perú en 1814; director supremo en 1815 y de 1819 a 1820; gobernador interino de Buenos Aires en 1818; gobernador y capitán general provisorio de la República Oriental del Uruguay de 1828 a 1830."],["Franklin D. Roosevelt","calle","Franklin Delano Roosevelt (1882 a 1945), político norteamericano; presidente de los Estados Unidos en 1932 y reelegido sucesivamente en 1936, 1940 y 1944; visita Buenos Aires en 1936."],["Rosales","avenida","Leonardo Rosales (1792 a 1836), coronel de marina; combate durante la guerra contra el Brasil como comandante del bergantín Belgrano y de la goleta 8 de Febrero."],["Capitán Claudio H. Rosales","calle","Claudio H. Rosales (1897 a 1930), militar; muere durante la revolución del 6 de septiembre de 1930 en un accidente aéreo en Campo de Mayo."],["Rosario","calle","Rosario: ciudad de la provincia de Santa Fe."],["Rosario de la Frontera","calle","Rosario de la Frontera: ciudad y departamento de la provincia de Salta."],["Nuestra Señora del Rosario","espacio público","Nuestra Señora del Rosario: Advocación de la Virgen del Rosario cuya festividad instituyó el papa Pío V, en agradecimiento por la victoria de Lepanto ocurrida el 7 de octubre de 1571."],["Brigadier General Juan Manuel de Rosas","autopista","Juan Manuel de Rosas (1793 a 1887), militar y político; gobernador de Buenos Aires de 1829 a 1832 y de 1835 a 1852."],["El Rosedal","plaza","El Rosedal: nombre popular del Jardín de las Rosas en los lagos de Palermo; es diagramado por el paisajista Benito Carrasco e inaugurado el 2 de noviembre de 1914; allí se encuentran el Patio Andaluz, la Glorieta y el Puente Blanco."],["Roseti","calle","Manuel Roseti (1832 a 1866), coronel; combate en Cepeda, Pavón y en la guerra contra el Paraguay."],["Rousseau","calle","Juan Jacobo Rousseau (1712 a 1778), filósofo y escritor francés, autor de Discurso sobre las ciencias, Emilio, El Contrato Social, Confesiones y Reflexiones de un paseante solitario."],["Eduardo Rovira","plazoleta","Eduardo Rovira (1925 a 1980) bandoneonista; integra las orquestas de Antonio Rodio, Miguel Caló y Osmar Maderna; en 1957 forma la suya propia; forma un trío junto a Osvaldo Manzi y Kicho Díaz. Hacia 1959 conforma la agrupación Tango Moderno. Entre 1965 y 1970 integra un trío con Atilio Stampone y Reynaldo Nichele. Se destaca por su visión vanguardista del tango y es autor de A don Alfredo Gobbi, A Evaristo Carriego, Contrapunteando, Febril y Sónico."],["Germán Nº 1.303. Rozenmacher","encauzadores de tránsito","Germán Rozenmacher (1936 a 1971), cuentista, dramaturgo y periodista; escribe en el semanario político peronista Compañero y en la revista Así; autor de Cabecita Negra, Los ojos del tigre (cuentos); Réquiem para un sábado a la noche y El caballero de la India (obras teatrales)."],["María Ruanova","cantero central","María Ruanova (1912 a 1976), primera bailarina del Teatro Colón; maestra, directora y coreógrafa del SODRE (Teatro Oficial de Montevideo-Uruguay); maestra y directora del Ballet del Teatro Colón desde 1967 hasta 1976; entre sus interpretaciones figuran El lago de los Cisnes y La bella durmiente del bosque."],["Rubens","calle","Pedro Pablo Rubens (1577 a 1640), pintor flamenco; autor de El juicio de París, Las tres Gracias, San Agustín meditando en la Trinidad y Descendimiento de la Cruz."],["José Ignacio Rucci","calle","José Ignacio Rucci (1924 a 1973), dirigente sindical; representante del gremio metalúrgico; Secretario General de la Confederación General del Trabajo en 1970; asesinado el 25 de septiembre de 1973."],["Rufino","calle","Rufino: ciudad del departamento de General López, provincia de Santa Fe."],["Silvio L. Ruggieri","calle","Silvio L. Ruggieri (1888 a 1947), jurisconsulto y periodista; miembro fundador y director del periódico Germinal; director del diario La Patria de Dolores y del periódico El Sol; diputado nacional en 1932, 1936 y 1940; autor de Los empréstitos de la provincia de Buenos Aires, Petróleo y Difteria."],["Ruiz de los Llanos","calle","Bonifacio Ruiz de los Llanos (1791 a 1870), coronel; combate en Tucumán, Salta, Vilcapugio y Ayohuma; jefe del Regimiento de Dragones Infernales de Güemes desde 1815."],["Ruiz Huidobro","calle","Pascual Ruiz Huidobro (1752 a 1813), teniente general; gobernador político y militar de Misiones en 1803; combate durante las Invasiones Inglesas y cae prisionero durante las mismas; inspector del ejército del Virreinato en 1809; asiste al Cabildo Abierto de 1810 pronunciándose por los patriotas. RUIZ MORENO, DOCTOR ISIDORO (cantero central), Ordenanza N° 43.383- 1988, BM N° J 8.517. Isidoro Ruiz Moreno (1905 a 1986), abogado en Derecho Internacional y Derecho Aeronáutico; diputado provincial; ministro de Hacienda y diputado nacional por Córdoba; autor de Derecho público aeronáutico, El pensamiento internacional de Alberdi, El derecho internacional público ante la Corte Suprema e Historia de las Relaciones Exteriores Argentinas."],["General Julio Ruiz Moreno","calle","Julio Ruiz Moreno (1840 a 1914), militar; combate en la guerra contra el Paraguay; jefe de la Frontera Sur de San Luis; participa en la Revolución de 1890."],["Rumania","calle","Rumania: país europeo. Capital: Bucarest."],["Rusia","calle","Rusia: nación euroasiática. Capital: Moscú."],["Russel","calle","Oliverio Russel (?-1815), teniente coronel de marina de origen escocés; participa en el sitio de Montevideo al mando de la corbeta Belfast; en 1815 es enviado a Chile para cooperar con el general San Martín que en Mendoza preparaba el cruce de Los Andes, pero su buque se pierde en el océano sin saberse nada más sobre él. Notas."],["Saavedra","barrio","El pueblo, hoy barrio, de este nombre fue fundado por don Florencio Núñez el 27 de abril de 1873."],["Brigadier General Cornelio de Saavedra","parque","Intendencia del Dr. Arturo Gramajo, de 1916, confirmado por Decreto N° 349-1946, BM N° 7.623. Por Ordenanza N° 25.940-1971, BM N° 14.125, su nombre actual. Cornelio de Saavedra (1759 a 1829), militar; presidente de la Primera Junta de Gobierno de 1810."],["Mariano Saavedra","plaza","Mariano Saavedra (1810 a 1883), político; miembro de la Municipalidad porteña desde su creación en 1856; diputado y miembro de la Convención en 1860; director y presidente del Banco de la Provincia de Buenos Aires; gobernador de Buenos Aires de 1862 a 1866; era hijo de don Cornelio de Saavedra."],["Doctor Carlos Saavedra Lamas","plazoleta","Carlos Saavedra Lamas (1878 a 1959), jurisconsulto; ministro de Relaciones Exteriores y Culto de 1932 a 1938, interviene en las negociaciones que ponen fin a la guerra del Chaco, entre Paraguay y Bolivia, por lo que se le otorga el Premio Nobel de la Paz en 1936."],["Ciudad de Sabadell","calle","Sabadell: ciudad española de la provincia de Barcelona. Se otorga este nombre por reciprocidad, ya que esta ciudad dio el nombre de Buenos Aires a una de sus calles."],["Amadeo Sabattini","plaza","Amadeo Sabattini (1892 a 1960), médico y político; gobernador de la provincia de Córdoba de 1936 a 1940."],["Presbítero Doctor Antonio Sáenz","plazoleta","Antonio María Norberto Sáenz (1780 a 1825), sacerdote; diputado por Buenos Aires en el Congreso de Tucumán."],["Manuela Sáenz","calle","Manuela Sáenz (1797 a 1856), patricia; forma parte del Estado Mayor del ejército de Simón Bolívar, de quien es compañera y amante, con el grado de coronel; combate en la batalla de Ayacucho; en 1828 le salva la vida a Bolívar dos veces en emboscadas de sus enemigos, por lo que se la conoce como “La Libertadora del Libertador”."],["Doctor Roque Sáenz Peña","plaza","Roque Sáenz Peña (1851 a 1914), jurisconsulto; combate como teniente coronel del Perú durante la guerra del Pacífico; presidente de la República de 1910 a 1914. Con respecto a la avenida, la Ley 1.682 de 2005 adopta en forma oficial el nombre popular de Diagonal Norte con el que esta avenida es conocida desde que en la década de 1910 se concreta su trazado diagonal que se destaca por quebrar el tradicional cuadriculado de las calles de Buenos Aires."],["Presidente Luis Sáenz Peña","calle","Luis Sáenz Peña (1822 a 1907), jurisconsulto; presidente de la República de 1892 a 1895."],["Almirante Juan Pablo Sáenz Valiente","calle","Juan Pablo Sáenz Valiente (1860 a 1925), marino; ministro de Marina del presidente Victorino de la Plaza; interventor federal en Corrientes en 1916."],["Anselmo Sáenz Valiente","calle","Anselmo Sáenz Valiente (1755 a 1815), comerciante y funcionario; alcalde de segundo voto en 1806, se destaca por su actuación durante las Invasiones Inglesas, habiendo sido uno de los principales sostenedores del cuerpo urbano de voluntarios Cántabros. Es éste un nombre tradicional de la ciudad pues entre 1808 y 1822 se denominó “Sáenz Valiente” la actual Cangallo."],["José María Sagasta Isla","calle","José María Sagasta Isla (1843 a 1926), funcionario; juez de Paz y presidente de la Municipalidad de Belgrano entre 1878 y 1880; concejal municipal entre 1898 y 1901."],["Antoine de Saint-Exupéry","patio de recreación","Antoine Jean-Baptiste Marie Roger de Saint-Exupéry (1900 a 1944), escritor y aviador francés; comienza a volar en la Sociedad Aéropostale y continúa haciéndolo en África y Sudamérica hasta el comienzo de la guerra. Durante la Segunda Guerra Mundial, su aeronave de reconocimiento, un Lockheed Lightning P-38 (conocido también como F-5), es derribado en el Mar Mediterráneo en lo que fue su última misión. Autor de El aviador, Tierra de hombre y El principito."],["Juan Francisco Salaberry","plaza","Juan Francisco Salaberry (1823 a 1908), hacendado, tambero y filántropo; propietario de un establecimiento en Las Heras (provincia de Buenos Aires). Tiene una activa labor en el barrio de Mataderos. Luego de su fallecimiento sus socios de la empresa Salaberry, Bercetche y Compañía, consignatarios de hacienda, forman una comisión de homenaje en su memoria y donan a la Municipalidad el terreno para la construcción del Hospital Juan Francisco Salaberry (hoy desactivado) como forma de perpetuar su memoria."],["Saladillo","calle","Saladillo: ciudad y partido de la provincia de Buenos Aires."],["Río Salado","calle","Río Salado: extenso río que nace en las serranías de Salta y desemboca en el Paraná. Recibe varios nombres: Calchaquí, de las Conchas, Guachipas, Pasaje y Juramento, este último en razón de que junto a él las tropas de Belgrano prestaron juramento de fidelidad a la Bandera el 13 de febrero de 1813."],["Salala","calle","Salala: localidad del norte chileno donde las fuerzas del Ejército de los Andes, pertenecientes a la columna de Cabot, batieron a las fuerzas realistas el 12 de febrero de 1817."],["Ciudad de Salamanca","cantero central","Salamanca: ciudad de España, capital de la provincia de su nombre."],["Salas","calle","Mariano Salas (1808 a 1866), coronel; combate durante la guerra contra el Brasil, en Sauce Grande, Quebracho Herrado, Cepeda, Pavón y en la guerra contra el Paraguay, donde muere como consecuencia de las heridas recibidas."],["Salcedo","calle","Miguel de Salcedo y Sierra Alta (1689 a 1765), militar; gobernador interino del Río de la Plata de 1734 a 1742."],["Adolfo Saldías","calle","Adolfo Saldías (1849 a 1914), historiador y periodista; vicegobernador de la provincia de Buenos Aires; interventor federal en La Rioja en 1910; director del diario La Argentina; autor de Historia de Rosas y su época, Historia de la Confederación Argentina y Cervantes y el Quijote."],["Jerónimo Salguero","calle","Salguero por Disposición del Presidente de la Corporación Municipal, Torcuato de Alvear, del 6-3-1882. (Archivo Histórico Municipal, Legajo 3, 1882, Obras Públicas). Por Decreto-Ordenanza N° 2.485- 1949, BM N° 8.529, su nombre actual. Jerónimo Salguero de Cabrera y Cabrera (1774 a 1847), funcionario; diputado por Córdoba en el Congreso de Tucumán."],["José Aarón Salmún Feijóo","calle","Aarón José Salmún Feijóo (1926 a 1945), estudiante de ingeniería que murió en la esquina de Perú y Avenida de Mayo durante una manifestación de protesta estudiantil el 4 de octubre de 1945."],["Salom","calle","Bartolomé Salom (1780 a 1863), general venezolano; participa con Bolívar en la campaña de Magdalena y en la de 1819; combate en Carabobo y Bomboná; intendente de Guayaquil."],["Martha Salotti","calle","Martha A. Salotti (1899 a 1981), educadora y escritora; maestra y profesora superior de Ciencias Sociales; se especializa en literatura infantil; colabora con Rosario Vera Peñaloza en la organización del Museo Juan B. Terán; publica Enseñanza de la lengua, Alas en libertad, Juguemos en el bosque y Un viaje a la luna."],["Provincia de Salta","cantero central","Salta: ciudad y provincia de la República Argentina."],["Salto","calle","Salto: ciudad de la provincia de Buenos Aires."],["Coronel Salvadores","calle","Ángel Antonio Salvadores (1792 a 1841), militar; combate en el sitio de Montevideo y Venta y Media; edecán de Bolívar en la batalla de Junín; combate en Quebracho Herrado, San Calá y Rodeo del Medio."],["Salvigny","calle","Elmidio Salvigny (1775 a 1860), teniente coronel de origen italiano; edecán del General Belgrano; combate en la Ciudadela en 1827."],["Arturo Enrique Sampay","cantero central","Arturo Enrique Sampay (1911 a 1977), jurisconsulto y constitucionalista; presidente de la Comisión de Estudios del Anteproyecto de Reformas a la Constitución Nacional del bloque Peronista y miembro informante en la Convención en 1949; entre sus obras se destacan La filosofía del iluminismo de la Constitución Argentina 1853, La crisis del estado de derecho liberal-burgués y La ontología del Estado."],["Manuel J. Samperio","calle","Manuel Joaquín Samperio (1897 a 1959), sacerdote y escritor; autor de La literatura y las civilizaciones, Cuestiones de Antropología argentina, Historia de la Iglesia y del barrio de Santa Lucía, El poema de las rosas y Palabras a Buenos Aires; párroco de Santa Lucía desde 1941."],["Sanabria","calle","Fernando de Trejo y Sanabria (¿1554?-1614), sacerdote, nieto del Adelantado Juan de Sanabria; Obispo de Tucumán desde 1592; fundador de la Universidad de Córdoba."],["Obispo San Alberto","calle","José Antonio San Alberto (1727 a 1804), sacerdote; obispo de Córdoba del Tucumán desde 1780; arzobispo de La Plata o Charcas desde 1784."],["San Antonio","calle","San Antonio: departamento de la provincia de Río Negro."],["San Antonio de Areco","calle","San Antonio de Areco: ciudad y partido de la provincia de Buenos Aires."],["N° 8.528. San Benito de Palermo","calle","San Benito de Palermo: nombre tradicional con que se conocía al barrio de Palermo y que se origina en la existencia de un oratorio en el que se veneraba la imagen de San Benito."],["San Blas","calle","San Blas: bahía y localidad de la provincia de Buenos Aires donde el 6 y 7 de marzo de 1827 se desarrolló una acción naval durante la guerra contra el Brasil."],["Combate de San Carlos","calle","San Carlos: combate librado el 8 de marzo de 1872 entre las fuerzas del general Ignacio Rivas y las del cacique Calfucurá."],["San Cayetano de Liniers","espacio verde","San Cayetano (1480 a 1547), eclesiástico italiano; fundador de la Orden de los Clérigos Regulares que después toman el nombre de Teatinos. Canonizado el 12 de abril de 1671. Los días 7 de cada mes y, en especial el 7 de agosto, la Parroquia de San Cayetano en el barrio de Liniers recibe a miles de fieles que lo reverencian como “Patrono del Pan y del Trabajo”."],["San Cristóbal","barrio","San Cristóbal (?-230), mártir cristiano en Palestina; obispo de Antioquía, es detenido y decapitado en la ciudad de Samos en el año 230. Según un motu proprio del 14 de febrero de 1969 quedó excluido del calendario litúrgico por existir serias dudas sobre su existencia, reservándosele solamente culto local en aquellos lugares donde la devoción popular le rinde homenaje. Esta zona se conoce así desde el 28 de junio de 1869 cuando la Legislatura de Buenos Aires crea la parroquia de San Cristóbal, estableciendo no obstante que la misma no se consideraría erigida hasta tanto se construyese el templo, hecho que se materializó el 10 de febrero de 1884."],["Sánchez","calle","Antonio Saturnino Sánchez (1795 a 1827), coronel; comandante de Armas de San Juan; teniente de gobernador de la Villa de Supe (Perú); combate en Pichincha; gobernador de Chayanta (Bolivia). Gregorio Sánchez (1797 a 1841), coronel; combate en el sitio de Montevideo; participa en la campaña de Ica de 1821 a 1822; actúa en 1826 en el Ejército de Observaciones sobre el Uruguay. Modesto Antonio Sánchez (1791 a 1857), teniente coronel; combate en el sitio de Montevideo y en Maipú; comisario de la seccional cuarta del Cuartel N° 25 en la calle Loria en 1826. Homenaje conjunto a los hermanos Sánchez, guerreros de la Independencia."],["Florencio Sánchez","plazoleta","Florencio Sánchez (1875 a 1910), dramaturgo uruguayo; autor de Barranca abajo, Los muertos, Nuestro hijos, Canillita y M´hijo el doctor."],["Joaquín Sánchez","plaza","Joaquín Sánchez (1842 a 1918), funcionario y político; miembro de la Comisión Municipal de Belgrano en 1885 y subintendente de la misma más tarde; concejal municipal en 1894 y 1895."],["Sánchez de Bustamante","calle","Teodoro Sánchez de Bustamante (1778 a 1851), jurisconsulto; diputado por Jujuy en el Congreso de Tucumán; gobernador de aquella provincia en 1826 y 1827."],["Sánchez de Loria","calle","Legajo 3, 1882. Obras Públicas) y Ordenanza N° 25.872-1971, BM N° 14.112. Mariano Sánchez de Loria (1774 a 1842), sacerdote y jurisconsulto; diputado por Charcas en el Congreso de Tucumán."],["Mariquita Bm N° 17.036. Sánchez de Thompson","calle","María de Todos los Santos Sánchez de Thompson y de Mendeville (1786 a 1868), patricia; adhirió a la causa de la libertad y se cuenta que en su casa se entonó por primera vez el Himno Nacional en el año 1813; fundadora de la Sociedad de Beneficencia en 1823, presidenta de la misma por varios períodos."],["Carlos Sánchez Viamonte","cantero central","Carlos Sánchez Viamonte (1892 a 1972), abogado, doctor en ciencias jurídicas y sociales; profesor universitario, al producirse el golpe de estado de 1930 mantiene una oposición inflexible hacia el mismo; diputado nacional de 1940 a 1943; autor de La defensa de un juez, Democracia y socialismo, Hacia un nuevo derecho constitucional e Historia institucional argentina."],["San Francisco de Asís","calle","San Francisco de Asís (1182 a 1226), sacerdote italiano; fundador de la Orden de los Hermanos Menores que luego llevará su nombre; autor del Cántico de las criaturas o Cántico del Hermano Sol."],["San Francisco Javier","plazoleta","San Francisco Javier (1506 a 1552), jesuita español; consagró su vida al servicio de Dios y de la Iglesia; se lo denominó “Apóstol de las Indias”; fue canonizado en 1622."],["Manuel de San Ginés","calle","Manuel Saturnino de San Ginés (1768 a 1825), sacerdote; fundador de la parroquia y del pueblo de San Fernando, provincia de Buenos Aires."],["San Ignacio","calle","San Ignacio: departamento y pueblo de la provincia de Misiones, célebre por sus ruinas jesuitas, que fueron declaradas Monumentos Históricos por Decreto N° 16.482 del 17 de diciembre de 1943."],["San Ireneo","calle","San Ireneo (¿130-208?), prelado francés; obispo de Lyon; discípulo de San Policarpo, escribió un tratado contra las herejías. Udaondo atribuye el origen de esta denominación al hecho de que sobre esta calle se encontraba la capilla que el doctor Ireneo Portela poseía en su casaquinta dedicada al santo de su nombre."],["San Isidro","avenida","San Isidro: ciudad y partido de la provincia de Buenos Aires."],["San José","calle","San José: combate librado en la Banda Oriental del Uruguay, en el pueblo de ese nombre, por el Comandante Venancio Benavídez el 25 de abril de 1811."],["San José de Calasanz","calle","San José de Calasanz (1556 a 1648), sacerdote español; fundador de la primera escuela pública y gratuita, a la que llamó Escuela Pía, en Roma en 1597; será el origen de las Escuelas Pías que se difundirán por todo el mundo."],["Provincia de San Juan","cantero central","San Juan: ciudad y provincia de la República Argentina. SAN JUAN BAUTISTA DE LA SALLE véase LA SALLE, SAN JUAN BAU-."],["Tista De. San Lorenzo","calle","San Lorenzo: combate sobre el río Paraná librado por el entonces coronel San Martín contra los realistas el 3 de febrero de 1813."],["Sanlúcar de Barrameda","calle","Sanlúcar de Barrameda: puerto español en la desembocadura del Guadalquivir, provincia de Cádiz, de donde partió Colón en su tercer viaje a América; también zarparon de este puerto Magallanes, Caboto y Mendoza."],["Provincia de San Luis","cantero central","San Luis: ciudad y provincia de la República Argentina."],["República de San Marino","calle","San Marino: república independiente situada en Italia central; es uno de los estados más pequeños de Europa y a la vez el más antiguo. Capital: San Marino."],["San Martín","avenida","Si bien su nombre primitivo de “Camino a San Martín” indicaba que ésta era la vía obligada para llegar al pueblo epónimo, hoy partido de General San Martín, en 1895 la Municipalidad incorporó esta denominación como un nuevo homenaje al General San Martín."],["San Martín","calle","De esta manera las calles que recordaban al Patrono de la ciudad y a la Patrona de América, pasaron a rendir homenaje a los dos libertadores, como lo prueba Mario Visiconte en su libro San Martín de Tours y don Juan Manuel de Rosas, Buenos Aires, 1969."],["Libertador General San Martín","plaza","José Francisco de San Martín (1778 a 1850), militar; Libertador de la Argentina, Chile y Perú; vencedor en San Lorenzo, Chacabuco y Maipú."],["Mercedes San Martín de Balcarce","plazoleta","Mercedes San Martín de Balcarce (1816 a 1875), patricia; hija del General José de San Martín, casada con don Mariano Balcarce, hijo a su vez de don Antonio González Balcarce."],["Patrono de Buenos Aires San Martín de Tours","plaza","San Martín de Tours (316 a 397), santo magiar, obispo de Tours; fue elegido Santo Patrono de la Ciudad de Buenos Aires por Acuerdo del Cabildo del 20 de octubre de 1580. Se celebra su día el 11 de noviembre."],["San Mateo","calle","San Mateo: batalla librada por las fuerzas de Bolívar y las del general español Boves el 25 de marzo de 1814 en el campo de San Mateo, al oriente del lago de Valencia (Venezuela), en la que el oficial colombiano Antonio Ricaurte, en acción heroica muere al hacer estallar el polvorín que estaba a su cargo para evitar que cayese en manos enemigas. Con ello muere gran parte de los realistas y el resto huye. La acción de Ricaurte está inmortalizada en el himno nacional colombiano, que dice: “Ricaurte en San Mateo –en átomos volando. ‘Deber antes que vida’– con llamas escribió”.14."],["San Miguel Garicoits","plazoleta","San Miguel Garicoits y Echeberri (1797 a 1863), sacerdote francés; fundador de la Congregación de Padres Bayoneses. Se otorga este nombre en el 125° aniversario de la llegada de esta congregación a la ciudad de Buenos Aires."],["Bo Nº 2.776. San Nicolás Nº 2.412-2007","plazoleta","San Nicolás de Bari (¿-?), obispo de Myra, en Licia (Asia Menor) que sufre la pena de cárcel durante el gobierno de Diocleciano. Es uno de los santos más populares del norte de Europa por la leyenda que lo pinta repartiendo juguetes a los niños en la víspera de la Navidad. Su nombre se remonta en Buenos Aires a la capilla fundada en 1733 por Domingo Acassuso en la esquina de las actuales Carlos Pellegrini y Corrientes. La plazoleta recibió también esta denominación por su carácter tradicional, ya que así se denominó la actual avenida Corrientes entre 1744 y 1808."],["San Nicolás","calle","San Nicolás: ciudad y partido de la provincia de Buenos Aires."],["San Pedrito","avenida","San Pedrito: combate librado en Jujuy el 6 de febrero de 1817 por el Sargento Mayor Juan Antonio Rojas al frente de los célebres gauchos de Güemes contra una avanzada realista."],["San Pedro","calle","San Pedro: ciudad y partido de la provincia de Buenos Aires."],["San Ricardo","calle","San Ricardo (?-722), señor y cuasi monarca de Sajonia Occidental; murió en Luca, Toscana, en 722 cuando se disponía a ir en peregrinación a Tierra Santa."],["San Sebastián","calle","San Sebastián: cerro, cabo, bahía y departamento de Tierra del Fuego."],["Santa Catalina","calle","Santa Catalina: pueblo y departamento de la provincia de Jujuy."],["Provincia de Santa Cruz","cantero central","Santa Cruz: provincia de la República Argentina. Capital: Río Gallegos."],["Santa Elena","calle","Santa Elena: cerro y paso situado en la provincia de Mendoza que sirve de límite entre la Argentina y Chile."],["Provincia de Santa Fe","cantero central","Santa Fe: ciudad y provincia de la República Argentina. SANTA FRANCISCA JAVIER CABRINI véase CABRINI, SANTA FRANCISCA."],["Javier. Santa Magdalena","calle","Santa Magdalena de Pazzi (1566 a 1604), religiosa italiana de la Orden de las Carmelitas; fue canonizada en 1669."],["La Santa María","calle","Santa María: una de las tres carabelas que, al mando de Cristóbal Colón, partieron del Puerto de Palos de Moguer en agosto de 1492 en la expedición del descubrimiento de América."],["N° 7.542. Santa María de los Buenos Aires","plazoleta","Santa María de los Buenos Aires: nombre que recibió la ciudad de Buenos Aires al ser fundada por don Pedro de Mendoza el 2 de febrero de 1536, como un homenaje a la Patrona de los Navegantes."],["Santander","calle","Francisco de Paula Santander (1792 a 1842), militar y político colombiano; participa en la campaña de Boyacá como jefe del Estado Mayor de Bolívar; vicepresidente de la Gran Colombia en 1821 y 1826; presidente de Nueva Granada de 1832 a 1837."],["Villa Santa Rita","barrio","Santa Rita de Casia (1381 a 1457), religiosa italiana de la orden agustiniana. Este barrio se conforma a fines del siglo pasado alrededor de un oratorio particular en el que se veneraba la imagen de esta santa."],["Villa Santa Rita","plazoleta","Santa Rita de Casia (1381 a 1457), religiosa italiana de la orden agustiniana. Este barrio se conforma a fines del siglo pasado alrededor de un oratorio particular en el que se veneraba la imagen de esta santa."],["Santa Rosa","calle","Santa Rosa de Lima (1586 a 1617), religiosa dominica peruana cuyo nombre era Isabel Flores de Oliva. Fue beatificada por Clemente IX el 12 de febrero de 1668. Clemente X la declaró en 1670 Patrona principal de América, Filipinas y las Indias Occidentales y la canonizó en 1672."],["Santa Teresa","calle","Santa Teresa de Jesús (Teresa de Cepeda y Ahumada) - (1515 a 1582), religiosa y escritora mística española; autora de El camino de perfección, Las moradas y Autobiografía; fue canonizada en 1622."],["Bo Nº 2.776. San Telmo, de Nº 2.412-2007","plazoleta","San Pedro González Telmo de Frómista (?-1246), sacerdote dominico proclamado Patrono de los navegantes y abogado de las tormentas. En 1806 se creó la parroquia de este nombre designándose a la iglesia de Nuestra Señora de Belén como sede de la misma."],["Soldado Archivista Miguel Santi","calle","Miguel Santi (?-1930), soldado artillero que muere durante los sucesos revolucionarios del 6 de septiembre de 1930."],["Santiago de Chile","calle","Santiago de Chile: ciudad capital de la República de Chile y de la provincia de su nombre."],["Santiago de Compostela","avenida","Santiago de Compostela: ciudad de España, en la provincia de La Coruña."],["Provincia de Santiago del Estero","cantero central","Santiago del Estero: ciudad y provincia de la República Argentina."],["Santo Domingo","calle","Santo Domingo: isla de las Antillas dividida entre la República Dominicana y Haití. Fue descubierta por Colón en diciembre de 1492 y bautizada La Española."],["Santojanni","parque","Francisco Santojanni (1860 a 1935), donante de los terrenos donde se construyó el hospital y la plaza que llevan su nombre."],["Roberto Jorge Santoro","plazoleta","Jorge Roberto Santoro (1939 a 1977), poeta, editor y periodista; dirige y funda en 1963 la revista literaria Barrilete. Autor de El último tranvía; Pedradas con mi patria; Literatura de la pelota y En esta tierra lo que mata es la humedad (tragedia musical). Es secuestrado el 1º de junio de 1977, en la Escuela Nacional de Educación Técnica Nº 25 Teniente Primero de Artillería Fray Luis Beltrán, donde el poeta prestaba servicio de preceptor con el cargo de subjefe. Permanece desaparecido."],["Santos Vega","calle","Santos Vega: payador legendario que fuera inmortalizado en la literatura argentina por la pluma de Rafael Obligado. Santos Vega, que habría sido enterrado en el Tuyú, dio origen a una leyenda popular que fue recogida además por otros autores, entre ellos Bartolomé Mitre, Hilario Ascasubi, que le atribuye el relato de Los mellizos de la Flor, y Ricardo Gutiérrez."],["Santo Tomé","calle","Santo Tomé: ciudad y departamento de la provincia de Corrientes."],["San Vicente de Paul","plazoleta","San Vicente de Paul (1576 a 1660), sacerdote francés; fundador de la Congregación de Las Hijas de la Caridad junto con Santa Luisa de Marillac, y de la Congregación de Sacerdotes de la Misión."],["San Vladimiro","plazoleta y paseo peatonal","Vladimiro I el Grande o San Vladimiro (956 a 1015), primer Zar de Rusia; llamado el Grande reúne bajo su cetro todo el imperio; impuso el cristianismo en toda Rusia."],["Saráchaga","calle","Juan Antonio Saráchaga (1781 a 1840), jurisconsulto; secretario de Gobierno en Salta y del presidente de Charcas en 1810; rector de la Universidad de Córdoba; ministro de Relaciones Exteriores y de Guerra del general José María Paz; fundador de El Montonero."],["Sarandí","calle","Sarandí: batalla librada en la Banda Oriental el 12 de octubre de 1825 durante la guerra contra el Brasil, entre las fuerzas orientales mandadas por el general Lavalleja y las brasileñas al mando del brigadier Bentos Manuel."],["Saravia","calle","José Apolinar de Saravia (?-1844), coronel; combate en Tucumán, Salta, Sauce Redondo y del Bañado; interviene en 1819 en el rechazo de los generales realistas Canterac y Olañeta. José Domingo de Saravia (?-1853), sargento mayor; combate en Vilcapugio y Sauce Redondo; preside en 1853 los actos de la jura de la Constitución en Salta. Pedro José de Saravia (1756 a 1832), general, padre de los anteriores; presidente interino de la Junta Provincial de Salta en 1811; combate en la batalla de Salta. Homenaje conjunto a la familia Saravia."],["Saraza","calle","Saturnino Saraza (1760 a 1835), teniente coronel; participa en la expedición al Paraguay bajo las órdenes del general Belgrano; teniente gobernador de San Juan de 1812 a 1813."],["Presidente Sarmiento","parque y centro deportivo","Domingo Faustino Sarmiento (1811 a 1888), político y escritor; fundador de El Zonda; presidente de la República de 1868 a 1874; autor de Civilización y barbarie, Vida de Juan Facundo Quiroga y Recuerdos de provincia."],["Capitán Domingo Fidel Sarmiento","plaza","Domingo Fidel Sarmiento (1845 a 1866), capitán; hijo adoptivo de Domingo Faustino Sarmiento, es conocido como Dominguito; combate en la guerra contra el Paraguay, donde muere en el asalto de Curupaytí."],["Manuel de Sarratea","plazoleta","Manuel de Sarratea (1774 a 1849), político; miembro del primer Triunvirato; general en jefe del Ejército de la Banda Oriental; gobernador de Buenos Aires de 1820 a 1821."],["Marcos Sastre","calle","Marcos Sastre (1808 a 1887), educador y escritor; idea en 1849 un método para aprender a leer que denominó “Anagnosia”; fundador del Salón Literario en 1837; profesor y subdirector del Colegio Republicano Federal en 1844 y del de San Jerónimo de Santa Fe en 1849; director de la Biblioteca Pública de Buenos Aires en 1853; director de la Escuela Normal en 1865."],["Marcos Sastre","plaza","Marcos Sastre (1808 a 1887), educador y escritor; idea en 1849 un método para aprender a leer que denominó “Anagnosia”; fundador del Salón Literario en 1837; profesor y subdirector del Colegio Republicano Federal en 1844 y del de San Jerónimo de Santa Fe en 1849; director de la Biblioteca Pública de Buenos Aires en 1853; director de la Escuela Normal en 1865."],["El Sauce","calle","Sauce: árbol de la familia de las Salicáceas. En nuestro país existen dos especies muy difundidas: el sauce criollo o crespo y el sauce llorón."],["Manuel Nicolás Savio","calle","Manuel Nicolás Savio (1892 a 1948), general e ingeniero; director de Fabricaciones Militares, interviene después de 1943 en la formación de empresas mixtas del Estado y privadas para promover la industria siderúrgica nacional; autor de la Ley N° 12.987 del Plan Siderúrgico Nacional que se conoce con su nombre."],["Sayos","calle","Francisco Dionisio Sayos (1785 a 1842), coronel; combate durante las Invasiones Inglesas, en el sitio de Montevideo y en Fraile Muerto; participa en la campaña al desierto de Martín Rodríguez; jefe de Policía de Buenos Aires en 1828 y 1829; muere en la batalla de Arroyo Grande el 16 de abril de 1842."],["Raúl Scalabrini Ortiz","avenida","Raúl Scalabrini Ortiz (1898 a 1959), escritor y periodista; autor de El hombre que está solo y espera, Política Británica en el Río de La Plata, Historia de los Ferrocarriles Argentinos, Yrigoyen y Perón y Tierra sin nada, tierra de profetas."],["Rodolfo Scapino","calle","Rodolfo Adolfo Scapino (1883-?), benefactor; fundador de asociaciones y oratorios; presidente de la Sociedad San Vicente de Paul."],["Eduardo Schiaffino","calle","Eduardo B. Schiaffino (1858 a 1935), pintor y crítico; director fundador del Museo Nacional de Bellas Artes en 1895; autor de Margot, Alrededores de Buenos Aires y Reposo y como crítico de Apuntes sobre el arte en Buenos Aires, Urbanización de Buenos Aires y La pintura y la escultura en la Argentina."],["Ulrico Schmidl","calle","Ulrico Schmidel o Schmidl (1500 a 1581), viajero alemán, acompaña a Men- doza en 1536 en la fundación de Buenos Aires; autor de Viaje al Río de la Plata. SCHOLEM ALEIJEM véase ALEIJEM, SCHOLEM."],["Ana María Schultz","cantero central","Ana María Schultz (1935-?), deportista; figura de la natación argentina, comienza su carrera en San Lorenzo de Almagro; en la década de 1950 alcanza figuración internacional en 100 y 200 metros espalda; participa en los Juegos Olímpicos de Londres y Helsinski en 1948 y 1952; obtiene dos medallas de oro y una de bronce en los Juegos Panamericanos realizados en 1951 en Buenos Aires."],["Intendente Seeber","plaza","Francisco Seeber (1841 a 1913), comerciante, militar y funcionario; combate en la guerra contra el Paraguay; presidente del Ferrocarril del Oeste; intendente municipal de Buenos Aires desde el 10 de mayo de 1889 hasta el 4 de junio de 1890."],["Almirante F. J. Seguí","calle","Francisco José Seguí (1794 a 1877), marino; comandante de la cañonera Americana en 1814; combate en el sitio de Montevideo y en la guerra contra el Brasil; capitán del puerto de Buenos Aires en 1855."],["Juan Francisco Seguí","calle","Juan Francisco Seguí (1822 a 1863), jurisconsulto; diputado en el Congreso Constituyente de 1853; director de El Nacional Argentino."],["Marcos Seguín","calle","Marcos Seguín (1786 a 1875), ingeniero francés; inventor de los puentes colgantes y de la caldera tubular. SEGUNDO SOMBRA, DON véase DON SEGUNDO SOMBRA."],["Segurola","calle","Saturnino Segurola y Lezica (1776 a 1854), sacerdote y funcionario; bibliotecario de la Biblioteca Pública en 1810; diputado en la Asamblea de 1813; regente de la Casa de Expósitos."],["La Selva","calle","Selva: extenso territorio inculto y muy poblado de vegetación; en nuestro país se ubica en las provincias de Chaco, Formosa, Misiones, Tucumán, Salta y Jujuy."],["Beniamino Semiza","pasaje peatonal","Beniamino Semiza (1902 a 1960) militante socialista; funda junto con José F. Penelón el Partido Concentración Obrera; militante de los sindicatos de obreros municipales y metalúrgicos; concejal de la ciudad de Buenos Aires de 1938 a 1941 y director de la caja de jubilaciones de los obreros municipales de 1938 a 1943."],["Senillosa","calle","Felipe Senillosa (1789 a 1858), ingeniero español; llega a Buenos Aires en 1815; director de la Academia de Matemáticas en 1816; presidente del Departamento Topográfico en 1828 y 1838; autor de Programa de un curso de geometría y Memoria sobre pesas y medidas; dirige la construcción de la Aduana Nueva."],["El Sereno","calle","Sereno: persona encargada de la vigilancia nocturna de las calles de Buenos Aires. El servicio de Cuerpo de Serenos se presta desde el 13 de marzo de 1834 hasta el 30 de noviembre de 1872, cuando son sustituidos por vigilantes."],["Serrano","calle","Legajo 3, 1882. Obras Públicas). José Mariano Serrano (1788 a 1851), jurisconsulto; diputado por Chuquisaca en la Asamblea de 1813 y por Charcas en el Congreso de Tucumán."],["Enrique Serrano","calle","Enrique Serrano (1891 a 1964), actor de origen español; radicado desde niño en la Argentina, se destaca fundamentalmente en el teatro nacional. Actúa en innumerables películas, entre las que se destacan Tres anclados en París (1937); Jettatore (1938); Los martes, orquídeas (1941); El tango en París (1955) y La Cigarra no es un bicho (1962)."],["Servet","calle","Miguel Serveto Conesa (1511 a 1553), teólogo, fisiólogo y médico español conocido como Miguel Servet; descubre la circulación pulmonar y el papel de la respiración en la transformación de la sangre venosa en arterial; autor de Cristianismo Restitutio y De trinitatis erroribus."],["Sevilla","calle","Sevilla: ciudad y provincia de España en la región de Andalucía."],["Shakespeare","calle","Guillermo Shakespeare (1564 a 1616), dramaturgo y poeta inglés; autor de El mercader de Venecia, El sueño de una noche de verano, Como gustéis, Romeo y Julieta, Julio César, Hamlet, Otelo y Macbeth."],["Shanghai","calle","Shanghai: ciudad de China, capital de la región oriental."],["Francisco A. Sicardi","plaza","Francisco A. Sicardi (1865 a 1927), médico y escritor; actúa en la epidemia de cólera de 1866; jefe de sala del Hospital San Roque (hoy Ramos Mejía); autor de Libro extraño, Genaro, La inquietud humana, La canción del insomnio, Pérdida y Misericordia."],["Sicilia","plaza","Sicilia: isla y región de Italia. Capital: Palermo."],["Padre Daniel de la Sierra","sendero","Daniel de la Sierra (1938 a 1992), sacerdote de origen español; conocido como El ángel de la Bicicleta, forma parte de la pastoral villera y desarrolla una intensa labor social en la Villa 21 de Barracas; en 1979 funda la Cooperativa de Vivienda Caacupé."],["Sierra Grande","calle","Sierra Grande: sierras de la provincia de Córdoba."],["Del Signo","calle","Norberto del Signo (1777 a 1817), jurisconsulto; asesor del gobierno de Salta en 1810; asiste a los combates de Cotagaita y Suipacha como auditor de guerra del Ejército; secretario de Castelli, asiste a las derrotas de Huaqui y Sipe-Sipe."],["Cayetano A. Silva","calle","Cayetano A. Silva (1868 a 1920), músico; autor de la Marcha de San Lorenzo, Curupaytí y Lomas Valentinas."],["Simbrón","calle","Pablo Simbrón (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580. SIMONE, VICENTE DE véase DE SIMONE, VICENTE."],["Sinclair","calle","Enrique Sinclair (1805 a 1904), capitán de navío de origen norteamericano; combate durante la guerra contra el Brasil; jefe de la escuadrilla que en 1839 conduce a Lavalle a Buenos Aires en su campaña contra Rosas. Se le atribuye el origen de la palabra “peringundín”, nacida de su escaso dominio del idioma español."],["República Árabe N° 18.494. Siria","plazoleta","Siria: país de Asia. Capital: Damasco."],["Eduardo Sívori","calle","Eduardo Sívori (1847 a 1918), pintor; autor de Tropas de carretas en La Pampa, Los bueyes, La muerte del campesino, La tranquera y Le lever de la bonne. SKANDERBERG “JORGE CASTRIOTA” (espacio público). Ley N° 841-2002, BO N° 1.511. Gjergj Kastrioti (1405 a 1468) su nombre se ha castellanizado como Jorge Castriota; conocido como Skanderberg (el señor o el líder, en turco) es el héroe nacional albanés. Célebre guerrero, por su valor es conocido también como “el diablo de Valaquia”. Proclamado príncipe, enfrenta a los otomanos formando una liga de príncipes albaneses con el apoyo de Venecia, Nápoles, Hungría y el Papado."],["Alférez José María Sobral","plaza","José María Sobral (1880 a 1961), militar y geólogo; participa en la expedición noruega al Polo Sur de 1901 a 1903; director de Mineralogía, Geología e Hidrología de 1922 a 1928; cónsul argentino en Oslo; autor de Dos años entre los hielos, El hielo y el mar y La exploración del continente antártico."],["Sócrates","calle","Sócrates (469-399 a.C.), filósofo griego; basaba su enseñanza en la conversación; acusado de atacar a la religión del Estado ateniense es condenado a beber cicuta; autor del célebre aforismo “sólo sé que nada sé”."],["Sofía","calle","Sofía: ciudad capital de Bulgaria y de los distritos de su nombre."],["Manuel Solá","calle","Manuel Solá (1798 a 1867), funcionario y político; gobernador de la provincia de Salta de 1838 a 1840 y de 1858 a 1860."],["Soldado de la Frontera","avenida","Soldado de la Frontera: homenaje a los soldados que lucharon por extender las fronteras de nuestro país hasta sus límites actuales, luchando no sólo contra el indio sino también contra el medio ambiente."],["Soldado de la Independencia","calle","Soldado de la Independencia: homenaje a los anónimos soldados que lucharon por nuestra Independencia."],["Villa Soldati","barrio","José Ferdinando Francisco Soldati (1864 a 1913), fundador de esta villa en 1908."],["Raúl Soldi","plazoleta","Raúl Soldi (1905 a 1994), pintor; realiza los frescos de la iglesia de Santa Ana en Glew y la decoración de la cúpula del teatro Colón; obtiene varios premios nacionales e internacionales; autor de Mi padre y su violoncelo, Mujer peinando a su hija, La uruguaya negra y Sombrero amarillo."],["Soler","calle","Miguel Estanislao Soler (1785 a 1849), general; gobernador de la provincia Oriental en 1814; vencedor en las Coimas; combate en Chacabuco; gobernador de Buenos Aires en 1820; combate durante la guerra contra el Brasil. SOLIER, ALMIRANTE DANIEL DE (calle), Ordenanza N° 13.537-1942, BM N° 6.639. Daniel de Solier (1846 a 1903), marino; combate en la guerra contra el Paraguay; diputado nacional de 1882 a 1886; en 1884 conduce desde Italia a la fragata La Argentina con destino a nuestro país."],["Solís","calle","Juan Díaz de Solís (1461 a 1516), navegante español; descubridor del Río de la Plata en 1516, donde muere atacado por los aborígenes al descender a tierra."],["Solís","plaza","Juan Díaz de Solís (1461 a 1516), navegante español; descubridor del Río de la Plata en 1516, donde muere atacado por los aborígenes al descender a tierra."],["Juan de Solórzano Pereira","calle","Juan de Solórzano Pereira (1575 a 1655), jurisconsulto; oidor de la Audiencia de Lima; autor de Recopilación de Leyes de Indias, Política indiana y De los emblemas."],["Somellera","calle","Antonio Somellera (1812 a 1889), comodoro de marina; combate durante la guerra contra el Brasil; actúa en la revolución unitaria de 1839 y en el sitio de Montevideo de 1843; autor de cuadros y pinturas del ambiente naval. Pedro Antonio Somellera (1774 a 1854), jurisconsulto, padre del anterior; combate durante las Invasiones Inglesas; asesor letrado del Cabildo de Buenos Aires, acompaña a Belgrano en su expedición al Paraguay; autor de Principios de derechos civil."],["Soria","calle","Pablo Soria (1763 a 1851), explorador; su verdadero apellido era Sardicat, aunque él adoptó el de Soria; explora en 1826 el río Bermejo y sus tierras adyacentes."],["Ezequiel Soria","calle","Ezequiel Soria (1870 a 1936), autor teatral; autor de El año 92, Justicia criolla, Política casera, Diógenes y El sargento Martín; como director teatral estrena Jesús Nazareno de García Velloso, y La piedra del escándalo de Martín Coronado; fundador del periódico El Porteño."],["Julio Sosa","plazoleta","Julio Sosa (1926 a 1964), cantor de tango de origen uruguayo; autor de Dos horas antes del alba, interpreta con singular éxito Por qué canto así, Madame Ivonne, Araca corazón, Margot y Que me quiten lo bailao; muere en un accidente automovilístico en el momento de su mayor éxito."],["Antonio Soto","pasaje peatonal","Antonio Soto (1897 a 1963), dirigente obrero de origen español, nacido en El Ferrol, Galicia; secretario general de la Sociedad Obrera de Río Gallegos y protagonista principal de la protesta obrera conocida como la Patagonia Trágica; luego de la misma consigue huir a Chile."],["Lindor B. Sotomayor","plazoleta","Lindor B. Sotomayor (1846 a 1916), educador y funcionario; autor de la primera ley de educación de la provincia de La Rioja, que es anterior a la nacional y modelo de la de muchas provincias; autor de la Ley de Bibliotecas Populares de 1871; creador del Boletín Oficial de la provincia; fundador de la Revista Pedagógica."],["Coronel Carlos Tomás Sourigues","calle","Carlos Tomás Sourigues (1805 a 1870), militar y educador de origen francés; profesor de Historia del Colegio Republicano Federal en 1843; combate en Caseros, Cepeda y Pavón; director del Departamento Topográfico de Entre Ríos en 1862; jefe político y de Policía de Paraná en 1870, muere en un enfrentamiento con las fuerzas jordanistas."],["Carlos Spegazzini","calle","Carlos Luis Spegazzini (1858 a 1926), botánico de origen italiano; químico micógrafo de la Oficina Química Municipal de Buenos Aires; vicedecano de la Facultad de Agronomía y Veterinaria de La Plata; autor de Expedición científica al polo antártico."],["General Enrique Spika","calle","Enrique Spika (1843 a 1920), militar; combate en Pavón, en la guerra contra el Paraguay y en la lucha contra el indio; profesor de Táctica y Organización del Colegio Militar."],["Capitan Samuel Spiro","calle","Miguel Samuel Spiro (?-1814), marino de origen griego; actúa junto al almirante Brown en 1813 y 1814; muere en el combate de Arroyo de la China al volar la balandra Carmen que estaba bajo su mando."],["Stephenson","calle","Jorge Stephenson (1781 a 1848), ingeniero inglés; en 1814 construye la primera locomotora."],["Alfonsina Storni","calle","Alfonsina Storni (1892 a 1938), poetisa; autora de La inquietud del rosal, El dulce daño, Irremediablemente, Languidez, Ocre, Mundo de siete pozos y Mascarilla y trébol."],["Alfonsina Storni","plaza","Alfonsina Storni (1892 a 1938), poetisa; autora de La inquietud del rosal, El dulce daño, Irremediablemente, Languidez, Ocre, Mundo de siete pozos y Mascarilla y trébol."],["Suárez","calle","Isidoro Ramón Suárez (1799 a 1846), coronel; combate en Chacabuco, Cancha Rayada, Maipú, Pasco, Junín, Ayacucho y en la guerra contra el Brasil."],["José León Suárez","calle","José León Suárez (1872 a 1929), jurisconsulto; miembro fundador de la Facultad de Ciencias Económicas y decano de la misma de 1921 a 1924; presidente del Ateneo Hispano-Americano de 1918 a 1929; propulsor del iberoamericanismo, al que diferencia del hispanoamericanismo por la necesidad de conjugar en él al Brasil y a Portugal; autor de Carácter de la revolución americana y Una escuela de diplomacia en América."],["Justo N° 20.103. Suárez","plazoleta","Justo Antonio Suárez (1909 a 1938), deportista; campeón argentino y sudamericano de box de los plumas y livianos; combate en los Estados Unidos pero su salud hace declinar su figura."],["General Antonio José de Sucre","plazoleta","Antonio José Francisco de Sucre (1795 a 1830), militar venezolano; vencedor en Laja, Cuenca, Riobamba, Pichincha y Ayacucho; presidente de Bolivia de 1826 a 1828; presidente del Congreso Constituyente de Colombia en 1829."],["Sudamérica","calle","Sudamérica: una de las tres regiones en que se divide al continente americano y que comprende a los siguientes países: Venezuela, Surinam, Guyana, Guayana, Colombia, Ecuador, Perú, Bolivia, Chile, Paraguay, Uruguay, Brasil y la Argentina."],["Sudamérica","plaza","Sudamérica: una de las tres regiones en que se divide al continente americano y que comprende a los siguientes países: Venezuela, Surinam, Guyana, Guayana, Colombia, Ecuador, Perú, Bolivia, Chile, Paraguay, Uruguay, Brasil y la Argentina."],["Suecia","calle","Suecia: país europeo. Capital: Estocolmo."],["Suipacha","calle","Suipacha: batalla librada el 7 de noviembre de 1810 en el Alto Perú, hoy Bolivia, entre las fuerzas patriotas al mando de don Antonio González Balcarce y las realistas del general José de Córdoba y Rojas."],["Suipacha","plazoleta","Suipacha: batalla librada el 7 de noviembre de 1810 en el Alto Perú, hoy Bolivia, entre las fuerzas patriotas al mando de don Antonio González Balcarce y las realistas del general José de Córdoba y Rojas."],["Suiza","calle","Suiza: país europeo. Capital: Berna."],["Sumaca Itatí","calle","Sumaca Itatí: nave perteneciente a la armada del almirante Brown, que comandada por Miguel Ferreres participa en el bloqueo de Montevideo en 1814."],["Sumaca Santísima Trinidad","calle","Sumaca Santísima Trinidad: nave perteneciente a la armada del almirante Brown en 1814."],["Sunchales","calle","Sunchales: localidad del departamento de Castellanos, en la provincia de Santa Fe."],["Superí","calle","José Superí (1790 a 1813), coronel; combate durante las Invasiones Inglesas, en Las Piedras, Tucumán, Salta, Vilcapugio y Ayohuma, donde muere en acción. SUPERINTENDENCIA DE BOMBEROS, POLICÍA FEDERAL ARGENTINA véase BOMBEROS POLICÍA FEDERAL ARGENTINA, SUPERINTENDEN-."],["Cia De. Sur","plazoleta","Sur: tango creado en 1948 por Homero Manzi con música de Aníbal Troilo, estrenado por la orquesta del compositor e interpretado por Edmundo Rivero."],["Coronel Antonio Susini","calle","Nicolás Antonio Pascual Susini (1819 a 1900), militar; jefe de la Legión Agrícola Militar, interviene en la expedición de las Salinas Grandes; combate en Cepeda; comandante militar de Martín García en 1859; combate en la guerra contra el Paraguay."],["Doctor Enrique T. Susini","plazoleta","Enrique Telémaco Pedro Susini (1891 a 1972), médico, empresario teatral y cinematográfico; presidió la empresa cinematográfica Luminton y dirigió la primera película hablada, Los tres berretines."],["De los Suspiros","plazoleta","De los Suspiros: denominación tradicional que se origina en el hecho de que en este lugar se reunían los vecinos, muchos de ellos inmigrantes y marinos, para recibir noticias de sus tierras lejanas o de aquellos que habían salido a navegar, lo que en ocasiones motivaba suspiros de dolor, resignación o tristeza ante las noticias que no eran buenas (Bucich, Antonio J. Orígen y evolución de la nomenclatura boquense, Bs. As., Seminario y Archivo de Historia de la Boca del Riachuelo, 1968, p. 81). Notas."],["Tabaré","calle","Tabaré: nombre del poema compuesto por el poeta uruguayo Juan Zorrilla de San Martín."],["Diógenes Taborda","calle","Diógenes Taborda (1890 a 1926), caricaturista; dibujante y redactor del diario Crítica; realizador de la película de dibujos animados de objetivo político El Apóstol."],["Tacuara","calle","Tacuara: voz guaraní que designa a una caña semejante al bambú que crece en casi toda Sudamérica, conociéndosela con este nombre en la Argentina, Chile y Uruguay."],["Tacuarí","calle","Tacuarí: combate librado el 9 de marzo de 1811 por las tropas del general Belgrano en su expedición al Paraguay."],["Tafí","calle","Tafí: ciudad y departamento de la provincia de Tucumán."],["Tagle","calle","Gregorio García de Tagle (1772 a 1845), jurisconsulto; asiste al Cabildo Abierto del 22 de mayo de 1810; secretario de Estado a cargo del Departamento de Gobierno del Director Supremo Pueyrredón de 1817 a 1819; encabeza el movimiento revolucionario de 1823."],["Reino de Tailandia","plazoleta","Tailandia: estado del Asia. Capital: Bangkok."],["El Tala","calle","Tala: árbol de la familia de las urticáceas."],["Talavera","calle","Talavera: ciudad fundada el 15 de agosto de 1567 por Diego Pacheco en la actual provincia de Salta, con el nombre de Nuestra Señora de Talavera, aunque se la conoció principalmente con el de Talavera de Esteco o simplemente Esteco."],["Talcahuano","calle","Talcahuano: ciudad fortificada y puerto de Chile ocupada por los realistas y atacada por las fuerzas de O´Higgins el 6 de diciembre de 1817. Rechazado ese ataque, Talcahuano será tomada en 1819 por Antonio González Balcarce."],["José P. Tamborini","calle","José Pascual Tamborini (1886 a 1955), médico y político; presidente del comité capitalino de la Unión Cívica Radical; ministro del Interior de 1925 a 1928; senador por la Capital de 1940 a 1943; candidato a presidente de la República en 1946."],["Tandil","calle","Tandil: ciudad, partido y sierras de la provincia de Buenos Aires."],["Del Tango","plazoleta","Tango: homenaje a la música nacional ciudadana."],["Ricardo Tanturi","plazoleta","Ricardo Tanturi (1905 a 1973), músico, compositor y autor de Campeonato, Mozo guapo, Decís que no te quiero, Desprecio y Pocas palabras."],["Tapalqué","calle","Tapalqué: ciudad y partido de la provincia de Buenos Aires."],["Tarija","calle","Tarija: ciudad y departamento de Bolivia que fue hasta 1826 provincia argentina."],["Tartagal","calle","Tartagal: ciudad de la provincia de Salta, cabecera del departamento de General San Martín."],["Tasso","calle","Torcuato Tasso (1544 a 1595), poeta italiano; autor de Reinaldo, Jerusalén libertada, Jerusalén conquistada, Ruinas y Aminta."],["De la Técnica","calle","Técnica: homenaje a la técnica, conjunto de procedimientos de los que se sirve una ciencia, arte o industria."],["Coronel Toribio Tedín","plazoleta","José Toribio Tedín (?-1847), militar; combate en Las Piedras, Tucumán y Salta; ministro de Gobierno de Salta, nombrado por Güemes, de 1815 a 1820; acompaña a Arenales en la campaña al Alto Perú."],["Juez Tedín","calle","Virgilio Mariano Tedín (1850 a 1893), jurisconsulto; asesor de menores de la provincia de Buenos Aires en 1875; juez de primera instancia en lo civil de la Capital Federal."],["Tegucigalpa","calle","Tegucigalpa: ciudad capital de Honduras y del municipio de su nombre."],["Armando Tejada Gómez","cantero central","Armando Tejada Gómez (1929 a 1992), poeta y compositor; autor junto con el músico César Isella de Canción para todos y Fuego en Animaná. Autor de los libros Tonadas de la piel, Antología de Juan y Canto popular de las comidas."],["Luis José de Tejeda","plazoleta","Luis José de Tejeda (1604 a 1680), sacerdote y poeta; procurador general de la ciudad de Córdoba en 1634 y alcalde de primer voto en 1637; autor de El peregrino de Babilonia, Romances al niño Jesús, Santa Rosa de Lima y A las soledades de María Santísima; es considerado el primer poeta argentino."],["Tejedor","calle","Carlos Tejedor (1817 a 1903), jurisconsulto y político; redactor de El Nacional; ministro de Relaciones Exteriores de Sarmiento; gobernador de Buenos Aires de 1878 a 1880; abandona el gobierno al ser derrotado por las fuerzas nacionales que declaran a Buenos Aires capital de la República Argentina."],["Los Telares","calle","Telares: recuerda a los viejos telares que se usaban en las provincias del Norte para la confección de ponchos, mantas y ropas en general."],["Temperley","calle","Temperley: ciudad del partido de Lomas de Zamora, provincia de Buenos Aires, que perpetúa el nombre del hacendado de origen inglés Jorge Temperley (1823 a 1900), quien funda en sus tierras el pueblo que lleva su nombre y construye por su cuenta la estación ferroviaria del lugar."],["Del Temple","calle","Temple: nombre tradicional que entre 1822 y 1883 perteneció a la actual Viamonte. El nombre provenía de la plaza del Temple, denominación con la que se conoció a la actual plaza Suipacha desde 1810 hasta 1893 por haberse instalado frente a ella una fábrica de armas en la cual se “templaban” las hojas de acero. Cabe señalar que según Taullard en su obra Los planos más antiguos de Buenos Aires este nombre era un homenaje al cautiverio sufrido por el rey de Francia Luis XVI y su familia en la prisión del Temple. Consideramos que esta versión carece de fundamentos."],["Juan B. Terán","plaza","Juan B. Terán (1880 a 1938), jurisconsulto e historiador; rector de la Universidad de Tucumán en 1914; presidente del Consejo Nacional de Educación en 1930; autor de El general José María Paz, Tucumán y el Norte argentino, El descubrimiento de América en la historia de Europa y El nacimiento de la América española."],["Mary Terán de Weiss","cantero central","María Luisa Terán de Weiss (1934 a 1984), tenista; gana los campeonatos internacionales en singles y dobles de Uruguay, Brasil, Dinamarca, Suiza, Bélgica, Yugoslavia, Austria, Francia, España, Filipinas, Grecia, Turquía, Israel, Líbano, Pakistán, India, Egipto, Italia, Portugal y Nicosia."],["Madre Teresa de Calcuta","espacio verde","Agnes Gonxha Bajaxhiu (1910 a 1997), religiosa albanesa; inicia su noviciado en el año 1928 al ingresar a la Orden de las Hermanas de Loreto en la ciudad de Dublín y recibe el nombre de Teresa por el de Santa Teresa de Lisleux. En 1929 llega a la India donde enseña geografía en la escuela de un convento en Calcuta; en 1936 hace votos de pobreza, castidad y obediencia; en 1949 funda la Orden Religiosa de las Misioneras de la Caridad; en 1979 recibe el Premio Nobel de la Paz por su trabajo con los desamparados y moribundos del mundo."],["Terrada","calle","Juan Florencio Terrada (1782 a 1824), general; combate durante las Invasiones Inglesas y en el sitio de Montevideo; gobernador de San Luis en 1813; ministro de Guerra de Pueyrredón de 1816 a 1817."],["Terrero","calle","Juan Nepomuceno Terrero (?-1865), comerciante; síndico de la obra de la iglesia de San José de Flores en 1831; juez de paz en 1832 y 1833; diputado por Flores a la Sala de Representantes. Esta calle se encuentra en las tierras de la antigua quinta de Terrero, ubicada en las actuales Rivadavia y Boyacá, y en la cual se alojó Rosas en numerosas oportunidades. Se firmó también en esta casa el Pacto de San José de Flores."],["Los Territorios","calle","Territorios Nacionales: recuerda a los territorios nacionales, cuyo origen se remonta a las Leyes N° 28 del 13 de octubre de 1862 en la que se declaró que “todos los territorios existentes fuera de los límites o posesión de las provincias son nacionales”, y N° 1.532 del 1° de octubre de 1884 en la que se establece el gobierno y organización de los territorios nacionales y determina que, cuando los mismos alcancen a sesenta mil habitantes, pasarán a ser provincias. Fueron territorios nacionales La Pampa, Neuquén, Río Negro, Chubut, Santa Cruz, Misiones, Chaco, Formosa y Tierra del Fuego, Antártida e Islas del Atlántico Sur. También existió el Territorio Nacional de Los Andes, creado por Ley del 9 de enero de 1903, y desmembrado por Decreto-Ley del 21 de septiembre de 1943 anexándoselo a Jujuy, Salta y Catamarca."],["José A. Terry","calle","José Antonio Terry (1846 a 1913), jurisconsulto; ministro de Hacienda de Luis Sáenz Peña de 1893 a 1895; ministro plenipotenciario y enviado extraordinario en Chile en 1902 durante los llamados Pactos de Mayo; ministro de Relaciones Exteriores y Culto de 1903 a 1904; ministro de Hacienda de Quintana de 1904 a 1906."],["Thames","calle","Legajo 3, 1882. Obras Públicas). José Ignacio Thames (1762 a 1832), sacerdote; diputado por Tucumán en el Congreso de 1816 que declara nuestra Independencia."],["Carlos Thays","jardín botánico","Carlos Thays (1849 a 1934), arquitecto paisajista de origen francés; director general de Paseos de la Municipalidad de Buenos Aires desde 1891; creador y director del Jardín Botánico que lleva su nombre."],["Carlos Thays","parque","Carlos Thays (1849 a 1934), arquitecto paisajista de origen francés; director general de Paseos de la Municipalidad de Buenos Aires desde 1891; creador y director del Jardín Botánico que lleva su nombre."],["Juan M. Thome","calle","Juan M. Thome (1843 a 1908), astrónomo estadounidense; director del Observatorio Nacional de Córdoba en 1885; participa en la confección del Catálogo General Argentino; descubridor del cometa que lleva su nombre."],["Thompson","calle","Martín Jacobo Thompson (1777 a 1819), coronel de marina; combate durante las Invasiones Inglesas; asiste al Cabildo Abierto del 22 de mayo de 1810; capitán del puerto de Buenos Aires en ese mismo año; diputado de las Provincias Unidas en los Estados Unidos en 1816."],["Thorne","calle","Juan B. Thorne (1807 a 1885), coronel de marina; combate durante la guerra contra el Brasil; participa en 1832 a las órdenes de Juan Manuel de Rosas en la campaña del Colorado; combate en Vuelta de Obligado, Caaguazú, Tonelero y en el sitio de Buenos Aires de 1853."],["César Tiempo","plazoleta","César Tiempo seudónimo de Israel Zeitlin (1906 a 1980), poeta y escritor de origen ucraniano; director del Suplemento Cultural de La Prensa de 1952 a 1955; autor de Libro para la pausa del sábado, Sábadomingo, Pan criollo (Premio Nacional de Teatro de 1937), Moravia, Vivian Wilde y compañía y El becerro de oro."],["Antártida e Islas del Atlántico Sur, Pro- Vincia de Tierra del Fuego","cantero central","Tierra del Fuego, Antártida e Islas del Atlántico Sur: provincia de la República Argentina. Capital: Ushuaia."],["Del Tigre","calle","Cabeza del Tigre: lugar próximo a la posta de Cruz Alta, en la provincia de Córdoba, donde son fusilados Santiago de Liniers, el coronel Santiago Allende, el tesorero Victoriano Rodríguez, el contador Joaquín Moreno y el ex gobernador Juan Gutiérrez de la Concha, el 26 de agosto de 1810. Eran los cabecillas de un movimiento opositor a la Primera Junta. Si bien las obras de Carranza señalan que es éste un nombre tradicional, y Udaondo menciona como razón tradicional de este nombre a un delincuente que merodeaba la zona disfrazado con una piel de tigre, creemos que no cabe, en este caso, atenerse a esa definición. La Ordenanza del 27-11-1893 no designa a ninguna calle con nombres originados en la tradición lugareña y, muy por el contrario, señala en el informe que le antecede, preparado por la Comisión Especial que la redacta, que “no es justo mantener en esas localidades nombres de vecinos que no tienen más título al recuerdo público que haber hecho pequeñas cesiones de terrenos”. Este punto es lo suficientemente claro como para decir que no es lógico que se perpetuara el recuerdo de un delincuente del que no existe certeza de su existencia real."],["Tilcara","calle","Tilcara: ciudad y departamento de la provincia de Jujuy."],["Timbó","calle","Timbó: puerto y pueblo sobre el río Paraguay, provincia del Chaco, en el cual desembarca el 8 de octubre de 1884 el general Benjamín Victorica para iniciar su campaña del Chaco. Dos días después cambia el nombre del lugar por el de Puerto Bermejo. Actualmente se conoce con el nombre de Timbó a un paraje del lugar."],["Timbúes","calle","Timbúes: aborígenes que ocupaban la margen derecha del río Paraná en la actual provincia de Santa Fe."],["Tinogasta","calle","Tinogasta: ciudad y departamento de la provincia de Catamarca."],["Toay","calle","Toay: departamento de la provincia de La Pampa."],["Tobas","calle","Tobas: aborígenes del Chaco que integran el grupo cultural y lingüístico de los guaycurúes."],["Plaza de Todos","plaza","Plaza de Todos: esta plaza fue construida mediante el esfuerzo de los vecinos y fue inaugurada el 25 de junio de 1994. Su nombre, elegido mediante votación, rinde homenaje a la participación de toda una comunidad barrial en pos de un objetivo común."],["Tokio","calle","Tokio: ciudad capital del Japón y de la prefectura de su nombre."],["Toledo","calle","Toledo: ciudad y provincia de España."],["Toll","calle","Juan Antonio Toll y Bernadet (1790 a 1864), coronel de marina; comandante del bergantín nacional Primero; en calidad de corso, en 1814, llega en su excursión hasta Calcuta; secretario de Brown durante la guerra contra el Brasil."],["Tonelero","calle","Tonelero: derrota de las fuerzas del general Lucio Mansilla frente a la escuadra brasileña que apoyaba a Urquiza, ocurrida el 17 de diciembre de 1851 en el paso del Tonelero, sobre el río Paraná, entre Ramallo y San Nicolás."],["Ernesto Tornquist","avenida","Ernesto Tornquist (1842 a 1908), comerciante, industrial y financista; directivo del Banco de la Provincia de Buenos Aires y del Hipotecario Nacional; fundador de la Refinería de Rosario y organizador de la Compañía Azucarera Tucumana."],["Lisandro de la Torre","calle","Lisandro de la Torre (1868 a 1939), médico y político; presidente de la Sociedad Rural Rosarina en 1907; funda el partido Demócrata Progresista en 1914; candidato a la presidencia de la Nación en 1916; senador por Santa Fe de 1922 a 1925 y de 1932 a 1935, cuando renuncia a su banca a raíz de la muerte del senador Enzo Bordabehere en pleno recinto del Senado; deja varias obras, entre ellas La cuestión social y las crisis sociales, Otra página de historia y Grandeza y decadencia del fascismo."],["Leopoldo Torre Nilson","plazoleta","Leopoldo Torre Nilson (1924 a 1978), director cinematográfico; con su aporte innova la cinematografía al producir obras como El hijo del crack, La casa del ángel, Un guapo del 900 y La mano en la trampa."],["Torrent","calle","Luciano Torrent (1819 a 1896), jurisconsulto y médico; diputado en el Congreso de 1853; gobernador de Corrientes."],["Presidente Torres y Tenorio","calle","José Camilo Clemente Torres y Tenorio (1766 a 1816), jurisconsulto y estadista colombiano; autor de Memorial de Agravios; presidente de 1812 a 1814 y en 1815; tomado prisionero por el general Morillo, es fusilado en 1816."],["Omar Torrijos","cantero","Omar Torrijos (1921 a 1981), militar y político panameño; participa en el derrocamiento de Arnulfo Arias en 1968; nombrado Jefe de Gobierno en 1972, sigue una línea reformista en la política interior y formula enérgicas reclamaciones de la Zona del Canal a EE.UU., las que culminan en 1977, con la firma del tratado con ese país, por el que se fija para el año 2000 la restitución a Panamá de la soberanía sobre el mismo."],["Arturo Toscanini","calle","Arturo Toscanini (1867 a 1957), músico italiano; director de la orquesta de la Scala de Milán, de la Opera Metropolitana de Nueva York y de la Filarmónica de Nueva York; director invitado de la Orquesta de Filadelfia; visita Buenos Aires en 1901, 1903, 1904, 1906, 1912, 1940 y 1941 y actúa en el Teatro Colón."],["Totoral","calle","Totoral: departamento de la provincia de Córdoba."],["Traful","calle","Traful: lago y río de la provincia de Neuquén."],["El Trébol","calle","Trébol: planta herbácea muy difundida en todo el país."],["Treinta y Tres Orientales","calle","Treinta y Tres Orientales: número de los patriotas que al mando de Juan Antonio de Lavalleja invadieron el Uruguay el 19 de abril de 1825, dispuestos a libertar el territorio en poder de las fuerzas brasileñas."],["Nemesio Trejo","calle","Nemesio Trejo (1862 a 1916), escritor y autor teatral; autor de Un día en la Capital, El Registro Civil, Los vividores, Los políticos, Libertad de sufragio, Frutas y verduras, La trilla y Los inquilinos."],["Manuel Ricardo Trelles","calle","Manuel Ricardo Trelles (1821 a 1893), historiador y publicista; director del Archivo General de la Nación de 1858 a 1875 y de la Biblioteca Nacional hasta 1884; autor de la trilogía Cuestión de límites entre la República Argentina y Bolivia, ...Chile y ...Paraguay, Apuntes para la historia del puerto de Buenos Aires y Diego García, primer descubridor del Río de la Plata."],["Trenque Lauquen","calle","Trenque Lauquen: ciudad y partido de la provincia de Buenos Aires."],["Tres Arroyos","calle","Tres Arroyos: ciudad y partido de la provincia de Buenos Aires. 3 DE FEBRERO (calle). Plano del Proyecto de Traza del Pueblo de Belgrano levantado por el Departamento Topográfico de la Provincia de Buenos Aires y aprobado por su gobierno el 6-12-1855. 3 DE FEBRERO (parque). Ley N° 658 del 25-6-1874. 3 de febrero de 1852: fecha de la batalla de Caseros, donde las fuerzas de Urquiza derrotan a las de Juan Manuel de Rosas."],["Tres Lomas","calle","Tres Lomas: localidad de la provincia de Buenos Aires en el partido de Pellegrini."],["Tres Sargentos","calle","Tres Sargentos: hazaña realizada por los soldados José Mariano Gómez, Santiago Albarracín y Juan Bautista Salazar el 24 de octubre de 1813, cuando atacaron por sorpresa a las fuerzas realistas en la Posta de Tambo Nuevo apresando a diez hombres que supusieron que eran atacados por una fuerza mayor; por ello fueron los tres soldados ascendidos a sargento."],["Tréveris","calle","Tréveris: ciudad de la República Federal Alemana."],["Rodrigo de Triana","calle","Rodrigo de Triana (¿-?), marino; su verdadero nombre era Juan Rodríguez Bermejo y como tripulante de la carabela La Pinta fue el primero en divisar tierra americana en la expedición de Cristóbal Colón en 1492."],["Tric y Trake","cantero central","Tric y Trake: protagonista de la historieta creada por Federico Norberto Daloisio, que aparece por primera vez en el diario El Mundo y que en 1954 comienza a publicarse como revista."],["Trieste","calle","Trieste: ciudad y provincia de Italia."],["La Trilla","calle","Trilla: operación en la que se separa el grano de la paja de los cereales y un buen número de leguminosas."],["Trinidad Tobago","plazoleta","Trinidad Tobago: país americano de las Antillas. Capital: Puerto España."],["Trípoli","calle","Trípoli: ciudad capital de Libia y de la provincia de su nombre."],["Triunvirato","avenida","Triunvirato: Poder Ejecutivo que el 23 de septiembre de 1811 sustituyó a la Junta Grande y que gobernó el país hasta el 26 de enero de 1814, cuando sus miembros cesan en el mando al crearse el Directorio."],["Aníbal Troilo","calle","TROILO “PICHUCO”, ANÍBAL (vereda). Ley Nº 2.380-2007, BO Nº 2.747. Aníbal Troilo (1914 a 1975), músico; su apodo de Pichuco es como un segundo nombre; llamado “el Bandoneón Mayor de Buenos Aires”, es el creador de un estilo bandoneonístico único e inconfundible; compositor de Pa´ que bailen los muchachos, Responso, Discepolín, La última curda, Sur, Che bandoneón, Barrio de tango, María y Romance de barrio."],["Aníbal Troilo","cantero central","TROILO “PICHUCO”, ANÍBAL (vereda). Ley Nº 2.380-2007, BO Nº 2.747. Aníbal Troilo (1914 a 1975), músico; su apodo de Pichuco es como un segundo nombre; llamado “el Bandoneón Mayor de Buenos Aires”, es el creador de un estilo bandoneonístico único e inconfundible; compositor de Pa´ que bailen los muchachos, Responso, Discepolín, La última curda, Sur, Che bandoneón, Barrio de tango, María y Romance de barrio."],["Trolé","calle","Domingo Eduardo Trolé (¿-?), coronel de origen francés; combate durante la guerra contra el Brasil; incorporado a las filas de Lavalle, es designado por éste para que lo represente ante el general San Martín."],["Tronador","calle","Tronador: cerro de la Cordillera de los Andes, en el departamento de Bariloche, Río Negro."],["Juan Tronconi","espacio público","Juan Tronconi (1841-?) empresario italiano y uno de los precursores del ramo de los chacinados; se establece en el barrio de Nueva Pompeya en el año de 1877; funda la empresa Tronconi-Gaudencio. Su familia dona al municipio este espacio público, con la finalidad de que el mismo lleve su nombre en homenaje a su memoria y a sus aportes para el desarrollo del barrio."],["Emilio Troncoso","plazoleta","Emilio Troncoso (1906 a 1973), vecino de Villa Lugano, barrio en el que se instaló en 1920; allí desplegó una intensa actividad fomentista y comunitaria; socio fundador del Club Pampero en 1946; militante radical; asesor del intendente Francisco Rabanal en 1963."],["El Trovador","calle","Trovador: homenaje al trovador o payador; hombre de campo que canta acompañado de la guitarra improvisando coplas."],["Julio Troxler","calle","Julio Tomás Troxler (?-1974), militante peronista; sobrevive a los fusilamientos de José León Suárez en 1956; en 1973, durante la gestión como gobernador de la provincia de Buenos Aires del doctor Oscar Bidegain, se desempeña como Jefe de la Policía de la provincia de Buenos Aires. Es asesinado el 20 de septiembre de 1974 en una emboscada en el pasaje Coronel Rico."],["Provincia de Tucumán","cantero central","Tucumán: ciudad y provincia de la República Argentina."],["Las Tunas","calle","Tunas: nombre tradicional con el cual se denominó a las actuales Callao y Entre Ríos hasta 1822 y que provenía de los cercos de tunas que existían sobre ella."],["Túnez","calle","Túnez: república de África. Capital: Túnez."],["Tupac Amarú","calle","José Gabriel Condorcanqui (¿1743?-1782), precursor de la independencia americana llamado Tupac Amarú; era cacique de Tungasuca e inició en 1780 una rebelión contra el poder español; fue vencido y descuartizado."],["Tupiza","calle","Tupiza: ciudad del Alto Perú, cerca de Suipacha, en poder de los realistas, que fue sorprendida por las fuerzas patriotas mandadas por el capitán Juan Rosa del Castillo en junio de 1820 y por las del coronel José María Pérez Urdininea en marzo de 1825."],["Turín","calle","Turín: ciudad y provincia de Italia."],["Turquía","calle","Turquía: país euroasiático. Capital: Ankara."],["Tuyú","calle","Tuyú: antiguo partido de la provincia de Buenos Aires denominado desde 1910 General Madariaga."],["Tuyutí","calle","Tuyutí: batalla en la que el general Bartolomé Mitre vence a las fuerzas paraguayas el 24 de mayo de 1866. Notas."],["Ucacha","calle","Ucacha: población y estación ferroviaria de la provincia de Córdoba."],["Enrique Udaondo","plazoleta","Enrique Udaondo (1880 a 1962), historiador; director del Museo Colonial e Histórico de Luján de 1923 a 1945; organizador de los Museos Casa del Acuerdo de San Nicolás y del Gauchesco de San Antonio de Areco; autor de Significado del nombre de las plazas y calles de Buenos Aires, Congresales de Tucumán, Árboles históricos, Diccionario biográfico colonial y Diccionario biográfico argentino."],["Guillermo Udaondo","avenida","Guillermo Udaondo (1859 a 1922), médico; gobernador de Buenos Aires en 1894; presidente del Departamento Nacional de Higiene."],["Ciudad de Udine","plaza","Udine: ciudad de Italia, capital de la provincia de su nombre."],["Manuel Ugarte","calle","Manuel Ugarte (1878 a 1951), escritor y diplomático; embajador argentino en México, Nicaragua y Cuba; incansable propagador de la unidad latinoamericana; autor de La novela de las horas y los días, Una tarde gris, Cuentos de la Pampa, Visiones de España, El dolor de escribir, El porvenir de la América Española, Mi campaña hispanoamericana, El destino de un continente, La Patria Grande y El naufragio de los argonautas."],["Ugarteche","calle","José Francisco de Ugarteche (1768 a 1834), jurisconsulto; diputado por La Rioja en la Asamblea de 1813; director de El Argentino en 1824; diputado en el Congreso de 1826; ministro de Hacienda de Balcarce."],["Ukrania","calle","Ukrania: país del este de Europa. Capital: Kiev."],["Miguel de Unamuno","calle","Miguel de Unamuno (1864 a 1936), escritor español; autor de Vida de Don Quijote y Sancho, Del sentimiento trágico de la vida, Paz en la guerra, La dignidad humana, Tres novelas ejemplares y un prólogo, El Otro y Andanzas y visiones españolas."],["Miguel de Unamuno","plazoleta","Miguel de Unamuno (1864 a 1936), escritor español; autor de Vida de Don Quijote y Sancho, Del sentimiento trágico de la vida, Paz en la guerra, La dignidad humana, Tres novelas ejemplares y un prólogo, El Otro y Andanzas y visiones españolas."],["Unanué","calle","José Hipólito Unanué (1758 a 1833), escritor, naturalista y político peruano; fundador de la Escuela de Medicina de San Fernando de Lima; ministro de Hacienda de San Martín; presidente del primer Congreso Constituyente y del Consejo de Ministros."],["Unidad Nacional","plaza","Unidad Nacional: invoca a la unidad de los argentinos."],["Unión Europea","cantero central","Unión Europea: organización supranacional europea dedicada a incrementar la integración económica y política, y reforzar la cooperación entre sus estados miembros. Establecida el 1º de noviembre de 1993, cuando entra en vigor el Tratado de la Unión Europea (TUE), es la sucesora de las Comunidades Europeas, creadas en los años 50 del siglo XX. El proceso hacia la unificación de Europa tiene un momento destacado en 2002 con la entrada en circulación del euro, como moneda de curso legal en los países del grupo."],["Baltasar de Unquera","calle","Baltasar de Unquera (1766 a 1807), teniente de navío; edecán de Liniers, muere en la Defensa de Buenos Aires ante las Invasiones Inglesas. Es éste un nombre tradicional de la ciudad, pues entre 1808 y 1822 se denominaron “Unquera” las actuales Florida y Perú."],["Urdaneta","calle","Rafael Urdaneta (1789 a 1845), general y político venezolano; lucha por la Independencia; jefe provisional del gobierno de Colombia de 1830 a 1831."],["Urdininea","calle","José María Pérez de Urdininea (1782 a 1865), general; gobernador de San Juan de 1822 a 1823; presidente de la Asamblea General Constituyente de Bolivia en 1826; presidente interino de esa república en 1828 y 1842."],["Uriarte","calle","Legajo 3, 1882. Obras Públicas). Pedro Francisco de Uriarte (1758 a 1839), sacerdote; diputado por Santiago del Estero en el Congreso de Tucumán."],["Uriburu","calle","Evaristo de Uriburu (1796 a 1885), coronel; combate en las Piedras, Tucumán, Salta y Chacabuco; gobernador de Salta en 1831, 1838 y 1842."],["General Napoleón Uriburu","calle","Napoleón Uriburu (1838 a 1895), militar; combate durante la guerra contra el Paraguay; gobernador del territorio del Chaco en 1875 y 1895; participa en la expedición al desierto de Roca en 1879 y en la del Nahuel Huapi de Villegas en 1881."],["Presidente José Evaristo Uriburu","calle","José Evaristo Uriburu (1831 a 1914), jurisconsulto; vicepresidente de la República durante la presidencia de Luis Sáenz Peña de 1892 a 1895 y presidente de la misma tras la renuncia de éste hasta 1898."],["Urién","calle","Carlos Urién (1816 a 1893), coronel; actúa en la expedición al desierto de 1833, en el sitio de Buenos Aires en 1852 y en la guerra contra el Paraguay; participa en la revolución de 1880. José María Urién (1791 a 1823), capitán; combate durante las Invasiones Inglesas, en Cotagaita, Suipacha y Huaqui; participa en 1823 en el movimiento encabezado por Tagle y es fusilado por ello. URONDO, FRANCISCO “PACO” (plazoleta). Ordenanza N° 52.135-1997, BO N° 365. Francisco Urondo (1930 a 1976), poeta; colabora como periodista en diversos medios nacionales y extranjeros, entre ellos Primera Plana, Crisis, La Opinión y Noticias; autor de Historia antigua, Breves, Lugares, Nombres y Del otro lado; de la novela Los pasos previos y del libro La patria fusilada (entrevistas). Muere en un enfrentamiento armado en junio de 1976."],["Villa Urquiza","barrio","Justo José de Urquiza (1801 a 1870), militar; gobernador de Entre Ríos; vencedor en Caseros y Cepeda; gobernador de Buenos Aires en 1852; director provisorio de la Confederación en 1852 y 1853 y presidente de la Confederación Argentina de 1854 a 1860."],["Comodoro Clodomiro Urtubey","calle","Clodomiro Urtubey (1840 a 1902), marino; combate en la guerra contra el Paraguay; director de los Talleres de Marina y presidente de la Comisión Naval en Londres en 1890."],["Uruguay","calle","Uruguay: río que nace en las sierras de Santa Catalina, Brasil, y desemboca en el Río de la Plata. Es límite de la Argentina con el Brasil y el Uruguay."],["República Oriental del Uruguay","plaza","Uruguay: país americano. Capital: Montevideo."],["Urunday","calle","Urunday: árbol de la familia de las anacardiáceas que se encuentra en la zona tropical y que abunda en nuestras provincias mesopotámicas, Jujuy, Salta y Chaco."],["Uspallata","calle","Uspallata: paso de la Cordillera de los Andes en la provincia de Mendoza por el que cruza una división del Ejército Libertador al mando del general Juan Gregorio de Las Heras."],["Francisco de Uzal","calle","Francisco de Uzal (1783 a 1823), coronel; combate durante las Invasiones Inglesas y en la expedición al Paraguay de Belgrano; comandante militar de San Fernando, delinea topográficamente los partidos de Olivos, Vicente López, San Fernando y San Isidro. Notas."],["Alberto Vacarezza","espacio verde","Bartolo Ángel Vaccarezza (1886 a 1959), dramaturgo, escritor conocido por su nombre artístico de Alberto Vacarezza; creador del sainete en nuestro país; autor de La casa de los Batallán, Los cardales, Lo que pasó a Reynoso, San Antonio de los pobres, Tu cuna fue un conventillo y El conventillo de la Paloma."],["Valdenegro","calle","Eusebio Valdenegro y Leal (1783 a 1818), general; combate en las Piedras y en el sitio de Montevideo; teniente gobernador de Corrientes en 1812 y 1814; combate en Palmar y Guayabos."],["Valderrama","calle","Valderrama: pueblo del departamento de Monteros, provincia de Tucumán."],["Pedro de Valdivia","calle","Pedro de Valdivia (1500 a 1554), conquistador español; fundador de Santiago de Chile en 1541."],["Valencia","calle","Valencia: ciudad y provincia de España."],["Tomás Valencia","calle","Tomás Valencia (?-1806), particular de valerosa actuación que muere durante la Reconquista de Buenos Aires en 1806. Es éste un nombre tradicional de la ciudad, pues entre 1808 y 1822 se denominó “Valencia” la actual Cochabamba."],["Valle","calle","Tomás Antonio Valle (1757 a 1830), jurisconsulto; preside la Asamblea de 1813; asesor y auditor del Ejército en 1815."],["Aristóbulo del Valle","calle","Aristóbulo del Valle (1845 a 1896), jurisconsulto; ministro de Gobierno de Bue- nos Aires durante las gobernaciones de Álvaro Barros y Casares; presidente provisional del Senado en 1880; propulsor de la revolución de 1890; ministro de Guerra y Marina en 1893."],["Aristóbulo del Valle","plaza","Aristóbulo del Valle (1845 a 1896), jurisconsulto; ministro de Gobierno de Bue- nos Aires durante las gobernaciones de Álvaro Barros y Casares; presidente provisional del Senado en 1880; propulsor de la revolución de 1890; ministro de Guerra y Marina en 1893."],["General Juan José Valle","cantero central","Juan José Valle (1904 a 1956), militar; General de División que el 9 de junio de 1956 encabezó el levantamiento militar contra el gobierno de la Revolución Libertadora, presidida por el vicepresidente provisional Isaac Rojas, siendo capturado y fusilado."],["María Remedios del Valle","calle","María Remedios del Valle (?-1847), sargento mayor del Ejército; heroína de la Independencia, de raza negra, asiste a los combates de Tucumán, Salta, Vilcapugio y Ayohuma, donde cae prisionera."],["Enrique del Valle Iberlucea","calle","Enrique del Valle Iberlucea (1878 a 1921), jurisconsulto y político socialista; profesor del Colegio Nacional de Buenos Aires, de la Facultad de Filosofía y Letras de Buenos Aires y de la de Derecho de La Plata; senador nacional en 1913; director de La Vanguardia en 1916 y 1917; autor de La lucha de clases y Nacionalismo e internacionalismo."],["César Vallejo","cantero central","César Vallejo (1892 a 1938), poeta peruano alineado en el movimiento surrealista junto a André Bretón; autor de Los heraldos negros, Trilce, España y Aparta de mí este cáliz."],["Vallejos","calle","Andrés de Vallejos (¿-?), acompaña a Garay en la fundación de Buenos Aires en 1580."],["Felipe Vallese","calle","Felipe Vallesse (1940 a 1962), militante peronista y delegado gremial en 1958; fue secuestrado y muerto en la noche del 23 de agosto de 1962 por una comisión policial de San Martín."],["Valparaíso","calle","Valparaíso: ciudad y provincia de la República de Chile."],["Matilde Vara de Anguita","patio recreativo","Matilde Vara de Anguita (1926 a 1978), a raíz de la detención de su hijo Eduardo en septiembre de 1973 (quien recupera su libertad en 1984) se ocupa de la situación de los presos. Es secuestrada el 24 de julio de 1978. Permanece desaparecida."],["José Varas","calle","José Varas (?-1910), periodista; redactor de La Nación; presidente del Círculo de La Prensa."],["Varela","avenida","Florencio Varela (1807 a 1848), jurisconsulto y periodista; escribe en El Mensajero Argentino, El Pampero y El Tiempo; miembro de la comisión argentina que lucha contra Rosas desde Montevideo; miembro fundador del Instituto Histórico y Geográfico del Uruguay y del Comercio del Plata. Juan Cruz Varela (1794 a 1839), periodista y poeta; redactor del Centinela, El Mensajero Argentino, El Porteño y El Tiempo; autor de Cantos a la batalla de Ituzaingó y Oda a los trabajos hidráulicos. Homenaje conjunto a los hermanos Varela."],["Jacobo Adrián Varela","calle","Jacobo Adrián Varela (?-1807), capitán de Granaderos del Tercio de Galicia; actúa brillantemente durante las Invasiones Inglesas y muere durante la Defensa. Es este un nombre tradicional de Buenos Aires pues entre 1808 y 1822 se denominaron “Varela” las actuales Lima y Cerrito."],["José Pedro Varela","calle","José Pedro Varela (1845 a 1879), educador uruguayo; fundador del diario La Paz de Montevideo; autor de De la legislación escolar; director general de Instrucción Pública en 1876."],["Teniente Coronel Don Héctor Varela","cantero central","Héctor B. Varela (?-1923), militar; comanda en 1920 y 1921 la represión de la revuelta obrera conocida como la Patagonia Trágica; es asesinado por un anarquista frente a su casa de Fitz Roy 2461 el 27 de enero de 1923."],["Varsovia","calle","Varsovia: ciudad capital de Polonia y del vaivodato de su nombre."],["Estado del Vaticano","plaza","Estado del Vaticano: Estado de Europa, enclavado en Roma (Italia); residencia del Sumo Pontífice de la Iglesia Católica Apostólica Romana."],["Doctor Carlos Vaz Ferreira","calle","Carlos Vaz Ferreira (1872 a 1958), jurisconsulto, escritor y pedagogo uruguayo; rector de la Universidad de Montevideo de 1920 a 1930 y de 1935 a 1937; autor de Fermenterio, Lógica viva, Sobre problemas sociales y La propiedad de la tierra."],["Ramón Vázquez","cantero central","Ramón Vázquez (1897 a 1983), futbolista de Huracán, equipo con el que se consagra campeón en 1921, 1922 y 1925; fundador de la Asociación Mutual Veteranos del Club Atlético Huracán."],["De los Vecinos Sensibles","plazoleta","De los Vecinos Sensibles: homenaje a la Asociación de Vecinos Sensibles de Palermo, por su participación en temas de interés municipal, aportando medios económicos y trabajos personales."],["Vedia","calle","Nicolás de Vedia (1771 a 1852), coronel mayor uruguayo; combate en Montevideo durante las Invasiones Inglesas; edecán de Saavedra en 1810; participa en el segundo sitio de Montevideo; combate en Cañada de la Cruz; jefe del Estado Mayor General del Ejército Uruguayo en 1852."],["Agustín de Vedia","calle","Agustín de Vedia (1843 a 1910), periodista uruguayo; escribe en La Reforma Pacífica de Buenos Aires; fundador y director de La América de Buenos Aires; diputado al Congreso uruguayo en 1872; colabora nuevamente en Buenos Aires en La Nación y La Prensa y funda Tribuna."],["Enrique de Vedia","calle","Enrique de Vedia (1867 a 1917), educador y escritor; director del Colegio Nacional del Uruguay; rector del Colegio Nacional de Buenos Aires de 1903 a 1912; autor de Geografía Argentina, Alcalis, Transfusión y Rosenia."],["Coronel Niceto Vega","calle","Niceto Vega (1799 a 1841), militar; combate en la expedición de Puertos Intermedios, en la guerra contra el Brasil, en Navarro, Puente del Marqués, Don Cristóbal, Sauce Grande y Quebracho Herrado."],["Lope de Vega","avenida","Félix Lope de Vega y Carpio (1562 a 1635), poeta y dramaturgo español; autor de Fuenteovejuna, Peribáñez y el comendador de Ocaña, El mejor alcalde el rey, La dama boba y El villano en su rincón."],["Ventura de la Vega","calle","Ventura de la Vega (1807 a 1865), poeta; autor de Un hombre de mundo, Don Fernando de Antequera, La muerte de César, El cantar de los cantares, El hambre y Musa diez."],["Carlos Vega Belgrano","calle","Carlos Vega Belgrano (1858 a 1930), periodista; fundador de La Actualidad, La Revista Literaria, La Revista del Plata; dirigente del Círculo de la Prensa; autor de Pensamientos, En alta voz y Así son muchachos. 20 DE FEBRERO (calle). Decreto N° 2.008-1956, BM N° 10.314. 20 de Febrero de 1813: batalla de Salta, triunfo del general Manuel Belgrano contra los realistas del general Tristán. 20 DE SEPTIEMBRE (calle). Ordenanza N° 10.423-1939, BM N° 5.587. 20 de septiembre de 1870: conmemora la gesta de la unificación italiana. En esta fecha las tropas del rey Víctor Manuel invaden los Estados Pontificios incorporando Roma al resto de Italia. El 26 de enero del año siguiente se vota en la Cámara el traslado de la residencia real y del gobierno a esa ciudad, hecho que se materializa el 2 de julio, cuando Víctor Manuel entra en la misma. 25 DE AGOSTO (plaza). Ordenanza N° 914 del 17-4-1925. 25 de agosto de 1825: fecha en la que el Congreso de la Florida reunido por Lavalleja en el pueblo de ese nombre, proclama la unidad de la Banda Oriental del Uruguay con las demás provincias argentinas. 25 DE MAYO (autopista). Ordenanza N° 33.582-1977, BM N° 15.540. 25 DE MAYO (calle). Plano topográfico del nombramiento de las principales Calles de la Ciudad de Buenos Aires y de los templos, plazas, Edificios públicos y Cuarteles en el año 1822, de Felipe Bertrés. 25 de Mayo de 1810: fecha de la instalación de la Primera Junta de Gobierno. 24 DE NOVIEMBRE (calle). Plano de la Ciudad de Buenos Aires de la Oficina Municipal de Obras Públicas de 1880. 24 de noviembre de 1820: fecha en la cual se firma el tratado de Benegas entre las provincias de Santa Fe y Buenos Aires y por el cual se establece la paz entre ambas. 24 DE SEPTIEMBRE (plaza). Ordenanza del 10-9-1912. 24 de septiembre de 1812: fecha en que se libra la batalla de Tucumán, donde el general Manuel Belgrano derrota a las fuerzas realistas de Tristán. 27 DE FEBRERO (avenida). Decreto N° 6.035-1956, BM N° 10.370. 27 de febrero de 1812: fecha en la que el general Manuel Belgrano dispone izar por primera vez la Bandera Nacional sobre las barrancas de Rosario. Cosme Maciel, ayudante de Celedonio Escalada, iza por primera vez nuestra enseña y Belgrano arenga a la tropa exigiendo el juramento de luchar por la independencia de América del Sur. 29 DE DICIEMBRE DE 2001 (espacio verde) Ley N° 1.891-2005 BO N° 2.363. 29 de diciembre de 2001: fecha en la que son muertos los jóvenes Adrián Matassa, Cristian Gómez y Maximiliano Tasca, en la esquina de Bahía Blanca y Gaona, en el barrio de Floresta, por un suboficial de la Policía Federal. Es este un caso excepcional ya que esta ley entrará en vigor a partir del año 2011, cuando se cumplan los diez años de transcurrido un hecho para poder ser incluido en la nomenclatura urbana."],["Pedro Velarde","calle","Pedro Velarde (?-1807), capitán del Tercio de Patricios que muere durante la Defensa de la ciudad ante las Invasiones Inglesas. Es éste un nombre tradicional de Buenos Aires, pues entre 1808 y 1822 se denominaron “Velarde” las actuales Salta y Libertad."],["Doctor José María Velazco Ibarra","espacio verde","José María Velazco Ibarra (1893 a 1979), político y escritor ecuatoriano; presidente de la República del Ecuador de 1934 a 1935, de 1944 a 1947, de 1952 a 1961 y de 1968 a 1972."],["Velázquez","calle","Diego Rodríguez de Silva y Velázquez (1599 a 1660), pintor español; autor de El aguador de Sevilla, Cristo en Emaús, Adoración de los magos, Los borrachos, La túnica de José, La fragua de Vulcano, La rendición de Breda, Cristo crucificado y Las Meninas."],["Doctor Bernardo Vélez","calle","Bernardo Vélez (1783 a 1862), jurisconsulto; secretario del gobernador intendente de Buenos Aires en 1812 y del Cabildo Abierto de Buenos Aires del 13 de febrero de 1816; redactor de La Gaceta en 1820; fundador de El Correo Judicial en 1834."],["Vélez Sarsfield","barrio","En 1910, la Municipalidad crea la subintendencia de este nombre, debido al aumento de la población del lugar y se concreta su identificación como barrio independiente."],["Vélez Sarsfield","avenida","Dalmacio Vélez Sarsfield (1800 a 1875), jurisconsulto; presidente de la Academia de Jurisprudencia en 1835; ministro de Hacienda de Mitre en 1862 y de Interior de Sarmiento en 1868; autor del Código Civil."],["Vélez Sarsfield","plaza","Dalmacio Vélez Sarsfield (1800 a 1875), jurisconsulto; presidente de la Academia de Jurisprudencia en 1835; ministro de Hacienda de Mitre en 1862 y de Interior de Sarmiento en 1868; autor del Código Civil."],["Venecia","calle","Venecia: ciudad y provincia de Italia."],["Venezuela","calle","Venezuela: país sudamericano. Capital: Caracas."],["Venezuela","plaza","Venezuela: país sudamericano. Capital: Caracas."],["Venialvo","calle","Lázaro de Venialvo (?-1580), acompaña a Garay en la fundación de la ciudad de Santa Fe en 1573 y en 1580 encabeza la “revolución de los mancebos” que, alegando que la ciudad había sido fundada por los nacidos en la tierra, ordenaba el retiro de los peninsulares que no habían intervenido en la empresa; reprimida la revolución, Venialvo es muerto. Algunos historiadores consideran esta revuelta como el primer antecedente independentista."],["Ventana","calle","Sierra de la Ventana: sistema montañoso de la provincia de Buenos Aires."],["Vera","calle","Juan Torres de Vera y Aragón (?-¿1606?), adelantado del Río de la Plata; sucede como tal a Juan Ortiz de Zárate; encomienda a Juan de Garay la fundación de Buenos Aires en 1580; fundador de la ciudad de Vera en el sitio que llaman de las Siete Corrientes (hoy Corrientes) el 3 de abril de 1588. Si bien la bibliografía existente sobre nomenclatura adjudica la razón de esta denominación al precursor de la independencia chilena don Bernardo de Vera y Pintado, entendemos que se trata de un error. La ubicación de este nombre otorgado por la Ordenanza del 27-11-1893, donde aparece junto a todos los fundadores de ciudades capitales argentinas que no se encontraban ya incluidos en la nomenclatura (casos de Mendoza y Garay) es elocuente. Cabe señalar aquí que la única excepción fue la del fundador de Córdoba, don Jerónimo Luis de Cabrera, en razón de que existía ya una calle Cabrera, referida, como vimos, a otra personalidad, y con lo que se hubiera incluido una denominación repetida, cosa que esta ordenanza quería precisamente evitar y para lo cual fue sancionada."],["Rosario Vera Peñaloza","plaza","Rosario Vera Peñaloza (1873 a 1950), educadora y escritora; directora de la Escuela Normal Provincial Alberdi, de Córdoba; de la Escuela Normal de Profesores N° 1 de Buenos Aires; fundadora y directora de la Escuela Argentina Modelo, junto con Carlos María Biedma; autora de La enseñanza práctica de la geometría y La casa histórica de Tucumán."],["Veracruz","calle","Veracruz: estado de México denominado oficialmente Veracruz-Llave."],["Verano Porteño","plazoleta","Verano porteño: composición musical de Astor Piazzola dada a conocer en la década de 1960, al formar la agrupación que definiría su estilo musical en forma definitiva con el Quinteto Nuevo Tango, formado por bandoneón, piano, violín, contrabajo y guitarra eléctrica."],["Jacinto Verdaguer","calle","Jacinto Verdaguer y Santaló (1845 a 1902), sacerdote y poeta español; autor de La Atlántida, Canigó y La Barrentina."],["José Verdi","calle","José Verdi (1813 a 1901), compositor italiano; autor de Rigoletto, La Traviata, Aída, Otelo y Réquiem."],["Carlos Norberto Vergara","plazoleta","Carlos Norberto Vergara (1859 a 1929), pedagogo; fundador de las revistas El Instructor popular y La Educación; inspector de escuelas de Mendoza."],["Vernet","avenida","Luis Vernet (1792 a 1871), comerciante de origen alemán; gobernador de las Malvinas en 1829."],["De Versalles","paseo","Versalles: ciudad de Francia, capital del departamento de Yuelines; forma parte de la aglomeración de París y en ella se encuentra el magnífico palacio edificado por Luis XIV. Su inclusión en la nomenclatura barrial de la ciudad se debe al Ferrocarril del Oeste, que el 1º de diciembre de 1911 inauguró allí la estación que recibió este nombre por sugerencia de José Guerrico, quien acababa de visitar Francia y llegaba admirado del célebre palacio. El paseo recibió también este nombre por encontrarse en el barrio homónimo."],["Virrey Vértiz","avenida","Juan José de Vértiz y Salcedo (1719 a 1799), militar; gobernador y virrey del Río de la Plata de 1770 a 1777 y de 1778 a 1784, respectivamente."],["Virrey Vértiz","plaza","Juan José de Vértiz y Salcedo (1719 a 1799), militar; gobernador y virrey del Río de la Plata de 1770 a 1777 y de 1778 a 1784, respectivamente."],["Vespucio","calle","Américo Vespucio (1454 a 1512), marino y cartógrafo italiano; participa en algunos viajes al nuevo mundo escribiendo las relaciones de los mismos, lo que le dio inmensa popularidad fuera de España. El alemán Martín Waldseemüller, en el mapa mundi que publica en una de sus obras, designa con el nombre de América al nuevo mundo y, aunque más tarde pretende rectificar su error al saber que fue Colón el descubridor de estas tierras, el nombre América se encontraba ya tan difundido que no fue posible modificarlo."],["Luis Viale","calle","Luis Viale (1815 a 1871), comerciante de origen italiano; fundador del Banco de Italia y Río de la Plata y del Hospital Italiano; perece en el naufragio del vapor América el 24 de diciembre de 1871 al ceder su salvavidas a la señora Carmen Pinedo de Marcó del Pont."],["Viamonte","calle","Gobernador Viamonte por Resolución del 13-8-1883. En el Plano Topográfico de la Ciudad de Buenos Aires, Municipalidad, 1895, su nombre actual. Juan José Viamonte (1774 a 1843), general; combate durante las Invasiones Inglesas y en Suipacha; gobernador intendente de Entre Ríos en 1813; gobernador provisorio de Buenos Aires en 1821 y 1829 y titular entre 1833 y 1834."],["Paseo de la Victoria","plaza","De la Victoria: homenaje al triunfo militar sobre las fuerzas inglesas, que en 1806 y 1807 intentaron apoderarse de los territorios del Río de la Plata."],["De las Victorias","parque","Victorias: homenaje a todos los triunfos obtenidos por nuestras armas a lo largo de su historia."],["General Benjamín Victorica","avenida","Benjamín Victorica (1831 a 1913), militar y jurisconsulto; combate en Caseros y Cepeda; asiste a Pavón como secretario de Guerra de Urquiza; ministro de Guerra y Marina de Derqui en 1860, de Roca de 1880 a 1885 y de Luis Sáenz Peña; presidente de la Suprema Corte de Justicia de 1888 a 1892."],["Miguel Carlos N° 13.701. Victorica","plazoleta","Miguel Carlos Victorica (1884 a 1955), pintor; autor de Desnudo entre flores y frutas, Convento y catedral, El expatriado y El secretario."],["Benjamín Vicuña Mackena","plaza","Benjamín Vicuña Mackena (1831 a 1886), político e historiador chileno; redactor jefe de El Mercurio de Valparaíso; intendente de Santiago de Chile; senador en 1876; autor de El ostracismo del general Bernardo O´Higgins, La revolución de la independencia del Perú e Historia de la campaña de Lima."],["De la Vida","paseo","De la Vida: con este nombre se rinde homenaje al reconocido médico René Favaloro (1923 a 2000) por su aporte a la cardiología y a la cirugía cardiovascular, al crear el puente aortocoronario, más conocido como bypass."],["Vidal","calle","Celestino Vidal (1780 a 1845), general; combate en la expedición al Paraguay de Belgrano y en el Ejército Auxiliar del Perú en 1814; diputado a la Legislatura de Buenos Aires en 1827, 1831 y de 1833 a 1844; jefe del Regimiento de Patricios de Buenos Aires en 1840."],["Emeric E. Vidal","calle","Emeric Essex Vidal (1791 a 1861), marino y acuarelista inglés; autor de Boleando avestruces, Aduana de Buenos Aires, Modo de enlazar ganado en Buenos Aires y otras numerosas escenas del Buenos Aires del siglo XIX."],["Nicolás E. Videla","calle","Nicolás E. Videla (1854 a 1915), jurisconsulto y economista; intendente de Quilmes; presidente del Banco de la Provincia de Buenos Aires; ministro de Hacienda de esta provincia durante el gobierno de Guillermo Udaondo; presidente del Banco Municipal."],["Videla Castillo","calle","José Videla Castillo (1792 a 1832), general; combate en Chacabuco, Talcahuano, Maipú, Pasco, en la campaña de Puertos Intermedios, en la guerra contra el Brasil, en Tablada, Oncativo y Ciudadela; gobernador provisional de San Luis en 1829 y luego de Mendoza."],["Vidt","calle","Jorge Enrique Vidt (1772-?), teniente coronel de origen francés; ingresa en 1817 en el Ejército del Alto Perú; en 1820 marcha a Salta con el general Heredia y lucha junto a Güemes; sitia la ciudad de Salta tomada por los realistas."],["Francisco de Viedma","calle","Francisco de Viedma (1737 a 1809), explorador español; fundador de Nuestra Señora del Carmen (hoy Viedma) y de Carmen de Patagones en 1779."],["Viejobueno","calle","Domingo Viejobueno (1843 a 1901), general; combate en Pavón, en la guerra contra el Paraguay y en la lucha contra el indio; jefe de Policía de Buenos Aires de 1877 a 1879 y de 1892 a 1893; director del Parque de Artillería de 1885 a 1890. Joaquín Viejobueno (1806 a 1885), coronel; combate durante la guerra contra el Brasil y en la defensa de Buenos Aires en 1852; ministro de Guerra y Marina en 1857; combate en Pavón y en la guerra contra el Paraguay. Joaquín Viejobueno (1833 a 1906), general; combate en Cepeda, Pavón y en la guerra contra el Paraguay; participa con Leandro N. Alem en la revolución de 1890. Homenaje conjunto a los tres militares. El coronel Joaquín Viejobueno era padre de los dos generales."],["Viel","calle","Benjamín Viel (1787 a 1868), general de origen francés; combate en Cancha Rayada, Maipú, en el sur de Chile y en Bío-Bío; jefe del Estado Mayor del Ejército de Chile en 1827 y de la División Sur en 1829; comandante general de Armas de Santiago de Chile."],["Viena","calle","Viena: ciudad capital de Austria y del estado de Austria Inferior."],["República Socialista de Vietnam","plazoleta","República Socialista de Vietnam: país asiático. Capital: Hanoi."],["Vieyra","calle","Jaime Vieyra (¿-?), propietario que dona terrenos para la apertura de diversas calles de la zona. (Véase Acta de la sesión ordinaria del Concejo Deliberante del 20-10-1886)."],["Vieytes","calle","Juan Hipólito Vieytes (1762 a 1815), periodista y funcionario; publica el Semanario de Agricultura, Industria y Comercio; combate durante las Invasiones Inglesas; redactor del Correo del comercio; precursor de la Revolución de Mayo, los patriotas solían reunirse en su fábrica de jabones ubicada en la intersección de las actuales 9 de Julio y México; secretario de la Junta en reemplazo de Moreno; secretario de la Asamblea de 1813."],["Constancio C. Vigil","plazoleta","Constancio C. Vigil (1876 a 1954), escritor y periodista; fundador en Montevideo de la revista Alborada; en Buenos Aires de Mundo Argentino con Alberto Haynes, y de la editorial Atlántida, donde nacen Billiken, Para Ti y La Chacra; autor de El Erial, Upa y Mangacha."],["Vigo","calle","Vigo: ciudad de España."],["Nicolás Vila","calle","Nicolás Vila (?-1829), comerciante; establece en 1821 la célebre pulpería del Caballito en la esquina sudoeste de las actuales Emilio Mitre y Rivadavia, cuya denominación perdurará en el nombre del barrio."],["Ingeniero Antonio Vilar","plaza","Antonio Ubaldo Vilar (1887 a 1966), ingeniero civil; entre sus obras se destacan el Hospital Churruca y la sede central del Automóvil Club Argentino."],["Teodoro Vilardebó","calle","Teodoro Vilardebó (1805 a 1857), médico y científico uruguayo; fallece en Montevideo víctima de la fiebre amarilla mientras luchaba por contrarrestar el mal."],["Vilela","calle","José María Vilela (1791 a 1841), coronel; era comerciante en el pueblo de la Conchas y forma el Regimiento de Colorados de las Conchas, con el que combate en los conflictos del litoral; interviene en la guerra contra el Brasil y en las luchas civiles bajo las órdenes de Paz, Lavalle y Lamadrid; derrotado en San Calá es ejecutado en Tucumán el 3 de octubre de 1841."],["Benjamín Villafañe","calle","Benjamín Villafañe (1819 a 1893), escritor y político; gobernador de Tucumán en 1861; rector del Colegio Nacional de Tucumán de 1865 a 1870; autor de Caudillos y principios, Orán y Bolivia a la margen del Bermejo y Reminiscencias históricas de un patriota."],["Wenceslao Villafañe","calle","Wenceslao Villafañe (1837 a 1903), jurisconsulto y empresario; fundador de la empresa de tranvías La Capital; implanta la primera red de tranvías eléctricos; miembro de la comisión pro templo que en 1883 coloca la piedra fundamental de la iglesia San Juan Evangelista."],["Boulevard Azucena Villaflor","calle","Azucena Villaflor de De Vicenti (1924 a 1977), defensora de los derechos humanos a raíz del secuestro y desaparición de uno de sus hijos; organiza la reunión de las Madres de Plaza de Mayo, cuyo primer encuentro se concreta el 30 de abril de 1977. A raíz de ello, ella misma fue secuestrada y desaparecida el 10 de diciembre del mismo año. VILLA JUNCAL véase JUNCAL, VILLA. VILLA LUGANO véase LUGANO, VILLA."],["Villanueva","calle","Nicolás Villanueva (1793 a 1874), sargento mayor; combate en el sitio de Montevideo en 1814, en Las Piedras, Vilohuma y Sipe Sipe; presidente de la Legislatura de Mendoza de 1823 a 1825; vicepresidente de la Constituyente de 1854."],["Villarino","calle","Basilio Villarino (1741 a 1785), explorador y colonizador; acompaña a Viedma en la fundación de Carmen de Patagones; explora el río Negro, el Limay y Collón Curá; muere en una expedición a Sierra de la Ventana."],["Villarroel","calle","Diego de Villarroel (1500 a 1580), conquistador español; fundador de la ciudad de San Miguel de Tucumán en 1565."],["General Conrado Excelso Villegas","calle","Conrado Excelso Villegas (1840 a 1884), militar; combate en la guerra contra el Paraguay y en la lucha contra el indio; derrota a Pincén en 1878 como jefe del campamento de Trenque Lauquen; acompaña a Roca en su campaña al Desierto en 1879."],["Vinchina","calle","Vinchina: localidad del departamento General Sarmiento, provincia de La Rioja."],["General Lorenzo Vintter","calle","Lorenzo Vintter (1842 a 1915), militar; combate en Cepeda, Pavón, en la guerra contra el Paraguay y en la lucha contra el indio; gobernador interino de la Patagonia en 1882 y gobernador de Formosa en 1901."],["Virasoro","calle","Benjamín Virasoro (1812 a 1897), teniente general; combate en Caaguazú, Arroyo Grande, Palmar y Vences; gobernador de Corrientes en 1847; combate en Cepeda, Pavón y en la guerra contra el Paraguay."],["Valentín Virasoro","calle","Valentín Virasoro (1842 a 1925), ingeniero civil y funcionario; gobernador de Corrientes en 1893; senador nacional en 1898 y presidente del Senado en 1912 y 1913; autor de Memorias de la Comisión de Límites de la Frontera Argentino-Chilena."],["Virgilio","calle","Publio Virgilio Marón (70-19 a.C.), poeta latino; autor de Geórgicas y La Eneida."],["Virreinato del Río de la Plata","plazoleta","Virreinato del Río de la Plata: organización político-administrativa que tuvo nuestro país entre el 1° de agosto de 1776 y el 25 de mayo de 1810, cuando cesa el mando de don Baltasar Hidalgo de Cisneros."],["De los Virreyes","plaza","Virreyes: recuerda a la suprema representación del monarca español en América durante la época hispánica."],["Francisco de Vittoria","calle","Francisco de Vittoria (¿-?), maestro; en 1605 recibe autorización para abrir una escuela en Buenos Aires; durante cierto tiempo se pensó que fue el primer maestro que hubo en la ciudad aunque ya no se lo considera como tal pues han sido individualizados antes que él en dicha profesión Diego Rodríguez y Ambrosio de Acosta."],["De los Viveros","plaza","De los Viveros: homenaje al vivero municipal, en ocasión de celebrarse en 1983 el centenario de la creación del primer criadero de plantas que funcionó en lo que hoy es la plaza España."],["Volta","calle","Alejandro Volta (1745 a 1827), físico italiano; inventor de la pila eléctrica que lleva a su nombre, del electróforo, del electrómetro y del eudiómetro."],["Voltaire","calle","Francisco María Arouet (1694 a 1778), escritor y filósofo francés conocido como Voltaire; autor de El siglo de Luis XV, Ensayo sobre las costumbres y el espíritu de las naciones, Diccionario filosófico y Cándido."],["Juan Vucetich","calle","Juan Vucetich (1858 a 1925), funcionario policial de origen austriaco; jefe de la Oficina de Dactiloscopía de la provincia de Buenos Aires; creador del sistema de identificación personal dactiloscópico basado en las impresiones digitales. VUELTA DE OBLIGADO véase OBLIGADO, VUELTA DE. Notas."],["Wagner","calle","Ricardo Wagner (1813 a 1883), músico alemán; autor de El anillo de los Nibelungos, tetralogía integrada por El oro del Rin, La Walkyria, Sigfrido y El ocaso de los dioses."],["Rodolfo Walsh","plazoleta","Rodolfo Walsh (1927 a 1977), escritor, periodista y militante político; considerado el creador de la novela de no-ficción en la Argentina. Colabora en las revistas Vea y Lea y Leoplán; en 1957 publica el libro Operación Masacre, en el que plasma sus investigaciones sobre el fusilamiento que había realizado la Revolución Libertadora en la localidad bonaerense de José León Suárez. En 1968 funda el Seminario CGT, de la Confederación General del Trabajo de los argentinos. Entre sus obras figuran: Variaciones en rojo, El caso Satanovsky y Quién mató a Rosendo García. Es secuestrado el 25 de marzo de 1977, por un grupo de tareas de la Escuela de Mecánica de la Armada, cuando hace pública su “Carta abierta de un escritor a la Junta Militar”. Está desaparecido."],["Warnes","avenida","José Ignacio Warnes (1772 a 1816), coronel; combate durante las Invasiones Inglesas, en la expedición al Paraguay de Belgrano, en Tucumán, Salta, Vilcapugio y Ayohuma; muere en acción el 21 de noviembre de 1816 en la batalla de la llanura del Parí."],["Washington","calle","Jorge Washington (1732 a 1799), general norteamericano; presidente de los Estados Unidos en 1789 y reelegido en 1793."],["White","calle","Guillermo Pío White (1770 a 1842), comerciante estadounidense; colabora económicamente durante la Revolución de Mayo y en el aprovisionamiento de armas para la escuadra que se estaba formando y cuyo mando asumió el almirante Guillermo Brown."],["Eduardo Wilde","calle","Eduardo Faustino Wilde (1844 a 1913), médico, escritor y político; cirujano del Ejército en la guerra contra el Paraguay; ministro de Justicia e Instrucción Pública de Roca, de Interior de Juárez Celman; presidente del Departamento Nacional de Higiene en 1898; autor de Aguas abajo, Prometeo y Cía., Por mares y por tierras y Tiempo perdido."],["Alberto Williams","calle","Alberto Williams (1862 a 1952), músico; fundador del Conservatorio de Música de Buenos Aires en 1893; autor de En la sierra, La bruja de la montaña, Rancho abandonado, Los batracios, Poema de la quebrada, Ataja caminos y Aires de la Pampa."],["Arquitecto Amancio Williams","plaza","Amancio Williams (1913 a 1989), arquitecto; miembro de la Academia Nacional de Bellas Artes; entre sus obras se destacan la Casa del Puente (Mar del Plata), la Casa de Di Tella (Punta del Este) y el edificio de la Unión Industrial en Buenos Aires."],["Jorge N. Williams","plazoleta","Jorge N. Williams (1857 a 1925), funcionario; se desempeña en el Ferrocarril del Oeste y en la Municipalidad de Buenos Aires como secretario privado del intendente Seeber, y como secretario general de los intendentes Bollini, Cané, Pinedo y Bullrich, con quienes se destacó por sus obras de asistencia social e higiene pública; director del Banco Hipotecario Nacional."],["Coronel de Ingenieros Jordán Czeslaw Wysocki","plaza","Jordán Czeslaw Wysocki (1839 a 1883), militar e ingeniero de origen polaco; llega a Buenos Aires en 1867; ejecuta en 1874 los trabajos de ingeniería del Parque Tres de Febrero en lo que respecta a delineación, planos, exclusas y portones; realiza planos en la expedición al Desierto de 1879 y en 1876 el estudio geográfico, estratégico y económico del río Santa Cruz. Notas."],["Gaspar Xuárez","plazoleta","Gaspar Xuárez (1731 a 1804), sacerdote misionero, educador, naturalista y escritor; autor de Observaciones fitológicas, Recuento de árboles curiosos y elegantes de las Indias Orientales y de América."],["Jaime Yankelevich","espacio verde","Jaime Yankelevich (1894 a 1952), empresario radial y televisivo de origen búlgaro; pionero de la radiofonía local; creador, fundador y director de Radio Belgrano en 1927; director de Radio Cultura, Mitre y Porteña; crea la Asociación de Radiodifusoras Argentinas; en 1951 deja constituida para Radio Belgrano la primera estación de televisión de Buenos Aires, cuya primera imagen, el rostro de Eva Perón, se emite el 17 de octubre de ese año."],["Yapeyú","calle","Se conoce ya con este nombre en 1891. (Véase Acta de la sesión ordinaria del Concejo Deliberante del 27-10-1891). La Resolución del 12-11-1907, restituye su nombre actual. Yapeyú: localidad cabecera del departamento de San Martín, Corrientes y pueblo natal del general José de San Martín."],["Yatay","calle","Yatay: batalla librada entre la vanguardia del ejército de la Triple Alianza al mando del general Venancio Flores y las fuerzas paraguayas al mando del mayor Duarte el 17 de agosto de 1865."],["Yerbal","calle","Yerbal: victoria obtenida por el general Juan Lavalle sobre las tropas brasileñas mandadas por Benito Gonzáles y Lucas Teodoro el 25 de mayo de 1827 durante la guerra contra el Brasil. El nombre proviene de un sembrado de yerba mate existente en las inmediaciones del lugar donde se desarrolló el combate."],["Yeruá","calle","Yeruá: victoria obtenida por el general Juan Lavalle sobre las tropas federales en la provincia de Entre Ríos sobre el arroyo del mismo nombre el 22 de septiembre de 1839."],["Hipólito Yrigoyen","calle","Hipólito Yrigoyen (1852 a 1933), estadista; presidente de la República de 1916 a 1922 y de 1928 a 1930; fundador de la Unión Cívica Radical; fue el primer presidente elegido mediante el sistema del sufragio universal."],["Hipólito Yrigoyen","plaza","Hipólito Yrigoyen (1852 a 1933), estadista; presidente de la República de 1916 a 1922 y de 1928 a 1930; fundador de la Unión Cívica Radical; fue el primer presidente elegido mediante el sistema del sufragio universal."],["Yrupé","calle","Yrupé o Irupé: planta acuática ninfácea del género Victoria llamada también “plato en el agua”, “maíz de agua” o “abatí irupé”."],["Rogelio Yrurtia","calle","Rogelio Yrurtia (1879 a 1950), escultor; autor de Las pescadoras, Canto al trabajo, Serenidad y de los monumentos a Rivadavia, Dorrego y Alejandro Castro."],["Yugoslavia","calle","Yugoslavia: país europeo. Capital: Belgrado."],["Yugoslavia","plazoleta","Yugoslavia: país europeo. Capital: Belgrado."],["Atahualpa Yupanqui","cantero central","Héctor Roberto Chavero (1908 a 1992), poeta, compositor, recopilador y guitarrista; autor de Camino del Indio, Luna tucumana, Piedra y camino y el Payador perseguido. Notas."],["Zabala","calle","Bruno Mauricio de Zabala (1682 a 1736), general español; gobernador del Río de la Plata desde 1717; fundador de Montevideo en 1726; capitán general de Chile en 1734."],["Doctor Joaquín Zabala","calle","Joaquín Zabala (1872 a 1919), veterinario y bacteriólogo; primer médico veterinario que integra la Academia Nacional de Agricultura y Veterinaria y el Consejo Superior de la Universidad de Buenos Aires; en 1894 es comisionado, junto con los doctores Carlos Malbrán y Juan N. Murtagh, para aplicar la tuberculina al ganado. Inicia la formación del Museo de Parasitología y de Anatomía Patológica de los Mataderos de Liniers. Describe junto a Otto Voges, por primera vez en nuestro medio, la queratitis infecciosa bovina; socio fundador de la Sociedad de Medicina y Veterinaria, de la que fue su presidente de 1899 a 1900 y de 1904 a 1905."],["Doctor Joaquín Zabala","patio de recreación","Joaquín Zabala (1872 a 1919), veterinario y bacteriólogo; primer médico veterinario que integra la Academia Nacional de Agricultura y Veterinaria y el Consejo Superior de la Universidad de Buenos Aires; en 1894 es comisionado, junto con los doctores Carlos Malbrán y Juan N. Murtagh, para aplicar la tuberculina al ganado. Inicia la formación del Museo de Parasitología y de Anatomía Patológica de los Mataderos de Liniers. Describe junto a Otto Voges, por primera vez en nuestro medio, la queratitis infecciosa bovina; socio fundador de la Sociedad de Medicina y Veterinaria, de la que fue su presidente de 1899 a 1900 y de 1904 a 1905."],["Rómulo Zabala","plazoleta","Rómulo Zabala (1894 a 1949), historiador; autor de Historia de la Ciudad de Buenos Aires (en colaboración con el Dr. Enrique de Gandía), Antecedentes de la Segunda Fundación de Buenos Aires y Los orígenes históricos de Buenos Aires."],["Zado","calle","Rufino Zado (1792 a 1871), coronel; combate en el sitio de Montevideo, en Chacabuco, Curapaligüe, Gavilán, Talcahuano, Maipú, Bío-Bío y Talca."],["Pedro F. Zaldívar","calle","Pedro F. Zaldívar (¿-?), funcionario municipal; jefe de la Oficina de Tránsito, hoy Dirección, de 1901 a 1910; integra la Comisión Municipal del Centenario de 1910; director de Limpieza en 1910; organizador de la Policía Municipal."],["Zamudio","calle","Máximo Zamudio (1787 a 1847), general; combate durante las Invasiones Inglesas, en Cotagaita, Suipacha, Vilcapugio, Sipe Sipe y en la campaña del Perú. Floro Zamudio (1789 a 1829), sargento mayor, hermano del anterior; combate durante las Invasiones Inglesas; oficial mayor de la Aduana de Buenos Aires."],["Comodoro Pedro L. N° 13.918. Zanni","plazoleta","Pedro L. Zanni (1891 a 1942), aviador militar; realiza en 1914 un vuelo desde El Palomar hasta Villa Mercedes, San Luis, recorriendo 640 kilómetros de distancia, lo que se constituye en el mayor vuelo registrado hasta entonces en América; cruza los Andes en 1920."],["Zañartú","calle","Miguel José de Zañartú (1781 a 1851), jurisconsulto y diplomático chileno; ministro de Interior de O´Higgins en 1817 a 1818; representante de su país en Lima y Buenos Aires; autor de Cuadro histórico del gobierno de Freire."],["Zapala","calle","Zapala: ciudad y departamento de la provincia de Neuquén."],["Zapata","calle","Martín Zapata (1811 a 1861), jurisconsulto; diputado por Mendoza en el Congreso Constituyente de 1853."],["Brigadier General José Matías Zapiola","plaza","José Matías Zapiola (1780 a 1874), militar; organizador del Regimiento de Granaderos a Caballo; combate en Chacabuco y Maipú; organiza los elementos navales que actúan en la guerra contra el Brasil; comandante general de Marina en 1825, 1852 y 1858; ministro de Guerra y Marina de Valentín Alsina de 1857 a 1859."],["Zárate","calle","Zárate: ciudad y partido de la provincia de Buenos Aires."],["Zárraga","calle","Clemente Zárraga (1808 a 1890), general venezolano; guerrero de la Independencia, interviene en la toma de Puerto Cabello; emigra a nuestro país en 1883."],["Canciller Miguel Ángel Zavala Ortiz","plazoleta","Miguel Ángel Zavala Ortiz (1905 a 1982), abogado especialista en Derecho Civil y Administrativo; legislador y miembro de la Junta Consultiva Nacional de 1955 a 1957; ministro de Relaciones Exteriores y Culto de 1963 a 1966."],["Zavaleta","calle","Diego Estanislao Zavaleta (1768 a 1842), sacerdote; vicario castrense en 1815, es elegido diputado al Congreso de Tucumán, incorporándose al mismo en 1817; presidente de la Comisión que redacta el Reglamento Provisorio de 1817."],["Zavalía","calle","Salustiano Zavalía (1810 a 1873), jurisconsulto; redactor de la Constitución de la provincia de Tucumán; gobernador provisional de la misma en 1856 y propietario en 1857."],["Estanislao S. Zeballos","calle","Estanislao Severo Zeballos (1854 a 1923), escritor y político; fundador de El Nacional; ministro de Relaciones Exteriores y Culto de Juárez Celman, Carlos Pellegrini y Figueroa Alcorta; decano de la Facultad de Derecho en 1910 y 1918; autor de Painé y la dinastía de los Zorros, Viaje al país de los araucanos, La dinastía de los Piedra y Cancionero popular de Buenos Aires."],["Zelada","calle","Francisco Zelada (1784 a 1863), teniente coronel; combate en el sitio de Montevideo, en Vilohuma, Sipe Sipe y Chacabuco; edecán del gobernador Martín Rodríguez."],["Zelarrayán","calle","Juan Zelarrayán (1790 a 1838), coronel; combate en la guerra contra el Brasil; participa en la campaña al desierto de 1833 con Juan Manuel de Rosas."],["Zelaya","calle","Cornelio Zelaya (1782 a 1855), coronel; combate durante las Invasiones Inglesas, en Cotagaita, Suipacha y Tucumán; diputado en el Congreso de 1826."],["Zenteno","calle","Pedro Alejandrino Zenteno (1794 a 1853), sacerdote; gobernador delegado de Catamarca en 1833; diputado en el Congreso Constituyente de 1853."],["Zepita","calle","Zepita: batalla librada en el Perú entre las fuerzas patriotas al mando del general Santa Cruz y las realistas del general Valdez el 25 de agosto de 1823."],["Antonio Abraham Zinny","plazoleta","Antonio Abraham Zinny (1821 a 1890), educador e historiador; organizador del archivo de Relaciones Exteriores en 1864 y del Municipal en 1871; autor de Efemeridografía Argirometropolitana, Historia de la prensa periódica de la República Oriental del Uruguay e Historia de los gobernadores de las Provincias Unidas."],["Alfredo Zitarrosa","paseo","Alfredo Zitarrosa (1936 a 1989), compositor e intérprete uruguayo; alcanza por su particular estilo y capacidad una alta jerarquía en ambas orillas del Río de la Plata; autor de Doña Soledad, Guitarra Negra y El violín de Becho."],["Emilio Zola","calle","Emilio Zola (1840 a 1902), escritor francés; autor de Naná, El vientre de París, Una página de amor, Germinal y Yo acuso."],["Antonio L. Zolezzi","calle","Antonio L. Zolezzi (1874 a 1953), comerciante y filántropo de origen italiano; concejal por la Boca entre 1908 y 1914; presidente de River Plate; fundador del Asilo Hogar de la Infancia de la Boca y del Hogar del Niño Boquense."],["El Zonda","calle","El Zonda: nombre de un viento característico de la provincia de San Juan con cuyo nombre Sarmiento bautizó su periódico fundado en 1839 y cuyo primer número apareció el 20 de julio."],["Pedro Zonza Briano","calle","Pedro Zonza Briano (1886 a 1941), escultor; autor de Creced y multiplicaos, Alma solitaria, Flor de juventud, Alma íntima y de los monumentos a Leandro N. Alem y Lucio Correa Morales."],["El Zorzal","calle","Zorzal: nombre con el que se denominan a varias especies de pájaros de la familia de los túrdidos."],["Carlos E. Zuberbühler","calle","Carlos E. Zuberbühler (1863 a 1916), educador y publicista; profesor de Historia del Arte de la Academia Nacional de Bellas Artes y de la Facultad de Filosofía y Letras; director del Museo de Bellas Artes; miembro fundador de la Unión Cívica de la Juventud, participa en la revolución de 1890; autor de La Unión Cívica del Parque."],["Brigadier General Ángel María Zuloaga","paseo","Ángel María Zuloaga (1885 a 1975), militar y aviador; efectuó en 1915 la primera travesía de la Cordillera de los Andes en globo libre; autor de Contribución al estudio de la organización y táctica de la aeronáutica militar, Arte y ciencia de volar, Curso elemental de aeronáutica y La victoria de las alas."],["Zurich","calle","Zurich: ciudad y estado de Suiza."],["Zuviría","calle","Facundo de Zuviría (1793 a 1861), jurisconsulto; gobernador de Salta; diputado y presidente del Congreso Constituyente de 1853; ministro de Justicia, Culto e Instrucción Pública de 1853 a 1855. Notas."]];
